def _permission_dict(value):
    """Normalize Supabase JSONB values and tolerate legacy/null records."""
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return dict(parsed) if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


@st.cache_data(max_entries=32, show_spinner=False)
def default_workspace_permissions(role):
    clean_role = str(role or "staff").strip().lower()
    allowed = ROLE_DEFAULT_WORKSPACES.get(
        clean_role,
        ROLE_DEFAULT_WORKSPACES["staff"],
    )
    return {
        key: key in allowed
        for key in WORKSPACE_LABELS
    }


@st.cache_data(max_entries=32, show_spinner=False)
def default_feature_permissions(role):
    clean_role = str(role or "staff").strip().lower()
    allowed = ROLE_DEFAULT_FEATURES.get(
        clean_role,
        ROLE_DEFAULT_FEATURES["staff"],
    )
    return {
        key: key in allowed
        for key in FEATURE_LABELS
    }


def _permission_cache_payload(value):
    """Return deterministic JSON for cache-safe permission evaluation."""
    normalized = _permission_dict(value)
    try:
        return json.dumps(
            normalized,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    except Exception:
        return "{}"


@st.cache_data(max_entries=256, show_spinner=False)
def _effective_workspace_permissions_cached(clean_role, stored_payload):
    """Compute workspace permissions once per role/permission payload."""
    if clean_role == "admin":
        return {key: True for key in WORKSPACE_LABELS}

    defaults = default_workspace_permissions(clean_role)
    supplied = _permission_dict(stored_payload)
    permissions = {
        key: bool(supplied.get(key, defaults[key]))
        for key in WORKSPACE_LABELS
    }

    if clean_role in STRICT_EXTERNAL_ROLES:
        permissions = {key: key == "technical" for key in WORKSPACE_LABELS}

    if not any(permissions.values()):
        permissions["technical"] = True

    return permissions


@st.cache_data(max_entries=256, show_spinner=False)
def _effective_feature_permissions_cached(clean_role, stored_payload):
    """Compute feature permissions once per role/permission payload."""
    if clean_role == "admin":
        return {key: True for key in FEATURE_LABELS}

    defaults = default_feature_permissions(clean_role)
    supplied = _permission_dict(stored_payload)
    permissions = {
        key: bool(supplied.get(key, defaults[key]))
        for key in FEATURE_LABELS
    }

    if clean_role in STRICT_EXTERNAL_ROLES:
        permissions["history"] = False
        permissions["woocommerce"] = False
        permissions["knowledge_upload"] = False
        permissions["product_library_upload"] = False
        permissions["product_library_manage"] = False

    return permissions


def effective_workspace_permissions(role=None, stored=None):
    clean_role = str(
        role if role is not None else st.session_state.get("role", "staff")
    ).strip().lower()
    stored_value = (
        stored if stored is not None
        else st.session_state.get("workspace_permissions")
    )
    return dict(_effective_workspace_permissions_cached(
        clean_role,
        _permission_cache_payload(stored_value),
    ))


def effective_feature_permissions(role=None, stored=None):
    clean_role = str(
        role if role is not None else st.session_state.get("role", "staff")
    ).strip().lower()
    stored_value = (
        stored if stored is not None
        else st.session_state.get("feature_permissions")
    )
    return dict(_effective_feature_permissions_cached(
        clean_role,
        _permission_cache_payload(stored_value),
    ))


def user_can_access_workspace(workspace_key):
    return bool(
        effective_workspace_permissions().get(str(workspace_key), False)
    )


def user_can_use_feature(feature_key):
    """Return the effective feature permission with workspace dependencies."""
    clean_key = str(feature_key or "").strip()
    permissions = effective_feature_permissions()

    # Product Library actions are never usable unless the workspace itself is
    # assigned. This prevents a partially configured user record from gaining
    # upload/manage access through a direct code path while the sidebar is hidden.
    if clean_key in {"product_library_upload", "product_library_manage"}:
        if not user_can_access_workspace("product_library"):
            return False

    # Manage is a superset of upload. Legacy or manually edited JSON records may
    # contain manage=true and upload=false; normalize that safely at runtime.
    if clean_key == "product_library_upload" and permissions.get(
        "product_library_manage", False
    ):
        return True

    return bool(permissions.get(clean_key, False))


def history_is_enabled():
    return user_can_use_feature("history")


