class ManagedUploadedFile(io.BytesIO):
    """Reusable in-memory upload object with Streamlit-compatible metadata.

    ``graphic_role`` and ``graphic_asset_id`` are optional internal metadata used
    by the conversation-level Graphic Project Engine. They do not affect any
    Technical, Sales, Marketing, Admin, or knowledge-upload workflow.
    """

    def __init__(
        self, data, name, mime_type="application/octet-stream",
        *, graphic_role="", graphic_asset_id="",
    ):
        file_bytes = bytes(data or b"")
        super().__init__(file_bytes)
        self.name = str(name or "upload")
        self.type = str(mime_type or "application/octet-stream")
        self.size = len(file_bytes)
        self.graphic_role = str(graphic_role or "").strip()
        self.graphic_asset_id = str(graphic_asset_id or "").strip()

    def getvalue(self):
        """Return the complete file bytes without changing the current position."""
        return super().getvalue()


def _normalized_upload_mime_type(file_name, reported_type=""):
    """Return a stable MIME type for browser uploads, especially Office files."""
    extension = Path(str(file_name or "")).suffix.lower()
    mime_by_extension = {
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".png": "image/png",
        ".pdf": "application/pdf",
        ".txt": "text/plain",
        ".doc": "application/msword",
        ".docx": (
            "application/vnd.openxmlformats-officedocument."
            "wordprocessingml.document"
        ),
        ".xls": "application/vnd.ms-excel",
        ".xlsx": (
            "application/vnd.openxmlformats-officedocument."
            "spreadsheetml.sheet"
        ),
        ".xlsm": "application/vnd.ms-excel.sheet.macroEnabled.12",
        ".xlsb": "application/vnd.ms-excel.sheet.binary.macroEnabled.12",
        ".csv": "text/csv",
        ".ppt": "application/vnd.ms-powerpoint",
        ".pptx": (
            "application/vnd.openxmlformats-officedocument."
            "presentationml.presentation"
        ),
        ".zip": "application/zip",
    }

    expected_type = mime_by_extension.get(extension)
    clean_reported_type = str(reported_type or "").strip()

    if expected_type:
        return expected_type
    return clean_reported_type or "application/octet-stream"


def _managed_upload_record(uploaded_file):
    data = uploaded_file.getvalue()
    digest = hashlib.sha256(data).hexdigest()
    file_name = str(getattr(uploaded_file, "name", "upload"))
    return {
        "id": digest,
        "name": file_name,
        "type": _normalized_upload_mime_type(
            file_name,
            getattr(uploaded_file, "type", ""),
        ),
        "size": len(data),
        "data": data,
    }


def _managed_upload_objects(records):
    return [
        ManagedUploadedFile(
            record["data"],
            record["name"],
            record.get("type") or "application/octet-stream",
        )
        for record in (records or [])
    ]


def clear_managed_uploads(storage_key, generation_key):
    st.session_state[storage_key] = []
    st.session_state[generation_key] = (
        int(st.session_state.get(generation_key, 0)) + 1
    )




@st.cache_data(show_spinner=False)
def _upload_preview_icon_data_url(icon_path):
    """Return a cached data URL for an upload-preview icon asset."""
    try:
        path = Path(icon_path)
        if not path.exists() or not path.is_file():
            return ""
        encoded = base64.b64encode(path.read_bytes()).decode()
        suffix = path.suffix.lower()
        mime_type = "image/png" if suffix == ".png" else "image/jpeg"
        return f"data:{mime_type};base64,{encoded}"
    except Exception:
        return ""


def _upload_preview_icon_for_file(file_name):
    """Select the matching local icon asset for a non-image upload."""
    extension = Path(str(file_name or "")).suffix.lower()

    if extension == ".pdf":
        return PDF_FILE_ICON
    if extension in {".doc", ".docx"}:
        return WORD_FILE_ICON
    if extension in {".xls", ".xlsx", ".xlsm", ".xlsb", ".csv"}:
        return EXCEL_FILE_ICON
    if extension in {".ppt", ".pptx"}:
        return POWERPOINT_FILE_ICON
    if extension == ".zip":
        return ZIP_FILE_ICON
    return None


def _managed_uploader_fragment_decorator(function):
    """Run uploader interactions inside a Streamlit fragment when available.

    Removing a pending file then reruns only the uploader region instead of the
    entire application. Older Streamlit versions safely keep the original
    full-page behavior.
    """
    fragment = getattr(st, "fragment", None)
    if callable(fragment):
        return fragment(function)
    return function


def _optional_ui_fragment(function):
    """Isolate frequent UI interactions when fragments are supported.

    Older Streamlit versions retain the original full-app rerun path. Successful
    database/storage mutations still call ``st.rerun()`` and invalidate their
    existing caches, preserving cross-workspace consistency.
    """
    fragment = getattr(st, "fragment", None)
    if callable(fragment):
        try:
            return fragment(function)
        except Exception:
            pass
    return function


def _rerun_fragment_or_app():
    """Rerun only the active fragment when supported, otherwise the full app.

    Streamlit versions before fragment-scoped reruns raise TypeError or a
    Streamlit API exception for ``scope="fragment"``. The compatibility
    fallback preserves the existing behavior without hiding unrelated errors.
    """
    try:
        st.rerun(scope="fragment")
    except Exception as error:
        message = str(error).lower()
        if "scope" not in message and "fragment" not in message:
            raise
        st.rerun()


def _rerun_upload_region():
    """Refresh only the active uploader fragment when the runtime supports it."""
    _rerun_fragment_or_app()


@st.cache_data(max_entries=256, show_spinner=False)
def _managed_image_data_url(file_type, file_bytes):
    """Return a compact cached thumbnail instead of embedding the full upload.

    Pending uploads can be several megabytes each. Embedding every original file
    as Base64 made each delete interaction resend and repaint all full-resolution
    images, even when Streamlit fragments were enabled. A small thumbnail keeps
    the preview visually identical while reducing browser payload and rerender
    work by orders of magnitude. The original bytes remain untouched in session
    state and are still used for the eventual upload.
    """
    raw = bytes(file_bytes or b"")
    if not raw:
        return ""

    if Image is not None:
        try:
            with Image.open(io.BytesIO(raw)) as source:
                preview = ImageOps.exif_transpose(source).copy()
                preview.thumbnail((420, 300), Image.Resampling.LANCZOS)

                # JPEG is much smaller for ordinary product photos. Preserve
                # transparency only when the source actually contains it.
                has_alpha = preview.mode in {"RGBA", "LA"} or (
                    preview.mode == "P" and "transparency" in preview.info
                )
                buffer = io.BytesIO()
                if has_alpha:
                    if preview.mode != "RGBA":
                        preview = preview.convert("RGBA")
                    preview.save(buffer, format="PNG", optimize=True)
                    mime_type = "image/png"
                else:
                    if preview.mode != "RGB":
                        preview = preview.convert("RGB")
                    preview.save(
                        buffer,
                        format="JPEG",
                        quality=74,
                        optimize=True,
                        progressive=True,
                    )
                    mime_type = "image/jpeg"

                encoded = base64.b64encode(buffer.getvalue()).decode()
                return f"data:{mime_type};base64,{encoded}"
        except Exception:
            # Unsupported/corrupt images retain the previous safe fallback.
            pass

    encoded = base64.b64encode(raw).decode()
    return f"data:{str(file_type or 'image/png')};base64,{encoded}"


def render_managed_upload_preview(record, delete_key, on_delete):
    """Render one preview card with a real Streamlit delete button."""
    file_type = str(record.get("type") or "")
    raw_file_name = str(record.get("name") or "upload")
    file_name = html.escape(raw_file_name)
    file_size = float(record.get("size") or 0) / (1024 * 1024)
    card_key = f"atp_upload_card_{record['id'][:16]}"

    with st.container(key=card_key):
        if file_type.startswith("image/"):
            preview_data_url = _managed_image_data_url(
                file_type,
                record["data"],
            )
            media_html = (
                '<div class="atp-gpt-upload-media">'
                f'<img src="{html.escape(preview_data_url)}" '
                f'alt="{file_name}">'
                "</div>"
            )
        else:
            icon_path = _upload_preview_icon_for_file(raw_file_name)
            icon_data_url = (
                _upload_preview_icon_data_url(str(icon_path))
                if icon_path is not None
                else ""
            )

            if icon_data_url:
                icon_html = (
                    f'<img src="{icon_data_url}" '
                    f'alt="{html.escape(Path(raw_file_name).suffix.upper().lstrip('.') or 'Document')} icon">'
                )
            else:
                icon_html = "📄"

            file_icon_class = (
                "atp-gpt-file-icon atp-gpt-file-icon-zip"
                if Path(raw_file_name).suffix.lower() == ".zip"
                else "atp-gpt-file-icon"
            )
            media_html = (
                '<div class="atp-gpt-upload-media">'
                f'<div class="{file_icon_class}">{icon_html}</div>'
                "</div>"
            )

        st.markdown(
            f"""
            {media_html}
            <div class="atp-gpt-upload-meta">
                <div class="atp-gpt-upload-name">{file_name}</div>
                <div class="atp-gpt-upload-size">{file_size:.1f} MB</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        st.button(
            "×",
            key=delete_key,
            help="Remove file",
            on_click=on_delete,
        )



def _chat_submission_fingerprint_v68690(
    assistant, prompt_text, upload_records, generation_number,
    *, attachment_only=False, conversation_id=None,
):
    """Create a stable fingerprint for one browser submission lifecycle."""
    upload_ids = sorted(
        str(record.get("id") or "")
        for record in (upload_records or [])
        if isinstance(record, dict) and str(record.get("id") or "")
    )
    payload = {
        "assistant": str(assistant or ""),
        "conversation_id": str(conversation_id or ""),
        "prompt": str(prompt_text or "").strip(),
        "upload_ids": upload_ids,
        "upload_generation": int(generation_number or 0),
        "attachment_only": bool(attachment_only),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _chat_submission_is_duplicate_v68690(fingerprint):
    """Reject the same attachment submission replayed by a Streamlit rerun."""
    value = str(fingerprint or "")
    if not value:
        return False
    return value in {
        str(st.session_state.get("_atp_active_submission_v68690") or ""),
        str(st.session_state.get("_atp_last_completed_submission_v68690") or ""),
    }


def _chat_submission_begin_v68690(fingerprint):
    value = str(fingerprint or "")
    if value:
        st.session_state["_atp_active_submission_v68690"] = value


def _chat_submission_complete_v68690(fingerprint):
    value = str(fingerprint or "")
    if value:
        st.session_state["_atp_last_completed_submission_v68690"] = value
    if str(st.session_state.get("_atp_active_submission_v68690") or "") == value:
        st.session_state.pop("_atp_active_submission_v68690", None)

ATTACHMENT_ONLY_CHAT_SENTINEL = "\u200b"


def _graphic_visible_submission_text_v68849(value):
    """Return the real user text without the invisible attachment sentinel.

    The managed uploader inserts a zero-width sentinel only to enable Streamlit's
    native send arrow.  It must never replace, hide, or influence visible text that
    the user typed into the composer.
    """
    text = str(value or "")
    return text.replace(ATTACHMENT_ONLY_CHAT_SENTINEL, "").strip()


def _graphic_project_generation_ready_v68849(state=None):
    """Return whether an existing Graphic project has product and style authority.

    This is an orchestration-only readiness check.  It does not change reference,
    installed-view, geometry, provider, QA, or final-rendering behavior.
    """
    project = _graphic_repair_project_asset_roles_v15000(
        state if isinstance(state, dict) else get_graphic_project_state()
    )
    roles = _graphic_project_role_set(project)
    has_product = bool({"product", "product_photo"} & roles)
    has_reference_asset = bool({"reference", "style_reference"} & roles)
    has_locked_reference = bool(
        str(project.get("active_reference_id") or "").strip()
        or project.get("last_reference_blueprint")
        or project.get("project_style_dna")
    )
    return bool(has_product and (has_reference_asset or has_locked_reference))


def _graphic_v68865_should_show_early_status(prompt_text, assistant, uploaded_files=None):
    """Fast local-only Graphic action detector used only for immediate UI feedback.

    This does not route or alter the request. The existing production detectors
    remain authoritative later in the turn.
    """
    if str(assistant or "") != "🎨 Graphic Marketing":
        return False
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not value:
        return False
    # Keep this intentionally narrow and deterministic.
    action_terms = (
        "create it",
        "create the image",
        "create the commercial",
        "create commercial",
        "generate it",
        "generate image",
        "generate the image",
        "make the image",
        "make this image",
        "regenerate",
        "try again",
        "proceed",
        "create now",
    )
    return any(term in value for term in action_terms)


def _sync_native_chat_send_arrow_for_attachments(has_attachments):
    """Enable the existing native chat send arrow for attachment-only turns.

    Streamlit's native ``st.chat_input`` disables submission when its textarea is
    completely empty.  A zero-width sentinel makes the native composer consider
    the turn non-empty without showing any visible text.  The main chat pipeline
    removes the sentinel and treats the turn as attachment-only.
    """
    enabled = "true" if bool(has_attachments) else "false"
    sentinel_json = json.dumps(ATTACHMENT_ONLY_CHAT_SENTINEL)
    components.html(
        f"""
        <script>
        (() => {{
          const parentWindow = window.parent;
          const doc = parentWindow.document;
          const sentinel = {sentinel_json};
          const hasAttachments = {enabled};

          function setNativeValue(textarea, value) {{
            const descriptor = Object.getOwnPropertyDescriptor(
              parentWindow.HTMLTextAreaElement.prototype,
              'value'
            );
            if (descriptor && descriptor.set) {{
              descriptor.set.call(textarea, value);
            }} else {{
              textarea.value = value;
            }}
            textarea.dispatchEvent(new parentWindow.Event('input', {{ bubbles: true }}));
            textarea.dispatchEvent(new parentWindow.Event('change', {{ bubbles: true }}));
          }}

          function syncComposer() {{
            const textarea =
              doc.querySelector('textarea[data-testid="stChatInputTextArea"]') ||
              doc.querySelector('div[data-testid="stChatInput"] textarea') ||
              doc.querySelector('textarea[placeholder="Message AutoTecPro AI..."]');
            if (!textarea) return false;

            const current = textarea.value || '';
            if (hasAttachments) {{
              if (current === '') setNativeValue(textarea, sentinel);
            }} else if (current === sentinel) {{
              setNativeValue(textarea, '');
            }}
            return true;
          }}

          let attempts = 0;
          const timer = parentWindow.setInterval(() => {{
            attempts += 1;
            if (syncComposer() || attempts > 40) parentWindow.clearInterval(timer);
          }}, 100);
          syncComposer();
        }})();
        </script>
        """,
        height=0,
        width=0,
    )


def _managed_file_uploader_core(
    *,
    storage_key,
    generation_key,
    widget_prefix,
    accepted_types,
    heading,
    attachment_submit_key=None,
):
    """
    Stable GPT-style upload manager.

    On supported Streamlit versions, uploader selection and removal rerun only
    this fragment. Older versions retain the original full-page fallback.
    """
    install_gpt_uploader_css()

    if storage_key not in st.session_state:
        st.session_state[storage_key] = []
    if generation_key not in st.session_state:
        st.session_state[generation_key] = 0

    records = list(st.session_state.get(storage_key) or [])
    shell_key = f"atp_upload_shell_{widget_prefix}"
    with st.container(key=shell_key):
        st.markdown(
            f'<div class="atp-upload-heading">{html.escape(heading)}</div>',
            unsafe_allow_html=True,
        )

        if records:
            # Render previews row-by-row instead of cycling items down fixed
            # columns. This keeps every row aligned horizontally and centers
            # the final incomplete row.
            cards_per_row = 5

            for row_start in range(0, len(records), cards_per_row):
                row_records = records[row_start:row_start + cards_per_row]

                with st.container(
                    key=f"atp_preview_grid_{widget_prefix}_{row_start}"
                ):
                    preview_columns = st.columns(
                        len(row_records),
                        gap="small",
                        vertical_alignment="top",
                    )

                    for column, record in zip(preview_columns, row_records):
                        record_id = record["id"]

                        def delete_record(record_id=record_id):
                            # Streamlit button callbacks run before the script body
                            # is rendered. Updating the managed preview list here
                            # makes the very next frame contain only the final state,
                            # instead of first painting the old preview/uploader tree
                            # and then forcing a second st.rerun(). The native uploader
                            # key remains unchanged, so the Upload control stays mounted,
                            # clickable, and cannot briefly duplicate during deletion.
                            st.session_state[storage_key] = [
                                item
                                for item in st.session_state.get(storage_key, [])
                                if item.get("id") != record_id
                            ]

                        with column:
                            render_managed_upload_preview(
                                record,
                                delete_key=(
                                    f"atp_delete_btn_{widget_prefix}_"
                                    f"{record_id[:16]}"
                                ),
                                on_delete=delete_record,
                            )

            st.markdown(
                '<div class="atp-add-file-label">＋ Add another file</div>',
                unsafe_allow_html=True,
            )


        incoming_files = st.file_uploader(
            "Upload files",
            type=accepted_types,
            accept_multiple_files=True,
            key=f"{widget_prefix}_{st.session_state[generation_key]}",
            label_visibility="collapsed",
        )

    if incoming_files:
        existing_ids = {item["id"] for item in records}
        oversized_names = []

        for uploaded_file in incoming_files:
            record = _managed_upload_record(uploaded_file)

            if record["size"] > MAX_UPLOAD_BYTES:
                oversized_names.append(record["name"])
                continue

            if record["id"] not in existing_ids:
                records.append(record)
                existing_ids.add(record["id"])

        st.session_state[storage_key] = records
        st.session_state[generation_key] += 1

        if oversized_names:
            st.session_state[f"{storage_key}_size_error"] = (
                f"These files exceed the {MAX_UPLOAD_SIZE_MB} MB limit: "
                + ", ".join(oversized_names)
            )

        # Refresh only this uploader region when fragments are supported.
        # This resets the native input without rerunning database, history,
        # Auto Learning, sidebar, or workspace code.
        _rerun_upload_region()

    # Keep the proven managed uploader interface. The normal bottom-right chat
    # send arrow becomes active whenever one or more managed attachments exist.
    _sync_native_chat_send_arrow_for_attachments(
        bool(st.session_state.get(storage_key) or [])
    )

    size_error = st.session_state.pop(f"{storage_key}_size_error", None)
    if size_error:
        st.error(size_error)

    return _managed_upload_objects(st.session_state.get(storage_key) or [])




@_managed_uploader_fragment_decorator
def managed_file_uploader(
    *,
    storage_key,
    generation_key,
    widget_prefix,
    accepted_types,
    heading,
    attachment_submit_key=None,
):
    """Fragment-scoped public uploader wrapper."""
    return _managed_file_uploader_core(
        storage_key=storage_key,
        generation_key=generation_key,
        widget_prefix=widget_prefix,
        accepted_types=accepted_types,
        heading=heading,
        attachment_submit_key=attachment_submit_key,
    )

