def _install_login_interaction_fastpath_v69044():
    """Event-driven login form polish with no auth, cookie, or submit authority."""
    components.html(
        """
        <script>
        (() => {
          const root = window.parent;
          const doc = root.document;
          const KEY = "__atpLoginInteractionFastpathV69044";
          try { root[KEY]?.cleanup?.(); } catch (error) {}

          let observer = null;
          let submitButton = null;
          let submitted = false;

          function configure() {
            const form = doc.querySelector(
              'form[data-testid="stForm"], div[data-testid="stForm"]'
            );
            if (!form) return false;
            const inputs = Array.from(form.querySelectorAll("input"));
            const username = inputs.find((input) => input.type === "text");
            const password = inputs.find((input) => input.type === "password");
            submitButton = form.querySelector('button[type="submit"]');
            if (!username || !password || !submitButton) return false;

            form.setAttribute("autocomplete", "off");
            username.setAttribute("autocomplete", "off");
            username.setAttribute("autocapitalize", "none");
            username.setAttribute("spellcheck", "false");
            password.setAttribute("autocomplete", "new-password");

            submitButton.addEventListener("click", () => {
              if (submitted || !username.value.trim() || !password.value) return;
              submitted = true;
              submitButton.setAttribute("aria-busy", "true");
              submitButton.style.cursor = "wait";
              const label = submitButton.querySelector("p, span");
              if (label) label.textContent = "Signing in…";
            }, { once: true });
            return true;
          }

          if (!configure()) {
            observer = new MutationObserver(() => {
              if (configure() && observer) {
                observer.disconnect();
                observer = null;
              }
            });
            observer.observe(doc.documentElement, { childList: true, subtree: true });
          }

          function cleanup() {
            try { observer?.disconnect(); } catch (error) {}
            observer = null;
          }
          root[KEY] = { cleanup };
          window.addEventListener("beforeunload", cleanup, { once: true });
        })();
        </script>
        """,
        height=0,
        width=0,
    )



def login_screen():
    apply_login_layout_css()

    # Keep the complete login page in one placeholder so every login element
    # (logo, heading, form) disappears together after authentication.
    login_page_placeholder = st.empty()

    # Read saved credentials only to prefill the form. This never logs the
    # user in automatically.
    saved_login = get_saved_login_credentials()
    remember_default = bool(saved_login.get("remember"))
    saved_username = str(saved_login.get("username") or "")
    saved_password = ""

    with login_page_placeholder.container():
        logo_base64 = get_logo_base64()

        if logo_base64:
            st.markdown(
                f"""
                <div class="login-logo">
                    <img src="data:image/png;base64,{logo_base64}">
                </div>
                """,
                unsafe_allow_html=True,
            )
        else:
            st.markdown(
                """
                <div class="login-logo">
                    <h1 style="font-size:48px;margin:0;color:white;">
                        AutoTecPro
                    </h1>
                    <p style="color:#94a3b8;margin-top:6px;">
                        Driven by Innovation
                    </p>
                </div>
                """,
                unsafe_allow_html=True,
            )

        st.markdown(
            """
            <div class="login-heading">
                <div class="login-heading-main">AutoTecPro AI Login</div>
                <div class="login-heading-sub">Internal AI Assistant</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        _install_login_interaction_fastpath_v69044()

        with st.form("login_form"):
            username = st.text_input(
                "Username",
                value=saved_username,
                placeholder="Enter your username",
            )
            password = st.text_input(
                "Password",
                value=saved_password,
                placeholder="Enter your password",
                type="password",
            )
            remember_me = st.checkbox(
                "Remember me",
                value=remember_default,
                help="Keep me signed in and remember my username on this browser for 30 days.",
            )
            login_submitted = st.form_submit_button(
                "Login",
                use_container_width=True,
            )

    if login_submitted:
        username = username.strip()

        if not username or not password:
            st.warning("Please enter your username and password.")
            return

        allowed, retry_after = security_login_rate_limit_status(username)
        if not allowed:
            st.error(f"Too many failed login attempts. Try again in {max(1, int(retry_after))} seconds.")
            return

        try:
            result = (
                supabase
                .table("users")
                .select(
                    "username,password,role,active,workspace_permissions,feature_permissions"
                )
                .eq("username", username)
                .eq("active", True)
                .limit(1)
                .execute()
            )

            user = result.data[0] if result.data else None
            password_valid = False
            legacy_password = False
            if user:
                password_valid, legacy_password = verify_user_password(
                    password, user.get("password")
                )

            if user and password_valid:
                security_clear_login_failures(username)
                if legacy_password:
                    _upgrade_legacy_user_password(user, password)

                st.session_state.logged_in = True
                st.session_state["_auth_transition"] = "login"
                st.session_state.username = user["username"]
                st.session_state.role = str(user.get("role") or "staff").lower()
                st.session_state.workspace_permissions = (
                    effective_workspace_permissions(
                        st.session_state.role,
                        user.get("workspace_permissions"),
                    )
                )
                st.session_state.feature_permissions = (
                    effective_feature_permissions(
                        st.session_state.role,
                        user.get("feature_permissions"),
                    )
                )
                st.session_state.messages = []
                st.session_state.conversation_id = None
                st.session_state["_atp_session_remembered"] = bool(remember_me)
                st.session_state.pop("_auth_bootstrap_attempt_v69042", None)

                if remember_me:
                    queue_login_cookie_action(
                        "save",
                        user["username"],
                        remember=True,
                    )
                else:
                    queue_login_cookie_action(
                        "clear",
                        user["username"],
                        remember=False,
                    )

                try:
                    st.query_params.clear()
                except Exception:
                    pass

                st.rerun()
            else:
                security_record_login_failure(username)
                clear_browser_login_profile()
                try:
                    st.query_params.clear()
                except Exception:
                    pass
                st.error("Invalid username or password.")

        except Exception as error:
            diagnostic_log(
                "login_failed_internal",
                error_type=type(error).__name__,
                error=str(error),
            )
            st.error("Login is temporarily unavailable. Please try again.")


if "logged_in" not in st.session_state:
    diagnostic_log(
        "new_streamlit_session_initialized",
        reason="logged_in key was absent from session_state",
    )
    st.session_state.logged_in = False

# A workspace change, mobile reconnect, or Streamlit rerun may leave a false
# login flag in an otherwise recoverable browser session. Restore only when this
# is not an explicit logout transition. Cookie deletion is browser-side and may
# require one or more reruns before the old signed cookie disappears.
_auth_restore_result_v69043 = True if bool(
    st.session_state.get("logged_in")
) else False
if not bool(st.session_state.get("logged_in")):
    explicit_logout_pending = bool(
        st.session_state.get("_explicit_logout_pending")
    )
    if explicit_logout_pending:
        try:
            remaining_auth_cookie = auth_cookie_controller.get(
                AUTH_SESSION_COOKIE
            )
        except Exception:
            remaining_auth_cookie = None

        if remaining_auth_cookie:
            # Retry deletion and continue showing only the logged-out UI.
            remove_authenticated_session()
        else:
            st.session_state.pop("_explicit_logout_pending", None)
    else:
        _auth_restore_result_v69043 = restore_login_session()
        if _auth_restore_result_v69043 is True:
            st.session_state.pop("_auth_bootstrap_attempt_v69042", None)

if not bool(st.session_state.get("logged_in")):
    # v69043 production hotfix: an empty or temporarily unavailable first cookie
    # read must never block a real user behind an authentication overlay. Render
    # Login immediately; CookieController may still trigger a later safe rerun.
    st.session_state.pop("_auth_bootstrap_attempt_v69042", None)
    st.session_state.pop("_auth_transition", None)
    if _auth_transition_placeholder is not None:
        try:
            _auth_transition_placeholder.empty()
        except Exception:
            pass
    login_screen()
    # The destination login UI is now complete; remove the transition cover
    # before stopping execution so authenticated content cannot render below it.
    _finish_auth_transition(_auth_transition_placeholder)
    st.stop()

# Complete any Remember Me cookie write/removal on a stable authenticated
# render. Do not rerun immediately after this call.
process_pending_login_cookie_action()

apply_app_layout_css()

