def _document_settings_state_key(workspace=None):
    active = str(workspace or st.session_state.get("current_assistant") or assistant or "")
    digest = hashlib.sha256(active.encode("utf-8")).hexdigest()[:12]
    return f"document_settings_{digest}"


def get_document_creator_settings(workspace=None):
    active = str(workspace or st.session_state.get("current_assistant") or assistant or "")
    defaults = dict(
        DOCUMENT_WORKSPACE_DEFAULTS.get(
            active,
            {
                "format": "pdf",
                "include_logo": False,
                "include_company_info": False,
                "watermark": "",
                "style": "Professional",
            },
        )
    )
    state_key = _document_settings_state_key(active)
    saved = st.session_state.get(state_key)
    if isinstance(saved, dict):
        defaults.update({
            key: saved.get(key, defaults[key])
            for key in defaults
        })
    defaults["format"] = str(defaults.get("format") or "pdf").lower()
    if defaults["format"] not in {"pdf", "docx", "pptx", "xlsx", "csv"}:
        defaults["format"] = "pdf"
    defaults["style"] = str(defaults.get("style") or "Professional")
    return defaults


def save_document_creator_settings(settings, workspace=None):
    clean = get_document_creator_settings(workspace)
    if isinstance(settings, dict):
        clean.update(settings)
    st.session_state[_document_settings_state_key(workspace)] = clean
    return clean


def _conversation_document_text(messages, current_answer=""):
    parts = []
    for message in messages or []:
        if not isinstance(message, dict):
            continue
        role = str(message.get("role") or "").strip().lower()
        content = str(message.get("content") or "")
        content, _ = extract_documents_from_message_content(content)
        content, _ = extract_images_from_message_content(content)
        content = clean_visible_chat_text(content).strip()
        if not content:
            continue
        label = "User" if role == "user" else "AutoTecPro AI"
        parts.append(f"{label}\n{content}")
    if str(current_answer or "").strip():
        parts.append(f"AutoTecPro AI\n{clean_visible_chat_text(current_answer).strip()}")
    return "\n\n".join(parts).strip()


def _document_request_uses_conversation(prompt_text):
    """Return True only when the user explicitly requests the chat transcript."""
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().lower()
    return any(
        phrase in value
        for phrase in (
            "this conversation",
            "the conversation",
            "current conversation",
            "last conversation",
            "previous conversation",
            "above conversation",
            "entire conversation",
            "whole conversation",
            "this chat",
            "the chat",
            "current chat",
            "last chat",
            "previous chat",
            "above chat",
            "entire chat",
            "whole chat",
        )
    )


def _document_request_uses_previous_response(prompt_text):
    """Return True for follow-up exports of the immediately preceding AI answer."""
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().lower()
    response_references = (
        "this response",
        "this answer",
        "the response",
        "the answer",
        "last response",
        "last answer",
        "previous response",
        "previous answer",
        "above response",
        "above answer",
    )
    direct_followups = (
        "convert this to pdf",
        "convert this into pdf",
        "convert this to a pdf",
        "convert this into a pdf",
        "turn this into pdf",
        "turn this into a pdf",
        "export this as pdf",
        "export this as a pdf",
        "export this to pdf",
        "export this to a pdf",
        "export this into pdf",
        "export this into a pdf",
        "save this as pdf",
        "save this as a pdf",
        "convert this to word",
        "convert this into word",
        "convert this to a word document",
        "convert this into a word document",
        "turn this into word",
        "turn this into a word document",
        "export this as word",
        "export this as a word document",
        "save this as word",
        "save this as a word document",
        "convert this to a document",
        "convert this into a document",
        "turn this into a document",
        "export this as a document",
        "save this as a document",
    )
    if any(phrase in value for phrase in response_references + direct_followups):
        return True
    # v69019: tolerate natural follow-up wording without reopening broad document routing.
    # The request still has to reference the current result (this/it/response/answer) and
    # a supported export format, so ordinary questions containing “pdf” are unaffected.
    return bool(re.search(
        r"\b(?:export|save|convert|turn|download|make)\b.{0,28}"
        r"\b(?:this|it|response|answer)\b.{0,28}"
        r"\b(?:to|into|as|a|an)?\s*(?:pdf|word|docx|document)\b",
        value,
    ))


def _previous_assistant_document_text(messages):
    """Return the latest visible assistant response before the export command."""
    for message in reversed(list(messages or [])):
        if not isinstance(message, dict):
            continue
        if str(message.get("role") or "").strip().lower() != "assistant":
            continue
        content = str(message.get("content") or "")
        content, _ = extract_documents_from_message_content(content)
        content, _ = extract_images_from_message_content(content)
        content = clean_visible_chat_text(content).strip()
        if content and content.lower() != "your document is ready.":
            return content
    return ""


def _previous_assistant_document_payload_v69018(messages):
    """Return the latest assistant text plus the exact images shown with it.

    Document export must use the already-published assistant result as its source
    of truth.  It must never ask the AI to regenerate a second "PDF-ready" answer.
    """
    for message in reversed(list(messages or [])):
        if not isinstance(message, dict):
            continue
        if str(message.get("role") or "").strip().lower() != "assistant":
            continue
        content = str(message.get("content") or "")
        content, _ = extract_documents_from_message_content(content)
        visible, images = extract_images_from_message_content(content)
        visible = clean_visible_chat_text(visible).strip()
        if visible and visible.lower() != "your document is ready.":
            return visible, list(images or [])
    return "", []


def _conversation_document_images_v69018(messages):
    """Collect unique assistant images already published in the requested chat."""
    output = []
    seen = set()
    for message in list(messages or []):
        if not isinstance(message, dict):
            continue
        if str(message.get("role") or "").strip().lower() != "assistant":
            continue
        content = str(message.get("content") or "")
        content, _ = extract_documents_from_message_content(content)
        _, images = extract_images_from_message_content(content)
        for image in list(images or []):
            if not isinstance(image, dict):
                continue
            data_url = str(image.get("data_url") or "").strip()
            if not data_url or data_url in seen:
                continue
            seen.add(data_url)
            output.append(dict(image))
    return output


