def _graphic_uploaded_file_bytes(uploaded_file):
    """Read an uploaded file without permanently changing its stream position."""
    if uploaded_file is None:
        return b""
    try:
        position = uploaded_file.tell()
    except Exception:
        position = None
    try:
        if hasattr(uploaded_file, "seek"):
            uploaded_file.seek(0)
        data = uploaded_file.read() if hasattr(uploaded_file, "read") else bytes(uploaded_file)
        return bytes(data or b"")
    except Exception:
        return b""
    finally:
        if position is not None:
            try:
                uploaded_file.seek(position)
            except Exception:
                pass


def _graphic_product_fingerprint(role_items):
    product = next((x for x in (role_items or []) if x.get("role") == "product_photo"), None)
    raw = _graphic_uploaded_file_bytes((product or {}).get("file"))
    return hashlib.sha256(raw).hexdigest() if raw else ""


def research_graphic_vehicle_profile(role_items, prompt_text=""):
    """Identify and web-verify the compatible vehicle for the uploaded unit.

    Results are cached in session state by source-image fingerprint. The function
    fails open: low-confidence or unavailable research never blocks generation.
    """
    product = next((x for x in (role_items or []) if x.get("role") == "product_photo"), None)
    if not product:
        return {}
    fingerprint = _graphic_product_fingerprint(role_items)
    cache = st.session_state.setdefault("graphic_vehicle_research_cache_v1000", {})
    cached = cache.get(fingerprint) if fingerprint else None
    if isinstance(cached, dict) and cached.get("profile"):
        return dict(cached["profile"])
    image_url = _graphic_role_data_url(product)
    if not image_url:
        return {}
    content = [
        {"type": "input_text", "text": (
            "Identify the vehicle compatibility of this AutoTecPro dashboard unit/fascia. "
            "Inspect the screen aspect ratio, fascia outline, vents, knobs, buttons, trim, mounting geometry, "
            "and any filename/model clues. Search the live web to verify the most likely make, model, generation, "
            "and year range using reputable automotive/OEM/parts sources. Return one JSON object only with keys: "
            "make, model, generation, year_range, vehicle_type, confidence_score, visual_evidence, web_evidence, "
            "alternative_matches, safe_exterior_description, safe_interior_description, generation_restrictions, "
            "search_summary. Do not invent certainty. Below 75 confidence, keep descriptions generic and list alternatives. "
            "Staff request: " + str(prompt_text or "")[:2500]
        )},
        {"type": "input_image", "image_url": image_url},
    ]
    try:
        response = client.responses.create(
            model="gpt-5.5",
            tools=[{"type": "web_search"}],
            instructions=(
                "Act as a cautious automotive fitment researcher. Use live web search to verify visual hypotheses. "
                "Prefer OEM, manufacturer, established parts catalog, and reputable automotive sources. Return JSON only."
            ),
            input=[{"role": "user", "content": content}],
            max_output_tokens=1800,
        )
        profile = extract_json_object(str(getattr(response, "output_text", "") or ""))
        if not isinstance(profile, dict):
            profile = {}
    except Exception as error:
        diagnostic_log("graphic_vehicle_research_failed", error_type=type(error).__name__, error=str(error))
        profile = {}
    if profile:
        profile["research_version"] = GRAPHIC_VEHICLE_RESEARCH_VERSION
        profile["source_filename"] = str(product.get("name") or "")
        if fingerprint:
            cache[fingerprint] = {"profile": dict(profile), "cached_at": now_iso()}
    return profile


def _graphic_vehicle_profile_text(profile):
    if not isinstance(profile, dict) or not profile:
        return ""
    keys = (
        "make", "model", "generation", "year_range", "vehicle_type", "confidence_score",
        "visual_evidence", "web_evidence", "alternative_matches", "safe_exterior_description",
        "safe_interior_description", "generation_restrictions", "search_summary",
    )
    return "\n".join(f"{key.replace('_', ' ').title()}: {profile.get(key)}" for key in keys if profile.get(key) not in (None, "", [], {}))


GRAPHIC_V56000_CACHE_EPOCH = "v63000-final-bezel-authority-2026-07-27-1"


def _graphic_apply_v56000_cache_epoch():
    """Invalidate geometry-sensitive Graphic Marketing caches once per engine epoch.

    The invalidation is intentionally narrow: conversation content and uploaded files
    remain untouched, while masks, background plates, source fingerprints and product
    analysis produced by older engines are discarded.
    """
    try:
        state = get_graphic_project_state()
        if state.get("graphic_cache_epoch") == GRAPHIC_V56000_CACHE_EPOCH:
            return state
        for key in (
            "background_plate_cache", "product_dna_cache", "product_analysis_cache",
            "product_cutout_cache", "product_mask_cache", "product_bezel_master_reports",
            "engineering_dna_cache_v21000", "engineering_approval_v21000",
            "reference_analysis_cache", "vehicle_analysis_cache", "dashboard_analysis_cache",
            "last_campaign_product_sha", "last_reference_product_composite",
            "last_product_cutout_report_v53000", "last_product_cutout_report_v54000",
            "last_product_cutout_report_v55000", "last_product_cutout_report_v56000",
        ):
            state.pop(key, None)
        state["graphic_cache_epoch"] = GRAPHIC_V56000_CACHE_EPOCH
        state["graphic_engine_version"] = GRAPHIC_ENGINE_VERSION
        state["graphic_adaptive_engine_version"] = GRAPHIC_ADAPTIVE_ENGINE_VERSION
        st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
        diagnostic_log("graphic_v59000_cache_epoch_applied", epoch=GRAPHIC_V56000_CACHE_EPOCH)
        return state
    except Exception as error:
        diagnostic_log("graphic_v59000_cache_epoch_failed", error_type=type(error).__name__, error=str(error))
        return {}


def _graphic_connected_components_numpy_v68974(mask):
    """Dependency-free 8-connected component count for small binary product masks."""
    try:
        import numpy as np
        arr = np.asarray(mask, dtype=np.uint8)
        if arr.size == 0:
            return 0
        h, w = arr.shape
        seen = np.zeros((h, w), dtype=np.uint8)
        count = 0
        for yy in range(h):
            for xx in range(w):
                if not arr[yy, xx] or seen[yy, xx]:
                    continue
                count += 1
                stack = [(yy, xx)]
                seen[yy, xx] = 1
                while stack:
                    cy, cx = stack.pop()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            ny, nx = cy + dy, cx + dx
                            if 0 <= ny < h and 0 <= nx < w and arr[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = 1
                                stack.append((ny, nx))
        return int(count)
    except Exception:
        return -1


def _graphic_alpha_geometry_signature_v55000(layer):
    """Return deterministic whole-product and lower-housing alpha geometry metrics.

    v68974 removes OpenCV as a single point of failure. OpenCV remains the preferred
    contour engine when installed, while NumPy/Pillow-compatible metrics provide the
    same release-critical alpha/lower-housing authority when cv2 is unavailable.
    """
    if Image is None or layer is None:
        return {"available": False}
    try:
        import numpy as np
        rgba = layer.convert("RGBA")
        alpha = np.asarray(rgba.getchannel("A"), dtype=np.uint8)
        mask = (alpha >= 8).astype(np.uint8)
        ys, xs = np.where(mask > 0)
        if not len(xs):
            return {"available": False}
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = mask[y0:y1, x0:x1]
        h, w = crop.shape
        lower_start = max(0, int(round(h * 0.70)))
        lower = crop[lower_start:, :]
        lower_widths = [int(row.sum()) for row in lower]
        lower_components = _graphic_connected_components_numpy_v68974(lower)
        perimeter = 0.0
        engine = "product-alpha-geometry-v68974-numpy"
        try:
            import cv2
            contours, _ = cv2.findContours(crop, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
            contour = max(contours, key=cv2.contourArea) if contours else None
            perimeter = round(float(cv2.arcLength(contour, True)), 4) if contour is not None else 0.0
            lower_components = int(cv2.connectedComponents(lower, connectivity=8)[0] - 1) if lower.size else 0
            engine = "product-alpha-geometry-v68974-opencv"
        except Exception as cv_error:
            diagnostic_log("graphic_v68974_opencv_geometry_fallback", error_type=type(cv_error).__name__, error=str(cv_error))
        payload = crop.tobytes() + b"|" + lower.tobytes()
        return {
            "available": True, "bbox": [x0, y0, x1, y1], "visible_size": [w, h],
            "aspect_ratio": round(w / max(1, h), 10),
            "alpha_sha256": hashlib.sha256(payload).hexdigest(),
            "area": int(crop.sum()), "perimeter": perimeter,
            "lower_start_ratio": 0.70, "lower_area": int(lower.sum()),
            "lower_row_widths": lower_widths, "lower_components": lower_components,
            "engine": engine,
        }
    except Exception as error:
        diagnostic_log("graphic_v55000_geometry_signature_failed", error_type=type(error).__name__, error=str(error))
        return {"available": False, "reason": str(error)[:300]}

def _graphic_lower_housing_fidelity_v55000(source, candidate):
    """Fail closed when the bezel, lower lip, tabs, openings or lower contour drift."""
    before = _graphic_alpha_geometry_signature_v55000(source)
    after = _graphic_alpha_geometry_signature_v55000(candidate)
    if not before.get("available") or not after.get("available"):
        return {"available": False, "passed": False, "reason": "lower-housing geometry unavailable", "engine": "lower-housing-fidelity-v55000"}
    bw = list(before.get("lower_row_widths") or [])
    aw = list(after.get("lower_row_widths") or [])
    if len(bw) != len(aw):
        width_error = 1.0
    else:
        denom = max(1.0, float(max(bw or [1])))
        width_error = max((abs(a-b) / denom for a,b in zip(aw,bw)), default=0.0)
    area_error = abs(float(after.get("lower_area",0))-float(before.get("lower_area",0))) / max(1.0,float(before.get("lower_area",1)))
    aspect_error = abs(float(after.get("aspect_ratio",0))-float(before.get("aspect_ratio",0))) / max(0.001,float(before.get("aspect_ratio",1)))
    exact_alpha = before.get("alpha_sha256") == after.get("alpha_sha256")
    passed = bool(exact_alpha and width_error <= 0.002 and area_error <= 0.002 and aspect_error <= 0.0005 and before.get("lower_components") == after.get("lower_components"))
    return {
        "available": True, "passed": passed, "exact_alpha": exact_alpha,
        "max_lower_row_width_error": round(width_error,8),
        "lower_area_relative_error": round(area_error,8),
        "aspect_ratio_relative_error": round(aspect_error,8),
        "source_lower_components": before.get("lower_components"),
        "candidate_lower_components": after.get("lower_components"),
        "source": before, "candidate": after, "engine": "lower-housing-fidelity-v55000",
    }


def _graphic_clear_reserved_product_zone_pillow_v68974(canvas, product, x, y):
    """Deterministic emergency fallback when OpenCV is unavailable.

    The normal production path remains OpenCV inpainting. This fallback never touches
    the uploaded product layer; it only neutralizes the reserved background zone before
    the exact source product is composited, preventing a missing optional dependency
    from turning a valid Reference Mode job into an EmptyGraphicResult.
    """
    if Image is None or canvas is None or product is None:
        return canvas, {"applied": False, "reason": "image unavailable", "engine": "protected-product-zone-v68974-pillow"}
    try:
        from PIL import ImageFilter, ImageDraw
        base = canvas.convert("RGBA")
        side_margin = max(28, int(round(product.width * 0.24)))
        top_margin = max(16, int(round(product.height * 0.08)))
        bottom_apron = max(36, int(round(product.height * 0.26)))
        rx0 = max(0, int(x) - side_margin)
        ry0 = max(0, int(y) - top_margin)
        rx1 = min(base.width, int(x) + product.width + side_margin)
        ry1 = min(base.height, int(y) + product.height + bottom_apron)
        if rx1 <= rx0 or ry1 <= ry0:
            return canvas, {"applied": False, "reason": "reserved region outside canvas", "engine": "protected-product-zone-v68974-pillow"}

        # Use a large-radius local background diffusion, then composite only the
        # reserved rectangle. The exact uploaded product is overlaid afterward.
        blur_radius = max(18, min(80, int(round(max(product.size) * 0.06))))
        diffused = base.filter(ImageFilter.GaussianBlur(radius=blur_radius))
        mask = Image.new("L", base.size, 0)
        draw = ImageDraw.Draw(mask)
        draw.rectangle((rx0, ry0, rx1 - 1, ry1 - 1), fill=255)
        out = Image.composite(diffused, base, mask)
        return out, {
            "applied": True,
            "engine": "protected-product-zone-v68974-pillow-fallback",
            "reserved_rect": [rx0, ry0, rx1, ry1],
            "side_margin_px": side_margin,
            "top_margin_px": top_margin,
            "bottom_apron_px": bottom_apron,
            "blur_radius_px": blur_radius,
            "product_region_provider_pixels_removed": True,
            "bottom_bezel_provider_exclusion": True,
            "provider_mounting_rail_exclusion": True,
            "fallback": True,
            "fail_closed": False,
        }
    except Exception as error:
        diagnostic_log("graphic_v68974_pillow_reserved_zone_failed", error_type=type(error).__name__, error=str(error))
        return canvas, {"applied": False, "reason": str(error)[:300], "engine": "protected-product-zone-v68974-pillow", "fail_closed": True}


def _graphic_clear_reserved_product_zone_v55000(canvas, product, x, y):
    """Remove every provider-created product remnant before exact local compositing.

    v57000 treats the full product bounding rectangle as reserved, not only the alpha
    silhouette. This is essential for products photographed on a neutral studio card:
    provider-generated rails, brackets, tabs and false lower bezels can otherwise sit
    just outside the real alpha edge and remain visible after the source product is
    composited. The reserved zone therefore includes:

      * the complete product rectangle;
      * a small top/side safety margin;
      * a much larger asymmetric bottom apron covering lower-housing hallucinations;
      * the dilated exact alpha silhouette as an additional geometry-aware mask.

    The function fails closed when the requested region cannot be fully covered.
    """
    if Image is None or canvas is None or product is None:
        return canvas, {"applied": False, "reason": "image unavailable", "engine": "protected-product-zone-v62000"}
    try:
        import cv2
        import numpy as np

        base = canvas.convert("RGBA")
        rgba = np.asarray(base, dtype=np.uint8)
        product_rgba = product.convert("RGBA")
        alpha = np.asarray(product_rgba.getchannel("A"), dtype=np.uint8)
        if alpha.size == 0 or int((alpha >= 8).sum()) == 0:
            return canvas, {"applied": False, "reason": "empty authoritative product alpha", "engine": "protected-product-zone-v62000"}

        # Asymmetric authority margins. The lower apron is intentionally large because
        # the observed Toyota failure was a provider-generated mounting frame extending
        # below the true product. Side/top margins remain conservative to protect layout.
        side_margin = max(28, int(round(product.width * 0.24)))
        top_margin = max(16, int(round(product.height * 0.08)))
        bottom_apron = max(36, int(round(product.height * 0.26)))
        alpha_halo = max(16, int(round(max(product.size) * 0.05)))

        mask = np.zeros((base.height, base.width), dtype=np.uint8)

        # 1) Full rectangular reserved region plus asymmetric bottom apron.
        rx0 = max(0, int(x) - side_margin)
        ry0 = max(0, int(y) - top_margin)
        rx1 = min(base.width, int(x) + product.width + side_margin)
        ry1 = min(base.height, int(y) + product.height + bottom_apron)
        if rx1 <= rx0 or ry1 <= ry0:
            return canvas, {"applied": False, "reason": "reserved region outside canvas", "engine": "protected-product-zone-v62000"}
        mask[ry0:ry1, rx0:rx1] = 255

        # 2) Geometry-aware alpha dilation catches unusual side ears and protrusions.
        local = (alpha >= 8).astype(np.uint8) * 255
        kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (alpha_halo * 2 + 1, alpha_halo * 2 + 1))
        local = cv2.dilate(local, kernel, iterations=1)
        lx0, ly0 = max(0, int(x) - alpha_halo), max(0, int(y) - alpha_halo)
        lx1 = min(base.width, int(x) + product.width + alpha_halo)
        ly1 = min(base.height, int(y) + product.height + alpha_halo)
        padded = cv2.copyMakeBorder(local, alpha_halo, alpha_halo, alpha_halo, alpha_halo, cv2.BORDER_CONSTANT, value=0)
        sx0, sy0 = lx0 - (int(x) - alpha_halo), ly0 - (int(y) - alpha_halo)
        sx1, sy1 = sx0 + (lx1 - lx0), sy0 + (ly1 - ly0)
        mask[ly0:ly1, lx0:lx1] = np.maximum(mask[ly0:ly1, lx0:lx1], padded[sy0:sy1, sx0:sx1])

        requested_pixels = int((mask > 0).sum())
        if requested_pixels <= 0:
            return canvas, {"applied": False, "reason": "empty protected mask", "engine": "protected-product-zone-v62000"}

        rgb = cv2.cvtColor(rgba[:, :, :3], cv2.COLOR_RGB2BGR)
        radius = max(5, min(19, int(round(max(product.size) * 0.012))))
        cleaned = cv2.inpaint(rgb, mask, radius, cv2.INPAINT_TELEA)
        if cleaned is None or cleaned.shape[:2] != rgb.shape[:2]:
            return canvas, {"applied": False, "reason": "inpainting returned invalid canvas", "engine": "protected-product-zone-v62000"}

        # Coverage is deterministic because the exact mask is known. Fail closed if any
        # requested pixel was lost through clipping or conversion.
        covered_pixels = int((mask[ry0:ry1, rx0:rx1] > 0).sum())
        expected_rect_pixels = int((ry1 - ry0) * (rx1 - rx0))
        coverage_ratio = covered_pixels / max(1, expected_rect_pixels)
        if coverage_ratio < 0.999:
            return canvas, {
                "applied": False,
                "reason": "protected rectangle coverage incomplete",
                "coverage_ratio": round(coverage_ratio, 6),
                "engine": "protected-product-zone-v62000",
            }

        out = np.dstack([cv2.cvtColor(cleaned, cv2.COLOR_BGR2RGB), rgba[:, :, 3]])
        return Image.fromarray(out.astype(np.uint8), "RGBA"), {
            "applied": True,
            "engine": "protected-product-zone-v62000",
            "mask_pixels": requested_pixels,
            "coverage_ratio": round(coverage_ratio, 6),
            "reserved_rect": [rx0, ry0, rx1, ry1],
            "side_margin_px": side_margin,
            "top_margin_px": top_margin,
            "bottom_apron_px": bottom_apron,
            "alpha_halo_px": alpha_halo,
            "inpaint_radius_px": radius,
            "product_region_provider_pixels_removed": True,
            "bottom_bezel_provider_exclusion": True,
            "provider_mounting_rail_exclusion": True,
            "fail_closed": True,
        }
    except Exception as error:
        diagnostic_log("graphic_v62000_reserved_zone_clear_failed", error_type=type(error).__name__, error=str(error))
        fallback_canvas, fallback_report = _graphic_clear_reserved_product_zone_pillow_v68974(canvas, product, x, y)
        if isinstance(fallback_report, dict) and fallback_report.get("applied"):
            fallback_report["opencv_error"] = f"{type(error).__name__}: {str(error)[:220]}"
            return fallback_canvas, fallback_report
        return canvas, {"applied": False, "reason": str(error)[:300], "engine": "protected-product-zone-v62000", "fail_closed": True}


# v64000 LTS — Conservative Universal Product Geometry Authority
# Reference Style Mode uses the proven v47000 border-connected background-removal
# philosophy. It intentionally forbids geometric-cliff/baseline cutting, dominant-
# component authority, silhouette filling, and selective mechanical-tail recovery.

# ============================================================
# v66100 LTS — Quality-Preserving Performance and Environmental Integration
# ============================================================
def _graphic_v66000_flood_connected_background(candidate):
    """Return only candidate background connected to the outside canvas."""
    import numpy as np
    from PIL import ImageDraw
    height, width = candidate.shape
    padded = Image.new("L", (width + 2, height + 2), 255)
    padded.paste(Image.fromarray((candidate.astype(np.uint8) * 255), mode="L"), (1, 1))
    ImageDraw.floodfill(padded, (0, 0), 128, thresh=0)
    return np.asarray(padded, dtype=np.uint8)[1:-1, 1:-1] == 128


def _graphic_v66000_source_geometry_evidence(rgb, bg):
    """Build a conservative source-side structural evidence map.

    This map is not used as a cutout. It exists only to veto masks that remove
    source-supported bezels, lower housings, brackets, tabs or mounting ears.
    """
    import numpy as np
    from PIL import ImageFilter
    rgbf = rgb.astype(np.float32)
    brightness = rgbf.mean(axis=2)
    chroma = rgbf.max(axis=2) - rgbf.min(axis=2)
    distance = np.sqrt(((rgbf - bg.reshape(1, 1, 3)) ** 2).sum(axis=2))
    # Evidence deliberately includes weak neutral structure. A small edge expansion
    # makes thin mounting ears and antialiased bezel boundaries first-class geometry.
    evidence = (brightness <= 228) | (chroma >= 24) | (distance >= 24)
    ev_img = Image.fromarray((evidence.astype(np.uint8) * 255), mode="L")
    evidence = np.asarray(ev_img.filter(ImageFilter.MaxFilter(3)), dtype=np.uint8) > 0
    return evidence, brightness, chroma, distance


def _graphic_v66000_geometry_report(source_evidence, alpha, candidate_name=""):
    """Validate source-to-cutout geometry and return a fail-closed scorecard."""
    import numpy as np
    height, width = source_evidence.shape
    kept = alpha >= 16
    opaque = alpha >= 220
    total = max(1, width * height)
    src_count = int(source_evidence.sum())
    retained = int((source_evidence & kept).sum())
    retention = retained / max(1, src_count)
    transparent_ratio = float((alpha == 0).sum()) / total
    foreground_ratio = float(kept.sum()) / total

    ys, xs = np.where(source_evidence)
    kys, kxs = np.where(source_evidence & kept)
    failures=[]
    metrics={
        "candidate": candidate_name,
        "source_evidence_pixels": src_count,
        "source_evidence_retention": round(retention, 6),
        "foreground_ratio": round(foreground_ratio, 6),
        "transparent_ratio": round(transparent_ratio, 6),
    }
    if src_count < max(24, int(total * 0.01)):
        failures.append("insufficient_source_geometry_evidence")
    if foreground_ratio < 0.08 or transparent_ratio < 0.05 or transparent_ratio > 0.94:
        failures.append("global_area_guard")
    if retention < 0.985:
        failures.append("source_geometry_retention")

    if len(xs) and len(kxs):
        src_box=(int(xs.min()),int(ys.min()),int(xs.max())+1,int(ys.max())+1)
        kept_box=(int(kxs.min()),int(kys.min()),int(kxs.max())+1,int(kys.max())+1)
        metrics["source_evidence_bbox"]=list(src_box)
        metrics["retained_evidence_bbox"]=list(kept_box)
        sw=max(1,src_box[2]-src_box[0]); sh=max(1,src_box[3]-src_box[1])
        extent_losses={
            "left": max(0, kept_box[0]-src_box[0])/sw,
            "right": max(0, src_box[2]-kept_box[2])/sw,
            "top": max(0, kept_box[1]-src_box[1])/sh,
            "bottom": max(0, src_box[3]-kept_box[3])/sh,
        }
        metrics["extent_losses"]={k:round(v,6) for k,v in extent_losses.items()}
        if extent_losses["left"] > 0.018: failures.append("left_extent_loss")
        if extent_losses["right"] > 0.018: failures.append("right_extent_loss")
        if extent_losses["bottom"] > 0.012: failures.append("lower_housing_extent_loss")
        if extent_losses["top"] > 0.025: failures.append("top_mount_extent_loss")

        # Region gates are relative to the source-supported product envelope.
        x0,y0,x1,y1=src_box
        regions={
            "left_bezel": (x0,y0,x0+max(1,int(sw*.18)),y1),
            "right_bezel": (x1-max(1,int(sw*.18)),y0,x1,y1),
            "lower_housing": (x0,y1-max(1,int(sh*.28)),x1,y1),
            "bottom_left_mount": (x0,y1-max(1,int(sh*.34)),x0+max(1,int(sw*.34)),y1),
            "bottom_right_mount": (x1-max(1,int(sw*.34)),y1-max(1,int(sh*.34)),x1,y1),
            "upper_left_ear": (x0,y0,x0+max(1,int(sw*.28)),y0+max(1,int(sh*.30))),
            "upper_right_ear": (x1-max(1,int(sw*.28)),y0,x1,y0+max(1,int(sh*.30))),
        }
        region_scores={}
        for name,(rx0,ry0,rx1,ry1) in regions.items():
            src=source_evidence[ry0:ry1,rx0:rx1]
            denominator=int(src.sum())
            if denominator < max(6,int(src.size*.008)):
                region_scores[name]=None
                continue
            score=float((src & kept[ry0:ry1,rx0:rx1]).sum())/denominator
            region_scores[name]=round(score,6)
            limit=0.975 if name in {"lower_housing","bottom_left_mount","bottom_right_mount"} else 0.965
            if score < limit:
                failures.append(f"{name}_retention")
        metrics["regional_retention"]=region_scores
    else:
        failures.append("empty_retained_geometry")

    # Confidence rewards verified source retention, useful background removal, and
    # opaque support. Any hard failure makes the candidate ineligible regardless.
    opaque_support=float((source_evidence & opaque).sum())/max(1,src_count)
    removal_quality=max(0.0,1.0-abs(transparent_ratio-0.45)/0.55)
    confidence=max(0.0,min(1.0,0.72*retention+0.18*opaque_support+0.10*removal_quality))
    metrics["opaque_source_support"]=round(opaque_support,6)
    metrics["confidence"]=round(confidence,6)
    metrics["failures"]=list(dict.fromkeys(failures))
    metrics["passed"]=not failures and confidence >= 0.94
    return metrics


def _graphic_v66000_build_candidate(rgb, bg, protected, profile):
    """Create one conservative border-connected matte candidate."""
    import numpy as np
    from PIL import ImageFilter
    rgbf=rgb.astype(np.float32)
    brightness=rgbf.mean(axis=2)
    chroma=rgbf.max(axis=2)-rgbf.min(axis=2)
    distance=np.sqrt(((rgbf-bg.reshape(1,1,3))**2).sum(axis=2))
    candidate=(brightness>=profile["brightness"]) & (chroma<=profile["chroma"]) & (distance<=profile["distance"])
    candidate &= ~protected
    background=_graphic_v66000_flood_connected_background(candidate)
    alpha=np.full(background.shape,255,dtype=np.uint8)
    alpha[background]=0
    bg_img=Image.fromarray((background.astype(np.uint8)*255),mode="L")
    adjacent=(np.asarray(bg_img.filter(ImageFilter.MaxFilter(3)),dtype=np.uint8)>0)&~background
    neutral_edge=adjacent & ~protected & (chroma<=profile["edge_chroma"]) & (brightness>=profile["edge_brightness"])
    strength=np.clip((distance-8.0)/max(1.0,profile["distance"]),0.0,1.0)
    edge_alpha=(72+strength*183).astype(np.uint8)
    alpha[neutral_edge]=np.minimum(alpha[neutral_edge],edge_alpha[neutral_edge])
    return alpha


def _graphic_v66000_select_exact_geometry_alpha(raw_bytes):
    """Select the highest-confidence eligible mask; otherwise fail closed."""
    import numpy as np
    from PIL import ImageFilter
    source=ImageOps.exif_transpose(Image.open(io.BytesIO(raw_bytes))).convert("RGBA")
    rgb=np.asarray(source.convert("RGB"),dtype=np.int16)
    height,width=rgb.shape[:2]
    if width<3 or height<3:
        return None,{"passed":False,"fallback":"untouched_master_card","reason":"image_too_small"}
    band=max(2,min(width,height)//80)
    border=np.concatenate([rgb[:band].reshape(-1,3),rgb[-band:].reshape(-1,3),rgb[:,:band].reshape(-1,3),rgb[:,-band:].reshape(-1,3)],axis=0)
    bbright=border.mean(axis=1); bchroma=border.max(axis=1)-border.min(axis=1)
    neutral=border[(bbright>=190)&(bchroma<=46)]
    samples=neutral if len(neutral)>=32 else border
    bg=np.median(samples,axis=0).astype(np.float32)
    evidence,brightness,chroma,distance=_graphic_v66000_source_geometry_evidence(rgb,bg)
    hard=(brightness<=202)|(chroma>=50)|(distance>=78)
    protected=np.asarray(Image.fromarray((hard.astype(np.uint8)*255),mode="L").filter(ImageFilter.MaxFilter(3)),dtype=np.uint8)>0
    profiles=[
        ("precision",{"brightness":198,"chroma":30,"distance":26,"edge_chroma":28,"edge_brightness":218}),
        ("conservative",{"brightness":208,"chroma":38,"distance":34,"edge_chroma":34,"edge_brightness":212}),
        ("balanced",{"brightness":220,"chroma":46,"distance":44,"edge_chroma":38,"edge_brightness":205}),
        ("v47000_compatible",{"brightness":186,"chroma":52,"distance":58,"edge_chroma":38,"edge_brightness":205}),
    ]
    reports=[]; eligible=[]
    for name,profile in profiles:
        alpha=_graphic_v66000_build_candidate(rgb,bg,protected,profile)
        report=_graphic_v66000_geometry_report(evidence,alpha,name)
        reports.append(report)
        if report.get("passed"):
            eligible.append((float(report["confidence"]),float(report["transparent_ratio"]),name,alpha,report))
    if not eligible:
        return None,{"passed":False,"fallback":"untouched_master_card","reason":"no_geometry_proven_candidate","candidates":reports,"fail_closed":True}
    # Highest confidence first; transparency is only a secondary preference.
    eligible.sort(key=lambda item:(item[0],item[1]),reverse=True)
    confidence,_,name,alpha,report=eligible[0]
    return alpha,{"passed":True,"selected":name,"confidence":confidence,"selected_report":report,"candidates":reports,"fail_closed":True}



def _graphic_extract_product_cutout(uploaded_file):
    """v66000 public extraction path backed by the single geometry authority."""
    layer,transparent=_graphic_open_product_layer_v3300(uploaded_file)
    if layer is None:
        return None
    if not transparent:
        return layer
    alpha=layer.getchannel("A")
    bbox=alpha.point(lambda a:255 if a>=8 else 0).getbbox()
    if not bbox:
        return layer
    pad=max(2,min(layer.size)//220)
    bbox=(max(0,bbox[0]-pad),max(0,bbox[1]-pad),min(layer.width,bbox[2]+pad),min(layer.height,bbox[3]+pad))
    return layer.crop(bbox)


def _graphic_font(size, bold=False):
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
    ]
    if Image is not None:
        try:
            from PIL import ImageFont
            for path in candidates:
                if Path(path).exists():
                    return ImageFont.truetype(path, max(10, int(size)))
            return ImageFont.load_default()
        except Exception:
            return None
    return None


def _graphic_extract_copy(prompt_text, reference_blueprint=None):
    text = str(prompt_text or "")
    def field(label):
        match = re.search(rf"(?im)^\s*-?\s*{re.escape(label)}\s*:\s*(.+)$", text)
        value = re.sub(r"\s+", " ", match.group(1)).strip() if match else ""
        return "" if value.lower().startswith(("no ", "not supplied", "none")) else value[:120]
    headline = field("Headline")
    cta = field("Call to action")
    product = field("Product / model")
    if not headline:
        quoted = re.search(r'["“]([^"”]{4,70})["”]', text)
        headline = quoted.group(1).strip() if quoted else "UPGRADE YOUR DRIVE"
    if not cta:
        cta = "SHOP AUTOTECPRO"
    features = []
    blueprint = reference_blueprint or {}
    raw_features = blueprint.get("feature_copy_structure")
    if isinstance(raw_features, list):
        features = [re.sub(r"\s+", " ", str(x)).strip()[:44] for x in raw_features if str(x).strip()][:4]
    elif isinstance(raw_features, str):
        features = [x.strip()[:44] for x in re.split(r"[;|•\n]+", raw_features) if x.strip()][:4]
    if not features:
        features = ["OEM-STYLE FITMENT", "PREMIUM DISPLAY", "SMART CONNECTIVITY", "BUILT FOR YOUR VEHICLE"]
    return {"headline": headline.upper(), "cta": cta.upper(), "product": product, "features": features}


def _graphic_layout_plan(reference_blueprint, prompt_text=""):
    """Normalize free-form reference analysis into deterministic safe zones."""
    bp=reference_blueprint if isinstance(reference_blueprint,dict) else {}
    blob=" ".join(str(bp.get(k) or "") for k in ("layout_archetype","canvas_zones","blueprint","product_placement","typography"))
    blob=(blob+" "+str(prompt_text or "")).lower()
    product_side="left" if any(x in blob for x in ("product left","left-side product","product on left")) else "right"
    copy_side="right" if product_side=="left" else "left"
    if any(x in blob for x in ("copy right","headline right","text right")): copy_side="right"; product_side="left"
    if any(x in blob for x in ("copy left","headline left","text left")): copy_side="left"; product_side="right"
    return {"product_side":product_side,"copy_side":copy_side,"bottom_bar":True,"product_ratio":0.50}


def _graphic_reference_palette(role_items):
    """Extract a stable accent/dark palette from current style references."""
    if Image is None: return {"accent":(236,52,45),"panel":(6,9,14),"text":(255,255,255)}
    colors=[]
    for item in role_items or []:
        if item.get("role")!="style_reference": continue
        raw=_graphic_uploaded_file_bytes(item.get("file"))
        try:
            with Image.open(io.BytesIO(raw)) as im:
                q=ImageOps.exif_transpose(im).convert("RGB").resize((64,64)).quantize(colors=12).convert("RGB")
                colors.extend(q.getdata())
        except Exception: pass
    if not colors: return {"accent":(236,52,45),"panel":(6,9,14),"text":(255,255,255)}
    # Prefer saturated, moderately bright colors as accent.
    def score(c):
        hi,lo=max(c),min(c); sat=hi-lo; lum=sum(c)/3
        return sat*2-abs(lum-145)
    accent=max(colors,key=score)
    if max(accent)-min(accent)<45: accent=(236,52,45)
    return {"accent":tuple(accent),"panel":(6,9,14),"text":(255,255,255)}



def _graphic_reference_background_plate(role_items, output_size="1536x1024"):
    """Build a clean reference-derived commercial plate with no product imagery.

    v2000 intentionally does not blur or reuse the reference advertisement pixels,
    because even heavy blur can leave a recognisable device silhouette that competes
    with the user's product. The plate borrows only palette, contrast, composition,
    accent rhythm, and rugged automotive atmosphere from the reference.
    """
    if Image is None:
        return b""
    try:
        from PIL import ImageDraw, ImageFilter
        width, height = [int(part) for part in str(output_size).lower().split("x", 1)]
    except Exception:
        width, height = 1536, 1024

    palette = _graphic_reference_palette(role_items)
    accent = tuple(palette.get("accent") or (236, 52, 45))
    dark = tuple(palette.get("panel") or (6, 9, 14))

    canvas = Image.new("RGBA", (width, height), dark + (255,))

    # v2002: retain the reference's real color distribution, lighting direction,
    # broad scene geometry and atmosphere. The reference is resized, heavily
    # blurred and darkened so its advertised hardware and readable text cannot
    # survive, while its authentic visual style still guides the final layout.
    reference_item = next(
        (item for item in (role_items or []) if item.get("role") == "style_reference"),
        None,
    )
    reference_raw = _graphic_uploaded_file_bytes((reference_item or {}).get("file"))
    if reference_raw:
        try:
            with Image.open(io.BytesIO(reference_raw)) as reference_source:
                reference_layer = ImageOps.exif_transpose(reference_source).convert("RGB")
            reference_layer = ImageOps.fit(
                reference_layer, (width, height), method=Image.Resampling.LANCZOS
            ).filter(ImageFilter.GaussianBlur(radius=max(46, min(width, height) // 13)))
            reference_layer = reference_layer.convert("RGBA")
            reference_layer.putalpha(178)
            canvas = Image.alpha_composite(canvas, reference_layer)
            neutralizer = Image.new("RGBA", (width, height), dark + (112,))
            canvas = Image.alpha_composite(canvas, neutralizer)
        except Exception as error:
            diagnostic_log(
                "graphic_reference_plate_style_transfer_failed",
                error_type=type(error).__name__, error=error,
            )

    draw = ImageDraw.Draw(canvas, "RGBA")

    # Cinematic vertical gradient.
    for y in range(height):
        t = y / max(1, height - 1)
        r = int(dark[0] * (1 - t) + 3 * t)
        g = int(dark[1] * (1 - t) + 8 * t)
        b = int(dark[2] * (1 - t) + 18 * t)
        draw.line((0, y, width, y), fill=(r, g, b, 255))

    # Reference-inspired atmospheric glow, deliberately free of devices/screens.
    glow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
    gd = ImageDraw.Draw(glow, "RGBA")
    for i in range(26, 0, -1):
        alpha = int(6 + (26 - i) * 2.1)
        rx = int(width * (0.22 + i * 0.018))
        ry = int(height * (0.16 + i * 0.014))
        cx, cy = int(width * 0.72), int(height * 0.44)
        gd.ellipse((cx-rx, cy-ry, cx+rx, cy+ry), fill=accent + (min(alpha, 58),))
    glow = glow.filter(ImageFilter.GaussianBlur(radius=max(32, min(width, height)//20)))
    canvas = Image.alpha_composite(canvas, glow)
    draw = ImageDraw.Draw(canvas, "RGBA")

    # Abstract terrain / road bands: style cue only, never a copied object.
    horizon = int(height * 0.69)
    draw.polygon([
        (0, horizon), (int(width*.12), int(height*.58)), (int(width*.27), int(height*.66)),
        (int(width*.42), int(height*.53)), (int(width*.58), int(height*.65)),
        (int(width*.76), int(height*.49)), (width, int(height*.62)), (width, height), (0, height)
    ], fill=(6, 12, 22, 220))
    draw.polygon([
        (0, int(height*.79)), (int(width*.24), int(height*.72)),
        (int(width*.52), int(height*.83)), (int(width*.78), int(height*.70)),
        (width, int(height*.78)), (width, height), (0, height)
    ], fill=(2, 6, 12, 245))

    # Dynamic diagonal accent lines and a clean hero zone.
    for i in range(4):
        y1 = int(height * (.18 + i*.075))
        draw.line((int(width*.57), y1, int(width*.97), y1-int(height*.12)),
                  fill=accent + (48-i*7,), width=max(2, width//420))
    draw.rounded_rectangle((int(width*.51), int(height*.12), int(width*.95), int(height*.82)),
                           radius=max(30, width//45), outline=(255,255,255,22), width=max(2,width//700))

    # Dark copy zone and bottom information rail.
    copy_overlay = Image.new("RGBA", (width, height), (0,0,0,0))
    cod = ImageDraw.Draw(copy_overlay, "RGBA")
    for i in range(24):
        alpha = int(178 * (1 - i/24)**1.8)
        cod.rectangle((0, 0, int(width*(.42-i*.008)), height), fill=(0,0,0,alpha))
    cod.rectangle((0, int(height*.88), width, height), fill=(1,4,9,228))
    canvas = Image.alpha_composite(canvas, copy_overlay).convert("RGB")

    buffer = io.BytesIO()
    canvas.save(buffer, format="PNG", optimize=True)
    return buffer.getvalue()

def _graphic_result_raw_bytes(result_item):
    """Read an Image API result from base64 or a temporary result URL."""
    encoded = getattr(result_item, "b64_json", None) or (
        result_item.get("b64_json") if isinstance(result_item, dict) else None
    )
    if encoded:
        try:
            return base64.b64decode(encoded)
        except Exception:
            return b""
    url = getattr(result_item, "url", None) or (
        result_item.get("url") if isinstance(result_item, dict) else None
    )
    if url:
        try:
            response = http_session.get(str(url), timeout=45)
            response.raise_for_status()
            return bytes(response.content or b"")
        except Exception as error:
            diagnostic_log("graphic_result_url_download_failed", error_type=type(error).__name__, error=error)
    return b""



def _graphic_open_product_layer(uploaded_file):
    """Return a usable RGBA product layer even when automatic cutout fails.

    The exact uploaded pixels are preferred. When background removal cannot be
    performed safely, the original image is preserved inside a clean rounded
    presentation card rather than failing the entire generation.
    """
    if Image is None:
        return None, False
    cutout = _graphic_extract_product_cutout(uploaded_file)
    if cutout is not None:
        try:
            if cutout.mode != "RGBA":
                cutout = cutout.convert("RGBA")
            if cutout.width > 8 and cutout.height > 8:
                return cutout, True
        except Exception:
            pass
    raw = _graphic_uploaded_file_bytes(uploaded_file)
    if not raw:
        return None, False
    try:
        with Image.open(io.BytesIO(raw)) as source:
            image = ImageOps.exif_transpose(source).convert("RGBA")
        image.thumbnail((2800, 2800), Image.Resampling.LANCZOS)
        return image, False
    except Exception as error:
        diagnostic_log("graphic_product_layer_open_failed", error_type=type(error).__name__, error=error)
        return None, False


def _graphic_responses_image_result_bytes(response):
    """Extract final image bytes from Responses image-generation tool outputs."""
    collected = []
    seen = set()
    outputs = getattr(response, "output", None)
    if outputs is None and isinstance(response, dict):
        outputs = response.get("output")
    for item in outputs or []:
        item_type = getattr(item, "type", None)
        if item_type is None and isinstance(item, dict):
            item_type = item.get("type")
        if str(item_type or "") != "image_generation_call":
            continue
        candidates = []
        for field in ("result", "b64_json", "image_base64", "output"):
            value = getattr(item, field, None)
            if value is None and isinstance(item, dict):
                value = item.get(field)
            if value:
                candidates.append(value)
        for value in candidates:
            if isinstance(value, dict):
                value = value.get("b64_json") or value.get("result") or value.get("data")
            if not isinstance(value, str):
                continue
            try:
                raw = base64.b64decode(value)
            except Exception:
                continue
            if not raw:
                continue
            digest = hashlib.sha256(raw).hexdigest()
            if digest not in seen:
                seen.add(digest)
                collected.append(raw)
    return collected


def _graphic_collect_result_bytes(result):
    """Collect final image bytes across compatible OpenAI SDK response shapes."""
    if result is None:
        return []
    candidates = []
    data = getattr(result, "data", None)
    if data:
        try:
            candidates.extend(list(data))
        except Exception:
            pass
    # Some SDK surfaces expose the completed image directly.
    if getattr(result, "b64_json", None) or getattr(result, "url", None):
        candidates.append(result)
    if isinstance(result, dict):
        raw_data = result.get("data")
        if isinstance(raw_data, list):
            candidates.extend(raw_data)
        if result.get("b64_json") or result.get("url"):
            candidates.append(result)
    collected = []
    seen = set()
    for item in candidates:
        raw = _graphic_result_raw_bytes(item)
        if not raw:
            continue
        digest = hashlib.sha256(raw).hexdigest()
        if digest in seen:
            continue
        seen.add(digest)
        collected.append(raw)
    return collected


def _graphic_emergency_exact_product_composite(role_items, output_size, prompt_text, reference_blueprint=None):
    """Last-resort compositor that never calls the main layered studio.

    It preserves the uploaded product pixels and produces a valid PNG even if
    cutout, typography, review, logo, or the professional compositor fails.
    """
    if Image is None:
        return b"", {"emergency_composite": False}
    try:
        width, height = [int(part) for part in str(output_size).lower().split("x", 1)]
    except Exception:
        width, height = 1536, 1024
    product_item = next((item for item in (role_items or []) if item.get("role") == "product_photo"), None)
    raw = _graphic_uploaded_file_bytes((product_item or {}).get("file"))
    if not raw:
        return b"", {"emergency_composite": False}
    try:
        plate = _graphic_reference_background_plate(role_items, f"{width}x{height}")
        if plate:
            with Image.open(io.BytesIO(plate)) as bg:
                canvas = ImageOps.exif_transpose(bg).convert("RGBA")
        else:
            canvas = Image.new("RGBA", (width, height), (7, 12, 22, 255))
        with Image.open(io.BytesIO(raw)) as source:
            product = ImageOps.exif_transpose(source).convert("RGBA")
        product.thumbnail((int(width * 0.52), int(height * 0.68)), Image.Resampling.LANCZOS)
        pad = max(18, int(min(width, height) * 0.018))
        card = Image.new("RGBA", (product.width + pad * 2, product.height + pad * 2), (248, 250, 252, 246))
        mask = Image.new("L", card.size, 0)
        ImageDraw.Draw(mask).rounded_rectangle((0, 0, card.width - 1, card.height - 1), radius=max(18, pad), fill=255)
        card.putalpha(mask)
        card.alpha_composite(product, (pad, pad))
        x = max(20, width - card.width - int(width * 0.055))
        y = max(20, (height - card.height) // 2)
        shadow = Image.new("RGBA", card.size, (0, 0, 0, 0))
        shadow.putalpha(card.getchannel("A").filter(ImageFilter.GaussianBlur(radius=max(12, min(width, height)//55))).point(lambda a: int(a * .48)))
        canvas.alpha_composite(shadow, (x + 12, y + 16))
        canvas.alpha_composite(card, (x, y))
        buffer = io.BytesIO()
        canvas.convert("RGB").save(buffer, format="PNG", optimize=True)
        return buffer.getvalue(), {"emergency_composite": True, "product_composited": True}
    except Exception as error:
        diagnostic_log("graphic_emergency_composite_failed", error_type=type(error).__name__, error=error)
        return b"", {"emergency_composite": False}




def compose_graphic_layered_ad(background_bytes, product_file, prompt_text, reference_blueprint=None, vehicle_profile=None, role_items=None):
    """Compose an agency-style ad from protected product pixels and deterministic layers."""
    if Image is None: return bytes(background_bytes or b""), {}
    try:
        from PIL import ImageDraw, ImageFilter
        with Image.open(io.BytesIO(background_bytes)) as bg_source:
            canvas=ImageOps.exif_transpose(bg_source).convert("RGBA")
    except Exception:
        return bytes(background_bytes or b""), {}
    W,H=canvas.size
    geometry = _graphic_reference_geometry_v3300(reference_blueprint=reference_blueprint, prompt_text=prompt_text)
    product, transparent_cutout = _graphic_open_product_layer(product_file)
    if product is None:
        diagnostic_log("graphic_layered_composite_missing_product")
        return bytes(background_bytes or b""), {"product_composited": False}
    bp=reference_blueprint or {}; plan=_graphic_layout_plan(bp,prompt_text); palette=_graphic_reference_palette(role_items)
    accent=palette["accent"]

    # Cinematic grading and subtle vignette unify generated plate and product.
    overlay=Image.new("RGBA",(W,H),(0,0,0,0)); od=ImageDraw.Draw(overlay,"RGBA")
    copy_left=plan["copy_side"]=="left"
    for i in range(18):
        a=int(150*(1-i/18)**1.5)
        if copy_left: od.rectangle((0,0,int(W*(.43-i*.012)),H),fill=(2,5,9,a))
        else: od.rectangle((int(W*(.57+i*.012)),0,W,H),fill=(2,5,9,a))
    od.rectangle((0,int(H*.88),W,H),fill=(3,6,10,205))
    canvas=Image.alpha_composite(canvas,overlay)

    # If safe cutout extraction was not possible, preserve the source image in a
    # premium card instead of altering or dropping the product.
    if not transparent_cutout:
        card_pad = max(18, int(min(W, H) * .024))
        card = Image.new("RGBA", (product.width + card_pad * 2, product.height + card_pad * 2), (246, 248, 252, 248))
        try:
            from PIL import ImageDraw as _ImageDraw
            card_mask = Image.new("L", card.size, 0)
            _ImageDraw.Draw(card_mask).rounded_rectangle((0, 0, card.width - 1, card.height - 1), radius=max(20, card_pad), fill=255)
            card.putalpha(card_mask)
        except Exception:
            pass
        card.alpha_composite(product, (card_pad, card_pad))
        product = card

    # Product placement follows reconstructed reference zoning.
    target_w=int(W*plan["product_ratio"]); target_h=int(H*.69)
    scale=min(target_w/max(1,product.width),target_h/max(1,product.height))
    product=product.resize((max(1,int(product.width*scale)),max(1,int(product.height*scale))),Image.Resampling.LANCZOS)
    x=int(W*.47) if plan["product_side"]=="right" else int(W*.045)
    if plan["product_side"]=="right": x=min(W-product.width-int(W*.035),x)
    y=max(int(H*.15),int(H*.50-product.height*.48))
    shadow_alpha=product.getchannel("A").filter(ImageFilter.GaussianBlur(radius=max(12,H//48)))
    shadow=Image.new("RGBA",product.size,(0,0,0,0)); shadow.putalpha(shadow_alpha.point(lambda a:int(a*.55)))
    canvas.alpha_composite(shadow,(x+max(7,W//150),y+max(10,H//90)))
    canvas.alpha_composite(product,(x,y))

    draw=ImageDraw.Draw(canvas,"RGBA"); copy=_graphic_extract_copy(prompt_text,bp)
    copy_x=int(W*.055) if copy_left else int(W*.63); copy_w=int(W*.31)
    headline_font=_graphic_font(H*.066,True); body_font=_graphic_font(H*.024,True); small_font=_graphic_font(H*.019,False); cta_font=_graphic_font(H*.023,True)
    # Accent rule creates consistent hierarchy without a heavy opaque box.
    draw.rounded_rectangle((copy_x,int(H*.165),copy_x+int(W*.075),int(H*.173)),radius=4,fill=accent+(255,))
    words=copy["headline"].split(); lines=[]; current=""
    for word in words:
        trial=(current+" "+word).strip()
        try: width=draw.textbbox((0,0),trial,font=headline_font)[2]
        except Exception: width=len(trial)*24
        if current and width>copy_w: lines.append(current); current=word
        else: current=trial
    if current: lines.append(current)
    ty=int(H*.205)
    for idx,line in enumerate(lines[:4]):
        draw.text((copy_x,ty),line,font=headline_font,fill=((accent+(255,)) if idx==0 else (255,255,255,255)),stroke_width=max(1,H//700),stroke_fill=(0,0,0,150)); ty+=int(H*.072)
    if copy.get("product"):
        draw.text((copy_x,ty+int(H*.008)),copy["product"][:58],font=small_font,fill=(218,226,236,250)); ty+=int(H*.05)
    fy=max(ty+int(H*.028),int(H*.53))
    for feature in copy["features"][:4]:
        icon=int(H*.027); cy=fy+icon//2
        draw.rounded_rectangle((copy_x,fy,copy_x+icon,fy+icon),radius=max(4,icon//4),fill=accent+(235,))
        draw.text((copy_x+icon+int(W*.012),fy-int(H*.001)),feature.upper(),font=small_font,fill=(247,249,252,250))
        fy+=int(H*.052)
    cta_y=min(int(H*.81),fy+int(H*.018)); cta_w=int(copy_w*.68); cta_h=int(H*.058)
    draw.rounded_rectangle((copy_x,cta_y,copy_x+cta_w,cta_y+cta_h),radius=cta_h//2,fill=accent+(255,))
    try: bb=draw.textbbox((0,0),copy["cta"],font=cta_font); tw=bb[2]-bb[0]; th=bb[3]-bb[1]
    except Exception: tw=len(copy["cta"])*12; th=20
    draw.text((copy_x+(cta_w-tw)//2,cta_y+(cta_h-th)//2-int(H*.003)),copy["cta"],font=cta_font,fill=(255,255,255,255))

    bar_y=int(H*.90); benefits=["OEM FIT","PREMIUM DISPLAY","SMART CONNECTIVITY","AUTOTECPRO SUPPORT"]
    cell=W/4
    for i,label in enumerate(benefits):
        cx=int(cell*i+cell/2)
        try: bb=draw.textbbox((0,0),label,font=body_font); tw=bb[2]-bb[0]
        except Exception: tw=len(label)*10
        draw.text((cx-tw//2,bar_y+int(H*.033)),label,font=body_font,fill=(245,247,250,245))
        if i: draw.line((int(cell*i),bar_y+int(H*.025),int(cell*i),H-int(H*.025)),fill=(255,255,255,48),width=1)
    output=io.BytesIO(); canvas.convert("RGB").save(output,format="PNG",optimize=True)
    return output.getvalue(), {"engine":GRAPHIC_LAYERED_ENGINE_VERSION,"product_pixels_preserved":True,"product_box":[x,y,product.width,product.height],"layout_plan":plan,"palette":{"accent":list(accent)},"copy":copy,"vehicle_profile":vehicle_profile or {}}

def _graphic_is_followup_edit_request(prompt_text):
    """Return True when the user is modifying the most recent generated artwork."""
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not value:
        return False
    edit_terms = (
        "edit", "change", "replace", "remove", "add", "move", "make it", "make the",
        "bigger", "smaller", "brighter", "darker", "left", "right", "top", "bottom",
        "headline", "text", "background", "logo", "color", "colour", "keep everything else",
        "same image", "same design", "this image", "current image", "previous image",
    )
    creation_terms = (
        "create it", "generate it", "create the ad", "make the ad", "new image", "new ad",
        "another version", "regenerate", "try again",
    )
    return any(term in value for term in edit_terms) and not any(term == value for term in creation_terms)


def _graphic_is_pending_edit_continuation_v68840(prompt_text, state=None):
    """Return True only for an explicit continuation of one unresolved canvas edit.

    This is an orchestration-only decision. It does not alter prompts, rendering,
    Reference Mode, Installed View, product authority, or generated pixels. The
    saved edit must still target the currently active canvas version, which keeps
    an old completed edit from leaking into a later request.
    """
    project = state if isinstance(state, dict) else get_graphic_project_state()
    text = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not text:
        return False

    continuation_patterns = (
        r"^(?:please\s+)?(?:create|generate|make|render|produce)\s+it(?:\s+now)?[.!]?$",
        r"^(?:please\s+)?(?:go ahead|proceed|do it|continue|apply it)(?:\s+now)?[.!]?$",
        r"^(?:please\s+)?(?:retry|try again|create it again|generate it again)[.!]?$",
    )
    if not any(re.fullmatch(pattern, text) for pattern in continuation_patterns):
        return False

    latest = dict(project.get("latest_generated") or {})
    directive = dict(project.get("last_edit_directive") or {})
    if not str(latest.get("data_url") or "").startswith("data:image/"):
        return False
    if not directive.get("is_edit"):
        return False

    current_canvas_id = str(project.get("current_canvas_id") or "").strip()
    directive_canvas_id = str(directive.get("canvas_id") or "").strip()
    current_version = int(project.get("current_canvas_version") or 0)
    try:
        directive_version = int(directive.get("canvas_version") or 0)
    except (TypeError, ValueError):
        directive_version = -1

    return bool(
        current_canvas_id
        and directive_canvas_id == current_canvas_id
        and directive_version == current_version
        and str(project.get("stage") or "").strip().casefold()
        in {"editing", "generating", "ready_to_generate", "generated"}
    )


def _graphic_latest_generated_role_item(prompt_text):
    """Materialize the current conversation's latest artwork as an edit base."""
    project = get_graphic_project_state()
    if not (
        _graphic_is_followup_edit_request(prompt_text)
        or _graphic_is_pending_edit_continuation_v68840(prompt_text, project)
    ):
        return None
    latest = (get_graphic_project_state() or {}).get("latest_generated") or {}
    data_url = str(latest.get("data_url") or "")
    raw, mime = data_url_to_bytes(data_url)
    if not raw:
        return None
    uploaded = ManagedUploadedFile(
        raw,
        str(latest.get("filename") or latest.get("name") or "latest_graphic.png"),
        mime or "image/png",
        graphic_role="edit_base",
        graphic_asset_id=hashlib.sha256(raw).hexdigest(),
    )
    return {
        "file": uploaded,
        "name": uploaded.name,
        "role": "edit_base",
        "reason": "latest generated artwork selected for conversational editing",
    }


def _graphic_safe_optional_call(event_name, callback, default):
    """Run optional Graphic intelligence without allowing it to block generation."""
    try:
        value = callback()
        return default if value is None else value
    except Exception as error:
        diagnostic_log(event_name, error_type=type(error).__name__, error=error)
        return default



def _graphic_asset_visual_profile_v8300(item):
    """Return cheap local visual signals used only to prevent reference/product swaps."""
    profile = {
        "white_fraction": 0.0,
        "near_white_fraction": 0.0,
        "dark_fraction": 0.0,
        "colorfulness": 0.0,
        "width": 0,
        "height": 0,
        "studio_product_likelihood": 0.0,
        "advertisement_likelihood": 0.0,
    }
    if Image is None or not isinstance(item, dict):
        return profile
    try:
        raw = _graphic_uploaded_file_bytes(item.get("file"))
        if not raw:
            return profile
        with Image.open(io.BytesIO(raw)) as im:
            im = ImageOps.exif_transpose(im).convert("RGB")
            im.thumbnail((320, 240), Image.Resampling.BILINEAR)
            profile["width"], profile["height"] = im.size
            pixels = list(im.getdata())
        if not pixels:
            return profile
        count = float(len(pixels))
        white = near_white = dark = 0
        colorfulness_total = 0.0
        for r, g, b in pixels:
            hi, lo = max(r, g, b), min(r, g, b)
            brightness = (r + g + b) / 3.0
            if r >= 242 and g >= 242 and b >= 242:
                white += 1
            if r >= 224 and g >= 224 and b >= 224:
                near_white += 1
            if brightness <= 55:
                dark += 1
            colorfulness_total += float(hi - lo)
        wf = white / count
        nwf = near_white / count
        df = dark / count
        cf = colorfulness_total / count
        profile.update({
            "white_fraction": round(wf, 4),
            "near_white_fraction": round(nwf, 4),
            "dark_fraction": round(df, 4),
            "colorfulness": round(cf, 2),
        })
        # Clean catalogue product photos normally have a dominant white/neutral field.
        studio = min(1.0, max(0.0, (nwf - 0.36) / 0.45))
        # Finished advertisements normally use dense scenery/colors with little empty white field.
        advert = min(1.0, max(0.0, ((0.40 - nwf) / 0.40) * 0.72 + min(cf / 85.0, 1.0) * 0.28))
        profile["studio_product_likelihood"] = round(studio, 4)
        profile["advertisement_likelihood"] = round(advert, 4)
    except Exception as error:
        diagnostic_log("graphic_v8300_asset_profile_failed", error_type=type(error).__name__, error=error)
    return profile


def _graphic_enforce_reference_product_roles_v8300(role_items, prompt_text=""):
    """Prevent a finished reference advertisement from becoming the hero product.

    This guard is local and deterministic. It never changes a forced logo/background role.
    It prefers a clean white/neutral catalogue source as the authoritative product and a
    dense colorful finished artwork as the style reference. In the common reference-first,
    product-second conversation, the newest plausible catalogue source wins.
    """
    items = [dict(item) for item in (role_items or []) if isinstance(item, dict)]
    image_items = [item for item in items if item.get("role") not in {"edit_base", "logo_asset", "background"}]
    if len(image_items) < 2:
        return items

    prompt_lower = str(prompt_text or "").lower()
    for index, item in enumerate(items):
        item["_v8300_index"] = index
        item["_v8300_profile"] = _graphic_asset_visual_profile_v8300(item)

    candidates = [item for item in items if item.get("role") not in {"edit_base", "logo_asset", "background"}]
    product_candidates = sorted(
        candidates,
        key=lambda item: (
            float((item.get("_v8300_profile") or {}).get("studio_product_likelihood") or 0.0),
            float((item.get("_v8300_profile") or {}).get("near_white_fraction") or 0.0),
            int(item.get("_v8300_index") or 0),
        ),
        reverse=True,
    )
    style_candidates = sorted(
        candidates,
        key=lambda item: (
            float((item.get("_v8300_profile") or {}).get("advertisement_likelihood") or 0.0),
            -float((item.get("_v8300_profile") or {}).get("near_white_fraction") or 0.0),
            -int(item.get("_v8300_index") or 0),
        ),
        reverse=True,
    )

    primary_product = product_candidates[0] if product_candidates else None
    primary_style = next((item for item in style_candidates if item is not primary_product), None)

    # Require meaningful evidence before overriding persistent metadata. The observed
    # failure case is very strong: reference ad ~11% near-white, product source ~82%.
    product_score = float(((primary_product or {}).get("_v8300_profile") or {}).get("studio_product_likelihood") or 0.0)
    style_score = float(((primary_style or {}).get("_v8300_profile") or {}).get("advertisement_likelihood") or 0.0)
    strong_split = bool(primary_product and primary_style and product_score >= 0.45 and style_score >= 0.45)

    explicit_product_language = any(token in prompt_lower for token in (
        "this product", "product unit", "actual product", "original unit", "product photo",
        "this unit", "this is 2020", "this is a 2020", "jeep cherokee",
    ))
    explicit_safe_split = bool(explicit_product_language and product_score >= 0.20 and style_score >= 0.45)
    if strong_split or explicit_safe_split:
        # Keep multi-view product photos only when they also look like catalogue sources.
        for item in candidates:
            profile = item.get("_v8300_profile") or {}
            if item is primary_product:
                item["role"] = "product_photo"
                item["role_locked_by"] = "v8300_visual_product_guard"
            elif item is primary_style:
                item["role"] = "style_reference"
                item["role_locked_by"] = "v8300_visual_reference_guard"
            elif float(profile.get("studio_product_likelihood") or 0.0) >= 0.58:
                item["role"] = "product_photo"
                item["role_locked_by"] = "v8300_multiview_product_guard"
            elif float(profile.get("advertisement_likelihood") or 0.0) >= 0.42:
                item["role"] = "style_reference"
                item["role_locked_by"] = "v8300_visual_reference_guard"

    for item in items:
        item.pop("_v8300_index", None)
        item.pop("_v8300_profile", None)
    diagnostic_log(
        "graphic_v8300_role_guard",
        roles=[f"{item.get('role')}:{item.get('name')}:{item.get('role_locked_by','existing')}" for item in items],
        strong_split=strong_split,
        product_score=round(product_score, 3),
        style_score=round(style_score, 3),
    )
    return items



def _graphic_current_product_authority_v52000(role_items):
    """Return the authoritative current product identity from the actual uploaded bitmap."""
    product = next((item for item in (role_items or []) if item.get("role") == "product_photo"), None)
    signature = _graphic_product_source_signature_v9000(product) if product else {}
    return {
        "available": bool(product and signature.get("sha256")),
        "sha256": str(signature.get("sha256") or ""),
        "name": str((product or {}).get("name") or ""),
        "asset_id": str((product or {}).get("asset_id") or (product or {}).get("id") or ""),
        "aspect_ratio": float(signature.get("aspect_ratio") or 0.0),
        "engine": "product-authority-v52000",
    }


def _graphic_invalidate_product_caches_v52000(role_items):
    """Invalidate every product-derived cache when the authoritative upload changes."""
    authority = _graphic_current_product_authority_v52000(role_items)
    if not authority.get("available"):
        return {"changed": False, "authority": authority, "cleared": []}
    state = get_graphic_project_state()
    previous = dict(state.get("active_product_authority_v52000") or {})
    changed = bool(previous.get("sha256") and previous.get("sha256") != authority.get("sha256"))
    cleared = []
    if changed:
        for key in (
            "active_product_dna", "product_dna", "product_dna_locked", "engineering_approval_v21000",
            "last_product_mask", "last_product_layer", "last_product_transform", "last_product_perspective",
            "last_campaign_product_sha", "last_reference_product_composite", "product_structure_profile",
            "product_segmentation_cache", "product_detail_masks", "last_generated_product_asset",
        ):
            if key in state:
                state.pop(key, None); cleared.append(key)
        # Cached Streamlit functions are keyed by raw bytes, but project-level stale assets must never survive.
        state["reference_blueprint_locked"] = False
    state["active_product_authority_v52000"] = authority
    state["active_product_source_sha256"] = authority.get("sha256")
    state["updated_at"] = datetime.now(timezone.utc).isoformat()
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
    diagnostic_log("graphic_v52000_product_authority", changed=changed, cleared=cleared, sha256=authority.get("sha256"), name=authority.get("name"))
    return {"changed": changed, "authority": authority, "cleared": cleared}


def _graphic_enforce_reference_exact_mode_v52000(product_mode, design_mode, has_product, has_style, prompt_text):
    """Reference-style front-view campaigns must use immutable uploaded pixels, never recreation."""
    mode = dict(product_mode or {})
    text = str(prompt_text or "").casefold()
    explicit_recreation = any(term in text for term in (
        "change the angle", "new camera angle", "three-quarter product view", "3/4 product view",
        "side view of the unit", "rear view of the unit", "recreate the product", "product recreation",
    ))
    if design_mode == "reference_template" and has_product and has_style and not explicit_recreation:
        mode.update({
            "exact_product": True,
            "recreates_product": False,
            "installed_view": False,
            "adaptive_mode": "commercial_lock",
            "mode": "reference_exact_product_v52000",
            "render_mode": "Pixel Immutable",
            "product_authority_policy": "uploaded_bitmap_only",
        })
    return mode


def _graphic_product_provenance_gate_v52000(result, role_items):
    """Prove that the commercial hero came from the current uploaded source and no AI product layer."""
    metadata = dict((result or {}).get("layered_metadata") or {})
    authority = _graphic_current_product_authority_v52000(role_items)
    issues = []
    if not authority.get("available"):
        issues.append("authoritative product source unavailable")
    if str(metadata.get("product_source_sha256") or "") != str(authority.get("sha256") or ""):
        issues.append("composited product SHA-256 does not match the current upload")
    if metadata.get("exact_product_pixels") is not True:
        issues.append("exact uploaded pixels were not confirmed")
    if metadata.get("product_pixels_provider_generated") is not False:
        issues.append("provider-generated product pixels entered the exact route")
    if metadata.get("product_master_rgb_preserved") is not True:
        issues.append("product master RGB was not preserved")
    if metadata.get("product_ai_reconstruction_prohibited") is not True:
        issues.append("AI product reconstruction was not prohibited")
    if str((result or {}).get("product_identity_method") or "").casefold().find("composite") < 0:
        issues.append("result does not identify a deterministic product composite")
    cutout_report = dict(metadata.get("product_cutout_integrity_v54000") or metadata.get("product_cutout_integrity_v53000") or {})
    if cutout_report and cutout_report.get("passed") is not True and cutout_report.get("source_alpha_preserved") is not True:
        issues.append("authoritative product cutout did not pass v53000 mask-integrity validation")
    manifest = {
        "source_sha256": authority.get("sha256"),
        "source_name": authority.get("name"),
        "selected_sha256": metadata.get("product_source_sha256"),
        "pixel_origin": "uploaded_product_bitmap",
        "allowed_product_operations": ["background removal", "uniform scale", "translation", "local lighting/reflection overlay", "contact shadow"],
        "forbidden_product_operations": ["generative redraw", "outpainting", "new brackets", "new holes", "new buttons", "bezel reshaping", "independent screen scaling"],
        "engine": "pixel-provenance-gate-v53000",
    }
    return {"passed": not issues, "issues": issues, "manifest": manifest, "engine": "product-provenance-v53000"}


def _graphic_role_integrity_v8300(role_items):
    """Fail closed when product/reference separation is still implausible."""
    products = [item for item in (role_items or []) if item.get("role") == "product_photo"]
    styles = [item for item in (role_items or []) if item.get("role") == "style_reference"]
    if not products:
        return {"passed": False, "reason": "No authoritative product source was resolved."}
    product_profile = _graphic_asset_visual_profile_v8300(products[0])
    style_profiles = [_graphic_asset_visual_profile_v8300(item) for item in styles[:3]]
    suspicious_product = (
        bool(styles)
        and float(product_profile.get("advertisement_likelihood") or 0.0) >= 0.72
        and float(product_profile.get("studio_product_likelihood") or 0.0) < 0.25
    )
    duplicate_source = any(
        str(item.get("name") or "") == str(products[0].get("name") or "")
        for item in styles
    )
    return {
        "passed": not suspicious_product and not duplicate_source,
        "reason": "Reference advertisement was incorrectly resolved as the product source." if suspicious_product or duplicate_source else "ok",
        "product_profile": product_profile,
        "style_profiles": style_profiles,
    }



def _graphic_project_role_items(uploaded_files, prompt_text, forced_role="Auto-detect"):
    """Resolve exactly one active product and one active style reference.

    v68800 closes the persistent-asset authority gap: v16000 recorded
    ``active_product_id`` and ``active_reference_id`` but the old resolver never
    consumed those fields. Historical product/reference assets therefore remained in
    ``role_items`` and downstream code selected the first ``product_photo``. In a
    reference-first workflow that could make the Ford reference advertisement become
    the product geometry authority.

    The active project IDs are now authoritative. Historical product/reference
    records are excluded from generation, while logos/supporting images and the edit
    base remain available.
    """
    effective_files = graphic_project_uploaded_files(uploaded_files or [])
    role_items = classify_graphic_uploaded_image_roles(
        effective_files, prompt_text, forced_role=forced_role
    )

    # Preserve the existing deterministic recovery for projects whose role metadata
    # predates the persistent-role transport.
    has_product = any(item.get("role") == "product_photo" for item in role_items)
    has_style = any(item.get("role") == "style_reference" for item in role_items)
    if effective_files and (not has_product or not has_style):
        recovered = _graphic_recover_role_items(
            effective_files, prompt_text, forced_role=forced_role
        )
        if recovered:
            role_items = recovered

    role_items = _graphic_enforce_reference_product_roles_v8300(
        role_items, prompt_text
    )

    project = get_graphic_project_state()
    active_product_id = str(project.get("active_product_id") or "").strip()
    active_product_ids = {
        str(value or "").strip() for value in (project.get("active_product_ids") or [])
        if str(value or "").strip()
    }
    if active_product_id:
        active_product_ids.add(active_product_id)
    active_reference_id = str(project.get("active_reference_id") or "").strip()

    def item_id(item):
        file_obj = item.get("file") if isinstance(item, dict) else None
        saved = str(
            getattr(file_obj, "graphic_asset_id", "") or
            item.get("graphic_asset_id", "") or
            item.get("id", "")
        ).strip()
        if saved:
            return saved
        try:
            return hashlib.sha256(_graphic_uploaded_file_bytes(file_obj)).hexdigest()
        except Exception:
            return ""

    # Re-label the exact active records by ID before filtering. This prevents a
    # filename/prompt classifier from overriding authoritative persistent roles.
    for item in role_items:
        digest = item_id(item)
        item["graphic_asset_id"] = digest
        if active_product_id and digest == active_product_id:
            item["role"] = "product_photo"
            item["role_locked_by"] = "v68800_active_product_id"
        elif digest and digest in active_product_ids:
            item["role"] = "product_variant"
            item["role_locked_by"] = "v68848_active_product_ids"
        elif active_reference_id and digest == active_reference_id:
            item["role"] = "style_reference"
            item["role_locked_by"] = "v68800_active_reference_id"

    filtered = []
    for item in role_items:
        role = str(item.get("role") or "")
        digest = item_id(item)

        if role == "product_photo":
            if active_product_id and digest != active_product_id:
                continue
        elif role == "product_variant":
            if active_product_ids and digest not in active_product_ids:
                continue
        elif role == "style_reference":
            if active_reference_id and digest != active_reference_id:
                continue

        filtered.append(item)

    role_items = filtered

    # Fail closed against one physical file being both product and reference.
    if active_product_id and active_reference_id and active_product_id == active_reference_id:
        raise RuntimeError(
            "The active product and style reference resolve to the same file. "
            "Start a new case or re-upload the product photo."
        )

    product_items = [
        item for item in role_items
        if item.get("role") == "product_photo"
    ]
    style_items = [
        item for item in role_items
        if item.get("role") == "style_reference"
    ]
    multi_image_plan_v68848 = _graphic_multi_image_intent_plan_v68848(prompt_text, role_items)
    active_plan_ids_v68848 = set(multi_image_plan_v68848.get("active_ids") or [])
    if active_plan_ids_v68848:
        role_items = [
            item for item in role_items
            if str(item.get("role") or "") not in {"product_photo", "product_variant"}
            or item_id(item) in active_plan_ids_v68848
        ]
        product_items = [item for item in role_items if item.get("role") == "product_photo"]
        variant_items_v68848 = [item for item in role_items if item.get("role") == "product_variant"]
    else:
        variant_items_v68848 = [item for item in role_items if item.get("role") == "product_variant"]

    # Current-turn product fallback: if persistent IDs are unavailable, the newest
    # non-reference current upload remains the product, preserving the established
    # reference-first/product-second workflow.
    if effective_files and not product_items:
        current_ids = []
        for file_obj in uploaded_files or []:
            try:
                current_ids.append(
                    hashlib.sha256(_graphic_uploaded_file_bytes(file_obj)).hexdigest()
                )
            except Exception:
                pass
        candidate = next(
            (
                item for item in role_items
                if item_id(item) in set(current_ids)
                and item.get("role") not in {
                    "style_reference", "edit_base", "logo_asset", "background"
                }
            ),
            None,
        )
        if candidate is not None:
            candidate["role"] = "product_photo"
            candidate["role_locked_by"] = "v68800_current_upload_product_fallback"
            product_items = [candidate]

    if effective_files and not product_items:
        raise RuntimeError(
            "The active uploaded product photo could not be resolved safely. "
            "The style reference will not be used as product geometry."
        )

    if len(product_items) > 1:
        # The established single-product path remains unchanged. Explicit multi-image
        # plans retain one primary product plus separately addressable variants.
        keep = product_items[0]
        for extra in product_items[1:]:
            extra["role"] = "product_variant"
            extra["role_locked_by"] = "v68848_multi_image_plan"
        product_items = [keep]
    if multi_image_plan_v68848.get("mode") not in {"together", "front_rear", "separate_designs"}:
        selected_ids = set(multi_image_plan_v68848.get("active_ids") or [])
        role_items = [
            item for item in role_items
            if item.get("role") != "product_variant" or item_id(item) in selected_ids
        ]

    if len(style_items) > 1:
        keep = style_items[0]
        role_items = [
            item for item in role_items
            if item.get("role") != "style_reference" or item is keep
        ]
        style_items = [keep]

    edit_base = _graphic_latest_generated_role_item(prompt_text)
    if edit_base:
        role_items = [
            edit_base
        ] + [
            item for item in role_items
            if item.get("role") != "edit_base"
        ]

    role_priority = {
        "edit_base": 0,
        "product_photo": 1,
        "product_variant": 2,
        "style_reference": 3,
        "logo_asset": 4,
        "supporting_image": 5,
    }
    role_items = sorted(
        role_items,
        key=lambda item: role_priority.get(str(item.get("role") or ""), 9),
    )

    final_product = next(
        (item for item in role_items if item.get("role") == "product_photo"),
        None,
    )
    final_reference = next(
        (item for item in role_items if item.get("role") == "style_reference"),
        None,
    )
    final_product_id = item_id(final_product) if final_product else ""
    final_reference_id = item_id(final_reference) if final_reference else ""

    if active_product_id and final_product_id != active_product_id:
        raise RuntimeError(
            "Product Geometry Authority failed: the selected product does not match "
            "the active uploaded product ID."
        )
    if active_reference_id and final_reference_id != active_reference_id:
        raise RuntimeError(
            "Reference authority failed: the selected style reference does not match "
            "the active reference ID."
        )

    state = get_graphic_project_state()
    state["last_role_authority_v68800"] = {
        "active_product_id": active_product_id,
        "selected_product_id": final_product_id,
        "active_reference_id": active_reference_id,
        "selected_reference_id": final_reference_id,
        "product_count": sum(
            1 for item in role_items if item.get("role") == "product_photo"
        ),
        "reference_count": sum(
            1 for item in role_items if item.get("role") == "style_reference"
        ),
        "product_variant_count_v68842": sum(
            1 for item in role_items if item.get("role") == "product_variant"
        ),
        "historical_product_reference_assets_excluded": True,
        "product_geometry_source": "active_product_id",
        "active_product_ids_v68848": sorted(active_product_ids),
        "multi_image_intent_plan_v68848": multi_image_plan_v68848,
    }
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
    diagnostic_log(
        "graphic_v68800_active_role_authority",
        product_match=(
            not active_product_id or final_product_id == active_product_id
        ),
        reference_match=(
            not active_reference_id or final_reference_id == active_reference_id
        ),
        product_count=state["last_role_authority_v68800"]["product_count"],
        reference_count=state["last_role_authority_v68800"]["reference_count"],
    )
    return role_items





@st.cache_data(ttl=86400, max_entries=128, show_spinner=False)
def _graphic_product_structure_profile_cached_v4300(raw_bytes, filename=""):
    """Extract critical hardware geometry that must survive every commercial render.

    The profile is advisory for provider prompts and QA. Exact product compositing is
    still the authoritative preservation mechanism, so analysis failure never blocks
    generation.
    """
    if not raw_bytes:
        return {}
    fallback = {
        "source_filename": str(filename or ""),
        "must_preserve": [
            "complete outer housing silhouette",
            "screen aspect ratio and visible screen UI",
            "left and right trim/handle geometry",
            "all physical knobs and buttons",
            "lower mounting frame and tabs",
            "all open negative-space cutouts",
            "the horizontal gap directly below the screen",
            "bottom bracket openings and mounting points",
        ],
        "critical_negative_spaces": [
            "gap below screen",
            "lower rectangular openings",
            "side handle openings",
        ],
        "analysis_available": False,
    }
    try:
        mime = "image/png" if raw_bytes[:8] == b"\x89PNG\r\n\x1a\n" else "image/jpeg"
        data_url = f"data:{mime};base64," + base64.b64encode(raw_bytes).decode("ascii")
        response = client.responses.create(
            model=_graphic_responses_model_v4000(),
            instructions=(
                "Act as a strict automotive hardware geometry inspector. Return JSON only. "
                "Identify exact silhouette, openings, gaps, tabs, controls, screen borders, and mounting geometry."
            ),
            input=[{"role":"user","content":[
                {"type":"input_text","text":(
                    "Analyze this exact AutoTecPro product source for immutable structural details. "
                    "Return one JSON object with keys: outer_silhouette, screen_geometry, side_structures, "
                    "physical_controls, lower_structure, critical_negative_spaces, mounting_points, "
                    "must_preserve, common_failure_risks. Explicitly inspect whether there is a visible "
                    "horizontal gap below the screen, open lower cavities, side handle openings, bottom tabs, "
                    "and any other empty spaces that an image model may accidentally fill."
                )},
                {"type":"input_image","image_url":data_url},
            ]}],
            max_output_tokens=1200,
        )
        parsed = extract_json_object(str(getattr(response, "output_text", "") or ""))
        if isinstance(parsed, dict) and parsed:
            parsed["source_filename"] = str(filename or "")
            parsed["analysis_available"] = True
            parsed.setdefault("must_preserve", fallback["must_preserve"])
            parsed.setdefault("critical_negative_spaces", fallback["critical_negative_spaces"])
            return parsed
    except Exception as error:
        diagnostic_log("graphic_v4300_product_structure_analysis_failed", error_type=type(error).__name__, error=str(error))
    return fallback


def _graphic_product_structure_profile_v4300(role_items):
    product = next((item for item in (role_items or []) if item.get("role") == "product_photo"), None)
    if not product:
        return {}
    raw = _graphic_uploaded_file_bytes(product.get("file"))
    return _graphic_product_structure_profile_cached_v4300(raw, str(product.get("name") or ""))


def _graphic_product_structure_text_v4300(profile):
    if not isinstance(profile, dict) or not profile:
        return ""
    parts = []
    for key in (
        "outer_silhouette", "screen_geometry", "side_structures", "physical_controls",
        "lower_structure", "critical_negative_spaces", "mounting_points", "must_preserve",
        "common_failure_risks",
    ):
        value = profile.get(key)
        if value not in (None, "", [], {}):
            parts.append(f"{key.replace('_',' ').title()}: {value}")
    return " | ".join(parts)[:7000]



