GRAPHIC_ENGINE_VERSION = "v63000"
GRAPHIC_V4000_ENGINE_VERSION = GRAPHIC_ENGINE_VERSION
GRAPHIC_V4000_ALLOWED_SIZES = {"1024x1024", "1024x1536", "1536x1024"}


def _graphic_normalize_output_size_v4000(value):
    """Return a provider-supported size without changing the public size behavior."""
    clean = str(value or "").strip().lower().replace(" ", "")
    if clean in GRAPHIC_V4000_ALLOWED_SIZES:
        return clean
    return "1536x1024"


def _graphic_compact_error_v4000(error):
    """Return a safe, bounded provider error for diagnostics and project state."""
    value = re.sub(r"\s+", " ", str(error or "")).strip()
    return value[:700]



def _graphic_sdk_capabilities_v4100():
    """Return safe local SDK capability flags without making a network request."""
    return {
        "responses": bool(getattr(client, "responses", None) and hasattr(client.responses, "create")),
        "images_edit": bool(getattr(client, "images", None) and hasattr(client.images, "edit")),
        "images_generate": bool(getattr(client, "images", None) and hasattr(client.images, "generate")),
    }


def _graphic_responses_model_candidates_v4100():
    """Return configured and default orchestration models in stable order."""
    configured = get_optional_secret("GRAPHIC_RESPONSES_MODEL", "gpt-5.5")
    candidates = []
    for value in (configured, "gpt-5.5"):
        clean = str(value or "").strip()
        if clean and clean not in candidates:
            candidates.append(clean)
    return candidates


def _graphic_validation_unavailable_v4100(reason="validation unavailable"):
    return {"verified": None, "available": False, "score": None, "reason": str(reason)}


def _graphic_validation_is_unavailable_v4100(value):
    value = value or {}
    return value.get("available") is False or value.get("verified") is None


def _graphic_mark_unverified_v4100(result, reason, status="completed_unverified"):
    result = dict(result or {})
    result["output_status"] = status
    result["verification_status"] = "unverified"
    result["verification_warning"] = str(reason or "Some optional quality checks were unavailable.")[:900]
    return result


def _graphic_responses_model_v4000():
    """Use an optional image-orchestration model override while preserving defaults."""
    configured = get_optional_secret("GRAPHIC_RESPONSES_MODEL", "gpt-5.5")
    return configured or "gpt-5.5"



def _graphic_responses_tool_variants_v4000(action, output_size, has_images):
    """Return a short, non-streaming compatibility ladder for image generation.

    ``partial_images`` is intentionally excluded because this application uses
    ``responses.create`` rather than a streaming response. The ladder starts
    with the preferred high-fidelity schema and removes only optional fields.
    """
    base = {
        "type": "image_generation",
        "action": action,
        "quality": "high",
        "size": _graphic_normalize_output_size_v4000(output_size),
        "output_format": "png",
        "background": "opaque",
    }
    if has_images:
        base["input_fidelity"] = "high"
    variants = [dict(base)]
    for remove in (
        ("background",),
        ("background", "output_format", "input_fidelity"),
        ("background", "output_format", "input_fidelity", "action"),
    ):
        item = dict(base)
        for key in remove:
            item.pop(key, None)
        if item not in variants:
            variants.append(item)
    return variants

def _graphic_response_image_bytes_v4000(response):
    """Extract image bytes from completed response objects and compatible SDK shapes."""
    images = _graphic_responses_image_result_bytes(response)
    if images:
        return images
    # Newer/alternate response serializers may expose a flat output list/dict.
    payload = response.model_dump() if hasattr(response, "model_dump") else response
    if isinstance(payload, dict):
        stack = [payload]
        seen = set()
        while stack:
            current = stack.pop()
            if id(current) in seen:
                continue
            seen.add(id(current))
            if isinstance(current, dict):
                for key, value in current.items():
                    if key in {"b64_json", "result", "image_base64", "partial_image_b64"} and isinstance(value, str):
                        try:
                            raw = base64.b64decode(value)
                        except Exception:
                            raw = b""
                        if raw:
                            return [raw]
                    if isinstance(value, (dict, list)):
                        stack.append(value)
            elif isinstance(current, list):
                stack.extend(current)
    return []



def _graphic_deterministic_hybrid_verification_v4000(hybrid, hard_vehicle, vehicle_validation):
    """Verify deterministic output while distinguishing failure from unavailable QA."""
    metadata = (hybrid or {}).get("layered_metadata") or {}
    data_url = str((hybrid or {}).get("data_url") or "")
    image_bytes, _ = data_url_to_bytes(data_url)
    image_valid = bool(image_bytes)
    exact_product = bool(metadata.get("exact_product_pixels") or metadata.get("product_preserved") or (hybrid or {}).get("strict_product_identity_lock"))
    zones = metadata.get("campaign_zones") or []
    zone_set = {str(item).strip().lower() for item in zones}
    required = {"logo", "headline", "compatibility_ribbon", "tagline", "feature_matrix", "hero_product", "bottom_benefit_bar"}
    zones_valid = required.issubset(zone_set) if zone_set else bool(metadata.get("deterministic_typography"))
    unavailable = bool(hard_vehicle and _graphic_validation_is_unavailable_v4100(vehicle_validation))
    vehicle_verified = True if not hard_vehicle else (vehicle_validation or {}).get("verified") is True
    vehicle_explicitly_failed = bool(hard_vehicle and not unavailable and not vehicle_verified)
    core_passed = bool(image_valid and exact_product and zones_valid)
    return {
        "passed": bool(core_passed and not vehicle_explicitly_failed),
        "verified": bool(core_passed and vehicle_verified),
        "unverified": bool(core_passed and unavailable),
        "image_valid": image_valid,
        "exact_product": exact_product,
        "zones_valid": zones_valid,
        "vehicle_valid": vehicle_verified,
        "vehicle_validation_unavailable": unavailable,
        "verification_source": "deterministic-renderer-plus-optional-focused-vehicle-audit",
    }

def _graphic_project_failure_v4000(stage, errors):
    """Persist a retryable Graphic failure without losing project assets."""
    state = get_graphic_project_state()
    state["stage"] = "ready_to_generate"
    state["last_error"] = "; ".join(str(item) for item in (errors or []) if item)[:1800]
    state["last_failed_stage"] = str(stage or "graphic_generation")
    state["graphic_engine_version"] = GRAPHIC_V4000_ENGINE_VERSION
    state["updated_at"] = datetime.now(timezone.utc).isoformat()
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state



# ============================================================
# v66100 LTS — quality-preserving performance and observability
# Keeps the v66000 geometry authority unchanged. All persistent optimizations
# fail open to the verified v66000 behavior when storage is unavailable.
# ============================================================
GRAPHIC_V66100_CACHE_TABLE = "graphic_runtime_cache"
GRAPHIC_V66100_CACHE_NAMESPACE = "v66100"
GRAPHIC_V66100_ROUTE_CACHE_KEY = "provider-route"


def _graphic_v66100_attempt_manifest():
    return st.session_state.setdefault("graphic_provider_attempt_manifest_v66100", [])


def _graphic_v66100_record_attempt(**entry):
    row = {"at": datetime.now(timezone.utc).isoformat(), **entry}
    manifest = _graphic_v66100_attempt_manifest()
    manifest.append(row)
    del manifest[:-80]
    diagnostic_log("graphic_v66100_provider_attempt", **{k:v for k,v in row.items() if k != "error"})
    return row


GRAPHIC_V68874_SESSION_CACHE_MAX_ENTRIES = 36
GRAPHIC_V68874_SESSION_CACHE_MAX_APPROX_BYTES = 24 * 1024 * 1024


def _graphic_v68874_approx_object_bytes(value):
    """Cheap bounded-size estimate for session-cache pressure accounting."""
    try:
        if isinstance(value, (bytes, bytearray)):
            return len(value)
        if isinstance(value, str):
            return len(value.encode("utf-8", "ignore"))
        return len(
            json.dumps(
                value,
                ensure_ascii=False,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8", "ignore")
        )
    except Exception:
        try:
            return len(str(value).encode("utf-8", "ignore"))
        except Exception:
            return 0


def _graphic_v68874_bound_session_cache(cache):
    """Bound the local v66100 cache without changing its Supabase authority.

    Large validated background plates can contain multi-megabyte Base64 strings.
    v68873 kept every cache entry in Streamlit session_state indefinitely.
    This helper evicts only the oldest LOCAL copies. An evicted entry remains
    available from the existing Supabase cache and is transparently reloaded by
    _graphic_v66100_cache_get when needed.
    """
    if not isinstance(cache, dict):
        return {}

    # First enforce count.
    while len(cache) > GRAPHIC_V68874_SESSION_CACHE_MAX_ENTRIES:
        try:
            cache.pop(next(iter(cache)), None)
        except Exception:
            break

    # Then enforce approximate payload size.
    try:
        sizes = {
            key: _graphic_v68874_approx_object_bytes(value)
            for key, value in cache.items()
        }
        total = sum(sizes.values())
        while (
            total > GRAPHIC_V68874_SESSION_CACHE_MAX_APPROX_BYTES
            and len(cache) > 1
        ):
            oldest = next(iter(cache))
            total -= sizes.get(oldest, 0)
            cache.pop(oldest, None)
            sizes.pop(oldest, None)
    except Exception:
        pass

    return cache


def _graphic_v68874_process_memory_snapshot():
    """Return best-effort Linux process/container memory telemetry without dependencies."""
    snapshot = {
        "rss_mb": None,
        "peak_rss_mb": None,
        "available_mb": None,
    }

    try:
        status_values = {}
        with open("/proc/self/status", "r", encoding="utf-8") as handle:
            for line in handle:
                if ":" not in line:
                    continue
                key, value = line.split(":", 1)
                status_values[key.strip()] = value.strip()

        def _kb(name):
            raw = status_values.get(name, "")
            match = re.search(r"(\d+)", raw)
            return int(match.group(1)) if match else None

        rss_kb = _kb("VmRSS")
        peak_kb = _kb("VmHWM")
        snapshot["rss_mb"] = round(rss_kb / 1024.0, 2) if rss_kb is not None else None
        snapshot["peak_rss_mb"] = round(peak_kb / 1024.0, 2) if peak_kb is not None else None
    except Exception:
        pass

    try:
        available_kb = None
        with open("/proc/meminfo", "r", encoding="utf-8") as handle:
            for line in handle:
                if line.startswith("MemAvailable:"):
                    match = re.search(r"(\d+)", line)
                    available_kb = int(match.group(1)) if match else None
                    break
        snapshot["available_mb"] = (
            round(available_kb / 1024.0, 2)
            if available_kb is not None
            else None
        )
    except Exception:
        pass

    return snapshot


def _graphic_v68874_release_transient_memory(stage=""):
    """Release unreachable image buffers at safe stage boundaries only.

    This never deletes project assets, generated results, history, provider
    inputs, reference/product authorities, or any deterministic caches needed
    for output. It only asks Python/Pillow/libc to return already-unreachable
    memory and records the resulting process footprint.
    """
    collected = 0
    try:
        collected = int(gc.collect())
    except Exception:
        collected = 0

    # Pillow maintains optional allocator caches. Clearing them does not alter
    # live Image objects or pixels; it only releases reusable internal blocks.
    try:
        core = getattr(Image, "core", None) if Image is not None else None
        clear_cache = getattr(core, "clear_cache", None)
        if callable(clear_cache):
            clear_cache()
    except Exception:
        pass

    # On Linux/glibc, return free heap arenas to the container where possible.
    try:
        if os.name == "posix":
            import ctypes
            libc = ctypes.CDLL(None)
            malloc_trim = getattr(libc, "malloc_trim", None)
            if callable(malloc_trim):
                malloc_trim(0)
    except Exception:
        pass

    snapshot = _graphic_v68874_process_memory_snapshot()
    diagnostic_log(
        "graphic_v68874_memory_checkpoint",
        stage=str(stage or ""),
        collected_objects=collected,
        **snapshot,
    )
    return snapshot


def _graphic_v66100_cache_get(cache_key):
    session = st.session_state.setdefault("graphic_persistent_cache_v66100", {})
    _graphic_v68874_bound_session_cache(session)
    if cache_key in session:
        # Refresh local recency without changing the cached payload.
        cached = session.pop(cache_key)
        session[cache_key] = cached
        return cached
    try:
        result = (supabase.table(GRAPHIC_V66100_CACHE_TABLE)
                  .select("payload")
                  .eq("cache_key", cache_key).limit(1).execute())
        rows = getattr(result, "data", None) or []
        if rows and isinstance(rows[0].get("payload"), dict):
            session[cache_key] = rows[0]["payload"]
            _graphic_v68874_bound_session_cache(session)
            return session.get(cache_key) or rows[0]["payload"]
    except Exception as error:
        diagnostic_log("graphic_v66100_cache_read_unavailable", error_type=type(error).__name__)
    return None


def _graphic_v66100_cache_put(cache_key, payload):
    if not isinstance(payload, dict):
        return False

    session = st.session_state.setdefault("graphic_persistent_cache_v66100", {})
    if cache_key in session:
        session.pop(cache_key, None)
    session[cache_key] = payload
    _graphic_v68874_bound_session_cache(session)

    try:
        record = {"cache_key": cache_key, "namespace": GRAPHIC_V66100_CACHE_NAMESPACE,
                  "payload": payload, "updated_at": datetime.now(timezone.utc).isoformat()}
        try:
            supabase.table(GRAPHIC_V66100_CACHE_TABLE).upsert(record, on_conflict="cache_key").execute()
        except Exception:
            supabase.table(GRAPHIC_V66100_CACHE_TABLE).insert(record).execute()
        return True
    except Exception as error:
        diagnostic_log("graphic_v66100_cache_write_unavailable", error_type=type(error).__name__)
        return False


def _graphic_v66100_route_fingerprint(action, output_size, has_images):
    return hashlib.sha256(f"{GRAPHIC_ENGINE_VERSION}|{action}|{output_size}|{int(has_images)}".encode()).hexdigest()


def _graphic_v66100_remember_route(action, output_size, has_images, route):
    key = GRAPHIC_V66100_ROUTE_CACHE_KEY + ":" + _graphic_v66100_route_fingerprint(action, output_size, has_images)
    _graphic_v66100_cache_put(key, {"route": route, "updated_at": datetime.now(timezone.utc).isoformat()})


def _graphic_v66100_preferred_route(action, output_size, has_images):
    key = GRAPHIC_V66100_ROUTE_CACHE_KEY + ":" + _graphic_v66100_route_fingerprint(action, output_size, has_images)
    data = _graphic_v66100_cache_get(key) or {}
    return str(data.get("route") or "")


def _graphic_v66100_bytes_sha(raw):
    return hashlib.sha256(raw or b"").hexdigest() if raw else ""



# ============================================================
# v66830 LTS — exact-product reliability + runtime optimization
# Mandatory non-regression contracts:
# 1) Reference Mode product pixels/geometry are immutable.
# 2) Flexible full-fitment wording remains authoritative.
# 3) A valid product/reference project must always return a local image, never
#    a provider-painted product and never a generic no-image failure.
# ============================================================
GRAPHIC_V66830_CACHE_NAMESPACE = "v66830"
GRAPHIC_V66830_PROBE_TIMEOUT_SECONDS = 38
GRAPHIC_V66830_ROUTE_FAILURE_TTL_SECONDS = 1800


def _graphic_v66830_job_fingerprint(purpose, prompt_text="", role_items=None, output_size=""):
    parts=[GRAPHIC_ENGINE_VERSION, GRAPHIC_V66830_CACHE_NAMESPACE, str(purpose), str(output_size), str(prompt_text or "")[:12000]]
    for item in role_items or []:
        raw=b""
        file_obj=item.get("file") if isinstance(item,dict) else None
        try:
            raw=file_obj.getvalue() if file_obj is not None else b""
        except Exception:
            raw=b""
        parts.append(str((item or {}).get("role") or "")); parts.append(hashlib.sha256(raw).hexdigest() if raw else str((item or {}).get("name") or ""))
    return hashlib.sha256("|".join(parts).encode("utf-8","ignore")).hexdigest()


def _graphic_v66830_remote_record(purpose, route, started, success, **fields):
    duration=max(0.0,time.perf_counter()-started)
    row={"purpose":purpose,"route":route,"duration_seconds":round(duration,3),"success":bool(success),**fields}
    _graphic_v66100_record_attempt(**row)
    return row


def _graphic_v66830_route_health_key(route):
    return "route-health:"+hashlib.sha256(str(route).encode()).hexdigest()


def _graphic_v66830_route_is_blocked(route):
    data=_graphic_v66100_cache_get(_graphic_v66830_route_health_key(route)) or {}
    try: return float(data.get("blocked_until") or 0)>time.time()
    except Exception: return False


def _graphic_v66830_route_health_update(route, success, error_class=""):
    key=_graphic_v66830_route_health_key(route)
    old=_graphic_v66100_cache_get(key) or {}
    failures=0 if success else int(old.get("consecutive_failures") or 0)+1
    blocked_until=0
    if not success and failures>=2:
        blocked_until=time.time()+GRAPHIC_V66830_ROUTE_FAILURE_TTL_SECONDS
    payload={"route":route,"consecutive_failures":failures,"blocked_until":blocked_until,"last_error_class":str(error_class or ""),"updated_at":datetime.now(timezone.utc).isoformat()}
    _graphic_v66100_cache_put(key,payload)


def _graphic_v66830_analysis_cache_get(kind, fingerprint):
    return _graphic_v66100_cache_get(f"analysis:{GRAPHIC_V66830_CACHE_NAMESPACE}:{kind}:{fingerprint}")


def _graphic_v66830_analysis_cache_put(kind, fingerprint, payload):
    if isinstance(payload,dict):
        _graphic_v66100_cache_put(f"analysis:{GRAPHIC_V66830_CACHE_NAMESPACE}:{kind}:{fingerprint}",payload)


