def _graphic_v66830_optional_store_background(raw, cache_key, metadata):
    """Best-effort private Storage mirror; JSONB/session fallback remains authoritative."""
    if not raw: return ""
    try:
        storage=getattr(supabase,"storage",None)
        if storage is None: return ""
        bucket_name=str(_read_app_secret("GRAPHIC_CACHE_BUCKET","graphic-runtime-cache") or "graphic-runtime-cache")
        path=f"{GRAPHIC_V66830_CACHE_NAMESPACE}/{cache_key}.png"
        bucket=storage.from_(bucket_name)
        try: bucket.upload(path,raw,{"content-type":"image/png","upsert":"true"})
        except TypeError: bucket.upload(path,raw)
        return path
    except Exception as error:
        diagnostic_log("graphic_v66830_storage_mirror_unavailable",error_type=type(error).__name__)
        return ""



def _graphic_v66850_local_scene_plate(output_size, prompt_text="", vehicle_profile=None):
    """Create a deterministic premium automotive scene without provider product pixels."""
    if Image is None:
        raise RuntimeError("Pillow is unavailable for the deterministic commercial fallback.")
    from PIL import ImageDraw, ImageFilter
    width, height = [int(v) for v in _graphic_normalize_output_size_v4000(output_size).split("x", 1)]
    scene = Image.new("RGBA", (width, height), (224, 235, 247, 255))
    px = scene.load()
    horizon = int(height * 0.57)
    # Cool sky to warm sunset gradient.
    for y in range(height):
        if y < horizon:
            t = y / max(1, horizon)
            top = (183, 216, 242)
            bottom = (246, 231, 207)
        else:
            t = (y - horizon) / max(1, height - horizon)
            top = (113, 104, 91)
            bottom = (51, 47, 43)
        row = tuple(int(top[i] * (1.0 - t) + bottom[i] * t) for i in range(3)) + (255,)
        for x in range(width):
            px[x, y] = row

    draw = ImageDraw.Draw(scene, "RGBA")
    # Sun and atmospheric glow on the right, consistent with the approved reference family.
    sun_x, sun_y = int(width * 0.89), int(height * 0.43)
    glow = Image.new("RGBA", scene.size, (0, 0, 0, 0))
    gd = ImageDraw.Draw(glow, "RGBA")
    for radius, alpha in ((int(height*.16), 18), (int(height*.10), 30), (int(height*.045), 70)):
        gd.ellipse((sun_x-radius, sun_y-radius, sun_x+radius, sun_y+radius), fill=(255, 214, 144, alpha))
    glow = glow.filter(ImageFilter.GaussianBlur(max(4, int(height*.018))))
    scene = Image.alpha_composite(scene, glow)
    draw = ImageDraw.Draw(scene, "RGBA")

    # Layered mountain silhouettes.
    mountain_layers = [
        ((97, 108, 119, 235), 0.48, 0.10),
        ((72, 78, 83, 245), 0.55, 0.14),
        ((50, 51, 51, 255), 0.64, 0.09),
    ]
    for color, base_ratio, amplitude in mountain_layers:
        base = int(height * base_ratio)
        points = [(0, height)]
        steps = 12
        for i in range(steps + 1):
            x = int(width * i / steps)
            wave = (i * 37 + 11) % 7
            peak = base - int(height * amplitude * (0.25 + wave / 7.0))
            points.append((x, peak))
        points.extend([(width, height), (0, height)])
        draw.polygon(points, fill=color)

    # Rugged ground with deterministic texture.
    ground_top = int(height * 0.68)
    draw.rectangle((0, ground_top, width, height), fill=(57, 52, 47, 255))
    for i in range(340):
        x = (i * 97) % width
        y = ground_top + ((i * 53) % max(1, height-ground_top))
        r = 1 + (i % 5)
        shade = 60 + (i * 17) % 65
        draw.ellipse((x-r, y-r, x+r*2, y+r), fill=(shade, max(40, shade-8), max(35, shade-14), 150))

    out = io.BytesIO()
    scene.convert("RGB").save(out, format="PNG", optimize=True)
    return out.getvalue()


def _graphic_v66850_campaign_completeness(result, prompt_text, campaign_spec=None):
    """Evidence-based release audit.

    Missing optional manifest metadata is reported as a warning. It is not treated
    as proof that a visually rendered local campaign is invalid. Hard failures are
    limited to direct evidence of provider-generated product geometry, an absent
    rendered payload, or actual loss of required fitment tokens.
    """
    if not isinstance(result, dict) or not result.get("data_url"):
        return {"passed": False, "hard_issues": ["missing rendered image"], "warnings": []}

    spec = dict(campaign_spec or result.get("campaign_spec") or {})
    metadata = dict(result.get("layered_metadata") or {})
    zones = set(metadata.get("campaign_zones") or [])
    required_zones = {
        "logo", "headline", "compatibility_ribbon", "tagline",
        "feature_matrix", "hero_product", "bottom_benefit_bar",
    }
    hard_issues = []
    warnings = []

    missing = sorted(required_zones - zones)
    if missing:
        warnings.append("campaign-zone manifest incomplete: " + ", ".join(missing))

    compatibility = str(spec.get("compatibility") or "").strip()
    if not compatibility:
        hard_issues.append("missing full compatibility wording")

    required_tokens = list(spec.get("compatibility_required_tokens") or [])
    rendered_copy = " ".join([
        str(spec.get("headline") or ""), compatibility,
        str(spec.get("tagline") or ""), str(spec.get("screen_size") or ""),
        str(spec.get("product_designation") or ""),
    ]).casefold()
    lost = [
        str(token) for token in required_tokens
        if str(token).strip() and str(token).casefold() not in rendered_copy
    ]
    if lost:
        hard_issues.append("missing required fitment tokens: " + ", ".join(lost))

    provider_generated = metadata.get("product_pixels_provider_generated")
    if provider_generated is None:
        provider_generated = result.get("product_geometry_provider_generated")
    ai_recreated = bool(result.get("ai_product_recreated") or metadata.get("ai_product_recreated"))
    if provider_generated is True or ai_recreated:
        hard_issues.append("direct evidence of provider-generated product geometry")

    immutable = result.get("product_layer_immutable")
    exact_asset = metadata.get("exact_product_asset_mode")
    if immutable is False or exact_asset is False:
        hard_issues.append("uploaded-product authority explicitly rejected")
    elif immutable is None and exact_asset is None:
        warnings.append("immutable-product metadata unavailable; result retained unless direct violation exists")

    return {
        "passed": not hard_issues,
        "hard_issues": hard_issues,
        "issues": hard_issues,
        "warnings": warnings,
        "required_zones": sorted(required_zones),
        "observed_zones": sorted(zones),
        "policy": "v66860-evidence-based-release-gate",
    }


def _graphic_v66830_source_canvas_result(prompt_text, role_items, output_size, reference_blueprint=None, vehicle_profile=None, failure_reason=""):
    """v66850 complete local commercial boundary; never return a blank source-photo canvas."""
    if Image is None:
        raise RuntimeError("Pillow is unavailable for exact-product local fallback.")
    product_item = next(
        (item for item in role_items or [] if item.get("role") == "product_photo" and item.get("file") is not None),
        None,
    )
    if product_item is None:
        raise RuntimeError("No exact product source is available for local fallback.")

    effective_prompt = _graphic_resolve_effective_prompt_v47000(prompt_text)
    vehicle_profile = dict(vehicle_profile or {})
    reference_blueprint = _graphic_safe_reference_blueprint_v16000(reference_blueprint or {})
    spec = _graphic_verified_campaign_spec_v3300(effective_prompt, vehicle_profile)
    # Preserve all user-stated compatibility and required tokens from the v66200 authority.
    explicit = _graphic_explicit_fitment_v41100(effective_prompt)
    if explicit:
        spec["compatibility"] = explicit
    spec["compatibility_required_tokens"] = _graphic_copy_required_tokens_v36000(
        spec.get("compatibility") or effective_prompt
    )
    spec["compatibility_locked"] = True
    spec["compatibility_source"] = "v66200-full-fitment-authority"

    background = _graphic_v66850_local_scene_plate(output_size, effective_prompt, vehicle_profile)
    composed, metadata = _graphic_compose_reference_campaign_v3200(
        background,
        product_item,
        effective_prompt,
        output_size,
        spec,
        vehicle_profile,
        role_items,
        reference_blueprint=reference_blueprint,
        template_key=str((get_graphic_project_state() or {}).get("brand_template") or "autotecpro_adventure"),
    )
    created = datetime.now(timezone.utc)
    result = _graphic_build_provider_result_v3000(
        composed,
        effective_prompt,
        output_size,
        role_items,
        "v66850-local-scene+deterministic-commercial-compositor",
        reference_blueprint,
        vehicle_profile,
        corrected=True,
    )
    result["product_layer_immutable"] = True
    result["product_geometry_provider_generated"] = False
    result["ai_product_recreated"] = False
    result["strict_product_identity_lock"] = True
    result["product_transform_mode"] = "Exact Original Product"
    result["product_identity_method"] = "v66000-authoritative-mask-local-commercial-composite"
    result["campaign_spec"] = spec
    result["output_status"] = "completed_guaranteed_commercial_v66850"
    result["verification_status"] = "verified_local_commercial"
    result.setdefault("layered_metadata", {}).update(metadata or {})
    result["layered_metadata"].update({
        "engine": "v66850-complete-local-commercial-fallback",
        "exact_product_pixels": True,
        "exact_product_asset_mode": True,
        "product_master_rgb_preserved": True,
        "product_pixels_provider_generated": False,
        "ai_product_recreated": False,
        "campaign_zones": [
            "logo", "headline", "compatibility_ribbon", "tagline",
            "feature_matrix", "hero_product", "bottom_benefit_bar",
        ],
        "failure_reason": str(failure_reason)[:1200],
        "fallback_background": "deterministic-local-automotive-scene",
    })
    gate = _graphic_v66850_campaign_completeness(result, effective_prompt, spec)
    result["commercial_completeness_gate_v66850"] = gate
    result["commercial_completeness_gate_v66860"] = gate
    if not gate.get("passed"):
        raise RuntimeError(
            "Guaranteed commercial fallback failed evidence-based release gates: "
            + "; ".join(gate.get("hard_issues") or gate.get("issues") or [])
        )
    if gate.get("warnings"):
        diagnostic_log(
            "graphic_v66860_completeness_warnings",
            warnings=" | ".join(gate.get("warnings") or []),
        )
    return [result]


def _graphic_v66830_guaranteed_exact_result(prompt_text, uploaded_files=None, *, style_strength="High", forced_upload_role="Auto-detect", failure_reason=""):
    effective=_graphic_resolve_effective_prompt_v47000(prompt_text)
    role_state=_graphic_exact_reference_request_v66820(effective,uploaded_files,forced_upload_role)
    role_items=list(role_state.get("role_items") or [])
    if not role_state.get("required"):
        role_items=_graphic_recover_role_items(uploaded_files,effective,forced_role=forced_upload_role)
    output_size=_graphic_normalize_output_size_v4000(choose_graphic_image_size(effective))
    blueprint,_=_graphic_v66830_cache_blueprint(role_items,effective,style_strength)
    vehicle,_=_graphic_v66830_cache_vehicle(role_items,effective)
    try:
        result=_graphic_build_hybrid_campaign_result_v3300(effective,role_items,output_size,blueprint,vehicle)
        result["product_layer_immutable"]=True; result["product_geometry_provider_generated"]=False; result["ai_product_recreated"]=False
        source_gate=_graphic_exact_product_quality_gate_v9000(result,role_items,vehicle)
        provenance=_graphic_product_provenance_gate_v52000(result,role_items)
        result["source_fidelity_gate_v66830"]=source_gate; result["product_provenance_v66830"]=provenance
        # Hard product gates remain mandatory. Optional vehicle/layout QA may be unavailable.
        if source_gate.get("passed") and provenance.get("passed") and _graphic_exact_reference_result_safe_v66820([result]):
            result["output_status"]="completed_guaranteed_exact_composite_v66830"; result["verification_status"]="verified_local_exact"
            _graphic_save_latest_project_result(result); return [result]
    except Exception as error:
        failure_reason=(str(failure_reason)+" | guaranteed-composite:"+_graphic_compact_error_v4000(error))[-1600:]
    result=_graphic_v66830_source_canvas_result(effective,role_items,output_size,blueprint,vehicle,failure_reason)
    _graphic_save_latest_project_result(result[0]); return result


def _graphic_responses_generate_v3000(role_items, production_prompt, output_size):
    """Responses route with remembered-success fast path and bounded fallback ladder."""
    capabilities = _graphic_sdk_capabilities_v4100()
    if not capabilities.get("responses"):
        raise RuntimeError("The installed OpenAI SDK does not expose responses.create.")
    content=[{"type":"input_text","text":str(production_prompt or "")[:30000]}]
    multi_unit_contract_v68846 = _graphic_explicit_multi_unit_contract_v68846(
        production_prompt, role_items
    )
    if multi_unit_contract_v68846.get("active"):
        content.append({
            "type": "input_text",
            "text": (
                "V68846 PROVIDER ENFORCEMENT: this request requires every PRIMARY PRODUCT SOURCE "
                "and every ADDITIONAL PRODUCT UNIT to appear simultaneously as separate complete "
                "products. Required count: "
                + str(multi_unit_contract_v68846.get("required_count") or 2)
                + ". Equal-size wording requires equal visual scale and prominence. Omitting any "
                "unit is a failed output, including all fallback/recovery routes."
            ),
        })
    labels={"edit_base":"CURRENT ARTWORK TO EDIT","product_photo":"MANDATORY PRIMARY PRODUCT UNIT 1 — preserve this exact product identity, color/finish and geometry","product_variant":"MANDATORY ADDITIONAL PRODUCT UNIT — this unit MUST appear as a separate complete product when the explicit multi-unit contract is active; preserve its own color/finish, bezel, controls and geometry; NEVER use it as style, logo, background, typography or color-grade authority","style_reference":"SOLE STYLE REFERENCE — copy design language, logo treatment, layout and color grade only","logo_asset":"OFFICIAL LOGO ASSET","supporting_image":"SUPPORTING VISUAL ASSET","installation_dashboard_reference":"AUTHORITATIVE UPLOADED OEM DASHBOARD — preserve this exact cabin geometry","installation_ui_reference":"AUTHORITATIVE SCREEN UI REFERENCE"}
    usable=0
    for item in role_items or []:
        url=_graphic_role_data_url(item)
        if not url: continue
        usable+=1; content += [{"type":"input_text","text":f"{labels.get(item.get('provider_role') or item.get('role'),'REFERENCE IMAGE')}: {item.get('name') or 'image'}"},{"type":"input_image","image_url":url,"detail":"high"}]
    action="edit" if usable else "generate"
    variants=_graphic_responses_tool_variants_v4000(action,output_size,bool(usable))[:3]
    models=list(_graphic_responses_model_candidates_v4100())
    preferred=_graphic_v66100_preferred_route(action,output_size,bool(usable))
    ordered=[]
    m=re.match(r"responses-image-tool-v4100-(.+)-(\d+)$",preferred)
    if m:
        model=m.group(1); idx=int(m.group(2))
        if model in models and 1<=idx<=len(variants): ordered.append((model,idx,variants[idx-1],True))
    ordered += [(model,idx,tool,False) for model in models for idx,tool in enumerate(variants,1) if not any(x[0]==model and x[1]==idx for x in ordered)]
    errors=[]; response_client=client.with_options(timeout=GRAPHIC_IMAGE_TIMEOUT_SECONDS,max_retries=0)
    for model,idx,tool,fast in ordered:
        request={"model":model,"input":[{"role":"user","content":content}],"tools":[tool],"max_output_tokens":1200}
        if idx==1: request["tool_choice"]={"type":"image_generation"}
        started=time.perf_counter()
        try:
            response=response_client.responses.create(**request); images=_graphic_response_image_bytes_v4000(response)
            duration=time.perf_counter()-started
            _graphic_v66100_record_attempt(route="responses",model=model,schema_variant=idx,duration_seconds=round(duration,3),success=bool(images),preferred_fast_path=fast,validation_purpose="generation")
            if images:
                route=f"responses-image-tool-v4100-{model}-{idx}"; _graphic_v66100_remember_route(action,output_size,bool(usable),route); return images,route
            errors.append(f"{model}/variant-{idx}:no-image")
        except Exception as error:
            duration=time.perf_counter()-started; compact=_graphic_compact_error_v4000(error)
            _graphic_v66100_record_attempt(route="responses",model=model,schema_variant=idx,duration_seconds=round(duration,3),success=False,error_class=type(error).__name__,error=compact,preferred_fast_path=fast,validation_purpose="generation")
            errors.append(f"{model}/variant-{idx}:{type(error).__name__}:{compact}")
    raise RuntimeError("Responses image generation failed: "+" | ".join(errors[-4:]))





def _graphic_images_api_fallback_v3000(role_items, production_prompt, output_size):
    """Images API fallback with bounded multi-image and single-image routes."""
    capabilities = _graphic_sdk_capabilities_v4100()
    image_client = client.with_options(timeout=GRAPHIC_IMAGE_TIMEOUT_SECONDS, max_retries=0)
    size = _graphic_normalize_output_size_v4000(output_size)
    errors = []

    product_files = [i.get("file") for i in role_items or [] if i.get("role") == "product_photo" and i.get("file") is not None]
    product_variant_files_v68846 = [i.get("file") for i in role_items or [] if i.get("role") == "product_variant" and i.get("file") is not None]
    style_files = [i.get("file") for i in role_items or [] if i.get("role") == "style_reference" and i.get("file") is not None]
    edit_files = [i.get("file") for i in role_items or [] if i.get("role") == "edit_base" and i.get("file") is not None]
    other_files = [i.get("file") for i in role_items or [] if i.get("file") is not None and i.get("role") not in {"product_photo", "product_variant", "style_reference", "edit_base"}]
    explicit_multi_unit_v68846 = bool(
        _graphic_explicit_multi_unit_contract_v68846(production_prompt, role_items).get("active")
    )
    mandatory_product_files_v68846 = (
        product_files[:1] + product_variant_files_v68846[:3]
        if explicit_multi_unit_v68846
        else product_files[:1]
    )

    groups = []
    for label, files_group in (
        ("all-mandatory-products-v68846", edit_files[:1] + mandatory_product_files_v68846 + style_files[:2] + other_files[:1]),
        ("mandatory-products-plus-style-v68846", mandatory_product_files_v68846 + style_files[:1]),
        ("mandatory-products-only-v68846", mandatory_product_files_v68846),
        ("edit-only", edit_files[:1]),
    ):
        clean = [f for f in files_group if f is not None]
        signature = tuple(id(f) for f in clean)
        if clean and signature not in {sig for _, _, sig in groups}:
            groups.append((label, clean, signature))

    if capabilities.get("images_edit"):
        for label, files_group, _ in groups[:4]:
            references = prepare_graphic_reference_images(files_group)
            if not references:
                continue
            image_input = references if len(references) > 1 else references[0]
            for index, extras in enumerate((
                {"input_fidelity": "high", "quality": "high"},
                {},
            ), start=1):
                try:
                    for reference in references:
                        reference.seek(0)
                    diagnostic_log("graphic_v4100_images_edit_attempt", route=label, variant=index, reference_count=len(references), fields=sorted(extras))
                    result = image_client.images.edit(
                        model=GRAPHIC_IMAGE_MODEL,
                        image=image_input,
                        prompt=str(production_prompt or "")[:32000],
                        n=1,
                        size=size,
                        **extras,
                    )
                    images = _graphic_collect_result_bytes(result)
                    if images:
                        return images, f"images-edit-api-v4100-{label}-{index}"
                    errors.append(f"edit/{label}/{index}:no-image")
                except Exception as error:
                    compact = _graphic_compact_error_v4000(error)
                    errors.append(f"edit/{label}/{index}:{type(error).__name__}:{compact}")
                    diagnostic_log("graphic_v4100_images_edit_attempt_failed", route=label, variant=index, error_type=type(error).__name__, error=compact)

    if capabilities.get("images_generate") and not groups:
        for index, extras in enumerate(({"quality": "high"}, {}), start=1):
            try:
                diagnostic_log("graphic_v4100_images_generate_attempt", variant=index, fields=sorted(extras))
                result = image_client.images.generate(
                    model=GRAPHIC_IMAGE_MODEL,
                    prompt=str(production_prompt or "")[:32000],
                    n=1,
                    size=size,
                    **extras,
                )
                images = _graphic_collect_result_bytes(result)
                if images:
                    return images, f"images-generate-api-v4100-{index}"
                errors.append(f"generate/{index}:no-image")
            except Exception as error:
                compact = _graphic_compact_error_v4000(error)
                errors.append(f"generate/{index}:{type(error).__name__}:{compact}")
                diagnostic_log("graphic_v4100_images_generate_attempt_failed", variant=index, error_type=type(error).__name__, error=compact)

    if not capabilities.get("images_edit") and groups:
        errors.append("installed SDK does not expose images.edit")
    if not capabilities.get("images_generate") and not groups:
        errors.append("installed SDK does not expose images.generate")
    raise RuntimeError("Images API fallback failed: " + " | ".join(errors[-5:]))


def _graphic_build_provider_result_v3000(
    raw_bytes,
    prompt_text,
    output_size,
    role_items,
    provider_route,
    reference_blueprint,
    vehicle_profile,
    quality_review=None,
    corrected=False,
):
    png_bytes = image_bytes_to_png(raw_bytes)
    if not png_bytes:
        raise RuntimeError("The image provider returned unreadable image data.")
    png_bytes, brand_logo_applied, brand_logo_position = apply_autotecpro_brand_logo(
        png_bytes, prompt_text=prompt_text
    )
    created_at = datetime.now(timezone.utc)
    filename = graphic_image_filename(prompt_text, created_at)
    data_url = "data:image/png;base64," + base64.b64encode(png_bytes).decode("ascii")
    result = {
        "name": filename,
        "filename": filename,
        "data_url": data_url,
        "generated": True,
        "professional_layered_studio": True,
        "provider_fallback_used": False,
        "output_status": "completed_after_correction" if corrected else "completed",
        "provider_route": provider_route,
        "strict_product_identity_lock": any(item.get("role") == "product_photo" for item in role_items),
        "product_identity_method": "high_fidelity_conversational_image_edit",
        "layered_engine_version": GRAPHIC_LAYERED_ENGINE_VERSION,
        "layered_metadata": {
            "engine": "chatgpt-style-conversational-image-v3000",
            "complete_provider_artwork": True,
            "reference_faithful_edit": any(item.get("role") == "style_reference" for item in role_items),
            "followup_edit": any(item.get("role") == "edit_base" for item in role_items),
            "explicit_vehicle_lock": bool((vehicle_profile or {}).get("hard_vehicle_lock")),
            "target_vehicle": str((vehicle_profile or {}).get("explicit_display_name") or ""),
            "reference_content_leakage_prohibited": True,
        },
        "vehicle_profile": vehicle_profile,
        "vehicle_research_version": str((vehicle_profile or {}).get("research_version") or ""),
        "prompt": prompt_text,
        "created_at": created_at.isoformat(),
        "model": GRAPHIC_IMAGE_MODEL,
        "size": output_size,
        "resolution": output_size,
        "mime_type": "image/png",
        "official_brand_logo_applied": bool(brand_logo_applied),
        "official_brand_logo_position": brand_logo_position,
        "official_brand_logo_file": AUTOTECPRO_BRAND_LOGO_FILE.name if brand_logo_applied else "",
        "style_memory_status": "not_reviewed",
        "style_collection": extract_graphic_style_collection_name(prompt_text) or "",
        "campaign_name": extract_graphic_campaign_name(prompt_text),
        "special_workflow": detect_graphic_special_workflow(prompt_text),
        "product_transform_mode": "High Fidelity Conversational Edit",
        "reference_blueprint": reference_blueprint,
        "reference_analysis_version": str((reference_blueprint or {}).get("analysis_version") or ""),
        "upload_roles": [{"name": item.get("name"), "role": item.get("role")} for item in role_items],
        "quality_review": quality_review or {},
        "auto_corrected_after_review": bool(corrected),
        "style_memory_fingerprint": hashlib.sha256((data_url + prompt_text).encode("utf-8")).hexdigest(),
    }
    return result




def _graphic_save_latest_project_result(image):
    """Persist one full active canvas and lightweight version metadata.

    Older versions remain traceable by metadata but do not retain duplicate full
    data URLs in Graphic project state. The generated image is still preserved in the
    conversation message/history path exactly as before.
    """
    if (
        not isinstance(image, dict)
        or not str(image.get("data_url") or "").startswith("data:image/")
    ):
        return

    state = get_graphic_project_state()
    raw, _mime = data_url_to_bytes(str(image.get("data_url") or ""))
    canvas_id = hashlib.sha256(
        raw or str(image.get("data_url") or "").encode()
    ).hexdigest()[:20]
    next_version = int(state.get("current_canvas_version") or 0) + 1

    snapshot = {
        key: image.get(key)
        for key in (
            "name", "filename", "data_url", "prompt", "created_at", "resolution",
            "mime_type", "provider_route", "output_status", "quality_review",
            "reference_geometry", "campaign_spec", "vehicle_validation",
            "zone_completeness", "graphic_engine_version", "verification_status",
            "verification_warning", "edit_mode", "edit_directive",
            "background_data_url", "product_render_mode", "ai_product_recreated",
            "product_structure_validation", "generation_route", "provider_route",
        )
    }
    snapshot["canvas_id"] = canvas_id
    snapshot["canvas_version"] = next_version

    history = [
        item for item in (state.get("generation_history") or [])
        if isinstance(item, dict)
    ]
    compact_snapshot = {
        key: value
        for key, value in snapshot.items()
        if key not in {"data_url", "background_data_url"}
    }
    compact_snapshot["full_canvas_in_active_state"] = True
    history.append(compact_snapshot)

    state["generation_history"] = history[-10:]
    state["latest_generated"] = snapshot
    state["current_canvas_id"] = canvas_id
    state["current_canvas_version"] = next_version
    state["stage"] = "generated"
    state["last_error"] = ""
    state["updated_at"] = datetime.now(timezone.utc).isoformat()
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state







def _graphic_reference_layout_blueprint_v9000(reference_blueprint=None, template_key=""):
    """Return bounded reference-locked geometry for deterministic composition.

    v13000 consumes normalized boxes produced by the reference analyst instead of
    merely storing them. Missing or malformed fields fall back to the approved
    AutoTecPro commercial hierarchy represented by the supplied reference artwork.
    Reference pixels and reference content remain prohibited.
    """
    bp = dict(reference_blueprint or {})
    cfg = _graphic_template_config_v8200(template_key)
    defaults = {
        "logo_box": [0.022, 0.025, 0.205, 0.105],
        "headline_box": [0.022, 0.145, 0.535, 0.090],
        "compatibility_box": [0.020, 0.235, 0.435, 0.055],
        "tagline_box": [0.022, 0.300, 0.535, 0.045],
        "feature_matrix_box": [0.565, 0.025, 0.410, 0.315],
        "hero_product_box": [0.018, 0.305, 0.682, 0.575],
        "vehicle_box": [0.695, 0.435, 0.275, 0.335],
        "bottom_bar_box": [0.035, 0.875, 0.930, 0.110],
    }
    aliases = {
        "product_box": "hero_product_box", "hero_box": "hero_product_box",
        "product": "hero_product_box", "hero_product": "hero_product_box",
        "copy_box": "headline_box", "title_box": "headline_box",
        "features_box": "feature_matrix_box", "feature_grid_box": "feature_matrix_box",
        "benefit_bar_box": "bottom_bar_box", "footer_box": "bottom_bar_box",
        "compatibility_ribbon_box": "compatibility_box", "subheadline_box": "tagline_box",
    }

    def clean_box(raw, fallback):
        if not isinstance(raw, (list, tuple)) or len(raw) != 4:
            return list(fallback)
        try:
            vals = [float(v) for v in raw]
            if max(abs(v) for v in vals) > 1.5:
                vals = [v / 100.0 for v in vals]
            x, y, w, h = vals
            x = max(0.0, min(0.94, x)); y = max(0.0, min(0.94, y))
            w = max(0.04, min(1.0 - x, w)); h = max(0.025, min(1.0 - y, h))
            return [round(x, 6), round(y, 6), round(w, 6), round(h, 6)]
        except Exception:
            return list(fallback)

    candidates = bp.get("normalized_boxes") or bp.get("layout_boxes") or bp.get("zones") or {}
    if isinstance(candidates, dict):
        for raw_key, raw_box in candidates.items():
            key = aliases.get(str(raw_key).strip().lower(), str(raw_key).strip().lower())
            if key in defaults:
                defaults[key] = clean_box(raw_box, defaults[key])

    # Backward-compatible scalar fields from earlier analyzers.
    scalar_map = {
        "top_ratio": ("headline_box", 1),
        "bar_ratio": ("bottom_bar_box", 1),
        "hero_left": ("hero_product_box", 0),
        "hero_top": ("hero_product_box", 1),
        "feature_left": ("feature_matrix_box", 0),
        "feature_top": ("feature_matrix_box", 1),
        "feature_width": ("feature_matrix_box", 2),
        "feature_height": ("feature_matrix_box", 3),
    }
    for scalar, (box_key, index) in scalar_map.items():
        if scalar not in bp:
            continue
        try:
            value = float(bp.get(scalar))
            if value > 1.5:
                value /= 100.0
            box = list(defaults[box_key]); box[index] = value
            defaults[box_key] = clean_box(box, defaults[box_key])
        except Exception:
            pass

    # Commercial guardrails: the reference product must remain dominant and the
    # information zones must stay substantial. These limits prevent sparse slide-like output.
    hero = list(defaults["hero_product_box"])
    hero[2] = max(hero[2], 0.64)
    hero[3] = max(hero[3], 0.56)
    hero[0] = min(hero[0], 0.045)
    hero[1] = min(max(hero[1], 0.285), 0.37)
    defaults["hero_product_box"] = clean_box(hero, defaults["hero_product_box"])

    features = list(defaults["feature_matrix_box"])
    features[2] = max(features[2], 0.385); features[3] = max(features[3], 0.285)
    defaults["feature_matrix_box"] = clean_box(features, defaults["feature_matrix_box"])

    footer = list(defaults["bottom_bar_box"])
    footer[2] = max(footer[2], 0.90); footer[3] = max(footer[3], 0.102)
    defaults["bottom_bar_box"] = clean_box(footer, defaults["bottom_bar_box"])

    defaults.update({
        "source": "reference_blueprint" if bp else "approved_reference_fallback",
        "content_policy": "geometry_only_no_reference_content",
        "reference_locked": bool(bp),
        "template_product_scale": float(cfg.get("product_scale", 1.0) or 1.0),
    })
    return defaults




def _graphic_product_source_signature_v9000(product_item):
    raw=_graphic_uploaded_file_bytes((product_item or {}).get("file"))
    result={"sha256":hashlib.sha256(raw).hexdigest() if raw else "","width":0,"height":0,"aspect_ratio":0.0}
    if raw and Image is not None:
        try:
            with Image.open(io.BytesIO(raw)) as im:
                im=ImageOps.exif_transpose(im)
                result.update({"width":im.width,"height":im.height,"aspect_ratio":round(im.width/max(1,im.height),6)})
        except Exception: pass
    return result



def _graphic_segmentation_diagnostics_v10000(product_item):
    """Return deterministic cutout diagnostics without altering source pixels.

    The diagnostic is intentionally local and bounded. It helps distinguish a clean
    transparent cutout from the safe presentation-card fallback used when neutral
    background removal is not reliable.
    """
    info = {
        "available": False,
        "transparent_cutout": False,
        "alpha_coverage_ratio": 0.0,
        "opaque_coverage_ratio": 0.0,
        "edge_pixel_ratio": 0.0,
        "source_aspect_ratio": 0.0,
        "cutout_aspect_ratio": 0.0,
        "aspect_ratio_delta": 0.0,
        "safe_for_exact_composite": False,
    }
    if Image is None or not product_item:
        return info
    try:
        source = _graphic_product_source_signature_v9000(product_item)
        layer, transparent = _graphic_open_product_layer_v3300(product_item.get("file"))
        if layer is None:
            return info
        layer = ImageOps.exif_transpose(layer).convert("RGBA")
        alpha = layer.getchannel("A")
        hist = alpha.histogram()
        total = max(1, layer.width * layer.height)
        transparent_count = sum(hist[:16])
        opaque_count = sum(hist[240:])
        edge_count = sum(hist[16:240])
        source_ratio = float(source.get("aspect_ratio") or 0.0)
        cutout_ratio = layer.width / max(1, layer.height)
        info.update({
            "available": True,
            "transparent_cutout": bool(transparent),
            "alpha_coverage_ratio": round(1.0 - transparent_count / total, 6),
            "opaque_coverage_ratio": round(opaque_count / total, 6),
            "edge_pixel_ratio": round(edge_count / total, 6),
            "source_aspect_ratio": round(source_ratio, 6),
            "cutout_aspect_ratio": round(cutout_ratio, 6),
            "aspect_ratio_delta": round(abs(source_ratio - cutout_ratio), 6) if source_ratio else 0.0,
            "safe_for_exact_composite": bool(
                layer.width > 8 and layer.height > 8 and opaque_count > total * 0.04
            ),
        })
    except Exception as error:
        diagnostic_log(
            "graphic_v10000_segmentation_diagnostics_failed",
            error_type=type(error).__name__,
            error=str(error),
        )
    return info


def _graphic_expected_product_layer_v10000(product_item, target_width, target_height, canvas_height=0):
    """Rebuild the exact product layer exactly as the deterministic compositor does."""
    if Image is None or not product_item or target_width <= 0 or target_height <= 0:
        return None
    try:
        product, transparent = _graphic_open_product_layer_v3300(product_item.get("file"))
        if product is None:
            return None
        product = ImageOps.exif_transpose(product).convert("RGBA")
        product, _trim = _graphic_trim_visible_product_canvas_v14000(product, transparent=transparent)
        if not transparent:
            pad = max(8, int((canvas_height or target_height) * 0.008))
            card = Image.new(
                "RGBA",
                (product.width + pad * 2, product.height + pad * 2),
                (250, 251, 253, 245),
            )
            card.alpha_composite(product, (pad, pad))
            product = card
        elif product.getchannel("A").getbbox():
            product = product.crop(product.getchannel("A").getbbox())
        return _graphic_premultiplied_resize_v20000(
            product, (int(target_width), int(target_height)), Image.Resampling.LANCZOS
        )
    except Exception as error:
        diagnostic_log(
            "graphic_v10000_expected_product_layer_failed",
            error_type=type(error).__name__,
            error=str(error),
        )
        return None


def _graphic_exact_product_visual_match_v10000(result, role_items):
    """Compare final product-region pixels with the exact uploaded product layer.

    Only high-opacity product pixels are compared, so the generated background and
    local grounding shadow do not affect the score. This is a deterministic check and
    does not add a model request or generation latency.
    """
    report = {
        "available": False,
        "passed": False,
        "score": 0.0,
        "mean_absolute_error": None,
        "sample_count": 0,
        "threshold": 0.90,
        "reason": "visual comparison unavailable",
    }
    if Image is None:
        return report
    try:
        metadata = dict((result or {}).get("layered_metadata") or {})
        box = list(metadata.get("product_box") or [])
        if len(box) != 4:
            report["reason"] = "product box unavailable"
            return report
        x, y, width, height = [int(round(float(value))) for value in box]
        if width <= 0 or height <= 0:
            report["reason"] = "invalid product box"
            return report
        product_item = next(
            (item for item in (role_items or []) if item.get("role") == "product_photo"),
            None,
        )
        canvas = list(metadata.get("canvas_size") or [])
        canvas_height = int(canvas[1]) if len(canvas) == 2 and canvas[1] else 0
        expected = _graphic_expected_product_layer_v10000(product_item, width, height, canvas_height)
        if expected is None:
            report["reason"] = "expected product layer unavailable"
            return report
        final_raw, _ = data_url_to_bytes(str((result or {}).get("data_url") or ""))
        if not final_raw:
            report["reason"] = "final image bytes unavailable"
            return report
        with Image.open(io.BytesIO(final_raw)) as final_image:
            final_image = ImageOps.exif_transpose(final_image).convert("RGB")
            if x < 0 or y < 0 or x + width > final_image.width or y + height > final_image.height:
                report["reason"] = "product region is cropped"
                return report
            observed = final_image.crop((x, y, x + width, y + height))
        expected_rgb = expected.convert("RGB")
        alpha = expected.getchannel("A")

        # Downsample the comparison to a bounded workload while preserving structure.
        max_side = 420
        scale = min(1.0, max_side / max(width, height))
        if scale < 1.0:
            size = (max(1, int(width * scale)), max(1, int(height * scale)))
            observed = observed.resize(size, Image.Resampling.BILINEAR)
            expected_rgb = expected_rgb.resize(size, Image.Resampling.BILINEAR)
            alpha = alpha.resize(size, Image.Resampling.BILINEAR)

        obs_pixels = observed.load()
        exp_pixels = expected_rgb.load()
        mask_pixels = alpha.load()
        sample_count = 0
        absolute_error = 0
        step = 1
        for yy in range(observed.height):
            for xx in range(observed.width):
                if mask_pixels[xx, yy] < 235:
                    continue
                observed_pixel = obs_pixels[xx, yy]
                expected_pixel = exp_pixels[xx, yy]
                absolute_error += (
                    abs(int(observed_pixel[0]) - int(expected_pixel[0]))
                    + abs(int(observed_pixel[1]) - int(expected_pixel[1]))
                    + abs(int(observed_pixel[2]) - int(expected_pixel[2]))
                )
                sample_count += 3
        if sample_count < 300:
            report["reason"] = "insufficient opaque product pixels"
            return report
        mean_error = absolute_error / sample_count
        score = max(0.0, min(1.0, 1.0 - mean_error / 255.0))
        report.update({
            "available": True,
            "passed": score >= report["threshold"],
            "score": round(score, 6),
            "mean_absolute_error": round(mean_error, 4),
            "sample_count": sample_count,
            "reason": "exact product pixels confirmed" if score >= report["threshold"] else "final product pixels differ from the uploaded source",
        })
    except Exception as error:
        report["reason"] = str(error)[:240]
        diagnostic_log(
            "graphic_v10000_visual_match_failed",
            error_type=type(error).__name__,
            error=str(error),
        )
    return report


def _graphic_runtime_audit_v10000(result, *, route="", provider_calls=0, retries=0, stages=None):
    """Attach compact production telemetry to each output without exposing secrets."""
    stages = {str(key): round(float(value or 0.0), 3) for key, value in (stages or {}).items()}
    return {
        "engine": GRAPHIC_ENGINE_VERSION,
        "route": str(route or ""),
        "provider_calls": int(provider_calls or 0),
        "retries": int(retries or 0),
        "stage_seconds": stages,
        "verification_status": str((result or {}).get("verification_status") or ""),
        "output_status": str((result or {}).get("output_status") or ""),
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }


# v23000: restored v20100 visual-baseline behavior for _graphic_exact_product_quality_gate_v9000.
def _graphic_exact_product_quality_gate_v9000(result, role_items, vehicle_profile=None):
    """Fail closed on product-source mismatch, structural drift, cropping and role leakage."""
    metadata = dict((result or {}).get("layered_metadata") or {})
    product_item = next(
        (item for item in (role_items or []) if item.get("role") == "product_photo"),
        None,
    )
    source = _graphic_product_source_signature_v9000(product_item)
    box = list(metadata.get("product_box") or [])
    canvas = list(metadata.get("canvas_size") or [])
    issues = []
    if not metadata.get("exact_product_pixels"):
        issues.append("exact product pixels not confirmed")
    if metadata.get("exact_product_asset_mode") is not True:
        issues.append("Graphic Engine 8 exact-product asset mode not confirmed")
    if metadata.get("product_master_rgb_preserved") is not True:
        issues.append("untouched product master RGB preservation not confirmed")
    if metadata.get("product_pixels_provider_generated") is not False:
        issues.append("provider-generated product pixels are prohibited in exact-product mode")
    if metadata.get("product_ai_reconstruction_prohibited") is not True:
        issues.append("exact-product reconstruction prohibition not confirmed")
    if source.get("sha256") and metadata.get("product_source_sha256") != source.get("sha256"):
        issues.append("product source fingerprint mismatch")
    required = {
        "logo", "headline", "compatibility_ribbon", "tagline", "feature_matrix",
        "hero_product", "target_vehicle", "bottom_benefit_bar",
    }
    if not required.issubset({str(item) for item in metadata.get("campaign_zones") or []}):
        issues.append("required campaign zones incomplete")
    if len(box) == 4 and len(canvas) == 2 and canvas[0] and canvas[1]:
        area = (box[2] * box[3]) / (canvas[0] * canvas[1])
        width_ratio = box[2] / canvas[0]
        height_ratio = box[3] / canvas[1]
        source_ratio = float(source.get("aspect_ratio") or 0.0)
        reference_driven = any(item.get("role") == "style_reference" for item in (role_items or []))
        minimum_height = 0.48 if reference_driven else 0.44
        minimum_width = 0.18 if source_ratio < 0.90 else 0.28
        if height_ratio < minimum_height or width_ratio < minimum_width:
            issues.append("hero product too small for the commercial reference hierarchy")
        if box[0] < 0 or box[1] < 0 or box[0] + box[2] > canvas[0] or box[1] + box[3] > canvas[1]:
            issues.append("hero product cropped")
        rendered_ratio = float(box[2]) / max(1.0, float(box[3]))
        visible_source_ratio = float(metadata.get("product_source_visible_aspect_ratio") or 0.0)
        authoritative_ratio = visible_source_ratio or source_ratio
        ratio_error = abs(authoritative_ratio - rendered_ratio) / max(authoritative_ratio, 0.001) if authoritative_ratio else 0.0
        if authoritative_ratio and ratio_error > 0.012:
            issues.append("hero product aspect ratio changed")
        if metadata.get("product_ratio_preserved") is False:
            issues.append("exact product source ratio was not preserved")
    else:
        issues.append("product geometry metadata unavailable")

    integrity = _graphic_role_integrity_v8300(role_items)
    if not integrity.get("valid", integrity.get("passed", True)):
        issues.append("reference/product role integrity failed")

    vehicle = (result or {}).get("vehicle_validation") or {}
    hard_vehicle = bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    if hard_vehicle and not _graphic_validation_is_unavailable_v4100(vehicle) and vehicle.get("verified") is not True:
        issues.append("target vehicle validation failed")

    visual_match = _graphic_exact_product_visual_match_v10000(result, role_items)
    if not visual_match.get("available"):
        issues.append("exact product visual comparison unavailable")
    elif not visual_match.get("passed"):
        issues.append("exact product visual comparison failed")

    segmentation = _graphic_segmentation_diagnostics_v10000(product_item)
    if segmentation.get("available") and not segmentation.get("safe_for_exact_composite"):
        issues.append("product segmentation is not safe for exact composition")

    engineering_geometry = _graphic_engineering_geometry_gate_v20000(result, role_items)
    if not engineering_geometry.get("passed"):
        issues.extend("engineering geometry: " + str(x) for x in (engineering_geometry.get("issues") or []))

    return {
        "passed": not issues,
        "issues": issues,
        "product_source": source,
        "visual_match": visual_match,
        "segmentation": segmentation,
        "engineering_geometry_gate": engineering_geometry,
        "hero_dominance": not any("hero product" in issue for issue in issues),
        "reference_leakage_blocked": bool(integrity.get("valid", integrity.get("passed", True))),
        "engine": "v20000-engine6-exact-product-quality-gate",
    }

def _graphic_render_mode_v9000(product_mode, has_style=False):
    if (product_mode or {}).get("recreates_product"): return "ai_product_recreation"
    if (product_mode or {}).get("exact_product") and has_style: return "commercial_recreation"
    if (product_mode or {}).get("exact_product"): return "autotecpro_studio"
    return "fully_generative_concept"



