def _graphic_build_hybrid_campaign_result_v3200(prompt_text, role_items, output_size, reference_blueprint, vehicle_profile):
    product_item=next((item for item in role_items if item.get("role")=="product_photo"),None)
    if not product_item:
        raise RuntimeError("A product source is required for the reference-locked campaign engine.")
    spec=_graphic_campaign_spec(prompt_text,vehicle_profile)
    state=get_graphic_project_state(); template_key=str(state.get("brand_template") or "autotecpro_adventure")
    background,route=_graphic_generate_background_plate_v3200(
        role_items,prompt_text,output_size,vehicle_profile,spec,reference_blueprint,template_key
    )
    composed,metadata=_graphic_compose_reference_campaign_v3200(
        background, product_item, prompt_text, output_size, spec, vehicle_profile,
        role_items, reference_blueprint=reference_blueprint, template_key=template_key,
        product_dna=state.get("product_dna") or {}
    )
    result=_graphic_build_provider_result_v3000(
        composed,prompt_text,output_size,role_items,
        route+"+strict-commercial-composer-v6000",reference_blueprint,vehicle_profile,
        corrected=True,
    )
    result["product_identity_method"]="exact_source_pixel_composite"
    result["background_data_url"] = "data:image/png;base64," + base64.b64encode(background).decode("ascii")
    result["generation_route"] = route + "+strict-commercial-composer-v7100"
    result["layered_metadata"].update(metadata)
    scene_plan = _graphic_scene_intelligence_v40000(prompt_text, state.get("studio_creative_brief") or {}, vehicle_profile, metadata.get("ultimate_product_fingerprint") or {})
    result["layered_metadata"]["ultimate_scene_intelligence"] = scene_plan
    quality = _graphic_quality_verification_v40000(result["layered_metadata"])
    result["layered_metadata"]["ultimate_quality_verification"] = quality
    result["layered_metadata"]["ultimate_adaptive_retry_plan"] = _graphic_adaptive_retry_plan_v40000(quality)
    result["layered_metadata"]["ultimate_multipass_trace"] = _graphic_multipass_trace_v40000(
        result["layered_metadata"].get("graphic_design_mode"),
        metadata.get("ultimate_product_fingerprint") or {},
        metadata.get("ultimate_material_fingerprint") or {},
        scene_plan, quality,
    )
    result["output_status"]="completed_reference_locked_campaign" if quality.get("passed") else "completed_with_quality_gate_warning"
    result["campaign_spec"]=spec
    return result


def _graphic_review_scores_v3200(review, has_product, has_style, hard_vehicle_lock):
    def score(name, default=100):
        try: return int(float((review or {}).get(name,default)))
        except Exception: return default
    scores={
        "product":score("product_accuracy_score"),
        "style":score("style_adherence_score"),
        "layout":score("layout_adherence_score"),
        "vehicle":score("vehicle_accuracy_score"),
        "density":score("content_density_score"),
        "text":score("text_quality_score"),
    }
    failed=(
        (has_product and scores["product"]<88)
        or (has_style and min(scores["style"],scores["layout"],scores["density"])<84)
        or (hard_vehicle_lock and scores["vehicle"]<97)
        or scores["text"]<74
        or not bool((review or {}).get("passed",True))
    )
    return scores,failed

def _generate_graphic_marketing_images_advanced_v3200(prompt_text, uploaded_files=None, *, use_approved_style=True,
                                      preserve_product=True, style_strength="High",
                                      forced_upload_role="Auto-detect", quality_retry=True,
                                      product_transform_mode="Auto", professional_layered_studio=True):
    """Authoritative ChatGPT-style Graphic creation and conversational editing pipeline."""
    prompt_text = str(prompt_text or "").strip()
    if not prompt_text:
        raise ValueError("Please enter an image-generation or editing command.")
    output_size = choose_graphic_image_size(prompt_text)
    role_items = _graphic_project_role_items(uploaded_files, prompt_text, forced_upload_role)
    has_product = any(item.get("role") == "product_photo" for item in role_items)
    has_style = any(item.get("role") == "style_reference" for item in role_items)
    has_edit_base = any(item.get("role") == "edit_base" for item in role_items)
    if preserve_product and has_style and not has_product and not has_edit_base:
        raise RuntimeError(
            "The reference advertisements are saved, but the product source could not be identified. "
            "Please upload the product photo once more, then select Create."
        )
    diagnostic_log(
        "graphic_v3000_role_resolution",
        roles=[f"{item.get('role')}:{item.get('name')}" for item in role_items],
        product=has_product,
        style=has_style,
        edit_base=has_edit_base,
    )
    reference_blueprint = _graphic_safe_optional_call(
        "graphic_v3000_reference_analysis_failed_open",
        lambda: analyze_graphic_reference_blueprint(
            role_items, prompt_text=prompt_text, style_strength=style_strength
        ),
        {},
    ) if has_style else {}
    reference_blueprint = _graphic_safe_reference_blueprint_v16000(reference_blueprint) if has_style else {}
    if has_style:
        _graphic_project_style_dna_v16000(reference_blueprint)
    vehicle_profile = _graphic_safe_optional_call(
        "graphic_v3100_vehicle_research_failed_open",
        lambda: research_graphic_vehicle_profile(role_items, prompt_text),
        {},
    ) if has_product else {}
    # Explicit user statements persisted from earlier turns always override visual guesses.
    vehicle_profile = _graphic_resolve_vehicle_lock(prompt_text, vehicle_profile)
    rejected_guidance = _graphic_safe_optional_call(
        "graphic_v3000_rejection_guidance_failed_open",
        _graphic_session_rejection_guidance,
        "",
    )
    production_prompt = _graphic_chatgpt_production_prompt(
        prompt_text,
        role_items,
        output_size,
        reference_blueprint=reference_blueprint,
        vehicle_profile=vehicle_profile,
        rejected_guidance=rejected_guidance,
    )
    provider_errors = []
    try:
        raw_images, provider_route = _graphic_responses_generate_v3000(
            role_items, production_prompt, output_size
        )
    except Exception as error:
        provider_errors.append(f"responses:{type(error).__name__}")
        diagnostic_log(
            "graphic_v3000_responses_failed",
            error_type=type(error).__name__, error=error,
        )
        try:
            raw_images, provider_route = _graphic_images_api_fallback_v3000(
                role_items, production_prompt, output_size
            )
        except Exception as fallback_error:
            provider_errors.append(f"images:{type(fallback_error).__name__}")
            diagnostic_log(
                "graphic_v3000_images_api_failed",
                error_type=type(fallback_error).__name__, error=fallback_error,
            )
            state = get_graphic_project_state()
            state["stage"] = "ready_to_generate"
            state["last_error"] = ",".join(provider_errors)
            state["updated_at"] = datetime.now(timezone.utc).isoformat()
            st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
            raise RuntimeError(
                "The professional image service did not return a completed artwork. "
                "Your product, references, and project state are preserved. Please select Regenerate or type ‘Create it again.’"
            ) from fallback_error
    if not raw_images:
        raise RuntimeError("The image service returned no completed artwork.")
    initial = _graphic_build_provider_result_v3000(
        raw_images[0], prompt_text, output_size, role_items, provider_route,
        reference_blueprint, vehicle_profile,
    )
    review = _graphic_safe_optional_call(
        "graphic_v3000_quality_review_failed_open",
        lambda: review_graphic_output_accuracy(
            initial.get("data_url"), role_items, prompt_text,
            "High Fidelity Conversational Edit", reference_blueprint=reference_blueprint,
        ),
        {},
    )
    initial["quality_review"] = review or {}
    corrected_result = None
    scores, needs_correction = _graphic_review_scores_v3200(
        review, has_product, has_style, bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    )
    diagnostic_log("graphic_v3200_initial_review", **scores, needs_correction=needs_correction)
    if quality_retry and review:
        correction = str(review.get("correction_prompt") or "").strip()
        if needs_correction and correction:
            current_raw, current_mime = data_url_to_bytes(initial.get("data_url"))
            correction_items = list(role_items)
            if current_raw:
                current_upload = ManagedUploadedFile(
                    current_raw, "current_generated_artwork.png", current_mime or "image/png",
                    graphic_role="edit_base", graphic_asset_id=hashlib.sha256(current_raw).hexdigest(),
                )
                correction_items = [{
                    "file": current_upload,
                    "name": current_upload.name,
                    "role": "edit_base",
                    "reason": "current output for one controlled correction pass",
                }] + [item for item in role_items if item.get("role") != "edit_base"]
            correction_prompt = _graphic_chatgpt_production_prompt(
                prompt_text,
                correction_items,
                output_size,
                reference_blueprint=reference_blueprint,
                vehicle_profile=vehicle_profile,
                rejected_guidance=rejected_guidance,
                correction_prompt=correction,
            )
            try:
                corrected_raw, corrected_route = _graphic_responses_generate_v3000(
                    correction_items, correction_prompt, output_size
                )
                if corrected_raw:
                    corrected_result = _graphic_build_provider_result_v3000(
                        corrected_raw[0], prompt_text, output_size, correction_items,
                        corrected_route, reference_blueprint, vehicle_profile,
                        quality_review=review, corrected=True,
                    )
            except Exception as error:
                diagnostic_log(
                    "graphic_v3000_correction_failed_open",
                    error_type=type(error).__name__, error=error,
                )
    candidate = corrected_result or initial
    candidate_review = candidate.get("quality_review") or {}
    if corrected_result:
        candidate_review = _graphic_safe_optional_call(
            "graphic_v3200_corrected_review_failed_open",
            lambda: review_graphic_output_accuracy(
                corrected_result.get("data_url"), role_items, prompt_text,
                "High Fidelity Conversational Edit", reference_blueprint=reference_blueprint,
            ),
            {},
        )
        corrected_result["quality_review"] = candidate_review
    _, candidate_failed = _graphic_review_scores_v3200(
        candidate_review, has_product, has_style, bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    )

    # For a reference-driven commercial with a hard vehicle lock, never display a
    # Ford-leaking, sparse, or product-inaccurate provider result. Build a controlled
    # campaign from a clean target-vehicle plate and the exact uploaded product.
    final_result = candidate
    hard_vehicle_lock = bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    # Reference-driven vehicle campaigns use the controlled campaign compositor as
    # the preferred final path. The first provider artwork still acts as a creative
    # attempt and edit candidate, but deterministic product/copy/layout layers avoid
    # the exact failures observed in production: Ford leakage, missing feature zones,
    # malformed compatibility text, and simplified product geometry.
    use_hybrid_campaign = has_product and has_style and not has_edit_base
    if use_hybrid_campaign:
        diagnostic_log("graphic_v3200_hybrid_campaign_started", candidate_route=candidate.get("provider_route"), hard_vehicle_lock=hard_vehicle_lock)
        try:
            hybrid_result = _graphic_build_hybrid_campaign_result_v3200(
                prompt_text, role_items, output_size, reference_blueprint, vehicle_profile
            )
            hybrid_review = _graphic_safe_optional_call(
                "graphic_v3200_hybrid_review_failed_open",
                lambda: review_graphic_output_accuracy(
                    hybrid_result.get("data_url"), role_items, prompt_text,
                    "Exact Product Reference-Locked Campaign", reference_blueprint=reference_blueprint,
                ),
                {},
            )
            hybrid_result["quality_review"] = hybrid_review
            _, hybrid_failed = _graphic_review_scores_v3200(
                hybrid_review, True, True, bool((vehicle_profile or {}).get("hard_vehicle_lock"))
            )
            if not hybrid_failed or not hybrid_review:
                final_result = hybrid_result
            elif not candidate_failed:
                # Keep the provider artwork only when it already passed strict QA.
                diagnostic_log("graphic_v3200_hybrid_rejected_using_passed_provider", review=hybrid_review)
                final_result = candidate
            else:
                diagnostic_log("graphic_v3200_hybrid_rejected_by_qa", review=hybrid_review)
                raise RuntimeError("The reference-locked campaign did not pass strict vehicle/content review.")
        except Exception as hybrid_error:
            diagnostic_log("graphic_v3200_hybrid_failed", error_type=type(hybrid_error).__name__, error=hybrid_error)
            # Do not knowingly show a wrong-vehicle result. Preserve the project and
            # return a retryable error instead of presenting the rejected candidate.
            if bool((vehicle_profile or {}).get("hard_vehicle_lock")):
                state = get_graphic_project_state()
                state["stage"] = "ready_to_generate"
                state["last_error"] = "strict_vehicle_or_reference_fidelity_failed"
                st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
                raise RuntimeError(
                    "The image did not pass the strict vehicle and reference-fidelity check. "
                    "Your product, Silverado lock, and references are preserved. Select Regenerate to try again."
                ) from hybrid_error
    _graphic_save_latest_project_result(final_result)
    # Existing learning and campaign-memory writes remain best-effort and never block output.
    _graphic_safe_optional_call(
        "graphic_v3000_generation_intelligence_failed_open",
        lambda: save_graphic_generation_intelligence(
            prompt_text, final_result, {}, final_result.get("quality_review") or {}
        ),
        None,
    )
    return [final_result]


def _graphic_recover_role_items(uploaded_files, prompt_text="", forced_role="Auto-detect"):
    """Recover a usable reference/product role map from a multi-turn Graphic project.

    The normal classifier remains authoritative. This recovery layer handles the
    common conversational workflow where reference advertisements are uploaded
    first and a clean product photo is uploaded on the next turn. If legacy role
    metadata is missing, the newest image is treated as the product and earlier
    images remain style references. This is intentionally used only after the
    advanced engine fails or cannot identify a product source.
    """
    files = [item for item in (uploaded_files or []) if str(getattr(item, "type", "") or "").lower().startswith("image/")]
    try:
        role_items = classify_graphic_uploaded_image_roles(
            files, prompt_text, forced_role=forced_role
        )
    except Exception as error:
        diagnostic_log(
            "graphic_role_recovery_classifier_failed",
            error_type=type(error).__name__, error=error,
        )
        role_items = []

    if not role_items:
        role_items = [
            {
                "file": item,
                "name": str(getattr(item, "name", "image")),
                "role": "style_reference" if index < len(files) - 1 else "product_photo",
            }
            for index, item in enumerate(files)
        ]

    product_items = [item for item in role_items if item.get("role") == "product_photo"]
    style_items = [item for item in role_items if item.get("role") == "style_reference"]

    if files and not product_items:
        # Prefer an explicitly saved project role. Otherwise the most recently
        # uploaded image is the product in the standard reference-then-product flow.
        preferred = None
        for item in reversed(role_items):
            file_obj = item.get("file")
            if str(getattr(file_obj, "graphic_role", "") or "").strip() == "product":
                preferred = item
                break
        preferred = preferred or role_items[-1]
        for item in role_items:
            if item is preferred:
                item["role"] = "product_photo"
            elif item.get("role") not in {"logo", "logo_asset", "supporting", "supporting_image"}:
                item["role"] = "style_reference"

    if len(role_items) >= 2 and not any(item.get("role") == "style_reference" for item in role_items):
        for item in role_items[:-1]:
            if item.get("role") not in {"logo", "logo_asset", "supporting", "supporting_image"}:
                item["role"] = "style_reference"
    # The earlier block may have converted the only product into a reference while the
    # newest item remained supporting. Guarantee the standard reference-first/product-second flow.
    if files and not any(item.get("role") == "product_photo" for item in role_items):
        newest = role_items[-1]
        newest["role"] = "product_photo"
        for item in role_items[:-1]:
            if item.get("role") not in {"logo", "logo_asset", "background"}:
                item["role"] = "style_reference"

    role_items = _graphic_enforce_reference_product_roles_v8300(role_items, prompt_text)
    diagnostic_log(
        "graphic_role_recovery_result",
        roles=[f"{item.get('role')}:{item.get('name')}" for item in role_items],
    )
    return role_items


