def _graphic_reference_geometry_v3300(reference_blueprint=None, prompt_text=""):
    """Normalize reference analysis into editable, bounded layout coordinates.

    Coordinates are [x, y, width, height] in 0..1 canvas space. The parser accepts
    structured boxes when the reference analyzer provides them and otherwise derives
    the dominant left/right composition from the existing layout plan.
    """
    bp = reference_blueprint if isinstance(reference_blueprint, dict) else {}
    defaults = {
        "logo_box": [0.025, 0.025, 0.25, 0.10],
        "headline_box": [0.025, 0.14, 0.54, 0.20],
        "hero_product_box": [0.035, 0.35, 0.57, 0.49],
        "vehicle_box": [0.61, 0.40, 0.35, 0.42],
        "feature_matrix_box": [0.61, 0.035, 0.355, 0.27],
        "bottom_bar_box": [0.045, 0.885, 0.91, 0.095],
    }
    plan = _graphic_layout_plan(bp, prompt_text)
    if plan.get("product_side") == "right":
        defaults["hero_product_box"] = [0.41, 0.35, 0.55, 0.49]
        defaults["vehicle_box"] = [0.04, 0.42, 0.34, 0.40]
        defaults["headline_box"] = [0.035, 0.14, 0.36, 0.22]
        defaults["feature_matrix_box"] = [0.035, 0.035, 0.36, 0.27]
    candidates = bp.get("normalized_boxes") or bp.get("layout_boxes") or bp.get("zones") or {}
    if isinstance(candidates, dict):
        aliases = {
            "product_box": "hero_product_box", "hero_box": "hero_product_box",
            "copy_box": "headline_box", "features_box": "feature_matrix_box",
            "benefit_bar_box": "bottom_bar_box", "footer_box": "bottom_bar_box",
        }
        for raw_key, raw_box in candidates.items():
            key = aliases.get(str(raw_key), str(raw_key))
            if key not in defaults or not isinstance(raw_box, (list, tuple)) or len(raw_box) != 4:
                continue
            try:
                vals = [float(v) for v in raw_box]
                if max(vals) > 1.5:  # tolerate percentages
                    vals = [v / 100.0 for v in vals]
                x, y, w, h = vals
                x = min(max(x, 0.0), 0.92); y = min(max(y, 0.0), 0.92)
                w = min(max(w, 0.08), 1.0 - x); h = min(max(h, 0.05), 1.0 - y)
                defaults[key] = [x, y, w, h]
            except Exception:
                continue
    return defaults


# v23000: restored v20100 visual-baseline behavior for _graphic_white_background_mask_v3300.
@st.cache_data(ttl=86400, max_entries=128, show_spinner=False)

@st.cache_data(ttl=86400, max_entries=96, show_spinner=False)
def _graphic_white_background_mask_v3300(raw_bytes, cache_version=GRAPHIC_MASK_CACHE_VERSION):
    """v66000 multi-candidate, fail-closed exact-geometry background removal.

    Every candidate uses v47000-style outside-connected background propagation.
    Approval requires source-to-cutout preservation of product extents and regional
    support. The uploaded RGB is copied unchanged; only verified alpha is applied.
    """
    if Image is None or not raw_bytes:
        return b""
    try:
        alpha,selection=_graphic_v66000_select_exact_geometry_alpha(raw_bytes)
        if alpha is None:
            diagnostic_log("graphic_v66000_mask_fail_closed", **selection)
            return b""
        source=ImageOps.exif_transpose(Image.open(io.BytesIO(raw_bytes))).convert("RGBA")
        result=source.copy()
        result.putalpha(Image.fromarray(alpha.astype("uint8"),mode="L"))
        buffer=io.BytesIO(); result.save(buffer,format="PNG",optimize=True)
        diagnostic_log("graphic_v66000_mask_selected", selected=selection.get("selected"), confidence=selection.get("confidence"))
        return buffer.getvalue()
    except Exception as error:
        diagnostic_log("graphic_v66000_mask_failed",error_type=type(error).__name__,error=str(error))
        return b""



# v23000: restored v20100 visual-baseline behavior for _graphic_open_product_layer_v3300.

def _graphic_open_product_layer_v3300(uploaded_file):
    """Open the immutable v66000 exact-product authority layer.

    Source alpha is authoritative. Opaque sources use only a v66000 geometry-proven
    alpha. Any uncertainty returns the complete untouched source card. Source RGB is
    never generated, repainted, relit, decontaminated, warped or selectively repaired.
    """
    raw=_graphic_uploaded_file_bytes(uploaded_file)
    if not raw or Image is None:
        return None,False
    digest=hashlib.sha256(raw).hexdigest()
    try:
        with Image.open(io.BytesIO(raw)) as source_image:
            master=ImageOps.exif_transpose(source_image).convert("RGBA")
    except Exception as error:
        diagnostic_log("graphic_v66000_master_open_failed",error_type=type(error).__name__,error=_graphic_compact_error_v4000(error))
        return None,False
    source_alpha=master.getchannel("A"); extrema=source_alpha.getextrema()
    selection={"passed":True,"selected":"authoritative_source_alpha","confidence":1.0,"fail_closed":True}
    if extrema and extrema[0]<250:
        layer=master.copy(); transparent=True; mask_method="authoritative_source_alpha"
    else:
        try:
            alpha,selection=_graphic_v66000_select_exact_geometry_alpha(raw)
        except Exception as error:
            alpha=None; selection={"passed":False,"reason":str(error)[:300],"fail_closed":True}
        if alpha is not None and selection.get("passed"):
            layer=master.copy(); layer.putalpha(Image.fromarray(alpha.astype("uint8"),mode="L"))
            transparent=True; mask_method=f"v66000_geometry_proven_{selection.get('selected','candidate')}"
        else:
            layer=master.copy(); transparent=False; mask_method="v66000_untouched_master_card_fallback"
    state=get_graphic_project_state(); reports=dict(state.get("product_bezel_master_reports") or {})
    reports[digest]={
        "applied":bool(transparent),"mode":"v66000_universal_fail_closed_exact_geometry_authority",
        "mask_method":mask_method,"master_rgb_sha256":digest,"selection":selection,
        "source_rgb_untouched":True,"immutable_product_compositing":True,"fail_closed":True,
    }
    state["product_bezel_master_reports"]={k:v for k,v in list(reports.items())[-12:]}
    st.session_state[GRAPHIC_PROJECT_STATE_KEY]=state
    return layer,transparent





def _graphic_product_library_grounding_v3300(prompt_text, state=None):
    """Resolve one authoritative Product Library record without forcing a chat lookup."""
    state = state or get_graphic_project_state()
    history = " ".join(state.get("project_brief_history") or [])
    vehicle = str((state.get("explicit_vehicle") or {}).get("display_name") or "")
    query = re.sub(r"\s+", " ", f"{prompt_text} {history} {vehicle}").strip()
    try:
        products = [p for p in (_product_library_cached_products() or []) if p.get("active") is not False]
        ranked = sorted(
            ((_product_library_product_score(product, query), product) for product in products),
            key=lambda pair: (pair[0], str(pair[1].get("updated_at") or "")), reverse=True,
        )
        if not ranked or ranked[0][0] < 24:
            return {}
        if len(ranked) > 1 and ranked[1][0] >= ranked[0][0] - 8 and ranked[0][0] < 200:
            return {}
        return dict(ranked[0][1] or {})
    except Exception as error:
        diagnostic_log("graphic_v3300_product_library_grounding_failed", error_type=type(error).__name__, error=error)
        return {}


def _graphic_list_value_v3300(value, limit=8):
    if isinstance(value, list):
        return [re.sub(r"\s+", " ", str(v)).strip() for v in value if str(v).strip()][:limit]
    if isinstance(value, str):
        return [v.strip() for v in re.split(r"[\n;|•]+", value) if v.strip()][:limit]
    return []


def _graphic_extract_full_compatibility_v36000(prompt_text, fallback=""):
    """Extract complete user-stated fitment without scene-lock collapse."""
    explicit = _graphic_explicit_fitment_v41100(prompt_text)
    if explicit:
        return explicit
    fallback_value = re.sub(r"\s+", " ", str(fallback or "")).strip()
    if fallback_value and not re.match(r"(?i)^for\b", fallback_value):
        fallback_value = "For " + fallback_value
    return fallback_value




def _graphic_copy_required_tokens_v36000(text):
    """Return every make, model, and year token that must survive rendering."""
    value = str(text or "")
    tokens = []
    pattern = (
        r"(?i)\b(?:toyota|tundra|tacoma|chevrolet|chevy|silverado|gmc|sierra|"
        r"ford|f\s*[\- ]?\s*(?:150|250|350|450|550)|dodge|ram|"
        r"tahoe|suburban|yukon|cadillac|escalade|jeep|wrangler|gladiator|"
        r"infiniti|q50|q60|(?:19|20)\d{2})\b"
    )
    for token in re.findall(pattern, value):
        clean = re.sub(r"[^a-z0-9]+", "", str(token).casefold())
        if clean and clean not in tokens:
            tokens.append(clean)
    return tokens




def _graphic_fit_ribbon_copy_v36000(draw, text, box_width, box_height, preferred_px, minimum_px):
    """Fit complete compatibility copy without deleting vehicle names or years."""
    value = re.sub(r"\s+", " ", str(text or "")).strip()
    max_text_w = max(20, int(box_width * 0.91))
    minimum_px = max(10, int(minimum_px))
    preferred_px = max(minimum_px, int(preferred_px))

    def width(v, font):
        try:
            b = draw.textbbox((0, 0), str(v), font=font)
            return max(0, b[2] - b[0])
        except Exception:
            return len(str(v)) * max(6, int(preferred_px * 0.5))

    for size in range(preferred_px, minimum_px - 1, -1):
        font = _graphic_font(size, True)
        if width(value, font) <= max_text_w:
            return {"lines": [value], "font": font, "font_px": size, "two_line": False, "complete": True}

    # Two-line fallback is allowed only if the reference ribbon has enough height.
    if box_height >= minimum_px * 2.05:
        words = value.split()
        best = None
        for split in range(1, len(words)):
            lines = [" ".join(words[:split]), " ".join(words[split:])]
            for size in range(preferred_px, minimum_px - 1, -1):
                font = _graphic_font(size, True)
                if all(width(line, font) <= max_text_w for line in lines):
                    score = abs(width(lines[0], font) - width(lines[1], font))
                    candidate = (score, size, lines, font)
                    if best is None or candidate[:2] < best[:2]:
                        best = candidate
                    break
        if best:
            _, size, lines, font = best
            return {"lines": lines, "font": font, "font_px": size, "two_line": True, "complete": True}

    font = _graphic_font(minimum_px, True)
    return {"lines": [value], "font": font, "font_px": minimum_px, "two_line": False, "complete": width(value, font) <= max_text_w}


def _graphic_verified_campaign_spec_v3300(prompt_text, vehicle_profile=None):
    """Build copy from explicit facts and verified Product Library data only."""
    state = get_graphic_project_state()
    spec = _graphic_extract_campaign_spec(prompt_text, state.get("campaign_spec") or {})
    product = _graphic_product_library_grounding_v3300(prompt_text, state)
    explicit_context = " ".join([str(prompt_text or ""), *[str(x) for x in (state.get("project_brief_history") or [])]])
    explicit_size = bool(re.search(r"\b\d{1,2}(?:\.\d)?\s*(?:inch|inches|[\"”])\b", explicit_context, re.I))
    explicit_category = bool(re.search(r"\b(?:digital gauge cluster|vertical dash display|infotainment|head unit|radio|display)\b", explicit_context, re.I))
    def first(*keys):
        for key in keys:
            value = product.get(key)
            if value not in (None, "", [], {}):
                return value
        return None
    # Product Library fills gaps; explicit user values already in spec always win.
    if not explicit_size and not product:
        spec.pop("screen_size", None)
    if not explicit_category and not product and str(spec.get("product_category") or "").upper() == "VERTICAL DASH DISPLAY":
        spec.pop("product_category", None)
    screen_size = first("screen_size", "display_size", "size")
    if screen_size and not spec.get("screen_size"):
        clean = re.sub(r"\s+", " ", str(screen_size)).strip()
        spec["screen_size"] = clean if '"' in clean else clean + ('"' if re.fullmatch(r"\d+(?:\.\d+)?", clean) else '')
    product_name = first("marketing_name", "product_name", "name", "title")
    category = first("product_category", "category", "type")
    if product_name and not spec.get("headline"):
        spec["headline"] = str(product_name).strip()
    elif category and not spec.get("product_category"):
        spec["product_category"] = str(category).strip().upper()
    compatibility = first("compatibility", "vehicle_compatibility", "fitment", "year_range")
    if compatibility and not spec.get("compatibility"):
        spec["compatibility"] = str(compatibility).strip()
    verified_features = _graphic_list_value_v3300(first("marketing_features", "features", "key_features", "selling_points"), 8)
    if verified_features:
        spec["feature_labels"] = verified_features
    verified_benefits = _graphic_list_value_v3300(first("bottom_benefits", "benefits", "highlights"), 5)
    if verified_benefits:
        spec["bottom_benefits"] = verified_benefits
    tagline = first("tagline", "marketing_tagline")
    if tagline and not spec.get("tagline"):
        spec["tagline"] = str(tagline).strip()
    vehicle_profile = _graphic_resolve_vehicle_lock(prompt_text, vehicle_profile or {})
    explicit_name = str(vehicle_profile.get("explicit_display_name") or "").strip()
    current_fitment = _graphic_explicit_fitment_v41100(prompt_text)
    project_context = str(prompt_text or "") if current_fitment else " ".join([str(prompt_text or ""), *[str(x) for x in (state.get("project_brief_history") or [])]])
    full_compatibility = _graphic_extract_full_compatibility_v36000(
        project_context,
        spec.get("compatibility") or explicit_name,
    )
    if full_compatibility:
        spec["compatibility"] = full_compatibility
    elif explicit_name:
        spec["compatibility"] = explicit_name
    if explicit_name:
        spec["vehicle_label"] = explicit_name.upper()
        spec["vehicle"] = dict(state.get("explicit_vehicle") or {})
    spec["compatibility_required_tokens"] = _graphic_copy_required_tokens_v36000(spec.get("compatibility"))
    # Remove unsafe universal defaults when no verified fact supports them.
    if not spec.get("headline"):
        size = str(spec.get("screen_size") or "").strip()
        category = str(spec.get("product_category") or "PREMIUM IN-VEHICLE DISPLAY").strip()
        spec["headline"] = f"{size} {category}".strip()
    if not spec.get("feature_labels"):
        spec["feature_labels"] = [
            "Vehicle-Specific Fitment", "Integrated Display", "Real-Time Vehicle Data",
            "Factory Controls Retained", "Smart Connectivity", "OEM-Style Integration",
            "Responsive Interface", "High-Brightness Screen",
        ]
    if not spec.get("bottom_benefits"):
        spec["bottom_benefits"] = [
            "Vehicle-Specific Installation", "Factory Integration", "Smart Connectivity",
            "OEM Fit & Finish", "High-Brightness Display",
        ]
    spec["product_library_grounded"] = bool(product)
    spec["product_library_code"] = str(product.get("product_code") or product.get("sku") or "")
    state["campaign_spec"] = spec
    state["product_library_grounding"] = {
        "matched": bool(product), "product_code": spec["product_library_code"],
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
    return spec




def _graphic_review_scores_v3300(review, has_product, has_style, hard_vehicle_lock):
    """Fail closed: missing QA values are unverified, never silently perfect."""
    required = ["text_quality_score"]
    if has_product: required.append("product_accuracy_score")
    if has_style: required.extend(["style_adherence_score", "layout_adherence_score", "content_density_score"])
    if hard_vehicle_lock: required.append("vehicle_accuracy_score")
    scores = {}
    missing = []
    for name, short in [
        ("product_accuracy_score", "product"), ("style_adherence_score", "style"),
        ("layout_adherence_score", "layout"), ("vehicle_accuracy_score", "vehicle"),
        ("content_density_score", "density"), ("text_quality_score", "text")]:
        value = (review or {}).get(name)
        try: scores[short] = int(float(value))
        except Exception:
            scores[short] = None
            if name in required: missing.append(name)
    failed = bool(missing) or not bool((review or {}).get("passed", False))
    failed = failed or (has_product and (scores["product"] is None or scores["product"] < 88))
    failed = failed or (has_style and any(scores[k] is None or scores[k] < 84 for k in ("style", "layout", "density")))
    failed = failed or (hard_vehicle_lock and (scores["vehicle"] is None or scores["vehicle"] < 97))
    failed = failed or (scores["text"] is None or scores["text"] < 74)
    return scores, failed, missing


def _graphic_focused_vehicle_validation_v3300(data_url, role_items, prompt_text, vehicle_profile):
    """Strictly verify make/model plus body class for a hard-locked vehicle."""
    explicit = str((vehicle_profile or {}).get("explicit_display_name") or "").strip()
    if not explicit:
        return {"verified": True, "available": True, "score": 100, "reason": "no explicit vehicle lock"}

    lowered = explicit.casefold()
    if any(term in lowered for term in ("silverado", "sierra", "ram", "f-150", "f150", "super duty", "truck", "pickup")):
        required_body = "pickup truck"
        forbidden_body = "SUV, crossover, sedan, coupe, van"
    elif any(term in lowered for term in ("tahoe", "suburban", "yukon", "escalade", "suv")):
        required_body = "SUV"
        forbidden_body = "pickup truck, sedan, coupe, van"
    elif any(term in lowered for term in ("q50", "q60", "sedan", "coupe")):
        required_body = "passenger car"
        forbidden_body = "pickup truck, SUV, van"
    else:
        required_body = "factory-correct body type"
        forbidden_body = "any conflicting body class"

    prohibited = ", ".join(
        str(value).strip()
        for value in ((vehicle_profile or {}).get("prohibited_reference_vehicle_terms") or [])
        if str(value).strip()
    )
    focused_prompt = (
        "VEHICLE IDENTITY AND BODY-TYPE AUDIT ONLY. "
        f"Required vehicle: {explicit}. Required body class: {required_body}. "
        f"Reject any {forbidden_body}. "
        "Inspect grille, headlamps, badge region, hood, fenders, cab/roofline, doors, bed or cargo body, wheelbase, and overall proportions. "
        "Reject if the vehicle is ambiguous, too hidden, materially cropped, a different generation, a different make/model, or the wrong body class. "
        + (("Explicitly prohibited identities: " + prohibited + ". ") if prohibited else "")
        + "Ignore all product, typography, and layout quality. Return a vehicle score only. "
        + str(prompt_text or "")[:900]
    )
    review = review_graphic_output_accuracy(
        data_url, role_items, focused_prompt, "Vehicle Identity Audit", reference_blueprint={}
    ) or {}
    try:
        score = int(float(review.get("vehicle_accuracy_score")))
    except Exception:
        score = 0
    summary = str(review.get("summary") or review.get("correction_prompt") or "vehicle verification unavailable")[:1000]
    available = bool(review) and score > 0
    verified = available and bool(review.get("passed", False)) and score >= 97
    return {
        "verified": verified,
        "available": available,
        "score": score,
        "required_vehicle": explicit,
        "required_body_type": required_body,
        "reason": summary,
        "raw": review,
    }





def _graphic_zone_completeness_v3300(review, campaign_spec):
    """Require all expected campaign zones, not merely a vague style match."""
    zones = (review or {}).get("zone_presence") or (review or {}).get("campaign_zones") or {}
    expected = ["logo", "headline", "compatibility_ribbon", "tagline", "feature_matrix", "hero_product", "target_vehicle", "bottom_benefit_bar"]
    if isinstance(zones, list):
        present = {str(x).strip().lower() for x in zones}
        missing = [z for z in expected if z not in present]
    elif isinstance(zones, dict):
        missing = [z for z in expected if not bool(zones.get(z))]
    else:
        # Existing reviewers may not emit zones. Treat as unverified for a reference job.
        missing = list(expected)
    return {"expected": expected, "missing": missing, "passed": not missing}


def _graphic_build_hybrid_campaign_result_v3300(prompt_text, role_items, output_size, reference_blueprint, vehicle_profile):
    """Run the compiled five-stage commercial pipeline with exact-product authority."""
    product_item = next((item for item in role_items if item.get("role") == "product_photo"), None)
    if not product_item:
        raise RuntimeError("A product source is required for the controlled campaign engine.")

    spec = _graphic_verified_campaign_spec_v3300(prompt_text, vehicle_profile)
    compiled = _graphic_execution_blueprint_v43000(
        prompt_text, spec, reference_blueprint, role_items, vehicle_profile, output_size
    )
    if not compiled.get("ready"):
        missing = []
        for name, stage in (compiled.get("stages") or {}).items():
            if isinstance(stage, dict) and stage.get("available") is False:
                missing.append(name)
        raise RuntimeError(
            "The five-stage graphic compiler could not prepare a safe campaign blueprint"
            + (": " + ", ".join(missing) if missing else ".")
        )

    campaign_stage = ((compiled.get("stages") or {}).get("3_campaign_compiler") or {})
    campaign_fields = dict(campaign_stage.get("fields") or {})
    spec.update({
        "compatibility": campaign_fields.get("compatibility") or spec.get("compatibility"),
        "headline": campaign_fields.get("headline") or spec.get("headline"),
        "tagline": campaign_fields.get("tagline") or spec.get("tagline"),
        "feature_labels": campaign_fields.get("features") or spec.get("feature_labels"),
        "bottom_benefits": campaign_fields.get("benefits") or spec.get("bottom_benefits"),
        "compatibility_required_tokens": campaign_stage.get("required_compatibility_tokens") or [],
        "compatibility_locked": True,
        "compatibility_source": "campaign-compiler-v43000",
    })

    state = get_graphic_project_state()
    template_key = str(state.get("brand_template") or "autotecpro_adventure")
    state["five_stage_execution_blueprint_v43000"] = compiled
    state["active_scene_intelligence_v41000"] = dict(compiled.get("scene_strategy") or {})
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state

    background, route = _graphic_generate_background_plate_v3200(
        role_items, prompt_text, output_size, vehicle_profile, spec,
        ((compiled.get("stages") or {}).get("4_layout_compiler") or {}).get("normalized_boxes") or reference_blueprint,
        template_key,
    )

    composed, metadata = _graphic_stage5_execute_v43000(
        background, product_item, prompt_text, output_size, spec, vehicle_profile,
        role_items, compiled, template_key=template_key, product_dna=state.get("product_dna") or {},
    )
    metadata["five_stage_execution_blueprint_v43000"] = compiled
    metadata["reference_geometry"] = _graphic_reference_geometry_v3300(reference_blueprint, prompt_text)
    metadata["product_library_grounded"] = bool(spec.get("product_library_grounded"))
    metadata["ultimate_scene_intelligence"] = dict(compiled.get("scene_strategy") or {})

    result = _graphic_build_provider_result_v3000(
        composed, prompt_text, output_size, role_items,
        route + "+five-stage-controlled-compositor-v48000",
        reference_blueprint, vehicle_profile, corrected=True,
    )
    result["product_identity_method"] = "engine-v48000-compiled-detail-restored-product-composite"
    result["layered_metadata"].update(metadata)

    # v68874: the completed result now owns the encoded final artwork.
    # Drop only local raw byte buffers before QA to reduce the peak footprint.
    # This does not alter the final data_url, metadata, product pixels, or QA.
    try:
        del composed
        del background
    except Exception:
        pass
    _graphic_v68874_release_transient_memory("reference_composite_ready")

    scorecard = _graphic_qa_scorecard_v42000(result["layered_metadata"])
    result["layered_metadata"]["qa_scorecard_v43000"] = scorecard
    quality = _graphic_quality_verification_v40000(result["layered_metadata"])
    if not scorecard.get("passed"):
        quality = {
            "passed": False,
            "failed": list(dict.fromkeys(
                list(quality.get("failed") or []) + list(scorecard.get("critical_failed") or [])
            )),
            "scorecard_v43000": scorecard,
        }

    retry_plan = _graphic_adaptive_retry_plan_v40000(quality)
    executed = []
    if "restore_immutable_product_master_no_provider_retry" in retry_plan.get("actions", []):
        executed.append("immutable product master retained by compiled compositor")
    if "rerender_local_typography_only" in retry_plan.get("actions", []):
        executed.append("campaign copy remained local and immutable")
    retry_plan["executed"] = executed
    result["layered_metadata"]["ultimate_quality_verification"] = quality
    result["layered_metadata"]["ultimate_adaptive_retry_plan"] = retry_plan

    stage_status = {
        "reference_intelligence": bool(((compiled.get("stages") or {}).get("1_reference_intelligence") or {}).get("version")),
        "product_intelligence": bool(((compiled.get("stages") or {}).get("2_product_intelligence") or {}).get("available")),
        "campaign_compiler": bool(((compiled.get("stages") or {}).get("3_campaign_compiler") or {}).get("available")),
        "layout_compiler": bool(((compiled.get("stages") or {}).get("4_layout_compiler") or {}).get("passed")),
        "image_generator": bool((metadata.get("five_stage_execution_v43000") or {}).get("version")),
        "quality": bool(quality),
        "final_composite": True,
    }
    result["layered_metadata"]["five_stage_trace_v43000"] = {
        "stage_status": stage_status,
        "completed": sum(1 for value in stage_status.values() if value),
        "total": len(stage_status),
        "all_completed": all(stage_status.values()),
        "version": "five-stage-trace-v43000",
    }

    if not quality.get("passed"):
        failed_checks = list(quality.get("failed") or [])
        result = _graphic_mark_unverified_v4100(
            result,
            "The exact-product compiled campaign was created, but these QA checks need review: "
            + ", ".join(failed_checks),
            status="completed_compiled_campaign_review_v43000",
        )
        result["controlled_qa_failed_checks"] = failed_checks
        diagnostic_log("graphic_v43000_compiled_qa_review", failed=failed_checks)
    else:
        result["output_status"] = "completed_compiled_campaign_v48000"
        result["verification_status"] = "verified"

    result["campaign_spec"] = spec
    result["graphic_design_mode"] = "reference_template" if reference_blueprint else "autotecpro_studio"
    result["studio_creative_brief"] = (
        state.get("studio_creative_brief") or {}
        if result["graphic_design_mode"] == "autotecpro_studio" else {}
    )
    result["reference_template_used"] = result["graphic_design_mode"] == "reference_template"
    result["reference_memory_isolated"] = result["graphic_design_mode"] == "autotecpro_studio"
    return result




def _graphic_correction_result_v3300(initial, prompt_text, role_items, output_size, reference_blueprint, vehicle_profile, rejected_guidance, correction):
    current_raw, current_mime = data_url_to_bytes(initial.get("data_url"))
    correction_items = list(role_items)
    if current_raw:
        current_upload = ManagedUploadedFile(
            current_raw, "current_generated_artwork.png", current_mime or "image/png",
            graphic_role="edit_base", graphic_asset_id=hashlib.sha256(current_raw).hexdigest(),
        )
        correction_items = [{"file": current_upload, "name": current_upload.name, "role": "edit_base", "reason": "current output for one controlled correction pass"}] + [item for item in role_items if item.get("role") != "edit_base"]
    correction_prompt = _graphic_chatgpt_production_prompt(
        prompt_text, correction_items, output_size,
        reference_blueprint=reference_blueprint, vehicle_profile=vehicle_profile,
        rejected_guidance=rejected_guidance, correction_prompt=correction,
    )
    try:
        corrected_raw, route = _graphic_responses_generate_v3000(correction_items, correction_prompt, output_size)
    except Exception:
        corrected_raw, route = _graphic_images_api_fallback_v3000(correction_items, correction_prompt, output_size)
    if not corrected_raw:
        return None
    result = _graphic_build_provider_result_v3000(
        corrected_raw[0], prompt_text, output_size, role_items, route,
        reference_blueprint, vehicle_profile, corrected=True,
    )
    result["output_status"] = "completed_after_correction_v3300"
    return result


