def _graphic_product_recreation_intent_v7000(prompt_text):
    """Return a bounded product-view recreation directive.

    Exact-product compositing remains the default. This mode is activated only when
    the user explicitly asks for a new camera angle, rotation, perspective, 3D view,
    or AI recreation of the product itself.
    """
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip()
    lower = value.casefold()
    patterns = (
        r"\bchange (?:the )?(?:product )?angle\b",
        r"\brotate (?:the )?(?:product|unit|device|screen)\b",
        r"\b(?:three|3)[ -]?quarter view\b",
        r"\b(?:left|right|side|rear|back|top|overhead|low)[ -]?(?:angle|view|perspective)\b",
        r"\bview (?:it|the product|the unit) from\b",
        r"\bnew camera angle\b",
        r"\bdifferent angle\b",
        r"\bai[- ]?(?:recreate|recreation|render|redraw)\b",
        r"\bconceptual (?:3d )?(?:render|view)\b",
        r"\bshow (?:the )?(?:product|unit) (?:at|from)\b",
    )
    matched = any(re.search(pattern, lower, flags=re.I) for pattern in patterns)
    exact_override = any(term in lower for term in (
        "use exact product", "keep exact product", "do not recreate", "do not redraw",
        "preserve exact pixels", "front view only", "same angle",
        "use uploaded product", "use the uploaded product", "actual product image",
        "same product", "exact same product", "do not change the product",
    ))
    if exact_override:
        matched = False
    requested_view = ""
    view_patterns = (
        (r"\b(?:three|3)[ -]?quarter\b", "three-quarter"),
        (r"\bleft[ -]?(?:angle|view|side|perspective)\b", "left three-quarter"),
        (r"\bright[ -]?(?:angle|view|side|perspective)\b", "right three-quarter"),
        (r"\b(?:rear|back)[ -]?(?:angle|view|perspective)?\b", "rear"),
        (r"\b(?:top|overhead)[ -]?(?:angle|view|perspective)?\b", "overhead"),
        (r"\bside[ -]?(?:angle|view|perspective)?\b", "side"),
    )
    for pattern, label in view_patterns:
        if re.search(pattern, lower, flags=re.I):
            requested_view = label
            break
    return {
        "enabled": bool(matched),
        "requested_view": requested_view or "new requested camera angle",
        "explicit": bool(matched),
        "source_text": value[:800],
    }


def _graphic_product_mode_v7000(prompt_text, role_items, has_edit_base=False):
    """Select one authoritative adaptive rendering mode for the request."""
    adaptive = _graphic_adaptive_intent_v44000(prompt_text, role_items, has_edit_base=has_edit_base)
    product_items = [i for i in (role_items or []) if i.get("role") == "product_photo"]
    style_items = [i for i in (role_items or []) if i.get("role") == "style_reference"]
    adaptive_mode = adaptive.get("mode")
    if has_edit_base and adaptive_mode == "commercial_lock":
        mode = "edit_existing"
    elif adaptive_mode == "ui_replacement":
        mode = "ui_replacement"
    elif adaptive_mode == "installed_view":
        mode = "installed_product_view"
    elif adaptive_mode == "product_variant":
        mode = "product_variant"
    elif adaptive_mode == "product_recreation" and len(product_items) >= 2:
        mode = "multi_view_product_reconstruction"
    elif adaptive_mode == "product_recreation" and product_items:
        mode = "ai_product_recreation"
    elif product_items and style_items:
        mode = "reference_guided_exact_product"
    elif product_items:
        mode = "autotecpro_style_exact_product"
    else:
        mode = "fully_generative_concept"
    return {
        "mode": mode,
        "adaptive_mode": adaptive_mode,
        "adaptive_intent": adaptive,
        "recreation": _graphic_product_recreation_intent_v7000(prompt_text),
        "product_count": len(product_items),
        "style_count": len(style_items),
        "exact_product": mode in {"reference_guided_exact_product", "autotecpro_style_exact_product"},
        "recreates_product": mode in {"ai_product_recreation", "multi_view_product_reconstruction", "product_variant", "installed_product_view"},
        "ui_replacement": mode == "ui_replacement",
        "installed_view": mode == "installed_product_view",
        "product_variant": mode == "product_variant",
    }


def _graphic_multiview_identity_prompt_v7000(role_items, mode_info, structure_profile):
    """Build Graphic Engine 6 measurement-driven guidance for a recreated viewpoint."""
    if not (mode_info or {}).get("recreates_product"):
        return ""
    products = [i for i in (role_items or []) if i.get("role") == "product_photo"]
    names = [str(i.get("name") or "product source") for i in products[:6]]
    requested_view = str(((mode_info or {}).get("recreation") or {}).get("requested_view") or "new requested camera angle")
    identity = _graphic_product_identity_v18000(role_items, structure_profile)
    engineering = _graphic_product_engineering_dna_v19000(role_items, identity, structure_profile)
    ratio_contract = _graphic_product_ratio_contract_v19400(role_items, identity, structure_profile)
    ui_contract = _graphic_ui_structure_dna_v19400(role_items, structure_profile)
    geometry_lock = _graphic_geometry_lock_v20000(role_items, identity, structure_profile)
    return f"""
GRAPHIC ENGINE 6.0 — MEASUREMENT-DRIVEN ENGINEERING RECONSTRUCTION MODE:
- Reproduce the same physical AutoTecPro unit from a {requested_view} viewpoint.
- Identity sources, in priority order: {', '.join(names) or 'uploaded product source'}.
- Camera angle, perspective, rotation, lighting, reflections, apparent size and composition MAY change naturally.
- Reconstruct one coherent engineered object, not a generic radio and not a flattened sticker.
- Preserve the intrinsic whole-unit geometry, screen aspect ratio, screen position, bezel relationship and every visible structural transition.
- Preserve left and right control columns independently: button count, order, spacing, bevels, recesses, legends and shadows.
- Preserve each knob independently: diameter, center cap, outer ring, chamfer, depth and location.
- Preserve mounting ears, tabs, lower bracket, fastener holes, lower opening, side handle openings, cavities and every real negative space.
- Preserve material separation between screen glass, glossy/satin/matte plastic, metallic trim and control surfaces.
- Adapt reflections to the scene without smoothing away seams, bevels, cutouts, legends, knob rings or control depth.
- Perspective foreshortening is allowed; stretching, widening, narrowing, melting, averaging, simplifying or redesigning is forbidden.
- Advertisement references control layout/style only and must never supply product geometry.
- Apply one coherent perspective transform to the complete unit. Never resize the screen, side rails, controls, knobs, openings or mounting features independently.
- ENGINEERING GEOMETRY LOCK: {json.dumps(geometry_lock, ensure_ascii=False, default=str)[:7000]}
- ADAPTIVE PRODUCT RATIO LOCK: {json.dumps(ratio_contract, ensure_ascii=False, default=str)[:6000]}
- UI STRUCTURE DNA: {json.dumps(ui_contract, ensure_ascii=False, default=str)[:4500]}
- ENGINEERING DNA: {json.dumps(engineering, ensure_ascii=False, default=str)[:9000]}
"""


