def _graphic_select_brand_template_v8000(prompt_text, has_style=False, studio_brief=None):
    """Select templates deterministically; reference mode never overrides measured geometry."""
    if has_style:
        selected="reference_guided"
    elif studio_brief:
        selected=_graphic_select_studio_template_v34000(studio_brief)
    else:
        value=str(prompt_text or "").casefold()
        mapping=((('white background','white studio','ecommerce'),'autotecpro_white_studio'),(('performance','sport','racing'),'autotecpro_performance'),(('luxury','elegant'),'autotecpro_luxury'),(('oem','factory','minimal'),'autotecpro_oem_clean'))
        selected="autotecpro_adventure"
        for terms,key in mapping:
            if any(term in value for term in terms): selected=key; break
    state=get_graphic_project_state(); state["brand_template"]=selected
    history=list(state.get("template_history") or []); history.append({"template":selected,"at":datetime.now(timezone.utc).isoformat()}); state["template_history"]=history[-20:]
    st.session_state[GRAPHIC_PROJECT_STATE_KEY]=state
    return selected


def _graphic_build_product_dna_v8000_original_v67200(role_items, structure_profile=None):
    """Build flexible Product DNA: preserve identity, not one fixed camera view."""
    products = [item for item in (role_items or []) if item.get("role") == "product_photo"]
    signatures = [_graphic_product_source_signature_v9000(item) for item in products[:8]]
    source_ratios = [float(sig.get("aspect_ratio") or 0.0) for sig in signatures if float(sig.get("aspect_ratio") or 0.0) > 0]
    dna = {
        "engine": "v17000-product-dna",
        "product_view_count": len(products),
        "source_names": [str(item.get("name") or "") for item in products[:8]],
        "source_ids": [str(item.get("asset_id") or item.get("id") or "") for item in products[:8]],
        "identity_policy": "preserve_engineering_identity_allow_camera_scale_perspective",
        "exact_pixel_default": True,
        "angle_recreation_allowed_when_explicit": True,
        "allowed_transformations": [
            "uniform size change", "camera-angle change", "perspective change",
            "rotation", "scene relighting", "realistic reflections", "partial artistic crop",
        ],
        "invariants": [
            "recognizable outer silhouette", "whole-unit width-to-height proportion",
            "visible screen width-to-height proportion", "screen position inside housing",
            "bezel thickness relationships", "button/knob count and placement",
            "side brackets and mounting tabs", "open cavities and negative spaces",
            "lower control-panel geometry", "trim and material identity",
            "visible screen interface and UI hierarchy",
        ],
        "critical_features": [
            "outer silhouette", "screen aspect ratio and visible UI", "bezel thickness",
            "gap below screen", "side openings", "climate knobs", "physical buttons",
            "lower cavities", "mounting tabs", "trim geometry",
        ],
        "source_aspect_ratios": source_ratios,
        "primary_source_aspect_ratio": source_ratios[0] if source_ratios else 0.0,
        "structure_profile": dict(structure_profile or {}),
        "multi_view": len(products) >= 2,
        "segmentation_diagnostics": _graphic_segmentation_diagnostics_v10000(products[0]) if products else {},
        "source_signatures": signatures,
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    state = get_graphic_project_state()
    state["product_dna"] = dna
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
    return dna



def _graphic_layer_stack_v8000(
    result=None,
    *,
    geometry=None,
    campaign_spec=None,
    template_key="",
):
    """Return editable layer metadata without duplicating the active background.

    Local edit routes already read the authoritative background from
    latest_generated.background_data_url. The layer stack therefore stores a stable
    source key instead of a second full Base64 copy.
    """
    geometry = dict(geometry or {})
    campaign_spec = dict(campaign_spec or {})
    result = dict(result or {})
    has_background = bool(result.get("background_data_url"))
    layers = {
        "background": {
            "editable": True,
            "source": "ai_scene",
            "asset_source_key": "latest_generated.background_data_url",
            "asset_available": has_background,
        },
        "vehicle": {
            "editable": True,
            "source": "ai_scene",
            "locked": False,
        },
        "product": {
            "editable": True,
            "source": (
                "uploaded_bitmap_deterministic_composite"
                if result.get("product_layer_immutable")
                else "bounded_recreated_product"
            ),
            "identity_locked": True,
            "engineering_dna": True,
            "pixel_locked": bool(
                result.get("product_layer_immutable")
                or result.get("exact_product_structure_lock")
            ),
            "source_sha256": (
                result.get("authoritative_product_sha256") or ""
            ),
        },
        "logo": {
            "editable": True,
            "source": "brand_asset",
            "locked": True,
        },
        "headline": {
            "editable": True,
            "source": "deterministic_text",
            "text": campaign_spec.get("headline") or "",
        },
        "ribbon": {
            "editable": True,
            "source": "deterministic_text",
            "text": campaign_spec.get("compatibility") or "",
        },
        "feature_grid": {
            "editable": True,
            "source": "deterministic_component",
            "items": campaign_spec.get("feature_labels") or [],
        },
        "bottom_bar": {
            "editable": True,
            "source": "deterministic_component",
            "items": campaign_spec.get("bottom_benefits") or [],
        },
        "effects": {
            "editable": True,
            "source": "local_compositor",
        },
    }
    for key, value in geometry.items():
        if key in layers and isinstance(value, (list, tuple)):
            layers[key]["box"] = list(value)
    return {
        "template": template_key,
        "layers": layers,
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }



def _graphic_local_edit_kind_v8000(edit_directive):
    targets = set((edit_directive or {}).get("change_targets") or [])
    if not targets:
        return "provider_edit"
    if targets.issubset({"headline", "feature_matrix", "bottom_benefit_bar", "logo"}):
        return "local_copy"
    if targets.issubset({"layout", "headline", "feature_matrix", "bottom_benefit_bar", "logo"}):
        return "local_layout"
    if targets == {"background"}:
        return "scene_regeneration"
    if targets == {"vehicle"}:
        return "vehicle_regeneration"
    if "hero_product" in targets:
        return "product_recreation"
    return "provider_edit"



def _graphic_update_metrics_v8000(*, elapsed=0.0, provider_calls=0, retries=0, local_edit=False, route="", stages=None):
    state=get_graphic_project_state(); metrics=dict(state.get("production_metrics") or {})
    metrics["generation_count"]=int(metrics.get("generation_count") or 0)+1
    metrics["provider_calls"]=int(metrics.get("provider_calls") or 0)+int(provider_calls or 0)
    metrics["retry_count"]=int(metrics.get("retry_count") or 0)+int(retries or 0)
    metrics["total_seconds"]=round(float(metrics.get("total_seconds") or 0.0)+float(elapsed or 0.0),3)
    if local_edit: metrics["local_edit_count"]=int(metrics.get("local_edit_count") or 0)+1
    count=max(1,int(metrics.get("generation_count") or 1)); metrics["average_seconds"]=round(float(metrics.get("total_seconds") or 0.0)/count,3)
    metrics["last_route"]=str(route or "")
    stage_totals=dict(metrics.get("stage_totals") or {})
    for key,value in (stages or {}).items(): stage_totals[str(key)]=round(float(stage_totals.get(str(key)) or 0.0)+float(value or 0.0),3)
    metrics["stage_totals"]=stage_totals; metrics["last_stages"]={str(k):round(float(v or 0.0),3) for k,v in (stages or {}).items()}
    state["production_metrics"]=metrics; st.session_state[GRAPHIC_PROJECT_STATE_KEY]=state
    return metrics




def _graphic_reference_layout_fidelity_gate_v13000(result, role_items):
    """Quantitatively verify that deterministic zones reproduce reference hierarchy."""
    has_reference = any(item.get("role") == "style_reference" for item in (role_items or []))
    if not has_reference:
        return {"required": False, "passed": True, "score": 1.0, "checks": {}, "issues": []}
    metadata = dict((result or {}).get("layered_metadata") or {})
    expected = dict(metadata.get("reference_layout_blueprint") or {})
    actual = dict(metadata.get("actual_normalized_boxes") or {})
    keys = ("headline_box", "feature_matrix_box", "hero_product_box", "bottom_bar_box")
    weights = {"headline_box": 0.16, "feature_matrix_box": 0.22, "hero_product_box": 0.44, "bottom_bar_box": 0.18}
    checks = {}; score = 0.0; issues = []

    def similarity(a, b):
        try:
            ax, ay, aw, ah = [float(v) for v in a]; bx, by, bw, bh = [float(v) for v in b]
            center_delta = ((ax + aw / 2 - bx - bw / 2) ** 2 + (ay + ah / 2 - by - bh / 2) ** 2) ** 0.5
            size_delta = abs(aw - bw) + abs(ah - bh)
            return max(0.0, min(1.0, 1.0 - center_delta * 2.2 - size_delta * 1.35))
        except Exception:
            return 0.0

    for key in keys:
        value = similarity(expected.get(key), actual.get(key))
        checks[key] = round(value, 4)
        score += value * weights[key]
        if value < (0.76 if key == "hero_product_box" else 0.68):
            issues.append(key.replace("_box", "").replace("_", " ") + " differs materially from reference")

    hero = actual.get("hero_product_box") or [0, 0, 0, 0]
    try:
        hero_width, hero_height = float(hero[2]), float(hero[3])
    except Exception:
        hero_width = hero_height = 0.0
    if hero_height < 0.48:
        issues.append("hero product is not vertically dominant")
    if hero_width < 0.18:
        issues.append("hero product is visually secondary")
    if hero_width * hero_height < 0.15:
        issues.append("hero product visible area is too small")
    trim_report = dict(metadata.get("product_trim_report") or {})
    if trim_report and not trim_report.get("trimmed") and hero_height < 0.52:
        issues.append("product source contains unresolved outer canvas margins")
    feature = actual.get("feature_matrix_box") or [0, 0, 0, 0]
    try:
        if float(feature[2]) < 0.31 or float(feature[3]) < 0.23:
            issues.append("feature matrix is too compressed")
    except Exception:
        issues.append("feature matrix geometry unavailable")
    footer = actual.get("bottom_bar_box") or [0, 0, 0, 0]
    try:
        if float(footer[2]) < 0.85 or float(footer[3]) < 0.08:
            issues.append("bottom benefit bar lacks reference prominence")
    except Exception:
        issues.append("bottom bar geometry unavailable")

    score = round(score, 4)
    return {
        "required": True,
        "passed": bool(score >= 0.78 and not issues),
        "score": score,
        "checks": checks,
        "issues": issues,
        "threshold": 0.78,
        "engine": "v13000-reference-layout-fidelity-gate",
    }


def _graphic_professional_qa_v8000(result, role_items, prompt_text, vehicle_profile, product_mode, structure_profile):
    """Route-aware quality gate for exact compositing and Product DNA recreation."""
    checks={"image_valid":False,"product_valid":True,"vehicle_valid":True,"branding_valid":True,"layout_valid":True,"text_valid":True,"reference_integrity":True,"hero_dominance":True,"reference_layout_fidelity":True}
    raw,_=data_url_to_bytes(str((result or {}).get("data_url") or "")); checks["image_valid"]=bool(raw)
    metadata=dict((result or {}).get("layered_metadata") or {})
    exact_gate={"passed":True,"issues":[],"required":False}
    dna_gate={"available":False,"passed":None,"score":None,"reason":"not required"}
    if product_mode.get("exact_product"):
        exact_gate=_graphic_exact_product_quality_gate_v9000(result,role_items,vehicle_profile)
        exact_gate["required"]=True
        checks["product_valid"]=exact_gate.get("passed",False)
        checks["reference_integrity"]=exact_gate.get("reference_leakage_blocked",False)
        checks["hero_dominance"]=exact_gate.get("hero_dominance",False)
    elif product_mode.get("recreates_product"):
        dna_gate=dict((result or {}).get("product_structure_validation") or {})
        if not dna_gate:
            dna_gate=_graphic_recreated_product_structure_validation_v7100(
                (result or {}).get("data_url"), role_items, prompt_text, structure_profile
            )
        checks["product_valid"] = bool(dna_gate.get("available") and dna_gate.get("passed") is True)
        checks["reference_integrity"] = True
        hero_box=list(metadata.get("product_box") or [])
        canvas=list(metadata.get("canvas_size") or [])
        if len(hero_box)==4 and len(canvas)==2 and canvas[0] and canvas[1]:
            hero_area=(float(hero_box[2])*float(hero_box[3]))/(float(canvas[0])*float(canvas[1]))
            checks["hero_dominance"]=hero_area >= 0.13
    hard=bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    vehicle=(result or {}).get("vehicle_validation") or {}
    if hard and not vehicle:
        vehicle=_graphic_safe_optional_call("graphic_v9000_vehicle_qa_unavailable",lambda:_graphic_focused_vehicle_validation_v3300((result or {}).get("data_url"),role_items,prompt_text,vehicle_profile),_graphic_validation_unavailable_v4100())
    if hard:
        checks["vehicle_valid"] = bool(not _graphic_validation_is_unavailable_v4100(vehicle) and vehicle.get("verified") is True)
    zones={str(x) for x in metadata.get("campaign_zones") or []}
    required={"logo","headline","compatibility_ribbon","tagline","feature_matrix","hero_product","target_vehicle","bottom_benefit_bar"}
    design_mode=str((result or {}).get("graphic_design_mode") or (metadata.get("graphic_design_mode") or ("reference_template" if any(i.get("role")=="style_reference" for i in role_items or []) else "autotecpro_studio")))
    if design_mode=="reference_template":
        layout_gate = _graphic_reference_fidelity_qa_v34000(result, role_items)
        studio_gate = {"required":False,"passed":True}
    else:
        layout_gate = {"required":False,"passed":True,"score":1.0,"issues":[],"engine":"v34000-reference-not-required"}
        studio_gate = _graphic_studio_commercial_qa_v34000(result, dict((get_graphic_project_state() or {}).get("studio_creative_brief") or {}))
    checks["reference_layout_fidelity"] = bool(layout_gate.get("passed"))
    checks["layout_valid"] = bool(required.issubset(zones) and layout_gate.get("passed") and studio_gate.get("passed"))
    checks["branding_valid"]=bool(metadata.get("deterministic_typography") and "logo" in zones)
    checks["text_valid"]=bool(metadata.get("deterministic_typography"))
    hierarchy_gate = _graphic_commercial_hierarchy_score_v18000(result)
    product_detail = _graphic_product_detail_score_v18000(product_mode, exact_gate, dna_gate)
    region_confidence = _graphic_product_region_confidence_v19000(product_mode, exact_gate, dna_gate)
    failure_memory = _graphic_failure_memory_v19000(product_mode, dna_gate, exact_gate)
    checks["commercial_hierarchy"] = bool(hierarchy_gate.get("passed"))
    # Preserve v17000 exact-product stability: the new score is informative for exact
    # composites and hard-gating only for AI-recreated viewpoints.
    if product_mode.get("recreates_product"):
        checks["product_detail"] = bool(product_detail.get("passed"))
    else:
        checks["product_detail"] = bool(checks.get("product_valid"))
    passed=all(checks.values())
    return {
        "passed":passed,
        "checks":checks,
        "exact_product_gate":exact_gate,
        "product_dna_gate":dna_gate,
        "product_detail_score":product_detail,
        "product_region_confidence":region_confidence,
        "failure_memory":failure_memory,
        "vehicle_validation":vehicle,
        "layout_fidelity_gate":layout_gate,
        "studio_commercial_qa":studio_gate,
        "graphic_design_mode":design_mode,
        "commercial_hierarchy_gate":hierarchy_gate,
        "engine":"v34000-dual-mode-lighting-quality-gate",
    }




def _graphic_promote_multiview_sources_v7100(role_items, prompt_text):
    """Promote likely alternate product views during explicit angle recreation.

    Normal generation keeps the existing role classifier untouched. During an
    angle-change request only, current supporting images with product-view names
    are promoted when fewer than two product sources were identified.
    """
    items = [dict(item) for item in (role_items or []) if isinstance(item, dict)]
    recreation = _graphic_product_recreation_intent_v7000(prompt_text)
    if not recreation.get("enabled"):
        return items
    product_count = sum(1 for item in items if item.get("role") == "product_photo")
    if product_count >= 2:
        return items
    product_terms = (
        "product", "unit", "front", "rear", "back", "left", "right", "side",
        "angle", "view", "three-quarter", "3-quarter", "dashboard", "screen",
        "infotainment", "cluster", "max", "pro",
    )
    protected_roles = {"edit_base", "style_reference", "logo_asset"}
    for item in items:
        if product_count >= 6:
            break
        role = str(item.get("role") or "")
        if role in protected_roles or role == "product_photo":
            continue
        name = str(item.get("name") or "").casefold()
        if any(term in name for term in product_terms):
            item["role"] = "product_photo"
            item["role_source"] = "v7100-angle-multiview-promotion"
            product_count += 1
    return items


def _graphic_exact_result_validation_v7100(result, role_items, prompt_text, vehicle_profile):
    """Run inexpensive deterministic checks plus one vehicle check when locked."""
    result = dict(result or {})
    metadata = result.get("layered_metadata") or {}
    raw, _mime = data_url_to_bytes(str(result.get("data_url") or ""))
    required = {
        "logo", "headline", "compatibility_ribbon", "tagline",
        "feature_matrix", "hero_product", "bottom_benefit_bar",
    }
    zones = {str(x).strip().lower() for x in (metadata.get("campaign_zones") or [])}
    image_valid = bool(raw)
    exact_product = bool(metadata.get("exact_product_pixels") or result.get("strict_product_identity_lock"))
    zones_valid = required.issubset(zones)
    hard_vehicle = bool((vehicle_profile or {}).get("hard_vehicle_lock"))
    vehicle = {"verified": True, "available": True, "score": 100, "reason": "not required"}
    if hard_vehicle:
        state_now=get_graphic_project_state(); verified_bg=dict(state_now.get("last_verified_background_v66100") or {})
        background_raw,_=data_url_to_bytes(str(result.get("background_data_url") or ""))
        same_background=bool(background_raw and verified_bg.get("sha256")==_graphic_v66100_bytes_sha(background_raw))
        cached_validation=dict(verified_bg.get("vehicle_validation") or {})
        if same_background and cached_validation.get("verified") is True:
            vehicle={**cached_validation,"reused_verified_background":True,"provider_calls":0,"background_sha256":verified_bg.get("sha256")}
        else:
            vehicle = _graphic_safe_optional_call(
                "graphic_v7100_fast_vehicle_validation_unavailable",
                lambda: _graphic_focused_vehicle_validation_v3300(
                    result.get("data_url"), role_items, prompt_text, vehicle_profile
                ),
                _graphic_validation_unavailable_v4100(),
            )
    unavailable = hard_vehicle and _graphic_validation_is_unavailable_v4100(vehicle)
    explicit_failure = hard_vehicle and not unavailable and vehicle.get("verified") is not True
    core_passed = bool(image_valid and exact_product and zones_valid)
    return {
        "passed": bool(core_passed and not explicit_failure),
        "verified": bool(core_passed and (not hard_vehicle or vehicle.get("verified") is True)),
        "unverified": bool(core_passed and unavailable),
        "image_valid": image_valid,
        "exact_product": exact_product,
        "zones_valid": zones_valid,
        "vehicle_validation": vehicle,
        "vehicle_validation_unavailable": unavailable,
    }


def _graphic_recreated_product_structure_validation_v7100(data_url, role_items, prompt_text, structure_profile):
    """Validate Engine 6.1 reconstructed geometry with 95%+ category thresholds."""
    product_sources=[item for item in (role_items or []) if item.get("role")=="product_photo"][:4]
    if not data_url or not product_sources:
        return {"available":False,"passed":None,"score":None,"reason":"product sources unavailable","provider_calls":0}
    identity=_graphic_product_identity_v18000(role_items,structure_profile)
    engineering=_graphic_product_engineering_dna_v19000(role_items,identity,structure_profile)
    geometry_lock=_graphic_geometry_lock_v20000(role_items,identity,structure_profile)
    thresholds={"overall":97,"geometry":97,"screen":98,"housing":98,"bezel":98,"landmark":97,"side_rails":96,"interface":96,"hardware":96,"left_controls":95,"right_controls":95,"knobs":96,"mounting":97,"openings":97,"materials":95}
    content=[{"type":"input_text","text":(
        "Act as a strict automotive industrial-design Graphic Engine 6.1 inspector. The first image is the generated result and later images are authoritative product sources. "
        "Different coherent perspective, uniform scale, crop, lighting and reflections are allowed; redesign is forbidden. Return JSON only with keys: passed, score, geometry_score, screen_ratio_score, housing_ratio_score, bezel_score, landmark_score, side_rail_score, interface_score, hardware_detail_score, left_controls_score, right_controls_score, knob_score, mounting_score, openings_score, material_score, missing_or_changed_details, confirmed_details, reason. "
        "Fail if housing, inner/outer bezel, display ratio or position, controls, knobs, mounting tabs/holes, openings, UI hierarchy, seams or material boundaries are changed, invented, merged, softened or simplified. "
        f"Required thresholds: {json.dumps(thresholds,sort_keys=True)}.\nUser request: {str(prompt_text or '')[:1200]}\nEngineering Geometry Lock: {json.dumps(geometry_lock,ensure_ascii=False,default=str)[:8500]}\nEngineering DNA: {json.dumps(engineering,ensure_ascii=False,default=str)[:7000]}"
    )},{"type":"input_image","image_url":data_url,"detail":"high"}]
    for item in product_sources:
        source=_graphic_role_data_url(item)
        if source: content.append({"type":"input_image","image_url":source,"detail":"high"})
    try:
        response=client.responses.create(model=_graphic_responses_model_v4000(),input=[{"role":"user","content":content}],max_output_tokens=1500)
        payload=extract_json_object(str(getattr(response,"output_text","") or "")); payload=payload if isinstance(payload,dict) else {}
        def sv(key,fallback=0):
            try:return max(0,min(100,int(float(payload.get(key,fallback) or fallback))))
            except Exception:return 0
        scores={
            "overall":sv("score"),"geometry":sv("geometry_score"),"screen":sv("screen_ratio_score"),
            "housing":sv("housing_ratio_score",sv("geometry_score")),"bezel":sv("bezel_score",sv("geometry_score")),
            "landmark":sv("landmark_score",sv("geometry_score")),"side_rails":sv("side_rail_score",sv("geometry_score")),
            "interface":sv("interface_score"),"hardware":sv("hardware_detail_score"),
            "left_controls":sv("left_controls_score",sv("hardware_detail_score")),"right_controls":sv("right_controls_score",sv("hardware_detail_score")),
            "knobs":sv("knob_score",sv("hardware_detail_score")),"mounting":sv("mounting_score",sv("hardware_detail_score")),
            "openings":sv("openings_score",sv("hardware_detail_score")),"materials":sv("material_score",max(0,sv("score")-2)),
        }
        failed_categories=[k for k,v in scores.items() if v<thresholds[k]]
        passed=bool(payload.get("passed")) and not failed_categories
        result={"available":True,"passed":passed,"score":scores["overall"],"thresholds":thresholds,"failed_categories":failed_categories,"provider_calls":1,
            "missing_or_changed_details":(payload.get("missing_or_changed_details") or [])[:30],"confirmed_details":(payload.get("confirmed_details") or [])[:30],"reason":str(payload.get("reason") or "")[:1500],"policy":"engine6.1_measurement_driven_geometry_and_landmark_lock"}
        mapping={"geometry":"geometry_score","screen":"screen_ratio_score","housing":"housing_ratio_score","bezel":"bezel_score","landmark":"landmark_score","side_rails":"side_rail_score","interface":"interface_score","hardware":"hardware_detail_score","left_controls":"left_controls_score","right_controls":"right_controls_score","knobs":"knob_score","mounting":"mounting_score","openings":"openings_score","materials":"material_score"}
        for k,outk in mapping.items(): result[outk]=scores[k]
        return result
    except Exception as error:
        diagnostic_log("graphic_v20010_product_engineering_validation_unavailable",error_type=type(error).__name__,error=_graphic_compact_error_v4000(error))
        return {"available":False,"passed":None,"score":None,"reason":"Product Engineering DNA validation unavailable","provider_calls":1}




