def _graphic_emergency_provider_result_v15000(
    prompt_text,
    uploaded_files=None,
    *,
    style_strength="High",
    forced_upload_role="Auto-detect",
):
    """Return a usable image when both professional pipelines fail.

    This route intentionally skips optional QA/memory stages but still preserves
    project roles, explicit vehicle facts, reference guidance, and the uploaded
    product inputs. It is a last-resort creation path, not a verified result.
    """
    output_size = choose_graphic_image_size(prompt_text)
    role_items = _graphic_project_role_items(
        uploaded_files, prompt_text, forced_upload_role
    )
    if not role_items:
        raise RuntimeError("No saved Graphic project images were available for recovery.")

    has_style = any(item.get("role") == "style_reference" for item in role_items)
    reference_blueprint = _graphic_safe_optional_call(
        "graphic_v15000_emergency_reference_analysis_unavailable",
        lambda: analyze_graphic_reference_blueprint(
            role_items,
            prompt_text=prompt_text,
            style_strength=style_strength,
        ),
        {},
    ) if has_style else {}
    reference_blueprint = _graphic_safe_reference_blueprint_v16000(reference_blueprint) if has_style else {}
    if has_style:
        _graphic_project_style_dna_v16000(reference_blueprint)
    vehicle_profile = _graphic_resolve_vehicle_lock(
        prompt_text,
        _graphic_safe_optional_call(
            "graphic_v15000_emergency_vehicle_profile_unavailable",
            lambda: research_graphic_vehicle_profile(role_items, prompt_text),
            {},
        ),
    )
    production_prompt = _graphic_chatgpt_production_prompt(
        prompt_text,
        role_items,
        output_size,
        reference_blueprint=reference_blueprint,
        vehicle_profile=vehicle_profile,
        rejected_guidance="",
    )
    recovery_spec = _graphic_verified_campaign_spec_v3300(prompt_text, vehicle_profile)
    recovery_compatibility = str(recovery_spec.get("compatibility") or "").strip()
    if recovery_compatibility:
        production_prompt += (
            "\n\nIMMUTABLE CAMPAIGN COPY — render this exact compatibility text without "
            "shortening, paraphrasing, or replacing it with the representative scene vehicle: "
            + recovery_compatibility
        )

    route_errors = []
    raw_images = []
    provider_route = ""
    for attempt in range(2):
        try:
            raw_images, provider_route = _graphic_responses_generate_v3000(
                role_items, production_prompt, output_size
            )
            if raw_images:
                break
        except Exception as error:
            route_errors.append(
                f"responses-{attempt + 1}:{type(error).__name__}:{_graphic_compact_error_v4000(error)}"
            )
    if not raw_images:
        raw_images, provider_route = _graphic_images_api_fallback_v3000(
            role_items, production_prompt, output_size
        )

    if not raw_images:
        raise RuntimeError("Emergency image provider returned no image bytes.")
    result = _graphic_build_provider_result_v3000(
        raw_images[0],
        prompt_text,
        output_size,
        role_items,
        provider_route,
        reference_blueprint,
        vehicle_profile,
    )
    result = _graphic_mark_unverified_v4100(
        result,
        "The image was created through the recovery route because the strict professional pipeline failed. Review product and vehicle accuracy before publishing.",
        status="completed_recovery_route_v15000",
    )
    result["graphic_engine_version"] = "v15000-graphic-recovery"
    result["recovery_route"] = True
    result["recovery_errors"] = route_errors[-3:]
    _graphic_save_latest_project_result(result)
    return [result]




def _graphic_installed_view_recovery_v47000(
    prompt_text,
    uploaded_files,
    *,
    output_size="1536x1024",
    forced_upload_role="Auto-detect",
):
    """Installed-only recovery using current authoritative role items."""
    effective_prompt = _graphic_resolve_effective_prompt_v47000(
        prompt_text
    )

    # Use the active-ID authority resolver rather than reclassifying all history.
    role_items = _graphic_project_role_items(
        uploaded_files or [],
        effective_prompt,
        forced_role=forced_upload_role,
    )
    product_items = [
        item for item in role_items
        if item.get("role") == "product_photo"
    ]
    if len(product_items) != 1:
        raise RuntimeError(
            "Installed View recovery requires exactly one active product."
        )

    vehicle_profile = _graphic_resolve_vehicle_lock(
        effective_prompt,
        {},
    )
    interior_profile = _graphic_installation_source_plan_v46000(
        effective_prompt,
        role_items,
        vehicle_profile,
    )
    dashboard_item = (
        interior_profile.get("dashboard_source_item")
        if isinstance(interior_profile, dict)
        else None
    )
    if isinstance(dashboard_item, dict):
        dashboard_item["provider_role"] = (
            "installation_dashboard_reference"
        )

    strict_prompt = (
        "FAIL-SAFE VEHICLE INSTALLATION RENDER. Create one photorealistic "
        "AFTER-INSTALLATION photograph from INSIDE the exact vehicle cabin. "
        "When an uploaded dashboard exists, preserve its camera, crop, steering "
        "wheel, cluster, vents, controls, trim, console, materials and lighting "
        "outside the factory replacement region. Modify only the installation "
        "opening and the narrowest seam-blending boundary. Do not return an "
        "advertisement, exterior vehicle, poster, generic dashboard, floating "
        "tablet, generic double-DIN radio, headline, logo, feature grid, banner "
        "or footer. Preserve the active AutoTecPro product identity, screen ratio, "
        "housing, controls and UI. Match dashboard plane, scale, perspective, "
        "occlusion, reflections, exposure, color temperature, contact shadows "
        "and trim seams. Never use historical products.\n"
        f"USER REQUEST: {effective_prompt}\n"
        "INTERIOR SOURCE CONTRACT: "
        + json.dumps(
            {
                key: value
                for key, value in dict(interior_profile or {}).items()
                if key != "dashboard_source_item"
            },
            ensure_ascii=False,
            default=str,
        )[:20000]
    )

    raw_images, route = _graphic_responses_generate_v3000(
        role_items,
        strict_prompt,
        output_size,
    )
    if not raw_images:
        raw_images, route = _graphic_images_api_fallback_v3000(
            role_items,
            strict_prompt,
            output_size,
        )
    if not raw_images:
        raise RuntimeError(
            "Installed View recovery returned no image."
        )

    result = _graphic_build_provider_result_v3000(
        raw_images[0],
        effective_prompt,
        output_size,
        role_items,
        route,
        {},
        vehicle_profile,
    )
    validation = _graphic_safe_optional_call(
        "graphic_v68817_installed_recovery_validation_unavailable",
        lambda: _graphic_installed_view_validation_v45000(
            result.get("data_url"),
            role_items,
            effective_prompt,
            vehicle_profile,
            interior_profile,
        ),
        {
            "available": False,
            "passed": None,
            "reason": "Installed View recovery validation unavailable",
            "provider_calls": 0,
        },
    )
    result.update({
        "adaptive_mode": "installed_view",
        "installed_interior_profile": interior_profile,
        "installed_view_validation": validation,
        "output_status": (
            "completed_installed_view_recovery_v68817"
            if validation.get("passed") is True
            else "completed_installed_view_needs_review_v68817"
        ),
        "verification_status": (
            "verified"
            if validation.get("passed") is True
            else "review_required"
        ),
        "recovery_route": "installed-view-active-authority-v68817",
        "poster_output_prohibited": True,
        "ai_product_recreated": True,
    })
    return [result]




def _graphic_exact_reference_request_v66820(prompt_text, uploaded_files=None, forced_upload_role="Auto-detect"):
    """Return role state for Reference Mode jobs that require immutable uploaded-product pixels."""
    role_items = _graphic_project_role_items(
        uploaded_files,
        _graphic_resolve_effective_prompt_v47000(prompt_text),
        forced_upload_role,
    )
    has_product = any(item.get("role") == "product_photo" for item in role_items or [])
    has_style = any(item.get("role") == "style_reference" for item in role_items or [])
    return {
        "required": bool(has_product and has_style),
        "role_items": role_items,
        "has_product": has_product,
        "has_style": has_style,
    }


def _graphic_exact_reference_result_safe_v66820(images):
    """Accept only results whose metadata proves local immutable-product composition."""
    if not isinstance(images, (list, tuple)) or not images:
        return False
    image = images[0] if isinstance(images[0], dict) else {}
    metadata = dict(image.get("layered_metadata") or {})
    exact_pixels = bool(
        metadata.get("exact_product_pixels")
        or metadata.get("exact_product_asset_mode")
        or image.get("strict_product_identity_lock")
        or image.get("product_layer_immutable")
    )
    source_rgb = bool(
        metadata.get("product_master_rgb_preserved")
        or metadata.get("v55000_product_pixel_authority")
        or image.get("product_layer_immutable")
    )
    provider_generated = metadata.get("product_pixels_provider_generated")
    if provider_generated is None:
        provider_generated = image.get("product_geometry_provider_generated")
    ai_recreated = bool(
        image.get("ai_product_recreated")
        or metadata.get("ai_product_recreated")
    )
    return bool(
        exact_pixels
        and source_rgb
        and provider_generated is False
        and not ai_recreated
    )



