def _graphic_v66860_direct_product_violation(images):
    """Return direct evidence of a product-authority violation, never infer from missing metadata."""
    if not isinstance(images, (list, tuple)) or not images:
        return "missing generated image"
    image = images[0] if isinstance(images[0], dict) else {}
    metadata = dict(image.get("layered_metadata") or {})
    provider_generated = metadata.get("product_pixels_provider_generated")
    if provider_generated is None:
        provider_generated = image.get("product_geometry_provider_generated")
    if provider_generated is True:
        return "provider-generated product geometry"
    if bool(image.get("ai_product_recreated") or metadata.get("ai_product_recreated")):
        return "AI-recreated product geometry"
    if image.get("product_layer_immutable") is False:
        return "product layer explicitly marked mutable"
    if metadata.get("exact_product_asset_mode") is False:
        return "exact product asset mode explicitly rejected"
    return ""


def _graphic_v66860_attach_diagnostic_audit(images, prompt_text):
    """Attach non-blocking completeness diagnostics to successful results."""
    for image in images or []:
        if not isinstance(image, dict):
            continue
        try:
            spec = dict(image.get("campaign_spec") or {})
            audit = _graphic_v66850_campaign_completeness(image, prompt_text, spec)
            image["evidence_release_audit_v66860"] = audit
        except Exception as error:
            image["evidence_release_audit_v66860"] = {
                "passed": True,
                "warnings": ["audit unavailable: " + _graphic_compact_error_v4000(error)],
                "policy": "diagnostic-only-when-unavailable",
            }
    return images



GRAPHIC_V67100_POLICY_VERSION = "v67100-current-job-adaptive-reference-and-proven-recovery"


def _graphic_v67100_item_bytes(item):
    """Return immutable upload bytes without changing the file pointer."""
    if not isinstance(item, dict):
        return b""
    file_obj = item.get("file")
    if file_obj is None:
        return b""
    try:
        return bytes(file_obj.getvalue() or b"")
    except Exception:
        return b""


def _graphic_v67100_item_sha(item):
    raw = _graphic_v67100_item_bytes(item)
    return hashlib.sha256(raw).hexdigest() if raw else ""


def _graphic_v67100_role_sha(role_items, role):
    for item in role_items or []:
        if str(item.get("role") or "") == str(role):
            sha = _graphic_v67100_item_sha(item)
            if sha:
                return sha
    return ""


def _graphic_v67100_job_fingerprint(prompt_text, role_items):
    """Bind mode, blueprint, product and fitment decisions to the current job."""
    parts = [
        GRAPHIC_V67100_POLICY_VERSION,
        re.sub(r"\s+", " ", str(prompt_text or "")).strip()[:12000],
    ]
    for item in role_items or []:
        parts.extend([
            str(item.get("role") or ""),
            _graphic_v67100_item_sha(item) or str(item.get("name") or ""),
        ])
    return hashlib.sha256("|".join(parts).encode("utf-8", "ignore")).hexdigest()


def _graphic_v67100_angle_language(value):
    """Return a conservative normalized angle class from explicit language."""
    text = re.sub(r"\s+", " ", str(value or "")).strip().casefold()
    if not text:
        return {"class": "unknown", "score": 0.0, "label": ""}
    exact_terms = (
        "front view", "straight-on", "straight on", "head-on", "head on",
        "same angle", "preserve angle", "do not change the angle", "no angle change",
    )
    modest_terms = (
        "slightly angled", "slight angle", "subtle angle", "mild perspective",
        "small perspective", "slightly rotate", "small rotation",
    )
    reconstructed_terms = (
        "three-quarter", "three quarter", "3/4", "side view", "rear view",
        "top view", "overhead", "dramatic perspective", "low angle", "high angle",
        "different angle", "new angle", "new perspective",
    )
    if any(term in text for term in exact_terms):
        return {"class": "front", "score": 1.0, "label": "front"}
    if any(term in text for term in reconstructed_terms):
        return {"class": "reconstructed", "score": 0.96, "label": "new-physical-viewpoint"}
    if any(term in text for term in modest_terms):
        return {"class": "modest", "score": 0.78, "label": "modest-2d-orientation"}
    return {"class": "unknown", "score": 0.0, "label": ""}


def _graphic_v67100_reference_blueprint_angle(role_items):
    """Use reference-angle metadata only when it is bound to the current style image."""
    try:
        state = dict(get_graphic_project_state() or {})
        blueprint = dict(state.get("last_reference_blueprint") or {})
    except Exception:
        state, blueprint = {}, {}

    current_sha = _graphic_v67100_role_sha(role_items, "style_reference")
    stored_sha = str(
        blueprint.get("style_reference_sha256")
        or blueprint.get("source_sha256")
        or blueprint.get("reference_sha256")
        or state.get("last_reference_blueprint_sha256")
        or state.get("active_style_reference_sha256")
        or ""
    ).strip()

    matched = bool(current_sha and stored_sha and current_sha == stored_sha)
    if not matched:
        return (
            {"class": "unknown", "score": 0.0, "label": ""},
            {},
            {
                "available": bool(blueprint),
                "matched_current_reference": False,
                "current_reference_sha256": current_sha,
                "stored_reference_sha256": stored_sha,
                "reason": "Blueprint ignored because it is not fingerprinted to the current style reference.",
            },
        )

    candidates = []
    for key in (
        "camera_angle", "product_angle", "product_perspective", "camera",
        "perspective", "product_view", "viewpoint", "composition",
        "layout_description",
    ):
        value = blueprint.get(key)
        if value not in (None, ""):
            candidates.append(str(value))
    for container_key in (
        "product", "hero_product", "composition_analysis", "spatial_blueprint",
    ):
        container = blueprint.get(container_key)
        if isinstance(container, dict):
            for key in ("camera_angle", "angle", "perspective", "view", "viewpoint"):
                if container.get(key) not in (None, ""):
                    candidates.append(str(container.get(key)))

    return (
        _graphic_v67100_angle_language(" | ".join(candidates)),
        blueprint,
        {
            "available": True,
            "matched_current_reference": True,
            "current_reference_sha256": current_sha,
            "stored_reference_sha256": stored_sha,
            "reason": "",
        },
    )


def _graphic_v67100_reference_adaptation_plan(prompt_text, role_items, base_mode):
    """Choose the least destructive treatment using current-job evidence only."""
    prompt = str(prompt_text or "")
    lower = prompt.casefold()
    has_product = any(item.get("role") == "product_photo" for item in role_items or [])
    has_reference = any(item.get("role") == "style_reference" for item in role_items or [])
    product_count = sum(1 for item in role_items or [] if item.get("role") == "product_photo")
    reference_style = bool(has_product and has_reference)

    explicit_exact = bool(re.search(
        r"\b(?:exact original|preserve exact|same angle|front view only|"
        r"do not change (?:the )?angle|no angle change)\b",
        lower, re.I,
    ))
    explicit_angle = bool(re.search(
        r"\b(?:change|turn|rotate|show|create|render|use)\b.{0,55}"
        r"\b(?:unit|product|device|screen|head unit|cluster)?\s*"
        r"(?:angle|view|perspective|three[- ]?quarter|3[- ]?quarter|"
        r"side view|rear view|top view)\b"
        r"|\b(?:different|new|left|right|side|rear|top|overhead|low|high)"
        r"[- ]?(?:angle|view|perspective)\b",
        lower, re.I,
    ))
    prompt_angle = _graphic_v67100_angle_language(prompt)
    reference_angle, blueprint, blueprint_binding = _graphic_v67100_reference_blueprint_angle(role_items)

    treatment = "not_reference_style"
    reason = "No simultaneous authoritative product and style reference."
    confidence = 1.0
    max_angle_change = "mode-defined"

    if reference_style:
        treatment = "exact_composite"
        reason = "The uploaded product remains the least-destructive source of truth."
        max_angle_change = "none"

        if explicit_exact:
            treatment = "exact_composite"
            reason = "The user explicitly requested the original product angle."
        elif explicit_angle:
            treatment = "controlled_product_recreation"
            reason = "The user explicitly requested a new physical viewpoint."
            confidence = 0.99
            max_angle_change = "modest-single-view" if product_count < 2 else "multi-view-product-dna-bounded"
        elif prompt_angle.get("class") == "modest":
            treatment = "exact_2d_adaptation"
            reason = "The user requested only a small complete-layer orientation adjustment."
            confidence = float(prompt_angle.get("score") or 0.78)
            max_angle_change = "small-complete-layer-2d-rotation"
        elif (
            blueprint_binding.get("matched_current_reference")
            and reference_angle.get("class") == "reconstructed"
        ):
            # Blueprint evidence alone cannot force recreation. It may recommend it,
            # but exact composition remains the default unless the user explicitly asks.
            treatment = "exact_composite"
            reason = (
                "The current reference suggests a different viewpoint, but automatic "
                "product recreation is disabled without an explicit angle request."
            )
            confidence = 0.9
        elif (
            blueprint_binding.get("matched_current_reference")
            and reference_angle.get("class") == "modest"
        ):
            treatment = "exact_2d_adaptation"
            reason = "The fingerprint-matched current reference requires only a modest orientation adjustment."
            confidence = float(reference_angle.get("score") or 0.78)
            max_angle_change = "small-complete-layer-2d-rotation"

    return {
        "version": GRAPHIC_V67100_POLICY_VERSION,
        "job_fingerprint": _graphic_v67100_job_fingerprint(prompt, role_items),
        "reference_style_mode": reference_style,
        "treatment": treatment,
        "reason": reason,
        "confidence": round(confidence, 3),
        "product_view_count": product_count,
        "explicit_angle_request": explicit_angle,
        "explicit_exact_request": explicit_exact,
        "prompt_angle": prompt_angle,
        "reference_angle": reference_angle,
        "reference_blueprint_binding": blueprint_binding,
        "max_angle_change": max_angle_change,
        "uniform_scale_allowed": True,
        "independent_xy_scale_allowed": False,
        "lighting_allowed": True,
        "glass_allowed": True,
        "glass_policy": (
            "screen-aperture-clipped-overlay-only"
            if reference_style else "mode-appropriate"
        ),
        "source_blueprint_available": bool(blueprint),
        "base_mode": str(base_mode or ""),
    }


def _graphic_v67100_mode_contract(
    prompt_text,
    uploaded_files=None,
    forced_upload_role="Auto-detect",
    product_transform_mode="Auto",
):
    """Resolve each Graphic mode without globally restricting creative workflows."""
    effective = _graphic_resolve_effective_prompt_v47000(prompt_text)
    role_items = _graphic_project_role_items(
        uploaded_files, effective, forced_upload_role
    )
    has_edit_base = any(item.get("role") == "edit_base" for item in role_items or [])
    mode_info = _graphic_product_mode_v7000(
        effective, role_items, has_edit_base=has_edit_base
    )
    mode = str(mode_info.get("mode") or "fully_generative_concept")
    adaptive_mode = str(mode_info.get("adaptive_mode") or "")
    plan = _graphic_v67100_reference_adaptation_plan(effective, role_items, mode)

    override = str(product_transform_mode or "Auto").strip().casefold()
    if override not in {"", "auto"}:
        if any(token in override for token in ("exact", "original", "preserve")):
            plan["treatment"] = "exact_composite"
            plan["reason"] = "Exact Original Product override selected."
            plan["explicit_exact_request"] = True
        elif any(token in override for token in ("recreate", "angle", "perspective")):
            plan["treatment"] = "controlled_product_recreation"
            plan["reason"] = "Product Recreation override selected."
            plan["explicit_angle_request"] = True
        elif "variant" in override:
            mode = "product_variant"
        elif "install" in override:
            mode = "installed_product_view"

    if plan.get("reference_style_mode"):
        if plan.get("treatment") == "controlled_product_recreation":
            mode = (
                "multi_view_product_reconstruction"
                if plan.get("product_view_count", 0) >= 2
                else "ai_product_recreation"
            )
            adaptive_mode = "product_recreation"
        else:
            mode = "reference_guided_exact_product"
            adaptive_mode = "commercial_lock"

    strict_exact_modes = {
        "reference_guided_exact_product",
        "autotecpro_style_exact_product",
    }
    screen_local_modes = {"ui_replacement"}
    reconstruction_modes = {
        "ai_product_recreation",
        "multi_view_product_reconstruction",
        "installed_product_view",
        "product_variant",
    }
    generative_modes = {"fully_generative_concept"}

    strict_exact = (
        mode in strict_exact_modes
        and plan.get("treatment") != "controlled_product_recreation"
    )
    reference_recreation = bool(
        plan.get("reference_style_mode")
        and plan.get("treatment") == "controlled_product_recreation"
    )
    screen_local = mode in screen_local_modes

    return {
        "version": GRAPHIC_V67100_POLICY_VERSION,
        "mode": mode,
        "adaptive_mode": adaptive_mode,
        "role_items": role_items,
        "job_fingerprint": plan.get("job_fingerprint"),
        "reference_adaptation": plan,
        "reference_style_mode": bool(plan.get("reference_style_mode")),
        "reference_recreation": reference_recreation,
        "strict_exact_product": strict_exact,
        "screen_local_edit": screen_local,
        "allows_product_reconstruction": (
            mode in reconstruction_modes or mode in generative_modes
        ),
        "requires_fitment_lock": bool(
            strict_exact or screen_local or reference_recreation
        ),
        "installed_view": mode == "installed_product_view",
        "product_recreation": mode in {
            "ai_product_recreation",
            "multi_view_product_reconstruction",
        },
        "product_variant": mode == "product_variant",
        "fully_generative": mode == "fully_generative_concept",
        "edit_existing": mode == "edit_existing",
        "uniform_scale_only": bool(
            strict_exact or screen_local or reference_recreation
        ),
        "glass_policy": plan.get("glass_policy"),
    }


def _graphic_v67100_reference_directive(contract):
    plan = dict(contract.get("reference_adaptation") or {})
    if not plan.get("reference_style_mode"):
        return ""
    common = (
        "\n\nV67100 REFERENCE STYLE AUTHORITY:\n"
        "Keep the commercial style, composition, hierarchy, background treatment, "
        "typography, banners, icons and vehicle relationship from the supplied style reference. "
        "The complete user-stated fitment wording remains authoritative and must not be narrowed "
        "by the representative background vehicle. Product size may change only with one uniform "
        "scale factor. Lighting, shadows and environment-aware glass are allowed. Glass effects "
        "must be clipped to the detected screen aperture and must not change the aperture boundary, "
        "screen ratio, bezel, controls, housing or silhouette. "
    )
    treatment = plan.get("treatment")
    if treatment == "controlled_product_recreation":
        return common + (
            "The user explicitly requested a new product viewpoint. Reconstruct only the viewing "
            "angle while preserving Product DNA: screen aspect ratio, bezel-to-screen ratio, "
            "buttons, knobs, lower housing, side panels, mounting structures, openings, seams, "
            "trim materials and OEM identity. With one product view, keep the angle change modest. "
            "With multiple views, use every view as geometry evidence. Do not independently stretch "
            "width and height."
        )
    if treatment == "exact_2d_adaptation":
        return common + (
            "Use the exact uploaded product layer. Permit only translation, uniform scaling and a "
            "small complete-layer 2D rotation. Do not perspective-warp, locally deform, redraw, "
            "widen, narrow or reconstruct hidden surfaces."
        )
    return common + (
        "Use the exact uploaded product layer. Permit translation and uniform scaling. Do not "
        "perspective-warp, locally deform, redraw, widen, narrow or reconstruct the unit."
    )


def _graphic_v67100_exact_proof(images):
    """Use evidence tiers so legacy local composites are not rejected for schema drift."""
    if not isinstance(images, (list, tuple)) or not images:
        return {"passed": False, "available": True, "tier": "missing", "issues": ["missing generated image"]}

    image = images[0] if isinstance(images[0], dict) else {}
    metadata = dict(image.get("layered_metadata") or {})
    violation = _graphic_v66860_direct_product_violation(images)
    if violation:
        return {"passed": False, "available": True, "tier": "direct-violation", "issues": [violation]}

    if _graphic_exact_reference_result_safe_v66820(images):
        return {"passed": True, "available": True, "tier": "explicit-v66820-proof", "issues": []}

    local_markers = [
        bool(image.get("product_layer_immutable")),
        str(image.get("product_identity_method") or "").casefold() == "exact_source_pixel_composite",
        str(image.get("product_transform_mode") or "").casefold() == "exact original product",
        str(image.get("model") or "").casefold().startswith("local-"),
        "deterministic" in str(image.get("recovery_route") or "").casefold(),
        "exact" in str(image.get("output_status") or "").casefold(),
        bool(metadata.get("product_source_sha256")),
        bool(metadata.get("exact_product_asset_mode")),
        bool(metadata.get("product_master_rgb_preserved")),
    ]
    provider_flag = metadata.get("product_pixels_provider_generated")
    if provider_flag is None:
        provider_flag = image.get("product_geometry_provider_generated")

    if sum(1 for marker in local_markers if marker) >= 3 and provider_flag is not True:
        return {
            "passed": True,
            "available": True,
            "tier": "legacy-local-compositor-lineage",
            "issues": [],
        }

    return {
        "passed": False,
        "available": False,
        "tier": "proof-unavailable",
        "issues": ["positive immutable-product provenance is unavailable"],
    }


def _graphic_v67100_recreation_evidence(images):
    """Require positive Product-DNA proof for Reference Style recreation."""
    if not isinstance(images, (list, tuple)) or not images or not isinstance(images[0], dict):
        return {
            "passed": False,
            "available": True,
            "hard_block": True,
            "issues": ["missing generated image"],
        }

    image = images[0]
    candidates = [
        image.get("product_structure_validation"),
        image.get("product_dna_validation"),
        image.get("engineering_validation"),
        (image.get("layered_metadata") or {}).get("product_structure_validation")
        if isinstance(image.get("layered_metadata"), dict) else None,
    ]
    available_reports = []
    failures = []
    positive = []

    for item in candidates:
        if not isinstance(item, dict):
            continue
        if item.get("available") is False:
            continue
        available_reports.append(item)
        if item.get("passed") is False:
            failures.extend(
                item.get("failed_categories")
                or item.get("issues")
                or ["Product DNA validation failed"]
            )
        elif item.get("passed") is True:
            positive.append(item)

    if failures:
        return {
            "passed": False,
            "available": True,
            "hard_block": True,
            "issues": [str(x) for x in failures],
        }
    if not positive:
        return {
            "passed": False,
            "available": bool(available_reports),
            "hard_block": False,
            "issues": ["positive Product DNA validation is unavailable"],
        }
    return {
        "passed": True,
        "available": True,
        "hard_block": False,
        "issues": [],
    }



def _graphic_v67100_fitment_gate(images, prompt_text, *, required, route_name=""):
    """Block only direct affirmative fitment narrowing.

    Missing copy metadata, missing rendered-text manifests, and unavailable OCR are
    diagnostics only. They are not proof that the final artwork removed or changed
    user-authoritative compatibility.
    """
    if not required:
        return {
            "passed": True,
            "available": True,
            "issues": [],
            "diagnostics": [],
            "required_tokens": [],
            "observed_tokens": [],
        }

    if (
        not isinstance(images, (list, tuple))
        or not images
        or not isinstance(images[0], dict)
    ):
        return {
            "passed": False,
            "available": True,
            "issues": ["missing generated image"],
            "diagnostics": [],
            "required_tokens": [],
            "observed_tokens": [],
        }

    image = images[0]
    spec = dict(image.get("campaign_spec") or {})
    layered = dict(image.get("layered_metadata") or {})

    expected = _graphic_extract_full_compatibility_v36000(
        prompt_text,
        "",
    )
    required_tokens = _graphic_copy_required_tokens_v36000(expected)

    compatibility_candidates = [
        image.get("rendered_compatibility"),
        image.get("deterministic_fitment_copy"),
        spec.get("compatibility"),
        layered.get("compatibility"),
        image.get("compatibility"),
    ]
    compatibility = next(
        (
            str(value).strip()
            for value in compatibility_candidates
            if str(value or "").strip()
        ),
        "",
    )
    observed_tokens = _graphic_copy_required_tokens_v36000(compatibility)

    issues = []
    diagnostics = []

    # Direct narrowing exists only when actual observed compatibility copy is
    # available and omits user-required tokens or year ranges.
    if compatibility:
        missing = [
            token for token in required_tokens
            if token not in observed_tokens
        ]
        if missing:
            issues.append(
                "missing required fitment tokens: " + ", ".join(missing)
            )
    elif required_tokens:
        diagnostics.append(
            "rendered compatibility metadata unavailable; not treated as narrowing"
        )

    explicit_size = re.search(
        r"\b\d{1,2}(?:\.\d)?\s*(?:inch|inches|[\"”])"
        r"\s*(?:hd|qhd|uhd|4k)?\b",
        str(prompt_text or ""),
        re.I,
    )

    observed_size_text = " ".join([
        str(spec.get("screen_size") or ""),
        str(layered.get("screen_size") or ""),
        str(image.get("rendered_screen_size") or ""),
        str(image.get("deterministic_screen_size_copy") or ""),
    ]).strip()

    # A screen-size blocker requires an actual conflicting observed size.
    # Absence of optional size metadata is diagnostic only.
    if explicit_size:
        expected_number_match = re.search(
            r"\d{1,2}(?:\.\d)?",
            explicit_size.group(0),
        )
        observed_numbers = re.findall(
            r"\b\d{1,2}(?:\.\d)?\b",
            observed_size_text,
        )
        if observed_size_text and expected_number_match:
            expected_number = expected_number_match.group(0)
            if observed_numbers and expected_number not in observed_numbers:
                issues.append(
                    "explicit screen size was changed from "
                    + expected_number
                    + " to "
                    + ", ".join(observed_numbers)
                )
        elif not observed_size_text:
            diagnostics.append(
                "screen-size metadata unavailable; not treated as removal"
            )

    return {
        "passed": not issues,
        "available": bool(compatibility or observed_size_text),
        "issues": issues,
        "diagnostics": diagnostics,
        "required_tokens": required_tokens,
        "observed_tokens": observed_tokens,
        "expected_compatibility": expected,
        "observed_compatibility": compatibility,
        "observed_screen_size": observed_size_text,
        "policy": "v68710-direct-affirmative-fitment-narrowing-only",
    }



def _graphic_v67100_accept_or_route(images, prompt_text, contract, *, route_name):
    """Balance strict product authority with the proven no-false-failure principle."""
    proof = None
    recreation = None

    if contract.get("strict_exact_product"):
        proof = _graphic_v67100_exact_proof(images)
        if not proof.get("passed"):
            return {
                "accepted": False,
                "hard_block": proof.get("tier") == "direct-violation",
                "reason": "; ".join(proof.get("issues") or ["exact-product proof unavailable"]),
                "exact_proof": proof,
            }

    elif contract.get("screen_local_edit"):
        violation = _graphic_v66860_direct_product_violation(images)
        if violation:
            return {
                "accepted": False,
                "hard_block": True,
                "reason": violation,
            }

    elif contract.get("reference_recreation"):
        recreation = _graphic_v67100_recreation_evidence(images)
        if not recreation.get("passed"):
            return {
                "accepted": False,
                "hard_block": bool(recreation.get("hard_block")),
                "reason": "; ".join(
                    recreation.get("issues") or ["Product DNA proof unavailable"]
                ),
                "recreation": recreation,
            }

    fitment = _graphic_v67100_fitment_gate(
        images,
        prompt_text,
        required=bool(contract.get("requires_fitment_lock")),
        route_name=route_name,
    )
    if not fitment.get("passed"):
        return {
            "accepted": False,
            "hard_block": False,
            "reason": "; ".join(fitment.get("issues") or ["fitment verification failed"]),
            "fitment": fitment,
        }
    if contract.get("requires_fitment_lock") and not fitment.get("available"):
        return {
            "accepted": False,
            "hard_block": False,
            "reason": "fitment proof unavailable; use deterministic copy recovery",
            "fitment": fitment,
        }

    for image in images or []:
        if not isinstance(image, dict):
            continue
        image["graphic_mode_contract_v67100"] = {
            key: value for key, value in contract.items() if key != "role_items"
        }
        image["reference_adaptation_v67100"] = dict(
            contract.get("reference_adaptation") or {}
        )
        image["fitment_gate_v67100"] = fitment
        image["exact_product_proof_v67100"] = proof or {}
        image["product_dna_proof_v67100"] = recreation or {}
        image["accepted_route_v67100"] = route_name
        image["glass_policy_v67100"] = str(
            (contract.get("reference_adaptation") or {}).get("glass_policy")
            or "mode-appropriate"
        )

    return {
        "accepted": True,
        "hard_block": False,
        "reason": "",
        "fitment": fitment,
        "exact_proof": proof,
        "recreation": recreation,
    }




GRAPHIC_V67400_POLICY_VERSION = "v67400-three-level-reference-style-authority"
GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES = 15.0
GRAPHIC_V67400_MAX_SINGLE_VIEW_RECONSTRUCTION_DEGREES = 30.0


def _graphic_v67400_requested_angle(prompt_text):
    """Parse an explicit product-angle request without confusing layout placement.

    Returns a normalized request:
    - `none`: no angle request;
    - `rotate_2d`: complete-layer clockwise/counter-clockwise rotation;
    - `viewpoint_3d`: physical left/right/three-quarter perspective recreation.
    """
    text = re.sub(r"\s+", " ", str(prompt_text or "")).strip()
    lower = text.casefold()

    degree_match = re.search(
        r"(?P<degrees>\d{1,3}(?:\.\d+)?)\s*(?:°|degrees?|deg)\b",
        lower,
        re.I,
    )
    degrees = float(degree_match.group("degrees")) if degree_match else None

    direction = ""
    if re.search(r"\b(?:clockwise|cw)\b", lower):
        direction = "clockwise"
    elif re.search(r"\b(?:counter[- ]?clockwise|anticlockwise|ccw)\b", lower):
        direction = "counterclockwise"
    elif re.search(r"\b(?:to the |toward the |towards the )?right\b", lower):
        direction = "right"
    elif re.search(r"\b(?:to the |toward the |towards the )?left\b", lower):
        direction = "left"
    elif re.search(r"\bthree[- ]?quarter\b|\b3\s*/\s*4\b", lower):
        direction = "three-quarter"
    elif re.search(r"\bside view\b", lower):
        direction = "side"
    elif re.search(r"\brear view\b", lower):
        direction = "rear"
    elif re.search(r"\btop view\b|\boverhead\b", lower):
        direction = "top"

    explicit_no_change = bool(re.search(
        r"\b(?:do not|don't|never)\s+(?:change|adjust|rotate|turn)\s+"
        r"(?:the\s+)?(?:unit|product|device|screen|head unit|cluster)?\s*angle\b"
        r"|\b(?:same|original|uploaded)\s+angle\b"
        r"|\bfront view only\b",
        lower,
        re.I,
    ))
    if explicit_no_change:
        return {
            "kind": "none",
            "requested": False,
            "degrees": 0.0,
            "direction": "",
            "explicit_original_angle": True,
            "source_text": text,
        }

    angle_intent = bool(re.search(
        r"\b(?:rotate|turn|angle|perspective|viewpoint|three[- ]?quarter|"
        r"3\s*/\s*4|side view|rear view|top view|overhead)\b",
        lower,
        re.I,
    ))
    if not angle_intent:
        return {
            "kind": "none",
            "requested": False,
            "degrees": 0.0,
            "direction": "",
            "explicit_original_angle": False,
            "source_text": text,
        }

    # Clockwise/counter-clockwise language means a flat complete-layer rotation.
    if direction in {"clockwise", "counterclockwise"}:
        return {
            "kind": "rotate_2d",
            "requested": True,
            "degrees": float(degrees or 8.0),
            "direction": direction,
            "explicit_original_angle": False,
            "source_text": text,
        }

    # "Tilt slightly" without a left/right physical viewpoint is also a 2D change.
    if re.search(r"\b(?:tilt|slightly rotate|small rotation|minor rotation)\b", lower) and direction not in {
        "left", "right", "three-quarter", "side", "rear", "top"
    }:
        return {
            "kind": "rotate_2d",
            "requested": True,
            "degrees": float(degrees or 8.0),
            "direction": direction or "clockwise",
            "explicit_original_angle": False,
            "source_text": text,
        }

    # Left/right and named viewpoints require hidden-surface reconstruction.
    return {
        "kind": "viewpoint_3d",
        "requested": True,
        "degrees": float(degrees or (25.0 if direction in {"left", "right"} else 30.0)),
        "direction": direction or "unspecified",
        "explicit_original_angle": False,
        "source_text": text,
    }


def _graphic_v67400_requested_uniform_scale(prompt_text):
    """Extract an optional displayed-size request; never create X/Y stretching."""
    text = re.sub(r"\s+", " ", str(prompt_text or "")).strip()
    lower = text.casefold()

    percent = re.search(
        r"\b(?:make|resize|scale|enlarge|increase|reduce|shrink)\b.{0,45}?"
        r"(?P<percent>\d{1,3}(?:\.\d+)?)\s*%",
        lower,
        re.I,
    )
    if percent:
        value = float(percent.group("percent"))
        if re.search(r"\b(?:reduce|smaller|shrink|decrease)\b", lower):
            factor = max(0.25, 1.0 - value / 100.0)
        else:
            factor = min(3.0, 1.0 + value / 100.0)
        return {
            "requested": True,
            "factor": round(factor, 4),
            "source": "explicit-percentage",
            "uniform_only": True,
        }

    relative = ""
    if re.search(r"\b(?:much|significantly)\s+larger\b|\bmake .{0,30}\blarger\b", lower):
        relative = "larger"
        factor = 1.20
    elif re.search(r"\b(?:slightly|a little)\s+larger\b", lower):
        relative = "slightly-larger"
        factor = 1.10
    elif re.search(r"\b(?:much|significantly)\s+smaller\b|\bmake .{0,30}\bsmaller\b", lower):
        relative = "smaller"
        factor = 0.80
    elif re.search(r"\b(?:slightly|a little)\s+smaller\b", lower):
        relative = "slightly-smaller"
        factor = 0.90
    else:
        return {
            "requested": False,
            "factor": None,
            "source": "",
            "uniform_only": True,
        }

    return {
        "requested": True,
        "factor": factor,
        "source": relative,
        "uniform_only": True,
    }


def _graphic_v67400_reference_adaptation_plan(prompt_text, role_items, base_mode):
    """Resolve the three Reference Style product treatments.

    Treatment order:
    1. exact composite;
    2. exact complete-layer 2D adaptation;
    3. verified Product-DNA viewpoint reconstruction.
    """
    prompt = str(prompt_text or "")
    has_product = any(item.get("role") == "product_photo" for item in role_items or [])
    has_reference = any(item.get("role") == "style_reference" for item in role_items or [])
    product_count = sum(1 for item in role_items or [] if item.get("role") == "product_photo")
    reference_style = bool(has_product and has_reference)

    angle = _graphic_v67400_requested_angle(prompt)
    scale = _graphic_v67400_requested_uniform_scale(prompt)
    reference_angle, blueprint, blueprint_binding = _graphic_v67100_reference_blueprint_angle(role_items)

    treatment = "not_reference_style"
    level = "not-reference-style"
    reason = "No simultaneous authoritative product and style reference."
    requires_product_dna = False
    max_angle_change = "mode-defined"

    if reference_style:
        treatment = "exact_composite"
        level = "reference-exact"
        reason = "Use the immutable uploaded product with uniform scale and placement."
        max_angle_change = "none"

        if angle.get("explicit_original_angle"):
            treatment = "exact_composite"
            level = "reference-exact"
            reason = "The user explicitly requested the uploaded product angle."
        elif angle.get("kind") == "rotate_2d":
            degrees = abs(float(angle.get("degrees") or 0.0))
            if degrees <= GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES:
                treatment = "exact_2d_adaptation"
                level = "reference-adaptive"
                reason = (
                    "The request can be satisfied by rotating the complete immutable "
                    "product layer without reconstructing hidden surfaces."
                )
                max_angle_change = f"{degrees:g}-degree-complete-layer-2d"
            else:
                treatment = "verified_product_dna_reconstruction"
                level = "reference-reconstruction"
                reason = (
                    "The requested flat rotation exceeds the safe 2D threshold and "
                    "requires verified Product-DNA reconstruction."
                )
                requires_product_dna = True
                max_angle_change = f"{degrees:g}-degree-verified-reconstruction"
        elif angle.get("kind") == "viewpoint_3d":
            treatment = "verified_product_dna_reconstruction"
            level = "reference-reconstruction"
            reason = (
                "A physical left/right or perspective viewpoint reveals hidden surfaces "
                "and therefore requires positive Product-DNA validation."
            )
            requires_product_dna = True
            max_angle_change = (
                f"{float(angle.get('degrees') or 0.0):g}-degree-"
                f"{str(angle.get('direction') or 'viewpoint')}"
            )
        elif (
            blueprint_binding.get("matched_current_reference")
            and reference_angle.get("class") == "modest"
        ):
            treatment = "exact_2d_adaptation"
            level = "reference-adaptive"
            reason = (
                "The fingerprint-matched current reference requires only a modest "
                "complete-layer orientation adjustment."
            )
            max_angle_change = "maximum-15-degree-complete-layer-2d"
        elif (
            blueprint_binding.get("matched_current_reference")
            and reference_angle.get("class") == "reconstructed"
        ):
            # A reference alone may not silently authorize product recreation.
            treatment = "exact_composite"
            level = "reference-exact"
            reason = (
                "The reference suggests another viewpoint, but the uploaded exact product "
                "is retained because the user did not explicitly authorize reconstruction."
            )

    return {
        "version": GRAPHIC_V67400_POLICY_VERSION,
        "job_fingerprint": _graphic_v67100_job_fingerprint(prompt, role_items),
        "reference_style_mode": reference_style,
        "reference_level": level,
        "treatment": treatment,
        "reason": reason,
        "product_view_count": product_count,
        "angle_request": angle,
        "scale_request": scale,
        "requires_positive_product_dna": requires_product_dna,
        "single_view_reconstruction_limit_degrees": (
            GRAPHIC_V67400_MAX_SINGLE_VIEW_RECONSTRUCTION_DEGREES
        ),
        "safe_2d_rotation_limit_degrees": (
            GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES
        ),
        "reference_angle": reference_angle,
        "reference_blueprint_binding": blueprint_binding,
        "max_angle_change": max_angle_change,
        "uniform_scale_allowed": True,
        "independent_xy_scale_allowed": False,
        "lighting_allowed": True,
        "shadow_allowed": True,
        "glass_allowed": True,
        "glass_policy": (
            "screen-aperture-clipped-overlay-only"
            if reference_style else "mode-appropriate"
        ),
        "source_blueprint_available": bool(blueprint),
        "base_mode": str(base_mode or ""),
    }


def _graphic_v67400_mode_contract(
    prompt_text,
    uploaded_files=None,
    forced_upload_role="Auto-detect",
    product_transform_mode="Auto",
):
    """Resolve mode while preserving Reference Style across all three levels."""
    effective = _graphic_resolve_effective_prompt_v47000(prompt_text)
    role_items = _graphic_project_role_items(
        uploaded_files, effective, forced_upload_role
    )
    has_edit_base = any(item.get("role") == "edit_base" for item in role_items or [])
    mode_info = _graphic_product_mode_v7000(
        effective, role_items, has_edit_base=has_edit_base
    )
    mode = str(mode_info.get("mode") or "fully_generative_concept")
    adaptive_mode = str(mode_info.get("adaptive_mode") or "")
    plan = _graphic_v67400_reference_adaptation_plan(effective, role_items, mode)

    override = str(product_transform_mode or "Auto").strip().casefold()
    if override not in {"", "auto"}:
        if any(token in override for token in ("exact", "original", "preserve")):
            plan["treatment"] = "exact_composite"
            plan["reference_level"] = "reference-exact"
            plan["reason"] = "Exact Original Product override selected."
            plan["requires_positive_product_dna"] = False
        elif any(token in override for token in ("recreate", "angle", "perspective")):
            plan["treatment"] = "verified_product_dna_reconstruction"
            plan["reference_level"] = "reference-reconstruction"
            plan["reason"] = "Verified Product Recreation override selected."
            plan["requires_positive_product_dna"] = True
        elif "variant" in override:
            mode = "product_variant"
        elif "install" in override:
            mode = "installed_product_view"

    if plan.get("reference_style_mode"):
        if plan.get("treatment") == "verified_product_dna_reconstruction":
            mode = (
                "multi_view_product_reconstruction"
                if plan.get("product_view_count", 0) >= 2
                else "ai_product_recreation"
            )
            adaptive_mode = "product_recreation"
        else:
            mode = "reference_guided_exact_product"
            adaptive_mode = "commercial_lock"

    strict_exact = bool(
        plan.get("reference_style_mode")
        and plan.get("treatment") in {"exact_composite", "exact_2d_adaptation"}
    )
    reference_recreation = bool(
        plan.get("reference_style_mode")
        and plan.get("treatment") == "verified_product_dna_reconstruction"
    )
    screen_local = mode == "ui_replacement"

    reconstruction_modes = {
        "ai_product_recreation",
        "multi_view_product_reconstruction",
        "installed_product_view",
        "product_variant",
    }

    return {
        "version": GRAPHIC_V67400_POLICY_VERSION,
        "mode": mode,
        "adaptive_mode": adaptive_mode,
        "role_items": role_items,
        "job_fingerprint": plan.get("job_fingerprint"),
        "reference_adaptation": plan,
        "reference_style_mode": bool(plan.get("reference_style_mode")),
        "reference_level": plan.get("reference_level"),
        "reference_recreation": reference_recreation,
        "strict_exact_product": strict_exact,
        "screen_local_edit": screen_local,
        "allows_product_reconstruction": bool(
            reference_recreation
            or mode in reconstruction_modes
            or mode == "fully_generative_concept"
        ),
        "requires_fitment_lock": bool(
            strict_exact or screen_local or reference_recreation
        ),
        "installed_view": mode == "installed_product_view",
        "product_recreation": mode in {
            "ai_product_recreation",
            "multi_view_product_reconstruction",
        },
        "product_variant": mode == "product_variant",
        "fully_generative": mode == "fully_generative_concept",
        "edit_existing": mode == "edit_existing",
        "uniform_scale_only": bool(
            strict_exact or screen_local or reference_recreation
        ),
        "glass_policy": plan.get("glass_policy"),
    }


def _graphic_v67400_reference_directive(contract):
    plan = dict(contract.get("reference_adaptation") or {})
    if not plan.get("reference_style_mode"):
        return ""

    scale = dict(plan.get("scale_request") or {})
    angle = dict(plan.get("angle_request") or {})
    scale_instruction = ""
    if scale.get("requested") and scale.get("factor"):
        scale_instruction = (
            f" Display the complete product at approximately {float(scale['factor']):.3f} "
            "times its normal campaign scale, using the same factor for width and height."
        )

    common = (
        "\n\nV67400 THREE-LEVEL REFERENCE STYLE AUTHORITY:\n"
        "Keep the supplied reference's commercial composition, visual hierarchy, "
        "background treatment, typography, banners, icons, vehicle relationship and "
        "overall campaign style. Preserve the complete user-stated fitment wording; "
        "the representative background vehicle must never narrow compatibility. "
        "Product resizing is allowed only through one uniform scale factor. "
        "Independent X/Y scaling, screen widening and local geometry warping are prohibited."
        + scale_instruction +
        " Lighting, body highlights, contact shadows and environmental integration are allowed. "
        "Glass enhancement must be clipped strictly inside the detected screen aperture and "
        "must not change the aperture boundary, screen ratio, bezel, controls, housing or silhouette. "
    )

    treatment = plan.get("treatment")
    if treatment == "verified_product_dna_reconstruction":
        degrees = float(angle.get("degrees") or 0.0)
        direction = str(angle.get("direction") or "requested viewpoint")
        return common + (
            f"The user explicitly requested a physical viewpoint change of approximately "
            f"{degrees:g} degrees toward {direction}. Keep Reference Style Mode active, but "
            "reconstruct only the viewpoint. Positive Product-DNA validation is mandatory for "
            "screen aspect ratio, bezel-to-screen ratio, button and knob positions, lower housing, "
            "side panels, mounting structures, openings, seams, trim materials and OEM identity. "
            "With one product view, do not exceed the supported modest reconstruction envelope and "
            "do not invent unsupported hidden brackets or housing. With multiple product views, use "
            "all views as geometry evidence. If positive validation is unavailable, retain the exact "
            "uploaded angle instead of returning an unverified product."
        )
    if treatment == "exact_2d_adaptation":
        degrees = min(
            abs(float(angle.get("degrees") or GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES)),
            GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES,
        )
        direction = str(angle.get("direction") or "clockwise")
        return common + (
            f"Use the exact uploaded product layer and apply only translation, uniform scaling "
            f"and a complete-layer 2D rotation of up to {degrees:g} degrees {direction}. "
            "Do not use perspective warping, redraw product details or reconstruct hidden surfaces."
        )
    return common + (
        "Use the exact uploaded product layer. Permit translation and uniform scaling only. "
        "Do not perspective-warp, locally deform, redraw, widen, narrow or reconstruct the unit."
    )


def _graphic_v67400_recreation_evidence(images, contract):
    """Require positive, relevant Product-DNA proof for Reference reconstruction."""
    if not isinstance(images, (list, tuple)) or not images or not isinstance(images[0], dict):
        return {
            "passed": False,
            "available": True,
            "hard_block": True,
            "issues": ["missing generated image"],
        }

    image = images[0]
    layered = dict(image.get("layered_metadata") or {})
    candidates = [
        image.get("product_structure_validation"),
        image.get("product_dna_validation"),
        image.get("engineering_validation"),
        layered.get("product_structure_validation"),
        layered.get("product_dna_validation"),
    ]
    failures = []
    positive = []

    for report in candidates:
        if not isinstance(report, dict) or report.get("available") is False:
            continue
        if report.get("passed") is False:
            failures.extend(
                report.get("failed_categories")
                or report.get("issues")
                or ["Product DNA validation failed"]
            )
        elif report.get("passed") is True:
            positive.append(report)

    if failures:
        return {
            "passed": False,
            "available": True,
            "hard_block": True,
            "issues": [str(item) for item in failures],
        }
    if not positive:
        return {
            "passed": False,
            "available": False,
            "hard_block": False,
            "issues": ["positive Product DNA validation is unavailable"],
        }

    plan = dict(contract.get("reference_adaptation") or {})
    angle = dict(plan.get("angle_request") or {})
    requested_degrees = abs(float(angle.get("degrees") or 0.0))
    product_views = int(plan.get("product_view_count") or 0)

    if (
        product_views < 2
        and requested_degrees
        > GRAPHIC_V67400_MAX_SINGLE_VIEW_RECONSTRUCTION_DEGREES
    ):
        return {
            "passed": False,
            "available": True,
            "hard_block": False,
            "issues": [
                "requested angle exceeds the single-view verified reconstruction limit"
            ],
        }

    required_categories = {
        "screen_aspect_ratio",
        "bezel_to_screen_ratio",
        "control_layout",
        "lower_housing",
        "mounting_structures",
        "overall_silhouette",
    }
    confirmed = set()
    for report in positive:
        for key in (
            "passed_categories",
            "confirmed_categories",
            "validated_categories",
        ):
            values = report.get(key) or []
            if isinstance(values, str):
                values = [values]
            confirmed.update(
                re.sub(r"[^a-z0-9]+", "_", str(value).casefold()).strip("_")
                for value in values
            )

    # Some existing validators provide only passed=True. Accept that report as
    # positive proof, but explicitly mark detailed category coverage unavailable.
    detailed_coverage = bool(confirmed)
    missing_categories = sorted(required_categories - confirmed) if detailed_coverage else []

    if missing_categories:
        return {
            "passed": False,
            "available": True,
            "hard_block": False,
            "issues": [
                "Product DNA validation did not confirm: "
                + ", ".join(missing_categories)
            ],
        }

    return {
        "passed": True,
        "available": True,
        "hard_block": False,
        "issues": [],
        "requested_degrees": requested_degrees,
        "product_view_count": product_views,
        "detailed_category_coverage": detailed_coverage,
    }


def _graphic_v67400_accept_or_route(images, prompt_text, contract, *, route_name):
    """Use v67310 exact authority and v67400 reconstruction authority."""
    if contract.get("reference_recreation"):
        recreation = _graphic_v67400_recreation_evidence(images, contract)
        if not recreation.get("passed"):
            return {
                "accepted": False,
                "hard_block": bool(recreation.get("hard_block")),
                "reason": "; ".join(
                    recreation.get("issues") or ["Product DNA proof unavailable"]
                ),
                "recreation": recreation,
            }

        fitment = _graphic_v67100_fitment_gate(
            images,
            prompt_text,
            required=True,
            route_name=route_name,
        )
        if not fitment.get("passed") or not fitment.get("available"):
            return {
                "accepted": False,
                "hard_block": False,
                "reason": "; ".join(
                    fitment.get("issues")
                    or ["fitment proof unavailable; use deterministic copy recovery"]
                ),
                "fitment": fitment,
                "recreation": recreation,
            }

        for image in images or []:
            if not isinstance(image, dict):
                continue
            image["graphic_mode_contract_v67400"] = {
                key: value for key, value in contract.items() if key != "role_items"
            }
            image["reference_adaptation_v67400"] = dict(
                contract.get("reference_adaptation") or {}
            )
            image["product_dna_proof_v67400"] = recreation
            image["fitment_gate_v67400"] = fitment
            image["accepted_route_v67400"] = route_name
            image["graphic_policy_version"] = GRAPHIC_V67400_POLICY_VERSION
        return {
            "accepted": True,
            "hard_block": False,
            "reason": "",
            "fitment": fitment,
            "recreation": recreation,
        }

    return _graphic_v67100_accept_or_route(
        images,
        prompt_text,
        contract,
        route_name=route_name,
    )




GRAPHIC_V67510_POLICY_VERSION = "v67510-feature-preserving-isolated-fallback"


def _graphic_v67510_optional_enrichment(prompt_text, role_items):
    """Collect already-available enhancement data without making it a dependency.

    Every lookup is isolated. Failure returns a smaller enrichment payload rather
    than raising, preserving the guaranteed local fallback.
    """
    enrichment = {
        "reference_blueprint": {},
        "vehicle_profile": {},
        "reference_style_available": False,
        "vehicle_profile_available": False,
        "feature_copy": [],
        "warnings": [],
    }

    try:
        state = dict(get_graphic_project_state() or {})
    except Exception as error:
        state = {}
        enrichment["warnings"].append(
            f"project-state:{type(error).__name__}"
        )

    style_item = next(
        (item for item in role_items or [] if item.get("role") == "style_reference"),
        None,
    )
    current_reference_sha = ""
    if style_item:
        try:
            raw = _graphic_v67100_item_bytes(style_item)
            if raw:
                current_reference_sha = hashlib.sha256(raw).hexdigest()
        except Exception:
            current_reference_sha = ""

    try:
        blueprint = dict(state.get("last_reference_blueprint") or {})
        stored_sha = str(
            blueprint.get("style_reference_sha256")
            or blueprint.get("source_sha256")
            or blueprint.get("reference_sha256")
            or state.get("last_reference_blueprint_sha256")
            or state.get("active_style_reference_sha256")
            or ""
        ).strip()
        if (
            blueprint
            and current_reference_sha
            and stored_sha
            and current_reference_sha == stored_sha
        ):
            enrichment["reference_blueprint"] = blueprint
            enrichment["reference_style_available"] = True
    except Exception as error:
        enrichment["warnings"].append(
            f"reference-blueprint:{type(error).__name__}"
        )

    try:
        vehicle = dict(
            state.get("last_vehicle_profile")
            or state.get("vehicle_profile")
            or {}
        )
        if vehicle:
            enrichment["vehicle_profile"] = vehicle
            enrichment["vehicle_profile_available"] = True
    except Exception as error:
        enrichment["warnings"].append(
            f"vehicle-profile:{type(error).__name__}"
        )

    try:
        spec = dict(_graphic_extract_campaign_spec(prompt_text) or {})
        features = spec.get("features") or spec.get("feature_matrix") or []
        if isinstance(features, str):
            features = [part.strip() for part in re.split(r"[,;|]", features) if part.strip()]
        if isinstance(features, (list, tuple)):
            enrichment["feature_copy"] = [str(item).strip() for item in features if str(item).strip()][:8]
    except Exception as error:
        enrichment["warnings"].append(
            f"campaign-copy:{type(error).__name__}"
        )

    return enrichment


def _graphic_v67510_blueprint_box(blueprint, key, default):
    """Read one normalized reference box safely; fall back without raising."""
    try:
        boxes = dict((blueprint or {}).get("normalized_boxes") or {})
        value = boxes.get(key)
        if not (isinstance(value, (list, tuple)) and len(value) == 4):
            return tuple(default)
        x, y, w, h = [float(part) for part in value]
        if w <= 0 or h <= 0:
            return tuple(default)
        return (
            max(0.0, min(1.0, x)),
            max(0.0, min(1.0, y)),
            max(0.02, min(1.0, w)),
            max(0.02, min(1.0, h)),
        )
    except Exception:
        return tuple(default)


def _graphic_v67510_optional_feature_pairs(enrichment, default_pairs):
    """Use cached/structured feature copy only when it is already available."""
    values = list((enrichment or {}).get("feature_copy") or [])
    if not values:
        return list(default_pairs)
    pairs = []
    for value in values[:6]:
        text = re.sub(r"\s+", " ", str(value)).strip()
        if not text:
            continue
        words = text.split()
        if len(words) <= 2:
            pairs.append((text, ""))
        else:
            split = max(1, len(words) // 2)
            pairs.append((" ".join(words[:split]), " ".join(words[split:])))
    return pairs or list(default_pairs)


GRAPHIC_V67500_POLICY_VERSION = "v67510-feature-preserving-isolated-fallback"


def _graphic_v67500_normalize_results(value):
    """Normalize historical/provider result shapes into a list of image dictionaries."""
    if value is None:
        return []
    if isinstance(value, dict):
        if value.get("data_url"):
            return [value]
        for key in ("images", "results", "output", "data"):
            nested = value.get(key)
            normalized = _graphic_v67500_normalize_results(nested)
            if normalized:
                return normalized
        return []
    if isinstance(value, (list, tuple)):
        normalized = []
        for item in value:
            normalized.extend(_graphic_v67500_normalize_results(item))
        return normalized
    return []


def _graphic_v67500_safe_font(size, *, bold=False, italic=False):
    """Load a local system font without depending on project font assets."""
    if Image is None:
        return None
    try:
        from PIL import ImageFont
    except Exception:
        return None

    candidates = []
    if bold and italic:
        candidates.extend([
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-BoldOblique.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-BoldItalic.ttf",
        ])
    elif bold:
        candidates.extend([
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
        ])
    elif italic:
        candidates.extend([
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Italic.ttf",
        ])
    else:
        candidates.extend([
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
        ])

    for candidate in candidates:
        try:
            return ImageFont.truetype(candidate, int(size))
        except Exception:
            continue
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def _graphic_v67500_fit_text(draw, text, max_width, start_size, *, bold=False, italic=False, minimum=18):
    clean = re.sub(r"\s+", " ", str(text or "")).strip()
    for size in range(int(start_size), int(minimum) - 1, -2):
        font = _graphic_v67500_safe_font(size, bold=bold, italic=italic)
        if font is None:
            continue
        try:
            box = draw.textbbox((0, 0), clean, font=font)
            if (box[2] - box[0]) <= max_width:
                return font
        except Exception:
            return font
    return _graphic_v67500_safe_font(minimum, bold=bold, italic=italic)


def _graphic_v67500_safe_campaign_copy(prompt_text):
    """Build deterministic copy without vehicle research or provider metadata."""
    prompt = _graphic_resolve_effective_prompt_v47000(prompt_text)
    compatibility = str(_graphic_explicit_fitment_v41100(prompt) or "").strip()
    if not compatibility:
        compatibility = str(
            _graphic_extract_full_compatibility_v36000(prompt, "") or ""
        ).strip()
    if not compatibility:
        compatibility = "Vehicle Compatibility as Specified"

    size_match = re.search(
        r"\b(\d{1,2}(?:\.\d)?)\s*(?:inch|inches|[\"”])\s*"
        r"((?:2k\s*)?(?:qhd|hd|uhd|4k)?)\b",
        prompt,
        re.I,
    )
    screen_size = ""
    display_grade = ""
    if size_match:
        screen_size = size_match.group(1).rstrip("0").rstrip(".") + '"'
        display_grade = re.sub(r"\s+", " ", size_match.group(2).upper()).strip()

    product_type = "MULTIMEDIA SCREEN"
    if re.search(r"\b(?:gauge cluster|digital cluster|instrument cluster)\b", prompt, re.I):
        product_type = "DIGITAL GAUGE CLUSTER"
    elif re.search(r"\b(?:digital display|display screen)\b", prompt, re.I):
        product_type = "DIGITAL DISPLAY"

    headline_parts = [part for part in (screen_size, display_grade, product_type) if part]
    headline = " ".join(headline_parts) or "AUTOTECPRO OEM-FIT DISPLAY"

    tagline = "Smarter Drive. Bigger Screen. OEM Fit."
    if product_type == "DIGITAL GAUGE CLUSTER":
        tagline = "Smarter Drive. More Control. All in Sight."

    return {
        "headline": headline,
        "compatibility": compatibility,
        "tagline": tagline,
        "screen_size": screen_size,
        "product_designation": product_type,
        "compatibility_required_tokens": _graphic_copy_required_tokens_v36000(
            compatibility
        ),
        "compatibility_locked": True,
        "compatibility_source": "v66200-full-fitment-authority",
    }


def _graphic_v67500_isolated_local_commercial(
    prompt_text,
    uploaded_files,
    *,
    forced_upload_role="Auto-detect",
    failure_reason="",
):
    """Feature-preserving isolated fallback.

    The exact product and local commercial rendering remain dependency-free.
    Already-available reference/vehicle/campaign facts may enrich the result,
    but every enrichment is optional and nonblocking.
    """
    if Image is None:
        raise RuntimeError("Pillow is unavailable for isolated local recovery.")

    from PIL import ImageDraw, ImageFilter

    effective = _graphic_resolve_effective_prompt_v47000(prompt_text)
    role_items = _graphic_recover_role_items(
        uploaded_files,
        effective,
        forced_role=forced_upload_role,
    )
    product_item = next(
        (
            item for item in role_items
            if item.get("role") == "product_photo" and item.get("file") is not None
        ),
        None,
    )
    if product_item is None:
        project_items = _graphic_project_role_items(
            [],
            effective,
            forced_upload_role,
        )
        product_item = next(
            (
                item for item in project_items
                if item.get("role") == "product_photo" and item.get("file") is not None
            ),
            None,
        )
    if product_item is None:
        raise RuntimeError("No authoritative product photo is available.")

    product_layer, transparent = _graphic_open_product_layer_v3300(
        product_item.get("file")
    )
    if product_layer is None:
        raise RuntimeError("The authoritative product layer could not be opened.")
    if not transparent:
        raise RuntimeError(
            "Exact product transparency could not be proven; isolated recovery failed closed."
        )

    # Optional enrichment is collected only after exact-product authority is proven.
    # Any failure produces defaults instead of terminating the fallback.
    try:
        enrichment = _graphic_v67510_optional_enrichment(effective, role_items)
    except Exception:
        enrichment = {
            "reference_blueprint": {},
            "vehicle_profile": {},
            "reference_style_available": False,
            "vehicle_profile_available": False,
            "feature_copy": [],
            "warnings": ["optional-enrichment-unavailable"],
        }

    blueprint = dict(enrichment.get("reference_blueprint") or {})
    width, height = 1536, 1024
    canvas = Image.new("RGB", (width, height), (229, 239, 248))
    pixels = canvas.load()

    # Deterministic outdoor plate. Reference lighting hints can alter only the
    # background palette; they never touch product RGB or alpha.
    lighting_text = " ".join(
        str(blueprint.get(key) or "")
        for key in ("lighting", "mood", "color_palette", "scene_description")
    ).casefold()
    warm_scene = any(token in lighting_text for token in ("warm", "sunset", "golden", "orange"))
    cool_scene = any(token in lighting_text for token in ("cool", "blue", "night", "overcast"))

    for y in range(height):
        vertical = y / max(1, height - 1)
        for x in range(width):
            horizontal = x / max(1, width - 1)
            warm = max(0.0, horizontal - 0.60) * (1.0 - vertical * 0.55)
            if warm_scene:
                r = int(230 + 28 * warm - 20 * vertical)
                g = int(235 + 13 * warm - 30 * vertical)
                b = int(243 - 35 * warm - 32 * vertical)
            elif cool_scene:
                r = int(214 + 12 * warm - 20 * vertical)
                g = int(230 + 10 * warm - 25 * vertical)
                b = int(250 - 10 * warm - 28 * vertical)
            else:
                r = int(225 + 22 * warm - 22 * vertical)
                g = int(237 + 11 * warm - 29 * vertical)
                b = int(248 - 24 * warm - 34 * vertical)
            pixels[x, y] = (
                max(0, min(255, r)),
                max(0, min(255, g)),
                max(0, min(255, b)),
            )

    draw = ImageDraw.Draw(canvas, "RGBA")
    draw.polygon(
        [(0, 610), (170, 470), (330, 590), (520, 430), (720, 610), (900, 490),
         (1080, 600), (1280, 450), (1536, 600), (1536, 1024), (0, 1024)],
        fill=(74, 91, 105, 150),
    )
    draw.polygon(
        [(0, 720), (230, 605), (420, 710), (610, 575), (820, 705), (1030, 590),
         (1250, 700), (1450, 610), (1536, 670), (1536, 1024), (0, 1024)],
        fill=(54, 62, 67, 205),
    )

    glow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
    gd = ImageDraw.Draw(glow, "RGBA")
    for radius in range(210, 10, -12):
        alpha = max(2, int(34 * (1 - radius / 220)))
        gd.ellipse(
            (1335 - radius, 365 - radius, 1335 + radius, 365 + radius),
            fill=(255, 204, 112, alpha),
        )
    canvas = Image.alpha_composite(
        canvas.convert("RGBA"),
        glow.filter(ImageFilter.GaussianBlur(18)),
    )

    copy = _graphic_v67500_safe_campaign_copy(effective)
    draw = ImageDraw.Draw(canvas, "RGBA")

    # Use matched reference geometry when available; otherwise deterministic defaults.
    logo_box = _graphic_v67510_blueprint_box(
        blueprint, "logo_box", (0.022, 0.025, 0.22, 0.10)
    )
    headline_box = _graphic_v67510_blueprint_box(
        blueprint, "headline_box", (0.022, 0.13, 0.52, 0.10)
    )
    compatibility_box = _graphic_v67510_blueprint_box(
        blueprint, "compatibility_box", (0.022, 0.23, 0.46, 0.065)
    )
    tagline_box = _graphic_v67510_blueprint_box(
        blueprint, "tagline_box", (0.022, 0.30, 0.50, 0.05)
    )
    hero_box = _graphic_v67510_blueprint_box(
        blueprint, "hero_product_box", (0.045, 0.35, 0.50, 0.53)
    )
    feature_box = _graphic_v67510_blueprint_box(
        blueprint, "feature_matrix_box", (0.58, 0.08, 0.39, 0.27)
    )
    bottom_box = _graphic_v67510_blueprint_box(
        blueprint, "bottom_bar_box", (0.022, 0.89, 0.956, 0.09)
    )

    def px(box):
        return (
            int(box[0] * width),
            int(box[1] * height),
            int(box[2] * width),
            int(box[3] * height),
        )

    logo_x, logo_y, logo_w, logo_h = px(logo_box)
    logo_applied = False
    try:
        if AUTOTECPRO_BRAND_LOGO_FILE.exists():
            with Image.open(AUTOTECPRO_BRAND_LOGO_FILE) as logo_img:
                logo = ImageOps.exif_transpose(logo_img).convert("RGBA")
            logo.thumbnail((max(120, logo_w), max(50, logo_h)), Image.Resampling.LANCZOS)
            canvas.alpha_composite(logo, (logo_x, logo_y))
            logo_applied = True
    except Exception:
        logo_applied = False
    if not logo_applied:
        font_logo = _graphic_v67500_safe_font(max(30, min(58, logo_h)), bold=True)
        draw.text((logo_x, logo_y), "AutoTecPro", font=font_logo, fill=(10, 30, 58, 255))

    hx, hy, hw, hh = px(headline_box)
    headline_font = _graphic_v67500_fit_text(
        draw, copy["headline"], max(360, hw), max(42, min(74, hh)), bold=True, minimum=34
    )
    draw.text((hx, hy), copy["headline"], font=headline_font, fill=(8, 34, 70, 255))

    cx, cy, cw, ch = px(compatibility_box)
    compatibility_font = _graphic_v67500_fit_text(
        draw, copy["compatibility"], max(360, cw - 40), max(25, min(38, ch - 8)),
        bold=True, minimum=21
    )
    draw.polygon(
        [(cx, cy), (cx + cw, cy), (cx + cw - 24, cy + ch), (cx - 10, cy + ch)],
        fill=(190, 18, 20, 250),
    )
    draw.text(
        (cx + 22, cy + max(6, int(ch * 0.18))),
        copy["compatibility"],
        font=compatibility_font,
        fill=(255, 255, 255, 255),
    )

    tx, ty, tw, th = px(tagline_box)
    tagline_font = _graphic_v67500_fit_text(
        draw, copy["tagline"], max(360, tw), max(22, min(31, th)), italic=True, minimum=20
    )
    draw.text((tx, ty), copy["tagline"], font=tagline_font, fill=(12, 37, 69, 255))

    alpha = product_layer.getchannel("A")
    bbox = alpha.getbbox()
    if not bbox:
        raise RuntimeError("The authoritative product layer has no visible alpha envelope.")
    product_crop = product_layer.crop(bbox)

    px0, py0, pw, ph = px(hero_box)
    factor = min(
        max(120, pw) / product_crop.width,
        max(120, ph) / product_crop.height,
    )
    scale_request = _graphic_v67400_requested_uniform_scale(effective)
    if scale_request.get("requested") and scale_request.get("factor"):
        factor *= max(0.65, min(1.45, float(scale_request["factor"])))
    new_size = (
        max(1, int(product_crop.width * factor)),
        max(1, int(product_crop.height * factor)),
    )
    product_crop = product_crop.resize(new_size, Image.Resampling.LANCZOS)

    angle = _graphic_v67400_requested_angle(effective)
    if angle.get("kind") == "rotate_2d":
        degrees = min(
            GRAPHIC_V67400_MAX_SAFE_2D_ROTATION_DEGREES,
            abs(float(angle.get("degrees") or 0.0)),
        )
        signed = -degrees if angle.get("direction") == "clockwise" else degrees
        product_crop = product_crop.rotate(
            signed,
            resample=Image.Resampling.BICUBIC,
            expand=True,
        )

    product_x = px0 + max(0, int((pw - product_crop.width) * 0.10))
    product_y = py0 + max(0, ph - product_crop.height)

    shadow = Image.new("RGBA", canvas.size, (0, 0, 0, 0))
    sd = ImageDraw.Draw(shadow, "RGBA")
    sd.ellipse(
        (
            product_x + 25,
            product_y + product_crop.height - 30,
            product_x + product_crop.width - 15,
            product_y + product_crop.height + 38,
        ),
        fill=(0, 0, 0, 105),
    )
    canvas = Image.alpha_composite(
        canvas,
        shadow.filter(ImageFilter.GaussianBlur(22)),
    )
    canvas.alpha_composite(product_crop, (product_x, product_y))

    draw = ImageDraw.Draw(canvas, "RGBA")
    default_features = [
        ("Large Screen", copy.get("screen_size") or "HD Display"),
        ("Wireless CarPlay", "Smart Connectivity"),
        ("Navigation", "Ready"),
        ("Plug & Play", "OEM Integration"),
        ("OEM Fit", "& Finish"),
        ("High Brightness", "IPS Screen"),
    ]
    features = _graphic_v67510_optional_feature_pairs(
        enrichment,
        default_features,
    )

    fx, fy, fw, fh = px(feature_box)
    columns = 3
    rows = 2
    cell_w = max(120, fw // columns)
    cell_h = max(82, fh // rows)
    feature_title = _graphic_v67500_safe_font(max(18, min(25, cell_h // 4)), bold=True)
    feature_body = _graphic_v67500_safe_font(max(16, min(21, cell_h // 5)), bold=False)

    for index, (title, body) in enumerate(features[:6]):
        row, col = divmod(index, columns)
        x = fx + col * cell_w
        y = fy + row * cell_h
        draw.rounded_rectangle(
            (x, y, x + cell_w - 18, y + cell_h - 18),
            radius=15,
            fill=(255, 255, 255, 118),
            outline=(15, 43, 78, 90),
            width=2,
        )
        draw.text((x + 12, y + 14), title, font=feature_title, fill=(9, 35, 68, 255))
        if body:
            draw.text((x + 12, y + 48), body, font=feature_body, fill=(20, 53, 83, 255))

    bx, by, bw, bh = px(bottom_box)
    draw.rounded_rectangle(
        (bx, by, bx + bw, min(height - 8, by + bh)),
        radius=18,
        fill=(10, 16, 23, 238),
        outline=(255, 255, 255, 95),
        width=2,
    )
    labels = [
        "Plug & Play",
        "GPS Navigation",
        "Wireless CarPlay",
        "OEM Fit & Finish",
        "High Brightness IPS",
    ]
    segment = bw / len(labels)
    for i, label in enumerate(labels):
        x = bx + int(i * segment)
        if i:
            draw.line(
                (x, by + 12, x, min(height - 15, by + bh - 12)),
                fill=(255, 255, 255, 130),
                width=2,
            )
        font = _graphic_v67500_fit_text(
            draw, label, int(segment - 26), max(18, min(25, bh // 3)), minimum=16
        )
        box = draw.textbbox((0, 0), label, font=font)
        text_x = x + int((segment - (box[2] - box[0])) / 2)
        text_y = by + max(12, int((bh - (box[3] - box[1])) / 2))
        draw.text((text_x, text_y), label, font=font, fill=(255, 255, 255, 255))

    output = io.BytesIO()
    canvas.convert("RGB").save(output, format="PNG", optimize=True)
    png_bytes = output.getvalue()
    data_url = "data:image/png;base64," + base64.b64encode(png_bytes).decode("ascii")
    created = datetime.now(timezone.utc)
    filename = graphic_image_filename(effective, created)

    result = {
        "name": filename,
        "filename": filename,
        "data_url": data_url,
        "generated": True,
        "mime_type": "image/png",
        "size": f"{width}x{height}",
        "resolution": f"{width}x{height}",
        "created_at": created.isoformat(),
        "model": "local-v67510-feature-preserving-commercial",
        "provider_route": "v67510-feature-preserving-isolated-fallback",
        "recovery_route": "v67510-feature-preserving-isolated-fallback",
        "provider_fallback_used": True,
        "product_layer_immutable": True,
        "product_geometry_provider_generated": False,
        "ai_product_recreated": False,
        "strict_product_identity_lock": True,
        "product_transform_mode": "Exact Original Product",
        "product_identity_method": "v66000-authoritative-mask-feature-preserving-local-commercial",
        "output_status": "completed_exact_local_commercial_v67510",
        "verification_status": "verified_local_exact",
        "campaign_spec": copy,
        "compatibility": copy["compatibility"],
        "deterministic_fitment_copy": copy["compatibility"],
        "official_brand_logo_applied": logo_applied,
        "reference_enrichment_used": bool(enrichment.get("reference_style_available")),
        "vehicle_enrichment_available": bool(enrichment.get("vehicle_profile_available")),
        "optional_enrichment_warnings": list(enrichment.get("warnings") or []),
        "failure_context": str(failure_reason or "")[-1200:],
        "layered_metadata": {
            "engine": "v67510-feature-preserving-isolated-fallback",
            "exact_product_asset_mode": True,
            "product_pixels_provider_generated": False,
            "ai_product_recreated": False,
            "product_master_rgb_preserved": True,
            "compatibility": copy["compatibility"],
            "compatibility_required_tokens": copy["compatibility_required_tokens"],
            "optional_metadata_missing_is_not_failure": True,
            "remote_dependencies_required": False,
            "optional_reference_enrichment": bool(enrichment.get("reference_style_available")),
            "optional_vehicle_enrichment": bool(enrichment.get("vehicle_profile_available")),
        },
    }
    _graphic_save_latest_project_result(result)
    return [result]




GRAPHIC_V67310_POLICY_VERSION = "v67310-non-terminating-exact-recovery-with-v67200-cache"

def _graphic_v67300_has_rendered_image(images):
    return bool(
        isinstance(images, (list, tuple))
        and any(isinstance(item, dict) and item.get("data_url") for item in images)
    )

def _graphic_v67300_route_failure(failures, route, error):
    message = (
        f"{route}:{type(error).__name__}:"
        f"{_graphic_compact_error_v4000(error)}"
    )
    failures.append(message)
    diagnostic_log(
        "graphic_v67300_route_failed",
        route=route,
        error_type=type(error).__name__,
        error=_graphic_compact_error_v4000(error),
    )
    return message

def _graphic_v67300_repair_local_authority(
    images,
    prompt_text,
    role_items,
    *,
    route_name,
):
    """Repair legacy/local metadata without changing rendered pixels.

    This function does not make an unverified provider image acceptable. It is
    only used for deterministic/local product composites that already state that
    the uploaded product layer is immutable and provider-generated product
    geometry is false.
    """
    if not _graphic_v67300_has_rendered_image(images):
        return images

    expected = _graphic_extract_full_compatibility_v36000(prompt_text, "")
    required_tokens = _graphic_copy_required_tokens_v36000(expected)
    explicit = _graphic_explicit_fitment_v41100(prompt_text)

    repaired = []
    for original in images or []:
        if not isinstance(original, dict) or not original.get("data_url"):
            continue
        image = dict(original)
        metadata = dict(image.get("layered_metadata") or {})

        provider_generated = metadata.get("product_pixels_provider_generated")
        if provider_generated is None:
            provider_generated = image.get("product_geometry_provider_generated")
        ai_recreated = bool(
            image.get("ai_product_recreated")
            or metadata.get("ai_product_recreated")
        )
        immutable = image.get("product_layer_immutable")
        exact_asset = metadata.get("exact_product_asset_mode")

        local_route = any(
            marker in str(route_name or "").casefold()
            for marker in (
                "deterministic",
                "guaranteed-local",
                "local-commercial",
                "exact-reference",
                "hybrid-local",
            )
        )
        direct_local_evidence = (
            provider_generated is False
            and not ai_recreated
            and (
                immutable is True
                or exact_asset is True
                or str(image.get("product_identity_method") or "").casefold()
                in {
                    "exact_source_pixel_composite",
                    "v66000-authoritative-mask-local-commercial-composite",
                }
            )
        )
        if not (local_route and direct_local_evidence):
            repaired.append(image)
            continue

        spec = dict(image.get("campaign_spec") or {})
        compatibility = str(
            spec.get("compatibility")
            or image.get("compatibility")
            or metadata.get("compatibility")
            or ""
        ).strip()

        if explicit:
            compatibility = explicit
        elif not compatibility and expected:
            compatibility = expected

        spec["compatibility"] = compatibility
        spec["compatibility_required_tokens"] = required_tokens
        spec["compatibility_locked"] = True
        spec["compatibility_source"] = "v66200-full-fitment-authority"
        image["campaign_spec"] = spec
        image["compatibility"] = compatibility
        image["deterministic_fitment_copy"] = compatibility
        image["product_layer_immutable"] = True
        image["product_geometry_provider_generated"] = False
        image["ai_product_recreated"] = False
        image["strict_product_identity_lock"] = True

        metadata.update(
            {
                "exact_product_asset_mode": True,
                "product_pixels_provider_generated": False,
                "ai_product_recreated": False,
                "compatibility": compatibility,
                "compatibility_required_tokens": required_tokens,
                "authority_repaired_v67300": True,
                "authority_repair_route": route_name,
            }
        )
        image["layered_metadata"] = metadata
        image["authority_repaired_v67300"] = True
        repaired.append(image)

    return repaired

def _graphic_v67300_local_result_acceptable(
    images,
    prompt_text,
    contract,
    *,
    route_name,
):
    """Evidence-based acceptance for exact local composites.

    Direct geometry violations remain release blockers. Missing optional
    manifests or newer metadata names do not discard an otherwise proven local
    exact-product commercial.
    """
    if not _graphic_v67300_has_rendered_image(images):
        return {
            "accepted": False,
            "hard_block": False,
            "reason": "route returned no rendered image",
        }

    violation = _graphic_v66860_direct_product_violation(images)
    if violation:
        return {
            "accepted": False,
            "hard_block": True,
            "reason": violation,
        }

    proof = _graphic_v67100_exact_proof(images)
    if not proof.get("passed"):
        return {
            "accepted": False,
            "hard_block": proof.get("tier") == "direct-violation",
            "reason": "; ".join(
                proof.get("issues") or ["positive local-product proof unavailable"]
            ),
            "exact_proof": proof,
        }

    fitment = _graphic_v67100_fitment_gate(
        images,
        prompt_text,
        required=True,
        route_name=route_name,
    )
    if not fitment.get("passed"):
        return {
            "accepted": False,
            "hard_block": False,
            "reason": "; ".join(
                fitment.get("issues") or ["fitment verification failed"]
            ),
            "fitment": fitment,
        }

    for image in images or []:
        if not isinstance(image, dict):
            continue
        image["exact_product_proof_v67300"] = proof
        image["fitment_gate_v67300"] = fitment
        image["accepted_route_v67300"] = route_name
        image["graphic_policy_version"] = GRAPHIC_V67310_POLICY_VERSION
        image["graphic_mode_contract_v67300"] = {
            key: value for key, value in contract.items() if key != "role_items"
        }

    return {
        "accepted": True,
        "hard_block": False,
        "reason": "",
        "exact_proof": proof,
        "fitment": fitment,
    }

def _graphic_v67300_direct_local_commercial(
    prompt_text,
    uploaded_files,
    *,
    style_strength,
    forced_upload_role,
    failure_reason,
):
    """Build a complete local advertisement with the v66000 exact product layer."""
    effective = _graphic_resolve_effective_prompt_v47000(prompt_text)
    role_state = _graphic_exact_reference_request_v66820(
        effective,
        uploaded_files,
        forced_upload_role,
    )
    role_items = list(role_state.get("role_items") or [])
    if not role_items:
        role_items = _graphic_recover_role_items(
            uploaded_files,
            effective,
            forced_role=forced_upload_role,
        )
    if not any(item.get("role") == "product_photo" for item in role_items):
        raise RuntimeError("No authoritative product photo is available.")

    output_size = _graphic_normalize_output_size_v4000(
        choose_graphic_image_size(effective)
    )

    # Use v67200 prepared facts when available. Every helper fails open to the
    # existing cache/session behavior.
    prepared = _graphic_v67200_prepare_locked_facts(
        role_items,
        effective,
        style_strength,
        has_style=any(item.get("role") == "style_reference" for item in role_items),
        has_product=True,
    )
    blueprint = _graphic_safe_reference_blueprint_v16000(
        prepared.get("reference_blueprint") or {}
    )
    vehicle = _graphic_resolve_vehicle_lock(
        effective,
        prepared.get("vehicle_profile") or {},
    )

    result = _graphic_v66830_source_canvas_result(
        effective,
        role_items,
        output_size,
        blueprint,
        vehicle,
        failure_reason,
    )
    return result

def _graphic_v67300_exact_recovery_ladder(
    prompt_text,
    uploaded_files,
    contract,
    *,
    style_strength,
    forced_upload_role,
    failures,
):
    """v67500 non-terminating exact-product recovery ladder."""
    effective = _graphic_resolve_effective_prompt_v47000(prompt_text)
    role_items = list(contract.get("role_items") or [])
    attempts = []

    routes = [
        (
            "v67500-deterministic-exact-reference",
            lambda: _graphic_exact_reference_deterministic_recovery_v66820(
                effective,
                uploaded_files,
                style_strength=style_strength,
                forced_upload_role=forced_upload_role,
            ),
        ),
        (
            "v67500-guaranteed-local-commercial",
            lambda: _graphic_v66830_guaranteed_exact_result(
                effective,
                uploaded_files,
                style_strength=style_strength,
                forced_upload_role=forced_upload_role,
                failure_reason=" | ".join(failures[-6:]),
            ),
        ),
        (
            "v67500-direct-local-commercial",
            lambda: _graphic_v67300_direct_local_commercial(
                effective,
                uploaded_files,
                style_strength=style_strength,
                forced_upload_role=forced_upload_role,
                failure_reason=" | ".join(failures[-8:]),
            ),
        ),
        (
            "v67500-isolated-final-local-commercial",
            lambda: _graphic_v67500_isolated_local_commercial(
                effective,
                uploaded_files,
                forced_upload_role=forced_upload_role,
                failure_reason=" | ".join(failures[-10:]),
            ),
        ),
    ]

    last_usable = None
    last_usable_route = ""

    for route_name, runner in routes:
        started = time.perf_counter()
        try:
            raw_result = runner()
            result = _graphic_v67500_normalize_results(raw_result)
            if _graphic_v67300_has_rendered_image(result):
                result = _graphic_v67300_repair_local_authority(
                    result,
                    effective,
                    role_items,
                    route_name=route_name,
                )
                last_usable = result
                last_usable_route = route_name

            decision = _graphic_v67300_local_result_acceptable(
                result,
                effective,
                contract,
                route_name=route_name,
            )
            attempt = {
                "route": route_name,
                "duration_seconds": round(time.perf_counter() - started, 3),
                "rendered_image": _graphic_v67300_has_rendered_image(result),
                "accepted": bool(decision.get("accepted")),
                "hard_block": bool(decision.get("hard_block")),
                "reason": str(decision.get("reason") or ""),
            }
            attempts.append(attempt)
            diagnostic_log("graphic_v67500_exact_recovery_attempt", **attempt)

            if decision.get("accepted"):
                for image in result:
                    image["exact_recovery_attempts_v67500"] = attempts
                    image["recovery_failures"] = failures[-10:]
                    image["recovered_from_v67500"] = True
                    image["graphic_policy_version"] = GRAPHIC_V67500_POLICY_VERSION
                return result, route_name, attempts

            failures.append(
                f"{route_name}-policy:"
                + str(decision.get("reason") or "not accepted")
            )
        except Exception as error:
            _graphic_v67300_route_failure(failures, route_name, error)
            attempts.append({
                "route": route_name,
                "duration_seconds": round(time.perf_counter() - started, 3),
                "rendered_image": False,
                "accepted": False,
                "hard_block": False,
                "reason": f"{type(error).__name__}:"
                f"{_graphic_compact_error_v4000(error)}",
            })

    # Never discard a directly proven local image because of an optional post-audit.
    if last_usable:
        repaired = _graphic_v67300_repair_local_authority(
            last_usable,
            effective,
            role_items,
            route_name=last_usable_route,
        )
        proof = _graphic_v67100_exact_proof(repaired)
        violation = _graphic_v66860_direct_product_violation(repaired)
        fitment = _graphic_v67100_fitment_gate(
            repaired,
            effective,
            required=True,
            route_name=last_usable_route,
        )
        if proof.get("passed") and not violation and fitment.get("passed"):
            for image in repaired:
                image["exact_recovery_attempts_v67500"] = attempts
                image["recovery_failures"] = failures[-10:]
                image["accepted_by_local_authority_v67500"] = True
                image["accepted_route_v67500"] = last_usable_route
                image["graphic_policy_version"] = GRAPHIC_V67500_POLICY_VERSION
            return repaired, last_usable_route, attempts

    raise RuntimeError(
        "All exact-product recovery routes failed, including the isolated local route. "
        + " | ".join(failures[-10:])
    )




GRAPHIC_V68200_POLICY_VERSION = "v68200-dual-exact-local-routes"


def _graphic_v68200_font(size, bold=False, italic=False):
    from PIL import ImageFont
    candidates=[]
    if bold and italic:
        candidates += ["/usr/share/fonts/truetype/dejavu/DejaVuSans-BoldOblique.ttf"]
    elif bold:
        candidates += ["/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"]
    elif italic:
        candidates += ["/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf"]
    else:
        candidates += ["/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"]
    for path in candidates:
        try:
            return ImageFont.truetype(path, max(10,int(size)))
        except Exception:
            pass
    return ImageFont.load_default()


def _graphic_v68200_fit_font(draw, text, width, start, minimum=16, bold=False, italic=False):
    size=int(start)
    while size>minimum:
        font=_graphic_v68200_font(size,bold=bold,italic=italic)
        try:
            box=draw.textbbox((0,0),str(text),font=font)
            if box[2]-box[0] <= width:
                return font
        except Exception:
            return font
        size-=2
    return _graphic_v68200_font(minimum,bold=bold,italic=italic)


def _graphic_v68200_guaranteed_exact_local_commercial(prompt_text, uploaded_files, *, forced_upload_role="Auto-detect"):
    """Pillow-only final exact-product route.

    It never asks a provider to draw the product and has no OpenCV, web, cache,
    Product-DNA or reference-analysis dependency. Source RGB is preserved; only
    alpha, uniform scale and placement are used.
    """
    if Image is None:
        raise RuntimeError("Pillow is unavailable.")
    from PIL import ImageDraw, ImageFilter
    effective=_graphic_resolve_effective_prompt_v47000(prompt_text)
    role_items=_graphic_project_role_items(uploaded_files,effective,forced_upload_role)
    product_item=next((x for x in role_items or [] if x.get('role')=='product_photo' and x.get('file') is not None),None)
    if product_item is None:
        raise RuntimeError("No uploaded product photo is available.")
    product,transparent=_graphic_open_product_layer_v3300(product_item.get('file'))
    if product is None:
        raise RuntimeError("The uploaded product photo could not be opened.")

    # Crop only transparent/outer white margin. Never warp or repaint source RGB.
    if transparent:
        bbox=product.getchannel('A').getbbox()
    else:
        bbox=None
        try:
            rgb=product.convert('RGB')
            import numpy as np
            a=np.asarray(rgb)
            nonwhite=(a.min(axis=2)<242)
            ys,xs=np.where(nonwhite)
            if len(xs):
                pad=8
                bbox=(max(0,int(xs.min())-pad),max(0,int(ys.min())-pad),min(product.width,int(xs.max())+pad+1),min(product.height,int(ys.max())+pad+1))
        except Exception:
            bbox=None
    if bbox:
        product=product.crop(bbox)

    W,H=1536,1024
    canvas=Image.new('RGBA',(W,H),(232,242,250,255))
    px=canvas.load()
    for y in range(H):
        t=y/(H-1)
        for x in range(W):
            warm=max(0,(x/W)-0.62)*(1-t*0.5)
            px[x,y]=(int(226+25*warm-22*t),int(238+12*warm-30*t),int(249-30*warm-38*t),255)
    draw=ImageDraw.Draw(canvas,'RGBA')
    # deterministic mountain scene
    draw.polygon([(0,620),(170,490),(320,585),(520,430),(730,610),(910,485),(1110,600),(1300,455),(1536,590),(1536,1024),(0,1024)],fill=(76,91,103,160))
    draw.polygon([(0,730),(220,610),(420,720),(620,580),(820,710),(1040,600),(1260,700),(1440,620),(1536,665),(1536,1024),(0,1024)],fill=(48,57,62,220))
    # sun glow
    glow=Image.new('RGBA',(W,H),(0,0,0,0)); gd=ImageDraw.Draw(glow,'RGBA')
    gd.ellipse((1260,250,1580,570),fill=(255,201,105,90)); canvas=Image.alpha_composite(canvas,glow.filter(ImageFilter.GaussianBlur(55)))

    spec=_graphic_extract_campaign_spec(effective,{})
    headline=str(spec.get('headline') or _graphic_v68100_headline(spec,effective)).upper()
    compatibility=_graphic_v68100_normalize_fitment(str(spec.get('compatibility') or ''))
    if compatibility and not compatibility.casefold().startswith('for '): compatibility='For '+compatibility
    tagline=str(spec.get('tagline') or 'Smarter Drive. Bigger Screen. OEM Fit.')

    draw=ImageDraw.Draw(canvas,'RGBA')
    # official logo only
    logo=get_official_brand_logo_image()
    if logo is not None:
        try:
            box=logo.getchannel('A').getbbox(); logo=logo.crop(box) if box else logo
            ratio=min(320/logo.width,92/logo.height); logo=logo.resize((int(logo.width*ratio),int(logo.height*ratio)),Image.Resampling.LANCZOS)
            canvas.alpha_composite(logo,(34,25))
        except Exception:
            draw.text((34,30),'AutoTecPro',font=_graphic_v68200_font(48,bold=True),fill=(8,25,52,255))
    else:
        draw.text((34,30),'AutoTecPro',font=_graphic_v68200_font(48,bold=True),fill=(8,25,52,255))
    draw.text((69,100),'www.AutoTecPro.com',font=_graphic_v68200_font(24,bold=True),fill=(30,30,30,255))

    hf=_graphic_v68200_fit_font(draw,headline,820,72,38,bold=True)
    draw.text((32,137),headline,font=hf,fill=(5,34,72,255))
    if compatibility:
        cf=_graphic_v68200_fit_font(draw,compatibility,600,36,22,bold=True)
        box=draw.textbbox((0,0),compatibility,font=cf); rw=(box[2]-box[0])+50
        draw.polygon([(32,230),(32+rw,230),(32+rw-22,286),(22,286)],fill=(190,16,18,255))
        draw.text((57,242),compatibility,font=cf,fill=(255,255,255,255))
    draw.text((35,303),tagline,font=_graphic_v68200_font(29,italic=True),fill=(10,38,72,255))

    # upper feature grid, exact deterministic wording
    features=_graphic_v68100_multimedia_features(spec)
    fx0,fy0,fw,fh=900,42,595,292; cols=4; rows=2; cw=fw//cols; ch=fh//rows
    for i,label in enumerate(features[:8]):
        r,c=divmod(i,cols); x=fx0+c*cw; y=fy0+r*ch
        if c: draw.line((x,y+8,x,y+ch-10),fill=(16,45,78,110),width=1)
        if r: draw.line((fx0,y,fx0+fw,y),fill=(16,45,78,110),width=1)
        # simple deterministic icon circle
        draw.ellipse((x+48,y+14,x+94,y+60),outline=(7,35,70,255),width=4)
        parts=label.split(); mid=max(1,len(parts)//2); lines=[' '.join(parts[:mid]),' '.join(parts[mid:])]
        font=_graphic_v68200_font(18,bold=True)
        for j,line in enumerate([v for v in lines if v]):
            bb=draw.textbbox((0,0),line,font=font); draw.text((x+(cw-(bb[2]-bb[0]))//2,y+72+j*24),line,font=font,fill=(7,35,70,255))

    # exact product hero; uniform scaling only
    target_w,target_h=700,610
    scale=min(target_w/product.width,target_h/product.height)
    product=product.resize((max(1,int(product.width*scale)),max(1,int(product.height*scale))),Image.Resampling.LANCZOS)
    product_x=90+(target_w-product.width)//2; product_y=355+(target_h-product.height)
    shadow=Image.new('RGBA',(W,H),(0,0,0,0)); sd=ImageDraw.Draw(shadow,'RGBA')
    sd.ellipse((product_x+30,product_y+product.height-25,product_x+product.width-30,product_y+product.height+35),fill=(0,0,0,115))
    canvas=Image.alpha_composite(canvas,shadow.filter(ImageFilter.GaussianBlur(22)))
    canvas.alpha_composite(product,(product_x,product_y))

    # footer always last, above product
    draw=ImageDraw.Draw(canvas,'RGBA'); bx,by,bw,bh=35,928,1466,78
    draw.rounded_rectangle((bx,by,bx+bw,by+bh),radius=18,fill=(8,18,31,248),outline=(255,255,255,120),width=2)
    footer=_graphic_v68100_multimedia_footer(); cell=bw/5
    for i,label in enumerate(footer):
        x=bx+int(i*cell)
        if i: draw.line((x,by+12,x,by+bh-12),fill=(255,255,255,150),width=2)
        font=_graphic_v68200_fit_font(draw,label,int(cell-30),23,16)
        bb=draw.textbbox((0,0),label,font=font)
        draw.text((x+int((cell-(bb[2]-bb[0]))/2),by+int((bh-(bb[3]-bb[1]))/2)-2),label,font=font,fill=(255,255,255,255))

    buf=io.BytesIO(); canvas.convert('RGB').save(buf,format='PNG',optimize=True)
    data_url='data:image/png;base64,'+base64.b64encode(buf.getvalue()).decode('ascii')
    created=datetime.now(timezone.utc)
    name=graphic_image_filename(effective,created)
    return [{
        'name':name,'filename':name,'data_url':data_url,'generated':True,
        'mime_type':'image/png','size':'1536x1024','resolution':'1536x1024',
        'created_at':created.isoformat(),'model':'local-v68200-pillow-exact',
        'provider_route':'v68200-guaranteed-pillow-exact-local',
        'product_layer_immutable':True,'product_geometry_provider_generated':False,
        'ai_product_recreated':False,'source_rgb_untouched':True,
        'exact_reference_fail_closed':True,'reference_supplies_style_only':True,
        'campaign_spec':spec,'verification_status':'verified-local-exact',
        'output_status':'completed-v68200-guaranteed-exact-local',
        'layered_metadata':{
            'engine':'v68200-guaranteed-pillow-exact-local','opencv_required':False,
            'provider_product_generation':False,'source_rgb_untouched':True,
            'product_angle_policy':'preserve-uploaded-view','optional_metadata_missing_is_not_failure':True,
        }
    }]



def _graphic_v68680_normalize_usable_images(images, route_name, failures=None):
    """Return usable image dictionaries without running metadata proof wrappers."""
    normalized = []
    for image in images or []:
        if not isinstance(image, dict):
            continue
        if not str(image.get("data_url") or "").strip():
            continue
        item = dict(image)
        item["graphic_engine_version"] = "v68680-v67610-state-machine"
        item["generation_route_v68680"] = route_name
        item["recovery_failures"] = list(failures or [])[-4:]
        normalized.append(item)
    return normalized


GRAPHIC_V68833_REFERENCE_ASPECT_TOLERANCE = 0.005


def _graphic_v68833_reference_aspect_release_gate(images):
    """Validate Reference Mode product proportions without changing image pixels.

    This is a release-only gate. It does not resize, crop, regenerate, rewrite, or
    otherwise mutate the output. Existing compliant images pass through unchanged;
    only a result carrying direct metadata evidence of non-uniform product scaling
    is rejected so the established v68832 state machine can try its existing next
    route. Missing optional ratio metadata remains diagnostic rather than a blocker.
    """
    reports = []
    issues = []
    available = False

    for index, image in enumerate(images or []):
        if not isinstance(image, dict):
            continue
        metadata = dict(image.get("layered_metadata") or {})
        source_ratio = float(metadata.get("product_source_visible_aspect_ratio") or 0.0)
        rendered_ratio = float(metadata.get("product_rendered_aspect_ratio") or 0.0)

        if rendered_ratio <= 0.0:
            box = list(metadata.get("product_box") or [])
            if len(box) == 4:
                try:
                    width = float(box[2])
                    height = float(box[3])
                    if width > 0.0 and height > 0.0:
                        rendered_ratio = width / height
                except Exception:
                    rendered_ratio = 0.0

        relative_error = None
        passed = None
        if source_ratio > 0.0 and rendered_ratio > 0.0:
            available = True
            relative_error = abs(rendered_ratio - source_ratio) / max(source_ratio, 1e-9)
            passed = relative_error <= GRAPHIC_V68833_REFERENCE_ASPECT_TOLERANCE
            if not passed:
                issues.append(
                    "image " + str(index + 1)
                    + " product width-to-height ratio drifted by "
                    + f"{relative_error * 100:.3f}%"
                )
        elif metadata.get("product_ratio_preserved") is False:
            available = True
            passed = False
            issues.append(
                "image " + str(index + 1)
                + " reports non-uniform product scaling"
            )

        reports.append({
            "image_index": index,
            "available": bool(source_ratio > 0.0 and rendered_ratio > 0.0),
            "source_visible_aspect_ratio": round(source_ratio, 10) if source_ratio > 0.0 else None,
            "rendered_aspect_ratio": round(rendered_ratio, 10) if rendered_ratio > 0.0 else None,
            "relative_error": round(relative_error, 10) if relative_error is not None else None,
            "tolerance": GRAPHIC_V68833_REFERENCE_ASPECT_TOLERANCE,
            "passed": passed,
        })

    return {
        "engine": "v68833-reference-aspect-release-gate",
        "available": available,
        "passed": not issues,
        "issues": issues,
        "reports": reports,
        "validation_only": True,
        "pixels_mutated": False,
        "pipeline_mutated": False,
    }


def _graphic_v68680_direct_release_blockers(
    images, prompt_text, uploaded_files, *, forced_upload_role="Auto-detect",
    preserve_product=True, route_name="",
):
    """Block only direct geometry corruption or direct fitment narrowing.

    Missing optional metadata, proof-schema fields, campaign-zone manifests, and
    provider diagnostics are never treated as affirmative evidence that the image
    is wrong.
    """
    images = list(images or [])
    role_items = _graphic_project_role_items(
        uploaded_files, prompt_text, forced_upload_role
    )
    has_product = any(
        item.get("role") == "product_photo" for item in role_items or []
    )
    has_style = any(
        item.get("role") == "style_reference" for item in role_items or []
    )
    reference_mode = bool(preserve_product and has_product and has_style)

    issues = []
    diagnostics = []

    if reference_mode:
        violation = _graphic_v66860_direct_product_violation(images)
        if violation and violation != "missing generated image":
            issues.append("geometry: " + violation)

        aspect_gate = _graphic_v68833_reference_aspect_release_gate(images)
        if aspect_gate.get("available") and not aspect_gate.get("passed"):
            issues.extend(
                "geometry: " + str(item)
                for item in (aspect_gate.get("issues") or [])
            )
        elif not aspect_gate.get("available"):
            diagnostics.append(
                "reference aspect-ratio metadata unavailable; existing exact-proof gates remain authoritative"
            )
        else:
            diagnostics.append(
                "reference product aspect ratio independently verified at release"
            )

        proof = _graphic_v67100_exact_proof(images)
        if not proof.get("passed"):
            diagnostics.extend(proof.get("issues") or [])
        else:
            diagnostics.append(
                "geometry proof tier: " + str(proof.get("tier") or "unknown")
            )

    fitment = _graphic_v67100_fitment_gate(
        images,
        prompt_text,
        required=bool(reference_mode),
        route_name=route_name,
    )
    # A fitment gate blocks only when it has actual observed copy and proves
    # narrowing. Unavailable optional metadata remains diagnostic.
    if fitment.get("available") and not fitment.get("passed"):
        issues.extend(
            "fitment: " + str(item)
            for item in (fitment.get("issues") or [])
        )
    elif not fitment.get("available"):
        diagnostics.append("fitment metadata unavailable; not treated as narrowing")

    primitive = any(
        "v68200-guaranteed-pillow" in str(image.get("provider_route") or "").casefold()
        or "local-v68200-pillow" in str(image.get("model") or "").casefold()
        for image in images if isinstance(image, dict)
    )
    if primitive:
        issues.append(
            "quality: primitive Pillow draft fallback is not a production result"
        )

    return {
        "passed": not issues,
        "issues": issues,
        "diagnostics": diagnostics,
        "reference_mode": reference_mode,
        "fitment": fitment,
        "reference_aspect_release_gate_v68833": (
            aspect_gate if reference_mode else {
                "engine": "v68833-reference-aspect-release-gate",
                "available": False,
                "passed": True,
                "not_required": True,
                "validation_only": True,
                "pixels_mutated": False,
                "pipeline_mutated": False,
            }
        ),
        "route": route_name,
        "policy": "v68680-direct-evidence-only-release-blockers+v68833-reference-aspect-validation",
    }


def _graphic_v68680_stage_result(
    route_name, runner, *, prompt_text, uploaded_files,
    forced_upload_role="Auto-detect", preserve_product=True, failures=None,
):
    """Execute one route in isolation and return a structured stage result."""
    try:
        raw_images = runner()
    except Exception as error:
        reason = (
            f"{type(error).__name__}:"
            f"{_graphic_compact_error_v4000(error)}"
        )
        diagnostic_log(
            "graphic_v68680_stage_exception",
            route=route_name,
            reason=reason,
        )
        return {
            "success": False,
            "images": [],
            "reason": reason,
            "route": route_name,
            "blocked": False,
            "blockers": {},
        }

    images = _graphic_v68680_normalize_usable_images(
        raw_images, route_name, failures
    )
    if not images:
        return {
            "success": False,
            "images": [],
            "reason": "route returned no usable image",
            "route": route_name,
            "blocked": False,
            "blockers": {},
        }

    blockers = _graphic_v68680_direct_release_blockers(
        images,
        prompt_text,
        uploaded_files,
        forced_upload_role=forced_upload_role,
        preserve_product=preserve_product,
        route_name=route_name,
    )
    for image in images:
        image["direct_release_blockers_v68680"] = blockers

    if not blockers.get("passed"):
        reason = "; ".join(blockers.get("issues") or ["direct release blocker"])
        diagnostic_log(
            "graphic_v68680_stage_blocked",
            route=route_name,
            reason=reason,
        )
        return {
            "success": False,
            "images": [],
            "reason": reason,
            "route": route_name,
            "blocked": True,
            "blockers": blockers,
        }

    return {
        "success": True,
        "images": images,
        "reason": "",
        "route": route_name,
        "blocked": False,
        "blockers": blockers,
    }



def generate_graphic_marketing_images(
    prompt_text, uploaded_files=None, *, use_approved_style=True,
    preserve_product=True, style_strength="High",
    forced_upload_role="Auto-detect", quality_retry=True,
    product_transform_mode="Auto", professional_layered_studio=True,
):
    """v68790 public generation path.

    Restore the proven v66200/v67610 order:

        advanced professional generation
        -> usable image exists
        -> return immediately

    The v3200 deterministic compositor remains recovery only. It is not promoted
    ahead of the advanced path because doing so allows reference-template hardware
    to survive behind the uploaded product when the provider background contains a
    larger product-like structure.
    """
    arguments = dict(
        use_approved_style=use_approved_style,
        preserve_product=preserve_product,
        style_strength=style_strength,
        forced_upload_role=forced_upload_role,
        quality_retry=quality_retry,
        product_transform_mode=product_transform_mode,
        professional_layered_studio=professional_layered_studio,
    )
    effective_prompt = _graphic_resolve_effective_prompt_v47000(prompt_text)
    installed_request = _graphic_installed_intent_hint_v47000(effective_prompt)
    failures = []

    project = _graphic_repair_project_asset_roles_v15000(
        get_graphic_project_state()
    )
    project = _graphic_active_project_assets_v16000(project)
    project["stage"] = "generating"
    project["last_error"] = ""
    project["generation_started_at"] = datetime.now(timezone.utc).isoformat()
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = project

    # Stage 1: exact v66200/v68720 professional path, returned immediately when
    # usable. This generator already performs its own product-source, geometry,
    # fitment, composition, and QA checks.
    try:
        advanced_raw = _generate_graphic_marketing_images_advanced(
            effective_prompt,
            uploaded_files,
            **arguments,
        )
        advanced_images = _graphic_v68680_normalize_usable_images(
            advanced_raw,
            "advanced-direct-return",
            failures,
        )
        if advanced_images:
            for image in advanced_images:
                if isinstance(image, dict):
                    image["generation_state_machine_v68790"] = {
                        "success": True,
                        "accepted_route": "advanced-direct-return",
                        "advanced_first": True,
                        "blocking_wrapper_bypassed": True,
                        "v3200_used_as_recovery_only": True,
                    }
            diagnostic_log(
                "graphic_v68790_advanced_direct_return",
                image_count=len(advanced_images),
            )
            return advanced_images

        failures.append(
            "advanced-direct-return:route returned no usable image"
        )
    except Exception as error:
        reason = (
            f"{type(error).__name__}:"
            f"{_graphic_compact_error_v4000(error)}"
        )
        failures.append("advanced-direct-return:" + reason)
        diagnostic_log(
            "graphic_v68790_advanced_exception",
            reason=reason,
        )

    # Installed View must remain interior-only and fail closed.
    if installed_request:
        try:
            installed_raw = _graphic_installed_view_recovery_v47000(
                effective_prompt,
                uploaded_files,
                output_size="1536x1024",
                forced_upload_role=forced_upload_role,
            )
            installed_images = _graphic_v68680_normalize_usable_images(
                installed_raw,
                "installed-view-only-v47000",
                failures,
            )
            if installed_images:
                for image in installed_images:
                    if isinstance(image, dict):
                        image["generation_state_machine_v68790"] = {
                            "success": True,
                            "accepted_route": "installed-view-only-v47000",
                            "advanced_first": True,
                        }
                return installed_images
            failures.append(
                "installed-view-only-v47000:"
                "route returned no usable image"
            )
        except Exception as error:
            failures.append(
                "installed-view-only-v47000:"
                f"{type(error).__name__}:"
                f"{_graphic_compact_error_v4000(error)}"
            )

        state = get_graphic_project_state()
        state["stage"] = "ready_to_generate"
        state["last_error"] = " | ".join(failures[-4:])[:1800]
        st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state
        raise RuntimeError(
            "Installed View failed safely after its dedicated routes. "
            + " | ".join(failures[-3:])
        )

    # Stage 2: unchanged v3200 compatibility recovery. It is intentionally not the
    # primary Reference Mode route.
    recovery_stages = [
        (
            "v3200-compatibility",
            lambda: _generate_graphic_marketing_images_advanced_v3200(
                effective_prompt,
                uploaded_files,
                **arguments,
            ),
        ),
        (
            "emergency-provider",
            lambda: _graphic_emergency_provider_result_v15000(
                effective_prompt,
                uploaded_files,
                style_strength=style_strength,
                forced_upload_role=forced_upload_role,
            ),
        ),
    ]

    stage_results = []
    for route_name, runner in recovery_stages:
        result = _graphic_v68680_stage_result(
            route_name,
            runner,
            prompt_text=effective_prompt,
            uploaded_files=uploaded_files,
            forced_upload_role=forced_upload_role,
            preserve_product=preserve_product,
            failures=failures,
        )
        stage_results.append(result)

        if result.get("success") and result.get("images"):
            images = result["images"]
            for image in images:
                if isinstance(image, dict):
                    image["generation_state_machine_v68790"] = {
                        "success": True,
                        "accepted_route": route_name,
                        "advanced_first": True,
                        "advanced_failure": failures[0] if failures else "",
                        "attempts": [
                            {
                                "route": item.get("route"),
                                "success": bool(item.get("success")),
                                "blocked": bool(item.get("blocked")),
                                "reason": str(item.get("reason") or "")[:500],
                            }
                            for item in stage_results
                        ],
                    }
            diagnostic_log(
                "graphic_v68790_recovery_accepted",
                route=route_name,
                attempts=len(stage_results),
            )
            return images

        reason = str(result.get("reason") or "route failed")
        failures.append(f"{route_name}:{reason}")

    state = get_graphic_project_state()
    state["stage"] = "ready_to_generate"
    state["last_error"] = " | ".join(failures[-6:])[:1800]
    state["last_failed_stage"] = "all_generation_routes"
    state["generation_failed_at"] = datetime.now(timezone.utc).isoformat()
    state["updated_at"] = datetime.now(timezone.utc).isoformat()
    st.session_state[GRAPHIC_PROJECT_STATE_KEY] = state

    diagnostic_log(
        "graphic_v68790_all_routes_failed",
        failures=failures[-6:],
    )
    raise RuntimeError(
        "All established image-generation routes genuinely failed. "
        "Your project remains saved. "
        + " | ".join(failures[-4:])
    )







# ============================================================
# v68826 — production shared Graphic learning and approved-output consistency
# The established v68790/Reference Mode generator above is retained unchanged.
# This wrapper reuses exact pixels only after explicit staff approval.
# ============================================================
GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE = "v68826-approved-company-output"
GRAPHIC_V68826_SHARED_OUTPUT_BUCKET = (
    _read_app_secret("GRAPHIC_CACHE_BUCKET", "graphic-runtime-cache")
    or "graphic-runtime-cache"
)
_GRAPHIC_V68826_UNCACHED_GENERATOR = generate_graphic_marketing_images


def _graphic_v68826_uploaded_file_digest(uploaded_file):
    """Return stable upload metadata without consuming the Streamlit file."""
    if uploaded_file is None:
        return {"name": "", "type": "", "sha256": "", "size": 0}
    try:
        raw = bytes(uploaded_file.getvalue() or b"")
    except Exception:
        position = None
        try:
            position = uploaded_file.tell()
        except Exception:
            pass
        try:
            raw = bytes(uploaded_file.read() or b"")
        except Exception:
            raw = b""
        if position is not None:
            try:
                uploaded_file.seek(position)
            except Exception:
                pass
    return {
        "name": Path(str(getattr(uploaded_file, "name", "") or "")).name,
        "type": str(getattr(uploaded_file, "type", "") or "").lower(),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "size": len(raw),
    }


def _graphic_v68978_persistent_authority_payload():
    """Return non-secret persistent Graphic authority for cache identity."""
    try:
        project = _graphic_active_project_assets_v16000(
            _graphic_repair_project_asset_roles_v15000(get_graphic_project_state())
        )
    except Exception:
        project = get_graphic_project_state()
    assets = [item for item in (project.get("assets") or []) if isinstance(item, dict)]
    active_reference_id = str(project.get("active_reference_id") or "").strip()
    active_product_id = str(project.get("active_product_id") or "").strip()
    active_product_ids = sorted(
        str(value or "").strip() for value in (project.get("active_product_ids") or [])
        if str(value or "").strip()
    )
    def asset_row(asset_id):
        if not asset_id:
            return {}
        for item in assets:
            if str(item.get("id") or "").strip() == asset_id:
                raw = bytes(item.get("data") or b"")
                return {
                    "id": asset_id,
                    "role": str(item.get("role") or ""),
                    "sha256": hashlib.sha256(raw).hexdigest() if raw else asset_id,
                    "size": len(raw),
                }
        return {"id": asset_id, "sha256": asset_id}
    style_dna = project.get("project_style_dna") or {}
    try:
        style_dna_sha = hashlib.sha256(json.dumps(
            style_dna, ensure_ascii=False, sort_keys=True, default=str,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest() if style_dna else ""
    except Exception:
        style_dna_sha = ""
    return {
        "active_reference": asset_row(active_reference_id),
        "active_product": asset_row(active_product_id),
        "active_product_ids": active_product_ids,
        "style_dna_sha256": style_dna_sha,
    }


def _graphic_v68826_request_key(prompt_text, uploaded_files, arguments):
    """Build a company-wide key with persistent Graphic authority fingerprints."""
    payload = {
        "namespace": GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE,
        "engine": str(GRAPHIC_ENGINE_VERSION),
        "release": str(GRAPHIC_V68300_RELEASE),
        "prompt": str(prompt_text or "").strip(),
        "uploads": [
            _graphic_v68826_uploaded_file_digest(item)
            for item in (uploaded_files or [])
        ],
        "persistent_authority_v68978": _graphic_v68978_persistent_authority_payload(),
        "arguments": {key: arguments.get(key) for key in sorted(arguments)},
    }
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), default=str,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _graphic_v68826_cache_record_key(request_key):
    return (
        f"approved-output:{GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE}:"
        f"{request_key}"
    )


def _graphic_v68826_storage_bucket():
    clients = []
    try:
        admin_client = get_supabase_admin_client()
        if admin_client is not None:
            clients.append(admin_client)
    except Exception:
        pass
    clients.append(supabase)
    for client_obj in clients:
        try:
            storage = getattr(client_obj, "storage", None)
            if storage is not None:
                return storage.from_(GRAPHIC_V68826_SHARED_OUTPUT_BUCKET)
        except Exception:
            continue
    return None


def _graphic_v68826_restore_approved_output(request_key):
    payload = _graphic_v66100_cache_get(
        _graphic_v68826_cache_record_key(request_key)
    )
    if not isinstance(payload, dict) or not payload.get("approved"):
        return None
    row = payload.get("image")
    if not isinstance(row, dict):
        return None
    metadata = dict(row.get("metadata") or {})
    data_url = str(row.get("inline_data_url") or "")
    storage_path = str(row.get("storage_path") or "")
    if not data_url.startswith("data:image/") and storage_path:
        bucket = _graphic_v68826_storage_bucket()
        if bucket is not None:
            try:
                raw = bucket.download(storage_path)
                if isinstance(raw, (bytes, bytearray)) and raw:
                    data_url = (
                        "data:image/png;base64," +
                        base64.b64encode(bytes(raw)).decode("ascii")
                    )
            except Exception as error:
                diagnostic_log(
                    "graphic_v68826_approved_output_download_failed",
                    request_key=request_key[:16],
                    error_type=type(error).__name__,
                )
    if not data_url.startswith("data:image/"):
        return None
    metadata["data_url"] = data_url
    metadata["generated"] = True
    metadata["company_wide_approved_output_hit_v68826"] = True
    metadata["graphic_v68826_request_key"] = request_key
    return [metadata]


def _graphic_v68826_publish_approved_output(image):
    """Publish one explicitly approved final PNG for exact company-wide reuse."""
    image = image or {}
    request_key = str(image.get("graphic_v68826_request_key") or "").strip()
    data_url = str(image.get("data_url") or "")
    raw, _ = data_url_to_bytes(data_url)
    if not request_key or not raw:
        return False
    storage_path = (
        f"{GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE}/"
        f"{request_key}/approved.png"
    )
    stored = False
    bucket = _graphic_v68826_storage_bucket()
    if bucket is not None:
        attempts = (
            lambda: bucket.upload(
                storage_path, raw,
                file_options={"content-type": "image/png", "upsert": "true"},
            ),
            lambda: bucket.upload(
                storage_path, raw,
                {"content-type": "image/png", "upsert": "true"},
            ),
            lambda: bucket.upload(storage_path, raw),
        )
        for attempt in attempts:
            try:
                attempt()
                stored = True
                break
            except TypeError:
                continue
            except Exception:
                continue
    metadata = {key: value for key, value in image.items() if key != "data_url"}
    payload = {
        "schema": GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE,
        "approved": True,
        "approved_at": datetime.now(timezone.utc).isoformat(),
        "approved_by": str(st.session_state.get("username") or ""),
        "image_fingerprint": _graphic_image_fingerprint(image),
        "image": {
            "metadata": metadata,
            "storage_path": storage_path if stored else "",
            "inline_data_url": "" if stored else data_url,
        },
    }
    saved = _graphic_v66100_cache_put(
        _graphic_v68826_cache_record_key(request_key), payload
    )
    diagnostic_log(
        "graphic_v68826_approved_output_published",
        request_key=request_key[:16], stored=bool(stored), saved=bool(saved),
    )
    return bool(saved)


def _graphic_v68826_revoke_approved_output(image):
    """Write a rejection tombstone so a rejected output cannot be reused."""
    request_key = str((image or {}).get("graphic_v68826_request_key") or "").strip()
    if not request_key:
        return False
    payload = {
        "schema": GRAPHIC_V68826_SHARED_OUTPUT_NAMESPACE,
        "approved": False,
        "rejected_at": datetime.now(timezone.utc).isoformat(),
        "rejected_by": str(st.session_state.get("username") or ""),
        "image_fingerprint": _graphic_image_fingerprint(image),
    }
    return bool(_graphic_v66100_cache_put(
        _graphic_v68826_cache_record_key(request_key), payload
    ))


def generate_graphic_marketing_images(
    prompt_text, uploaded_files=None, *, use_approved_style=True,
    preserve_product=True, style_strength="High",
    forced_upload_role="Auto-detect", quality_retry=True,
    product_transform_mode="Auto", professional_layered_studio=True,
):
    """Reuse exact pixels company-wide only after explicit approval.

    Cache misses execute the untouched v68790 generator. The wrapper neither
    changes Reference Mode analysis nor alters prompt, product, rendering, QA,
    recovery, or provider-routing behavior.
    """
    arguments = {
        "use_approved_style": use_approved_style,
        "preserve_product": preserve_product,
        "style_strength": style_strength,
        "forced_upload_role": forced_upload_role,
        "quality_retry": quality_retry,
        "product_transform_mode": product_transform_mode,
        "professional_layered_studio": professional_layered_studio,
    }
    request_key = _graphic_v68826_request_key(
        prompt_text, uploaded_files, arguments
    )
    cached = _graphic_v68826_restore_approved_output(request_key)
    if cached:
        diagnostic_log(
            "graphic_v68826_company_approved_output_hit",
            request_key=request_key[:16],
        )
        return cached

    images = _GRAPHIC_V68826_UNCACHED_GENERATOR(
        prompt_text, uploaded_files, **arguments
    )
    for image in images or []:
        if isinstance(image, dict):
            image["graphic_v68826_request_key"] = request_key
            image["company_wide_approved_output_hit_v68826"] = False
    return images



# ============================================================
# v68827 — Automatic Company-Wide Style Intelligence
# Built directly on v68826. Reference Mode and product-authority code are not
# modified. Intelligence is refreshed opportunistically and applied only to
# non-Reference-Mode cache misses.
# ============================================================
GRAPHIC_V68827_INTELLIGENCE_RECORD_TYPE = "graphic_style_intelligence"
GRAPHIC_V68827_INTELLIGENCE_SCHEMA = "v68827-company-style-intelligence"
GRAPHIC_V68827_MIN_NEW_DECISIONS = 3
GRAPHIC_V68827_MAX_FEEDBACK_ROWS = 500
GRAPHIC_V68827_REFRESH_SECONDS = 24 * 60 * 60
_GRAPHIC_V68827_BASE_SAVE_STYLE_MEMORY = save_graphic_style_memory
_GRAPHIC_V68827_BASE_GENERATOR = generate_graphic_marketing_images


def _graphic_v68827_parse_iso(value):
    try:
        return datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))
    except Exception:
        return None


def _graphic_v68827_feedback_rows(limit=GRAPHIC_V68827_MAX_FEEDBACK_ROWS):
    """Load company-wide explicit Graphic approval/rejection decisions."""
    rows = safe_select_rows(
        "learned_knowledge",
        order_columns=["updated_at", "created_at"],
        limit=max(20, min(int(limit), GRAPHIC_V68827_MAX_FEEDBACK_ROWS)),
    )
    allowed = {"approved_visual_style", "rejected_visual_style", "approved_reference_style_set"}
    return [
        row for row in (rows or [])
        if str(row.get("assistant") or "").strip().lower() == "graphic marketing"
        and str(row.get("record_type") or "").strip().lower() in allowed
    ]


def _graphic_v68827_latest_snapshot(rows=None):
    rows = rows if rows is not None else safe_select_rows(
        "learned_knowledge",
        order_columns=["updated_at", "created_at"],
        limit=100,
    )
    for row in rows or []:
        if str(row.get("assistant") or "").strip().lower() != "graphic marketing":
            continue
        if str(row.get("record_type") or "").strip().lower() == GRAPHIC_V68827_INTELLIGENCE_RECORD_TYPE:
            return row
    return None


def _graphic_v68827_feedback_signature(rows):
    compact = []
    for row in rows or []:
        compact.append({
            "id": row.get("id"),
            "record_type": row.get("record_type"),
            "updated_at": row.get("updated_at") or row.get("created_at"),
            "confidence_score": row.get("confidence_score"),
        })
    return hashlib.sha256(json.dumps(
        compact, ensure_ascii=False, sort_keys=True, default=str,
        separators=(",", ":"),
    ).encode("utf-8")).hexdigest()


def _graphic_v68827_extract_snapshot_payload(row):
    if not isinstance(row, dict):
        return {}
    raw = str(row.get("solution") or row.get("approved_answer") or "").strip()
    if not raw:
        return {}
    payload = extract_json_object(raw)
    if isinstance(payload, dict):
        return payload
    marker = "STYLE INTELLIGENCE JSON:"
    if marker in raw:
        payload = extract_json_object(raw.split(marker, 1)[1].strip())
        if isinstance(payload, dict):
            return payload
    return {}


def _graphic_v68827_feedback_digest(rows):
    """Create bounded evidence for synthesis; no image bytes or user secrets."""
    records = []
    for row in reversed(list(rows or [])):
        solution = re.sub(r"\s+", " ", str(
            row.get("solution") or row.get("approved_answer") or ""
        )).strip()
        records.append({
            "decision": "approved" if "approved" in str(row.get("record_type") or "").lower() else "rejected",
            "title": str(row.get("issue") or "")[:300],
            "request": str(row.get("question") or row.get("source_question") or "")[:1000],
            "style_profile": solution[:4500],
            "confidence": row.get("confidence_score"),
            "times_seen": row.get("times_seen"),
            "created_at": row.get("created_at"),
        })
    return records[-GRAPHIC_V68827_MAX_FEEDBACK_ROWS:]


def _graphic_v68827_should_refresh(feedback_rows, snapshot):
    if not feedback_rows:
        return False
    signature = _graphic_v68827_feedback_signature(feedback_rows)
    current = _graphic_v68827_extract_snapshot_payload(snapshot)
    if str(current.get("feedback_signature") or "") == signature:
        return False
    previous_count = int(current.get("decision_count") or 0)
    new_count = max(0, len(feedback_rows) - previous_count)
    updated = _graphic_v68827_parse_iso((snapshot or {}).get("updated_at") or (snapshot or {}).get("created_at"))
    stale = not updated or (datetime.now(timezone.utc) - updated.astimezone(timezone.utc)).total_seconds() >= GRAPHIC_V68827_REFRESH_SECONDS
    return (snapshot is None and len(feedback_rows) >= GRAPHIC_V68827_MIN_NEW_DECISIONS) or new_count >= GRAPHIC_V68827_MIN_NEW_DECISIONS or (snapshot is not None and stale)


def _graphic_v68827_synthesize(feedback_rows):
    evidence = _graphic_v68827_feedback_digest(feedback_rows)
    approved_count = sum(1 for row in evidence if row.get("decision") == "approved")
    rejected_count = sum(1 for row in evidence if row.get("decision") == "rejected")
    instructions = (
        "You are AutoTecPro's company-wide Graphic Style Intelligence analyst. "
        "Derive stable reusable rules only from the supplied explicit staff approvals and rejections. "
        "Return one strict JSON object only, no markdown. Include: schema, title, decision_count, "
        "approved_count, rejected_count, stable_approved_patterns, stable_rejected_patterns, "
        "composition_rules, lighting_rules, background_rules, color_rules, typography_rules, "
        "spacing_rules, logo_rules, cta_rules, product_presentation_rules, vehicle_presentation_rules, "
        "conditional_rules, conflicts_or_low_confidence_patterns, non_reference_prompt_guidance, "
        "prohibited_guidance, confidence_score. Never create a rule unsupported by repeated evidence. "
        "Rejects are negative evidence, not desired style. Most importantly, all derived rules are optional "
        "and subordinate to the user's current request, uploaded reference, exact product pixels, product geometry, "
        "fitment wording, vehicle identity, brand-logo authority, and every existing product-authority/QA constraint. "
        "Do not propose changing Reference Mode or any generation pipeline behavior."
    )
    response = client.responses.create(
        model="gpt-5.5",
        instructions=instructions,
        input=[{
            "role": "user",
            "content": [{
                "type": "input_text",
                "text": json.dumps({
                    "approved_count": approved_count,
                    "rejected_count": rejected_count,
                    "decisions": evidence,
                }, ensure_ascii=False, default=str),
            }],
        }],
        max_output_tokens=5000,
    )
    payload = extract_json_object(str(getattr(response, "output_text", "") or ""))
    if not isinstance(payload, dict):
        raise RuntimeError("Automatic Style Intelligence returned no valid JSON.")
    payload["schema"] = GRAPHIC_V68827_INTELLIGENCE_SCHEMA
    payload["decision_count"] = len(feedback_rows)
    payload["approved_count"] = approved_count
    payload["rejected_count"] = rejected_count
    payload["feedback_signature"] = _graphic_v68827_feedback_signature(feedback_rows)
    payload["generated_at"] = now_iso()
    payload["reference_mode_policy"] = "never_apply"
    payload["authority_policy"] = (
        "Subordinate to user request, uploaded references, exact product pixels, geometry, fitment, "
        "vehicle identity, official branding, product authority, QA and recovery constraints."
    )
    return payload


def _graphic_v68827_save_snapshot(payload, existing=None):
    text_payload = json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str)
    confidence = payload.get("confidence_score", 80)
    try:
        confidence = max(0, min(100, int(float(confidence))))
    except Exception:
        confidence = 80
    record = {
        "username": "company_style_intelligence",
        "record_type": GRAPHIC_V68827_INTELLIGENCE_RECORD_TYPE,
        "assistant": "Graphic Marketing",
        "vehicle": "Company-wide",
        "issue": "Automatic Company-Wide Graphic Style Intelligence",
        "solution": text_payload,
        "approved_answer": text_payload,
        "question": "Synthesize all explicit Graphic Marketing approvals and rejections into reusable company design rules.",
        "keywords": "graphic style intelligence company approved rejected design rules",
        "source_question": "Automatic Style Intelligence",
        "source_answer": text_payload,
        "source_conversation_id": None,
        "confidence_score": confidence,
        "times_seen": int(payload.get("decision_count") or 0),
        "times_used": int((existing or {}).get("times_used") or 0),
        "search_count": int((existing or {}).get("search_count") or 0),
        "vector_store_id": GRAPHIC_VECTOR_STORE_ID,
        "synced": False,
        "embedding_status": "pending",
        "source_type": "graphic_style_intelligence_v68827",
        "staff_confirmed": True,
        "created_at": (existing or {}).get("created_at") or now_iso(),
        "updated_at": now_iso(),
    }
    openai_file_id, vector_ready, ingestion_status = upload_learned_record_to_vector_store(
        record, GRAPHIC_VECTOR_STORE_ID, return_status=True,
    )
    record["openai_file_id"] = openai_file_id
    record["synced"] = bool(vector_ready)
    record["embedding_status"] = "synced" if vector_ready else (ingestion_status or "processing")
    if existing and existing.get("id") is not None:
        old_file_id = existing.get("openai_file_id")
        result = safe_update_row("learned_knowledge", record, existing.get("id"))
        if getattr(result, "data", None):
            if old_file_id and old_file_id != openai_file_id:
                remove_old_learned_vector_file(GRAPHIC_VECTOR_STORE_ID, old_file_id)
            return result.data[0]
        remove_old_learned_vector_file(GRAPHIC_VECTOR_STORE_ID, openai_file_id)
        raise RuntimeError("Automatic Style Intelligence snapshot update failed.")
    result = safe_insert_row("learned_knowledge", record)
    if not getattr(result, "data", None):
        remove_old_learned_vector_file(GRAPHIC_VECTOR_STORE_ID, openai_file_id)
        raise RuntimeError("Automatic Style Intelligence snapshot save failed.")
    return result.data[0]


def refresh_graphic_style_intelligence(force=False):
    """Opportunistically refresh one shared intelligence snapshot.

    Streamlit has no always-running worker, so periodic means: refresh after a
    qualifying feedback change or when a later request observes a stale snapshot.
    Fail-open behavior guarantees that image generation remains available.
    """
    try:
        feedback_rows = _graphic_v68827_feedback_rows()
        all_rows = safe_select_rows(
            "learned_knowledge", order_columns=["updated_at", "created_at"], limit=100,
        )
        snapshot = _graphic_v68827_latest_snapshot(all_rows)
        if not force and not _graphic_v68827_should_refresh(feedback_rows, snapshot):
            return _graphic_v68827_extract_snapshot_payload(snapshot)
        if not feedback_rows:
            return {}
        payload = _graphic_v68827_synthesize(feedback_rows)
        _graphic_v68827_save_snapshot(payload, snapshot)
        st.session_state["graphic_v68827_intelligence"] = payload
        diagnostic_log(
            "graphic_v68827_intelligence_refreshed",
            decisions=len(feedback_rows),
            approved=payload.get("approved_count"),
            rejected=payload.get("rejected_count"),
        )
        return payload
    except Exception as error:
        diagnostic_log(
            "graphic_v68827_intelligence_refresh_failed_open",
            error_type=type(error).__name__, error=str(error),
        )
        return {}


def _graphic_v68827_current_intelligence():
    cached = st.session_state.get("graphic_v68827_intelligence")
    if isinstance(cached, dict) and cached:
        return cached
    try:
        rows = safe_select_rows(
            "learned_knowledge", order_columns=["updated_at", "created_at"], limit=100,
        )
        payload = _graphic_v68827_extract_snapshot_payload(
            _graphic_v68827_latest_snapshot(rows)
        )
        if payload:
            st.session_state["graphic_v68827_intelligence"] = payload
        return payload
    except Exception as error:
        diagnostic_log(
            "graphic_v68827_intelligence_load_failed_open",
            error_type=type(error).__name__,
        )
        return {}


