@st.cache_data(ttl=300, max_entries=256, show_spinner=False)
def _build_recent_memory_text_cached(message_rows):
    """Build the recent clean chat-memory block once per message snapshot."""
    if not message_rows:
        return ""

    memory_parts = ["Previous conversation in this case:\n\n"]
    for role, raw_content in message_rows:
        clean_content, _ = extract_images_from_message_content(raw_content)
        clean_content = clean_visible_chat_text(clean_content)
        memory_parts.append(f"{str(role or 'assistant').upper()}: {clean_content}\n\n")
    return "".join(memory_parts)


def _recent_memory_rows(max_messages=10):
    """Return an immutable recent-message snapshot suitable for caching."""
    messages = list(st.session_state.get("messages") or [])
    return tuple(
        (
            str(message.get("role") or "assistant"),
            str(message.get("content") or ""),
        )
        for message in messages[-max(1, int(max_messages or 10)):]
    )



def _uploaded_file_bytes(uploaded_file):
    """Read uploaded bytes without leaving the file pointer changed."""
    original_position = None
    try:
        original_position = uploaded_file.tell()
    except Exception:
        original_position = None

    try:
        if hasattr(uploaded_file, "getvalue"):
            payload = uploaded_file.getvalue()
        else:
            payload = uploaded_file.read()
    finally:
        if original_position is not None:
            try:
                uploaded_file.seek(original_position)
            except Exception:
                pass

    return bytes(payload or b"")


def _uploaded_file_session_identity_v68872(uploaded_file):
    """Return a stable Streamlit upload identity when available."""
    file_id = str(getattr(uploaded_file, "file_id", "") or "").strip()
    if not file_id:
        return ""
    return "|".join([
        file_id,
        str(getattr(uploaded_file, "name", "") or ""),
        str(getattr(uploaded_file, "type", "") or ""),
        str(getattr(uploaded_file, "size", "") or ""),
    ])


def _uploaded_file_payload_digest_v68872(uploaded_file):
    """Reuse unchanged attachment bytes/digest across reruns without altering uploads."""
    session_identity = _uploaded_file_session_identity_v68872(uploaded_file)
    cache = st.session_state.setdefault(
        "_uploaded_file_payload_digest_cache_v68872",
        {},
    )

    if session_identity:
        cached = cache.get(session_identity)
        if isinstance(cached, dict):
            payload = cached.get("payload")
            digest = str(cached.get("digest") or "")
            if isinstance(payload, (bytes, bytearray)) and digest:
                return bytes(payload), digest

    payload = _uploaded_file_bytes(uploaded_file)
    digest = hashlib.sha256(payload).hexdigest()

    if session_identity:
        # Keep memory bounded. This only avoids rereading/re-hashing files that
        # Streamlit replays across reruns; OpenAI upload authority is unchanged.
        if len(cache) >= 16:
            cache.clear()
        cache[session_identity] = {
            "payload": payload,
            "digest": digest,
        }

    return payload, digest


def upload_openai_file_once(uploaded_file):
    """
    Upload one unchanged chat attachment only once per user session.

    v68872 keeps the exact existing OpenAI upload cache and adds a safe
    Streamlit-file-id byte/digest cache so reruns do not repeatedly read/hash
    the same unchanged attachment.
    """
    payload, digest = _uploaded_file_payload_digest_v68872(uploaded_file)
    cache_key = (
        str(getattr(uploaded_file, "name", "") or ""),
        str(getattr(uploaded_file, "type", "") or ""),
        len(payload),
        digest,
    )

    upload_cache = st.session_state.setdefault(
        "openai_chat_file_upload_cache",
        {},
    )
    cached_file_id = upload_cache.get(cache_key)
    if cached_file_id:
        return cached_file_id

    filename = str(
        getattr(uploaded_file, "name", "")
        or "AutoTecPro_attachment"
    )
    uploaded_openai_file = client.files.create(
        file=(filename, payload),
        purpose="assistants",
    )
    upload_cache[cache_key] = uploaded_openai_file.id

    # Bound session memory even during long staff sessions.
    if len(upload_cache) > 64:
        oldest_key = next(iter(upload_cache))
        if oldest_key != cache_key:
            upload_cache.pop(oldest_key, None)

    return uploaded_openai_file.id


ARCHIVE_SUPPORTED_EXTENSIONS = {
    ".jpg", ".jpeg", ".png", ".webp",
    ".pdf", ".txt", ".doc", ".docx",
    ".xls", ".xlsx", ".xlsm", ".xlsb", ".csv",
    ".ppt", ".pptx",
}
ARCHIVE_IGNORED_NAMES = {".ds_store", "thumbs.db", "desktop.ini"}
ARCHIVE_MAX_FILES = 100
ARCHIVE_MAX_DEPTH = 3
ARCHIVE_MAX_EXTRACTED_BYTES = MAX_UPLOAD_BYTES
ARCHIVE_MAX_COMPRESSION_RATIO = 200


class ArchiveValidationError(ValueError):
    """Raised when a ZIP attachment is unsafe or exceeds archive limits."""


def _archive_member_is_hidden(member_name):
    """Ignore macOS metadata, hidden folders/files, and common OS artifacts."""
    normalized = str(member_name or "").replace("\\", "/").strip("/")
    if not normalized:
        return True
    parts = [part for part in normalized.split("/") if part]
    lowered = [part.casefold() for part in parts]
    return (
        any(part == "__macosx" for part in lowered)
        or any(part.startswith(".") for part in parts)
        or any(part in ARCHIVE_IGNORED_NAMES for part in lowered)
    )


def _safe_archive_member_path(member_name):
    """Return a normalized relative ZIP path or reject traversal/absolute paths."""
    raw = str(member_name or "").replace("\\", "/")
    if not raw or raw.startswith("/") or re.match(r"^[A-Za-z]:/", raw):
        raise ArchiveValidationError("The ZIP contains an unsafe absolute file path.")
    parts = [part for part in raw.split("/") if part not in {"", "."}]
    if any(part == ".." for part in parts):
        raise ArchiveValidationError("The ZIP contains an unsafe parent-directory path.")
    return "/".join(parts)


def _archive_member_is_symlink(info):
    """Reject Unix symbolic links stored inside an archive."""
    unix_mode = (int(getattr(info, "external_attr", 0)) >> 16) & 0xFFFF
    return (unix_mode & 0o170000) == 0o120000


def _archive_flattened_filename(archive_label, relative_path):
    """Create an OpenAI-safe filename while the manifest preserves exact folders."""
    clean_archive = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(archive_label).stem).strip("_")
    clean_path = re.sub(r"[^A-Za-z0-9._-]+", "__", relative_path).strip("_")
    return f"{clean_archive or 'archive'}__{clean_path or 'file'}"


def _extract_zip_payload(payload, archive_label, *, depth=0, parent_path="", state=None):
    """Safely extract supported files from a ZIP entirely in memory."""
    if depth > ARCHIVE_MAX_DEPTH:
        raise ArchiveValidationError(
            f"Nested ZIP depth exceeds the supported limit of {ARCHIVE_MAX_DEPTH}."
        )
    if state is None:
        state = {
            "files": [], "manifest": [], "ignored": [], "unsupported": [],
            "total_bytes": 0, "member_count": 0,
        }
    try:
        archive = zipfile.ZipFile(io.BytesIO(payload))
    except (zipfile.BadZipFile, OSError) as error:
        raise ArchiveValidationError(f"{archive_label} is not a valid ZIP archive.") from error
    with archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            state["member_count"] += 1
            if state["member_count"] > ARCHIVE_MAX_FILES:
                raise ArchiveValidationError(f"The ZIP contains more than {ARCHIVE_MAX_FILES} files.")
            if int(getattr(info, "flag_bits", 0)) & 0x1:
                raise ArchiveValidationError(
                    f"Encrypted or password-protected ZIP entries are not supported: {info.filename}"
                )
            if _archive_member_is_symlink(info):
                raise ArchiveValidationError(f"Symbolic links are not allowed in ZIP files: {info.filename}")
            relative_path = _safe_archive_member_path(info.filename)
            full_path = "/".join(part for part in (parent_path, relative_path) if part)
            if _archive_member_is_hidden(relative_path):
                state["ignored"].append(full_path)
                continue
            compressed_size = max(1, int(getattr(info, "compress_size", 0) or 0))
            uncompressed_size = int(getattr(info, "file_size", 0) or 0)
            if uncompressed_size > 1024 * 1024 and uncompressed_size / compressed_size > ARCHIVE_MAX_COMPRESSION_RATIO:
                raise ArchiveValidationError(f"Potential ZIP bomb detected in {full_path}.")
            if uncompressed_size > MAX_UPLOAD_BYTES:
                raise ArchiveValidationError(
                    f"Extracted file exceeds the {MAX_UPLOAD_SIZE_MB} MB limit: {full_path}"
                )
            if state["total_bytes"] + uncompressed_size > ARCHIVE_MAX_EXTRACTED_BYTES:
                raise ArchiveValidationError(
                    f"Total extracted ZIP content exceeds {MAX_UPLOAD_SIZE_MB} MB."
                )
            try:
                member_bytes = archive.read(info)
            except RuntimeError as error:
                raise ArchiveValidationError(
                    f"Could not read {full_path}; encrypted archives are not supported."
                ) from error
            state["total_bytes"] += len(member_bytes)
            extension = Path(relative_path).suffix.lower()
            if extension == ".zip":
                state["manifest"].append(f"[Nested ZIP] {full_path}")
                _extract_zip_payload(
                    member_bytes, archive_label, depth=depth + 1,
                    parent_path=full_path, state=state,
                )
                continue
            if extension not in ARCHIVE_SUPPORTED_EXTENSIONS:
                state["unsupported"].append(full_path)
                continue
            output_name = _archive_flattened_filename(archive_label, full_path)
            state["files"].append(
                ManagedUploadedFile(
                    member_bytes, output_name, _normalized_upload_mime_type(output_name, "")
                )
            )
            state["manifest"].append(
                f"[Analyzed] {full_path} -> {output_name} ({len(member_bytes)} bytes)"
            )
    return state


def expand_chat_archives(uploaded_files):
    """Replace ZIP attachments with validated extracted files plus a folder manifest."""
    expanded = []
    archive_summaries = []
    for uploaded_file in uploaded_files or []:
        filename = str(getattr(uploaded_file, "name", "") or "attachment")
        if Path(filename).suffix.lower() != ".zip":
            expanded.append(uploaded_file)
            continue
        result = _extract_zip_payload(_uploaded_file_bytes(uploaded_file), filename)
        if not result["files"]:
            raise ArchiveValidationError(f"{filename} contains no supported files to analyze.")
        manifest_lines = [
            "AUTOTECPRO INTELLIGENT ARCHIVE MANIFEST",
            f"Archive: {filename}",
            f"Analyzed files: {len(result['files'])}",
            f"Extracted bytes: {result['total_bytes']}",
            "", "Folder structure and routing:", *result["manifest"],
        ]
        if result["ignored"]:
            manifest_lines.extend(["", "Ignored hidden/system files:", *result["ignored"]])
        if result["unsupported"]:
            manifest_lines.extend(["", "Unsupported files not analyzed:", *result["unsupported"]])
        manifest_lines.extend([
            "",
            "Instruction: Treat the extracted attachments as files from this one archive. "
            "Use the manifest to preserve their original folder relationships. Do not infer "
            "content from ignored or unsupported files.",
        ])
        expanded.append(ManagedUploadedFile(
            "\n".join(manifest_lines).encode("utf-8"),
            f"{Path(filename).stem}_Archive_Manifest.txt", "text/plain",
        ))
        expanded.extend(result["files"])
        archive_summaries.append(
            f"{filename}: {len(result['files'])} supported files, "
            f"{result['total_bytes'] / (1024 * 1024):.1f} MB extracted"
        )
    return expanded, archive_summaries



_LIVE_DATA_UNSET = object()


def _woocommerce_orders_from_live_data(live_data):
    """Return sanitized order records from any WooCommerce router result."""
    if not isinstance(live_data, dict):
        return []

    direct_order = live_data.get("order")
    if isinstance(direct_order, dict) and direct_order:
        return [direct_order]

    return [
        order for order in (live_data.get("orders") or [])
        if isinstance(order, dict) and order
    ]


def _woocommerce_person_text(person):
    """Format only values actually supplied by WooCommerce."""
    if not isinstance(person, dict):
        return []

    lines = []
    full_name = " ".join(
        str(person.get(key) or "").strip()
        for key in ("first_name", "last_name")
        if str(person.get(key) or "").strip()
    ).strip()
    if full_name:
        lines.append(("Name", full_name))

    field_labels = (
        ("company", "Company"),
        ("address_1", "Address"),
        ("address_2", "Address 2"),
        ("city", "City"),
        ("state", "Province / State"),
        ("postcode", "Postal / ZIP Code"),
        ("country", "Country"),
        ("email", "Email"),
        ("phone", "Phone"),
    )
    for key, label in field_labels:
        value = _clean_woocommerce_meta_text(person.get(key))
        if value:
            lines.append((label, value))
    return lines


def build_woocommerce_order_display_text(live_data, technical_view=False):
    """
    Build a persistent order section from exact sanitized WooCommerce values.

    Product names, SKUs, option labels, option values, shipping methods, notes,
    status, dates, and permitted customer fields are not rewritten or inferred.
    """
    orders = _woocommerce_orders_from_live_data(live_data)
    missing_numbers = []
    batch_errors = []
    if isinstance(live_data, dict):
        missing_numbers = [
            str(number)
            for number in (live_data.get("not_found") or [])
            if str(number).strip()
        ]
        batch_errors = [
            item
            for item in (live_data.get("errors") or [])
            if isinstance(item, dict)
        ]

    if not orders and not missing_numbers and not batch_errors:
        return ""

    blocks = []
    for order in orders:
        order_number = _clean_woocommerce_meta_text(
            order.get("number") or order.get("id")
        )
        heading = "WooCommerce Order Information"
        if order_number:
            heading += f" — Order #{order_number}"
        lines = [f"## {heading}"]

        summary_fields = (
            ("Status", order.get("status")),
            ("Date Created", order.get("date_created")),
            ("Date Modified", order.get("date_modified")),
            ("Date Paid", order.get("date_paid")),
            ("Date Completed", order.get("date_completed")),
            ("Customer Note", order.get("customer_note")),
        )
        for label, raw_value in summary_fields:
            value = _clean_woocommerce_meta_text(raw_value)
            if value:
                lines.append(f"**{label}:** {value}")

        billing_lines = _woocommerce_person_text(order.get("billing"))
        if billing_lines:
            lines.append("\n### Billing / Customer Information")
            for label, value in billing_lines:
                lines.append(f"**{label}:** {value}")

        shipping_lines_person = _woocommerce_person_text(order.get("shipping"))
        if shipping_lines_person:
            lines.append("\n### Shipping Information")
            for label, value in shipping_lines_person:
                lines.append(f"**{label}:** {value}")

        for item_index, item in enumerate(order.get("line_items") or [], start=1):
            if not isinstance(item, dict):
                continue
            lines.append(
                "\n### Purchased Item"
                + (f" {item_index}" if len(order.get("line_items") or []) > 1 else "")
            )
            item_fields = (
                ("Product", item.get("name")),
                ("SKU", item.get("sku")),
                ("Quantity", item.get("quantity")),
            )
            for label, raw_value in item_fields:
                value = _clean_woocommerce_meta_text(raw_value)
                if value:
                    lines.append(f"**{label}:** {value}")

            for option in item.get("selected_options") or []:
                if not isinstance(option, dict):
                    continue
                label = _clean_woocommerce_meta_text(option.get("label"))
                value = _clean_woocommerce_meta_text(option.get("value"))
                if label and value:
                    lines.append(f"**{label}:** {value}")

            if not technical_view:
                commercial_fields = (
                    ("Subtotal", item.get("subtotal")),
                    ("Item Total", item.get("total")),
                    ("Item Tax", item.get("tax")),
                )
                for label, raw_value in commercial_fields:
                    value = _clean_woocommerce_meta_text(raw_value)
                    if value:
                        lines.append(f"**{label}:** {value}")

        methods = []
        for shipping_line in order.get("shipping_lines") or []:
            if not isinstance(shipping_line, dict):
                continue
            method = _clean_woocommerce_meta_text(
                shipping_line.get("method_title")
            )
            if method:
                methods.append(method)
        if methods:
            lines.append("\n### Shipping Method")
            lines.extend(f"- {method}" for method in methods)

        if not technical_view:
            commercial_order_fields = (
                ("Currency", order.get("currency")),
                ("Payment Method", order.get("payment_method_title")),
                ("Shipping Total", order.get("shipping_total")),
                ("Discount Total", order.get("discount_total")),
                ("Total Tax", order.get("total_tax")),
                ("Order Total", order.get("total")),
            )
            commercial_values = []
            for label, raw_value in commercial_order_fields:
                value = _clean_woocommerce_meta_text(raw_value)
                if value:
                    commercial_values.append((label, value))
            if commercial_values:
                lines.append("\n### Commercial Information")
                for label, value in commercial_values:
                    lines.append(f"**{label}:** {value}")

        blocks.append("\n\n".join(lines))

    if missing_numbers:
        blocks.append(
            "## WooCommerce Orders Not Found\n\n"
            + "\n".join(f"- Order #{number}" for number in missing_numbers)
        )

    if batch_errors:
        safe_error_lines = []
        for item in batch_errors:
            number = _clean_woocommerce_meta_text(item.get("order_number"))
            error_text = _clean_woocommerce_meta_text(item.get("error"))
            if number:
                safe_error_lines.append(
                    f"- Order #{number}: {error_text or 'Lookup failed.'}"
                )
        if safe_error_lines:
            blocks.append(
                "## WooCommerce Lookup Errors\n\n"
                + "\n".join(safe_error_lines)
            )

    return "\n\n---\n\n".join(blocks)


def build_response_mode_instruction(response_mode):
    """Return completeness rules without shortening ordinary staff requests."""
    mode = str(
        (
            response_mode
            if isinstance(response_mode, dict)
            else {}
        ).get("type")
        or "complete_standard"
    ).strip().lower()

    common = (
        "\n\nRESPONSE COMPLETENESS — generated by the AutoTecPro application:\n"
        "- Never decide response length from the number of words in the prompt.\n"
        "- A short staff note may be an instruction to produce a complete, "
        "professional customer-facing response.\n"
        "- Preserve every active Technical Support, Sales, Marketing, document, "
        "and specialized troubleshooting workflow.\n"
        "- In every customer-facing draft, state staff-confirmed and approved facts "
        "directly and clearly. Do not weaken confirmed facts with phrases such as "
        "we need to verify, may, might, normally, depends, or should unless the fact "
        "is genuinely unresolved.\n"
        "- Separate CONFIRMED facts, COMMERCIAL items that belong to Sales, and "
        "genuinely UNKNOWN items. Ask for confirmation only for UNKNOWN items.\n"
        "- Do not repeat internal analysis, evidence, warnings, database fields, or "
        "knowledge-record language inside the Customer Reply Draft. The draft must "
        "be natural, concise, easy to understand, and ready to send.\n"
    )
    if mode == "explicit_concise":
        return common + (
            "- The staff member explicitly requested brevity. Follow the exact "
            "requested limit without omitting essential safety or accuracy facts."
        )
    if mode == "professional_reply":
        return common + (
            "- Produce a polished, ready-to-send reply with an appropriate greeting, "
            "clear explanation, next steps, and a natural professional closing.\n"
            "- Expand the staff's short notes; do not merely repeat them.\n"
            "- Use CURRENT-CASE STAFF-CONFIRMED KNOWLEDGE immediately when supplied. "
            "Do not repeat an earlier Product Confirmation Needed response and do "
            "not ask for facts that staff already confirmed.\n"
            "- When a confirmed product family contains both a standard and Pro "
            "version, state the confirmed family confidently and ask only which "
            "version the customer prefers when that choice is still unresolved."
        )
    if mode == "technical_expert":
        return common + (
            "- Produce the complete existing Technical Support troubleshooting flow.\n"
            "- Include the customer-ready reply section when useful.\n"
            "- Do not shorten because the issue description is brief."
        )
    if mode == "document":
        return common + (
            "- Produce the complete requested document content with all necessary "
            "sections and details."
        )
    return common + (
        "- Provide a complete, useful response. Be concise only when the staff member "
        "explicitly asks for a short or limited-length answer."
    )



def build_ai_loading_status(
    selected_assistant,
    detected_live_request=None,
    use_file_search=False,
):
    """
    Return an accurate visible status for the current AI request.

    The message describes only work the application is actually performing and
    disappears as soon as the first streamed response text is received.
    """
    live_type = str(
        (
            detected_live_request
            if isinstance(detected_live_request, dict)
            else {}
        ).get("type")
        or "none"
    ).strip().lower()

    if bool(use_file_search):
        if selected_assistant == "🔧 Technical Support":
            return "Searching AutoTecPro Technical Support knowledge base…"
        if is_sales_workspace(selected_assistant):
            return "Searching AutoTecPro Sales and Technical knowledge bases…"
        if is_marketing_workspace(selected_assistant):
            return "Searching AutoTecPro Marketing, Sales, and Technical knowledge bases…"
        return "Searching AutoTecPro knowledge base…"

    if live_type == "web":
        return "Searching the web…"

    if live_type == "connection_check":
        return "Testing AutoTecPro live connections…"

    if live_type.startswith("woocommerce_"):
        return "Analyzing the WooCommerce order information…"

    return "Analyzing your request…"


def _loading_status_html(message):
    """Render a lightweight loading line that works in dark and light modes."""
    safe_message = html.escape(str(message or "Analyzing your request…"))
    return (
        '<div class="atp-ai-loading-status" role="status" aria-live="polite">'
        '<span class="atp-ai-loading-dot"></span>'
        f'<span>{safe_message}</span>'
        '</div>'
    )



def _assistant_stream_html(visible_text):
    """Render the active streaming response using the existing chat design."""
    logo_base64 = get_logo_base64()
    if logo_base64:
        icon_html = (
            f'<img src="data:image/png;base64,{logo_base64}" '
            'alt="AutoTecPro AI">'
        )
    else:
        icon_html = "AI"

    return (
        '<div class="chat-row">'
        f'<div class="chat-icon assistant-icon">{icon_html}</div>'
        '<div class="chat-bubble assistant-bubble">'
        f'{html_from_text(visible_text, assistant_mode=True)}'
        '</div>'
        '</div>'
    )



def _recent_case_learned_knowledge_context(selected_assistant, limit=5):
    """
    Return approved staff-confirmed knowledge learned in the current conversation.

    v68864 performance behavior:
    - Keep the existing direct-Supabase authority.
    - Cache the already-built current-case context per browser session.
    - Invalidate immediately whenever this session successfully learns new
      current-case knowledge.
    - Ordinary follow-up commands therefore avoid a redundant Supabase round trip.
    """
    conversation_id = str(st.session_state.get("conversation_id") or "").strip()
    if not conversation_id:
        return ""

    clean_assistant = clean_assistant_label(selected_assistant).strip()
    revision = int(st.session_state.get("_case_learning_context_revision_v68864", 0) or 0)
    cache_key = f"{conversation_id}|{clean_assistant}|{int(limit or 5)}|{revision}"
    session_cache = st.session_state.setdefault(
        "_case_learning_context_cache_v68864",
        {},
    )

    cached = session_cache.get(cache_key)
    if isinstance(cached, dict):
        cached_at = float(cached.get("cached_at") or 0.0)
        # Five minutes is long enough to remove repeated query latency while the
        # revision above guarantees same-session learning is visible immediately.
        if time.monotonic() - cached_at <= 300.0:
            return str(cached.get("text") or "")

    try:
        query = (
            supabase.table("learned_knowledge")
            .select(
                "id,assistant,record_type,vehicle,issue,solution,approved_answer,"
                "keywords,staff_confirmed,source_type,confidence_score,updated_at"
            )
            .eq("source_conversation_id", conversation_id)
            .eq("assistant", clean_assistant)
            .order("updated_at", desc=True)
            .limit(max(1, min(int(limit or 5), 10)))
            .execute()
        )
        rows = list(query.data or [])
    except Exception as error:
        diagnostic_log(
            "recent_case_learned_context_failed",
            error_type=type(error).__name__,
            error=str(error),
        )
        return ""

    approved_rows = [
        row for row in rows
        if not is_pending_knowledge_row(row)
        and str(row.get("solution") or row.get("approved_answer") or "").strip()
    ]

    if not approved_rows:
        context_text = ""
    else:
        blocks = [
            "CURRENT-CASE STAFF-CONFIRMED KNOWLEDGE — direct Supabase record:\n",
            "These records were explicitly taught or confirmed by staff in this same "
            "conversation. For an exact vehicle/product match, they override ambiguous "
            "Product Library suggestions, older conflicting drafts, and the temporary "
            "absence of the new record from file_search indexing. Do not ask staff to "
            "reconfirm facts already confirmed here. Ask only for genuinely unresolved "
            "choices, such as standard versus Pro when both remain valid.\n",
        ]
        for index, row in enumerate(approved_rows, start=1):
            solution = str(
                row.get("solution") or row.get("approved_answer") or ""
            ).strip()
            blocks.append(
                f"\nRECORD {index}\n"
                f"Title: {str(row.get('issue') or '').strip()}\n"
                f"Vehicle/Product: {str(row.get('vehicle') or '').strip()}\n"
                f"Record type: {str(row.get('record_type') or '').strip()}\n"
                f"Staff confirmed: {bool(row.get('staff_confirmed'))}\n"
                f"Confidence: {row.get('confidence_score')}\n"
                f"Approved knowledge:\n{solution}\n"
            )
        context_text = "".join(blocks).strip()

    # Keep this tiny and session-local.
    if len(session_cache) >= 16:
        session_cache.clear()
    session_cache[cache_key] = {
        "cached_at": time.monotonic(),
        "text": context_text,
    }
    return context_text




def _technical_recent_conversation_context_v69106(limit=6):
    """Return bounded same-case dialogue context for Technical follow-up continuity.

    v69106 deliberately uses only already-visible messages from the current owned
    Streamlit case.  It does not create factual authority by itself; it tells the
    provider what exact vehicle/product/configuration the follow-up refers to so
    file_search does not silently jump to a nearby legacy record.
    """
    if str(assistant or "") != "🔧 Technical Support":
        return ""
    rows = list(st.session_state.get("messages") or [])
    if not rows:
        return ""
    bounded = []
    for row in rows[-max(2, min(int(limit or 6), 10)):]:
        if not isinstance(row, dict):
            continue
        role = str(row.get("role") or "").strip().lower()
        if role not in {"user", "assistant"}:
            continue
        value = clean_visible_chat_text(str(row.get("content") or ""))
        value = re.sub(r"\s+", " ", value).strip()
        if not value:
            continue
        # Keep enough exact menu/vehicle wording for identity continuity while
        # preventing a long old transcript from dominating the current query.
        bounded.append((role, value[:1800]))
    if not bounded:
        return ""
    lines = [
        "CURRENT TECHNICAL CASE CONTINUITY — context only, not independent factual authority:",
        "Use this only to resolve pronouns/elliptical follow-ups and preserve the exact vehicle, product, factory-system, and already-established configuration family. Re-check Technical knowledge for the requested fact. Do not switch to a different Car Model or nearby product merely because a new vector-search chunk ranks higher.",
    ]
    for role, value in bounded:
        lines.append(("USER" if role == "user" else "ASSISTANT") + ": " + value)
    return "\n".join(lines)


def _technical_variant_retrieval_instruction_v69106(prompt_text):
    """Add generic same-family Manual/Automatic retrieval requirements.

    This contains no vehicle-specific menu values.  Learned Technical evidence
    remains the sole factual authority.
    """
    if str(assistant or "") != "🔧 Technical Support":
        return ""
    prompt = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not prompt:
        return ""
    configuration_query = bool(
        re.search(r"\bcar\s*model\b|\bcare\s*model\b|\bprotocol\b|\bcanbus\b|\ba\s*/?\s*c\b|\bclimate\b", prompt)
    )
    if not configuration_query:
        return ""
    asks_manual = bool(re.search(r"\bmanual\b|\bman\s*a/?c\b|\blo\b", prompt))
    asks_auto = bool(re.search(r"\bauto(?:matic)?\b|\bdigital\s+climate\b|\bhi\b", prompt))
    lines = [
        "TECHNICAL SAME-CONFIGURATION VARIANT AUTHORITY (v69106):",
        "- Resolve one exact vehicle/product/factory-system configuration family first, then keep every setting in the answer inside that same family.",
        "- Car Model and climate/A-C option are separate fields. A Manual/Automatic follow-up must not silently replace the previously established Car Model with a nearby model-name chunk unless the same authoritative Technical source explicitly requires a different Car Model.",
        "- Prefer values that coexist in the same learned Technical page/file/configuration package. Do not splice Car Model from one package with A/C values from another.",
    ]
    if asks_auto and not asks_manual:
        lines += [
            "- This is an Automatic-A/C follow-up. Preserve the exact vehicle/product/Car Model established by the current case, re-check the same Technical configuration family, and return its verified Automatic climate option.",
        ]
    elif asks_manual and not asks_auto:
        lines += [
            "- This is a Manual-A/C follow-up. Preserve the exact vehicle/product/Car Model established by the current case, re-check the same Technical configuration family, and return its verified Manual climate option.",
        ]
    else:
        lines += [
            "- Climate type is not uniquely specified. Before answering, retrieve/reconcile BOTH verified Manual and Automatic climate branches for this exact configuration family when both exist in Technical knowledge.",
            "- In the first settings table, keep one base Car Model row. Show both verified climate choices together in A/C Type (or separate Manual A/C and Automatic A/C rows when clearer). Do not answer with only whichever climate-specific chunk ranked first if the same source contains both branches.",
        ]
    lines += [
        "- If the same authoritative source does not support both variants, say which variant is confirmed and which requires verification; never manufacture the missing counterpart.",
        "- These rules change retrieval/continuity only. Existing v69050 image publication, vehicle/year/product/topic gates, Sales/Marketing routing, Graphic pipeline, security, and persistence remain unchanged.",
    ]
    return "\n".join(lines)


def build_user_input(
    prompt_text,
    uploaded_files,
    detected_live_request=None,
    detected_technical_tool=None,
    detected_workspace_tool=None,
    response_mode=None,
    live_data_override=_LIVE_DATA_UNSET,
    order_displayed_by_app=False,
):
    content = [
        {
            "type": "input_text",
            "text": build_live_context_text(),
        }
    ]

    detected_live_request = (
        detected_live_request
        if isinstance(detected_live_request, dict)
        else detect_live_request(prompt_text, assistant)
    )
    if live_data_override is _LIVE_DATA_UNSET:
        live_data = get_live_data_for_prompt(
            prompt_text,
            assistant,
            request_type=detected_live_request,
        )
    else:
        live_data = live_data_override

    if (
        str(detected_live_request.get("type") or "").startswith("woocommerce_")
        and live_data is None
    ):
        live_data = {
            "source": "AutoTecPro WooCommerce router",
            "error": (
                "A WooCommerce request was detected, but no live result was "
                "returned. Do not provide a generic admin-lookup path; report "
                "this routing error."
            ),
            "detected_request": detected_live_request,
        }

    if live_data is not None:
        live_instruction = (
            "LIVE DATA RESULT — retrieved by the AutoTecPro application:\n"
            + json.dumps(live_data, ensure_ascii=False, default=str)
            + "\n\nUse this live result exactly as supplied. Mention its source. "
              "Do not invent any missing fields, order status, payment status, "
              "shipment status, refund status, customer detail, price, rate, "
              "date, delivery estimate, or tracking event."
        )
        if (
            order_displayed_by_app
            and str(
                detected_live_request.get("type") or ""
            ).startswith("woocommerce_")
        ):
            live_instruction += (
                "\n\nThe application has already displayed the exact WooCommerce "
                "order information above your response. Do not repeat, shorten, "
                "replace, or rewrite that order section. In the Sales workspace, "
                "append the organized enrichment sections required by the Sales "
                "order workflow after the displayed order details. In Marketing, "
                "preserve the displayed order and append Order Snapshot, Customer "
                "Profile, Purchased Product and Options, separate AutoTecPro Model "
                "Match and KVN Part Number Match, Product Highlights, Customer "
                "Segmentation, Marketing Opportunities, follow-up content, brief "
                "installation details, verified installation resources, and the "
                "Customer Reply Draft required by the Marketing order instructions. "
                "In Technical Support, preserve the displayed order and append the "
                "complete separate AutoTecPro Model Match, KVN Part Number Match, "
                "Product Specifications, compatibility, detailed installation, "
                "verified resources, and customer-reply workflow required by the "
                "Technical order instructions."
            )
        content.append({
            "type": "input_text",
            "text": live_instruction,
        })

    detected_technical_tool = (
        detected_technical_tool
        if isinstance(detected_technical_tool, dict)
        else detect_technical_support_tool(
            prompt_text,
            assistant,
            has_images=any(
                str(getattr(item, "type", "") or "").startswith("image/")
                for item in (uploaded_files or [])
            ),
        )
    )
    technical_tool_context = build_technical_tool_context(
        prompt_text,
        routing=detected_technical_tool,
    )
    if technical_tool_context:
        content.append({
            "type": "input_text",
            "text": technical_tool_context,
        })

    detected_workspace_tool = (
        detected_workspace_tool
        if isinstance(detected_workspace_tool, dict)
        else detect_workspace_ai_tool(
            prompt_text,
            assistant,
            has_images=any(
                str(getattr(item, "type", "") or "").startswith("image/")
                for item in (uploaded_files or [])
            ),
        )
    )
    workspace_tool_context = build_workspace_ai_tool_context(
        prompt_text,
        routing=detected_workspace_tool,
    )
    if workspace_tool_context:
        content.append({
            "type": "input_text",
            "text": workspace_tool_context,
        })

    response_mode_instruction = build_response_mode_instruction(response_mode)
    if response_mode_instruction:
        content.append({
            "type": "input_text",
            "text": response_mode_instruction,
        })

    memory_text = _build_recent_memory_text_cached(_recent_memory_rows(10))
    if memory_text:
        content.append({"type": "input_text", "text": memory_text})

    # A newly taught record can take several seconds to become searchable in the
    # OpenAI vector store. Supply approved records from this exact case directly
    # so immediate follow-ups such as "how to reply?" use the correction now.
    case_learned_context = _recent_case_learned_knowledge_context(assistant)
    if case_learned_context:
        content.append({"type": "input_text", "text": case_learned_context})

    # v69106: preserve exact same-case vehicle/product/configuration identity for
    # elliptical Technical follow-ups (for example, "how about auto A/C?").
    # This is context only; factual values must still be re-verified from Technical
    # knowledge.  The separate variant directive forces Manual/Automatic siblings
    # to be retrieved from one configuration family instead of mixed packages.
    technical_case_context_v69106 = _technical_recent_conversation_context_v69106()
    if technical_case_context_v69106:
        content.append({"type": "input_text", "text": technical_case_context_v69106})
    technical_variant_instruction_v69106 = _technical_variant_retrieval_instruction_v69106(prompt_text)
    if technical_variant_instruction_v69106:
        content.append({"type": "input_text", "text": technical_variant_instruction_v69106})

    if prompt_text:
        content.append({"type": "input_text", "text": prompt_text})

    if uploaded_files:
        for uploaded_file in uploaded_files:
            if uploaded_file.type.startswith("image/"):
                content.append({
                    "type": "input_image",
                    "image_url": image_to_data_url(uploaded_file),
                })
            else:
                uploaded_file_id = upload_openai_file_once(uploaded_file)
                content.append({
                    "type": "input_file",
                    "file_id": uploaded_file_id,
                })

    return [{"role": "user", "content": content}]


@st.cache_data(ttl=3600, max_entries=32, show_spinner=False)
def _workspace_knowledge_priority_instruction(selected_assistant):
    """Describe one-way knowledge access and source authority for the active workspace."""
    if selected_assistant == "🔧 Technical Support":
        return (
            "KNOWLEDGE ACCESS AND AUTHORITY:\n"
            "- This workspace may use Technical knowledge only.\n"
            "- Never use or infer Sales/Marketing pricing, promotions, dealer terms, "
            "campaigns, margins, or commercial policy.\n"
            "- Technical sources are authoritative for compatibility, installation, "
            "wiring, firmware, hardware behavior, retained functions, limitations, and "
            "troubleshooting.\n"
            "- When information is not supported by Technical knowledge, say what is "
            "missing instead of guessing.\n"
            "- Website knowledge may contain SECTION_HEADING, NEARBY_INSTRUCTION_TEXT, "
            "IMAGE_ANALYSIS, an exact AUTO_DISPLAY_IMAGE URL, or older raw HTML with an exact "
            "<img src=...> inside the same Technical section. Prefer images whose section heading "
            "and nearby instruction text match the exact installation step being answered. For a "
            "legacy raw-HTML image, use it only when the <img> belongs to the SAME matching section "
            "(after that section's relevant instructions and before the next section heading). "
            "When one directly supports the current answer, append up to 4 internal control lines "
            "at the END of the response, each exactly in this format: "
            "[[ATP_WEB_IMAGE_JSON:{\"url\":\"EXACT_AUTO_DISPLAY_IMAGE_URL\","
            "\"caption\":\"short factual caption\","
            "\"source_page\":\"EXACT Final source URL from the retrieved package\","
            "\"page_title\":\"EXACT Page title from the retrieved package\","
            "\"section_heading\":\"EXACT SECTION_HEADING\","
            "\"nearby_instruction_text\":\"EXACT NEARBY_INSTRUCTION_TEXT\","
            "\"visual_analysis\":\"EXACT IMAGE_ANALYSIS text or empty string for a legacy HTML image\","
            "\"legacy_html_section_bound\":false}]]. "
            "For an older raw-HTML image with no IMAGE_ANALYSIS, copy its exact <img src> URL, exact "
            "source page/title, exact matching section heading and nearby instructions, set "
            "visual_analysis to an empty string, and set legacy_html_section_bound to true. "
            "Copy provenance only from the SAME retrieved image/HTML section; do not summarize or "
            "invent it. Use only an exact URL retrieved from Technical file_search knowledge. Never "
            "invent, rewrite, guess, or use an image merely because it is from the same webpage. "
            "If no retrieved image directly supports the answer, append no image control line."
        )
    if is_sales_workspace(selected_assistant):
        return (
            "KNOWLEDGE ACCESS AND AUTHORITY:\n"
            "- Search Sales knowledge and Technical knowledge.\n"
            "- Sales knowledge is authoritative for pricing, promotions, dealer policy, "
            "commercial terms, shipping, availability, warranty/returns, and sales SOP.\n"
            "- Technical knowledge is authoritative for compatibility, installation, "
            "wiring, firmware, hardware behavior, retained functions, limitations, and "
            "troubleshooting.\n"
            "- Do not let a Sales statement override a conflicting Technical fact.\n"
            "- Combine both sources only when their subject areas are compatible; identify "
            "uncertainty instead of blending conflicting records."
        )
    if is_marketing_workspace(selected_assistant):
        return (
            "KNOWLEDGE ACCESS AND AUTHORITY:\n"
            "- Search Marketing, Sales, and Technical knowledge.\n"
            "- Marketing knowledge is authoritative for brand voice, campaign rules, and "
            "approved creative guidance.\n"
            "- Sales knowledge is authoritative for pricing, promotions, dealer policy, "
            "commercial terms, shipping, availability, and warranty/returns.\n"
            "- Technical knowledge is authoritative for compatibility, specifications, "
            "installation, wiring, firmware, hardware behavior, limitations, and troubleshooting.\n"
            "- Never let marketing copy or a sales claim override a conflicting Technical fact."
        )
    return ""


def _build_ai_request(
    prompt_text,
    uploaded_files,
    detected_live_request=None,
    detected_technical_tool=None,
    detected_workspace_tool=None,
    response_mode=None,
    use_file_search=True,
    live_data_override=_LIVE_DATA_UNSET,
    order_displayed_by_app=False,
):
    user_input = build_user_input(
        prompt_text,
        uploaded_files,
        detected_live_request=detected_live_request,
        detected_technical_tool=detected_technical_tool,
        detected_workspace_tool=detected_workspace_tool,
        response_mode=response_mode,
        live_data_override=live_data_override,
        order_displayed_by_app=order_displayed_by_app,
    )
    knowledge_priority_instruction = _workspace_knowledge_priority_instruction(assistant)
    instructions = (
        get_instructions(assistant)
        + ("\n\n" + knowledge_priority_instruction if knowledge_priority_instruction else "")
        + "\n\nThe AutoTecPro application may supply LIVE APPLICATION CONTEXT "
          "and LIVE DATA RESULT blocks. Treat those application-supplied blocks "
          "as authoritative. Use web search for current public information, "
          "recent news, recalls, software updates, laws, specifications, or facts "
          "that may have changed. Use file_search for AutoTecPro internal "
          "technical, product, policy, sales, or marketing facts when the "
          "application enables it. When CURRENT-CASE STAFF-CONFIRMED KNOWLEDGE "
          "is supplied, treat it as the highest-priority internal source for the "
          "exact matched case and do not fall back to an earlier clarification. "
          "Always name the source of live data. "
          "Never invent an order status, payment status, shipment status, refund "
          "status, tracking event, exchange rate, weather condition, or delivery "
          "estimate. When the user explicitly requests a PDF, manual, guide, "
          "report, handbook, proposal, SOP, or training document, write the "
          "complete document content in clean structured plain text or Markdown. "
          "Do not claim that you created a downloadable file; the AutoTecPro "
          "application will build the file locally from your response."
    )

    tools = []
    live_request_type = str(
        (
            detected_live_request
            if isinstance(detected_live_request, dict)
            else {}
        ).get("type")
        or "none"
    ).strip().lower()

    if live_request_type == "web":
        tools.append({"type": "web_search"})

    if use_file_search:
        vector_store_ids = []
        if assistant == "🔧 Technical Support":
            vector_store_ids = _configured_vector_store_ids(
                TECHNICAL_VECTOR_STORE_ID,
            )
        elif is_sales_workspace(assistant):
            vector_store_ids = _configured_vector_store_ids(
                SALES_VECTOR_STORE_ID,
                TECHNICAL_VECTOR_STORE_ID,
            )
        elif is_marketing_workspace(assistant):
            vector_store_ids = _configured_vector_store_ids(
                MARKETING_VECTOR_STORE_ID,
                SALES_VECTOR_STORE_ID,
                TECHNICAL_VECTOR_STORE_ID,
            )
        elif is_graphic_workspace(assistant):
            # Graphic Chat now supports ordinary conversational turns. Keep the
            # Responses API request narrowly scoped to the dedicated Graphic
            # vector store; broader product facts are already supplied through
            # Product Library context and the structured generation pipeline.
            # Sending several stores here can be rejected by some Responses API
            # deployments and was the cause of the v1200 planning-message 400.
            vector_store_ids = _configured_vector_store_ids(
                GRAPHIC_VECTOR_STORE_ID,
            )

        if vector_store_ids:
            tools.insert(
                0,
                {
                    "type": "file_search",
                    "vector_store_ids": vector_store_ids,
                },
            )

    request = {
        "model": "gpt-5.5",
        "instructions": instructions,
        "input": user_input,
        "max_output_tokens": MAX_AI_OUTPUT_TOKENS,
    }
    if tools:
        request["tools"] = tools
        # v69012: Technical automatic image recovery must use the exact file_search
        # evidence returned for this answer instead of depending on the model to emit
        # a hidden image-control line. The Responses API can include those result
        # records in the final response without adding another search call.
        if not is_graphic_workspace(assistant) and any(
            isinstance(tool, dict) and tool.get("type") == "file_search"
            for tool in tools
        ):
            request["include"] = ["file_search_call.results"]
    return request



def _response_file_search_results_v69012(response):
    """Return exact file_search result records included in one Responses result.

    This is deliberately tolerant of SDK object/dict shapes. Only file id/name,
    relevance score, and retrieved text are retained; no user prompt or secrets are
    persisted. These records let Technical image recovery inspect the exact knowledge
    that supported the answer instead of asking the model to reproduce image metadata.
    """
    if response is None:
        return []

    output = response.get("output") if isinstance(response, dict) else getattr(response, "output", None)
    rows = []
    for item in list(output or []):
        item_type = item.get("type") if isinstance(item, dict) else getattr(item, "type", "")
        if str(item_type or "") != "file_search_call":
            continue
        results = item.get("results") if isinstance(item, dict) else getattr(item, "results", None)
        for result in list(results or []):
            def value(name, default=""):
                if isinstance(result, dict):
                    return result.get(name, default)
                return getattr(result, name, default)
            file_id = str(value("file_id") or "").strip()
            filename = str(value("filename") or value("file_name") or "").strip()
            text = str(value("text") or "")
            try:
                score = float(value("score", 0.0) or 0.0)
            except Exception:
                score = 0.0
            if not (file_id or text):
                continue
            rows.append({
                "file_id": file_id,
                "filename": filename,
                "score": score,
                "text": text,
            })
    return rows


def _capture_response_file_search_results_v69012(response):
    """Accumulate exact workspace file_search evidence for the current AI turn."""
    if is_graphic_workspace(assistant):
        return
    incoming = _response_file_search_results_v69012(response)
    if not incoming:
        return
    existing = list(st.session_state.get("_workspace_file_search_results_v69040") or [])
    seen = {
        (str(row.get("file_id") or ""), str(row.get("text") or ""))
        for row in existing if isinstance(row, dict)
    }
    for row in incoming:
        key = (str(row.get("file_id") or ""), str(row.get("text") or ""))
        if key in seen:
            continue
        seen.add(key)
        existing.append(row)
    existing.sort(key=lambda row: float((row or {}).get("score") or 0.0), reverse=True)
    st.session_state["_workspace_file_search_results_v69040"] = existing[:24]
    if str(assistant or "") == "🔧 Technical Support":
        st.session_state["_technical_file_search_results_v69012"] = existing[:24]


def _response_incomplete_reason(response):
    """Return the normalized reason for an incomplete Responses API result."""
    details = getattr(response, "incomplete_details", None)
    if details is None:
        return ""

    if isinstance(details, dict):
        reason = details.get("reason")
    else:
        reason = getattr(details, "reason", "")

    return str(reason or "").strip().lower()


def _response_error_message(response, default_message):
    """Extract a readable Responses API failure without exposing request data."""
    error = getattr(response, "error", None)
    if isinstance(error, dict):
        message = error.get("message") or error.get("code")
    else:
        message = (
            getattr(error, "message", "")
            or getattr(error, "code", "")
        )
    return str(message or default_message)


def _continuation_request(previous_response, original_request):
    """
    Continue an output-limited response without resending the uploaded document.

    The Responses API retains the prior response through previous_response_id.
    Instructions are supplied again because they are not automatically inherited
    when previous_response_id is used.
    """
    previous_response_id = str(
        getattr(previous_response, "id", "") or ""
    ).strip()
    if not previous_response_id:
        return None

    return {
        "model": original_request["model"],
        "instructions": original_request.get("instructions"),
        "previous_response_id": previous_response_id,
        "input": [{
            "role": "user",
            "content": [{
                "type": "input_text",
                "text": (
                    "Continue exactly where the previous response stopped. "
                    "Do not repeat earlier sections. Preserve the same headings, "
                    "format, factual constraints, and source discipline. Complete "
                    "the remaining requested document review or extraction."
                ),
            }],
        }],
        "max_output_tokens": MAX_AI_OUTPUT_TOKENS,
    }


class _StreamingNotSupportedError(RuntimeError):
    """Raised only when the installed OpenAI SDK rejects stream=True."""


def _is_openai_bad_request(error):
    """Return True for a Responses API HTTP 400 without importing SDK internals."""
    name = type(error).__name__.casefold()
    status_code = getattr(error, "status_code", None)
    response = getattr(error, "response", None)
    response_status = getattr(response, "status_code", None)
    return (
        "badrequest" in name
        or status_code == 400
        or response_status == 400
    )


def _request_without_file_search(request):
    """Return a defensive retry request with only file_search removed."""
    retry_request = dict(request or {})
    tools = [
        dict(tool) if isinstance(tool, dict) else tool
        for tool in (retry_request.get("tools") or [])
        if not (isinstance(tool, dict) and tool.get("type") == "file_search")
    ]
    if tools:
        retry_request["tools"] = tools
    else:
        retry_request.pop("tools", None)
    # v69012: an include path for file_search results is invalid once the tool is
    # removed. Strip only that optional field while preserving any unrelated include.
    include_values = [
        value for value in (retry_request.get("include") or [])
        if str(value or "") != "file_search_call.results"
    ]
    if include_values:
        retry_request["include"] = include_values
    else:
        retry_request.pop("include", None)
    return retry_request


def _request_without_file_search_results_include_v69012(request):
    """Retry the same tool request without optional file_search result expansion."""
    retry_request = dict(request or {})
    include_values = [
        value for value in (retry_request.get("include") or [])
        if str(value or "") != "file_search_call.results"
    ]
    if include_values:
        retry_request["include"] = include_values
    else:
        retry_request.pop("include", None)
    return retry_request


def _website_request_vector_search_rows_v69047(request, max_results=12):
    """Use the SDK vector-search endpoint when optional result expansion is rejected."""
    request = dict(request or {})
    vector_store_ids = []
    for tool in request.get("tools") or []:
        if not isinstance(tool, dict) or tool.get("type") != "file_search":
            continue
        vector_store_ids.extend(tool.get("vector_store_ids") or [])
    vector_store_ids = _configured_vector_store_ids(*vector_store_ids)
    search_method = getattr(getattr(client, "vector_stores", None), "search", None)
    if not vector_store_ids or not callable(search_method):
        return []

    text_parts = []
    def collect(value):
        if isinstance(value, str):
            if value.strip():
                text_parts.append(value.strip())
        elif isinstance(value, dict):
            for key, child in value.items():
                if key in {"text", "content", "input"}:
                    collect(child)
        elif isinstance(value, (list, tuple)):
            for child in value:
                collect(child)
    collect(request.get("input"))
    query = re.sub(r"\s+", " ", " ".join(text_parts)).strip()[:6000]
    if not query:
        return []

    rows = []
    for vector_store_id in vector_store_ids[:3]:
        try:
            response = search_method(
                vector_store_id=vector_store_id,
                query=query,
                max_num_results=max(1, min(int(max_results or 12), 50)),
            )
        except Exception as error:
            diagnostic_log(
                "website_vector_search_fallback_failed_v69047",
                error_type=type(error).__name__,
                error=str(error)[:300],
            )
            continue
        data = response.get("data") if isinstance(response, dict) else getattr(response, "data", None)
        for result in list(data or []):
            def field(name, default=None):
                return result.get(name, default) if isinstance(result, dict) else getattr(result, name, default)
            content_parts = []
            for item in list(field("content", []) or []):
                item_type = item.get("type") if isinstance(item, dict) else getattr(item, "type", "")
                item_text = item.get("text") if isinstance(item, dict) else getattr(item, "text", "")
                if str(item_type or "") == "text" and str(item_text or "").strip():
                    content_parts.append(str(item_text))
            file_id = str(field("file_id", "") or "").strip()
            filename = str(field("filename", "") or "").strip()
            try:
                score = float(field("score", 0.0) or 0.0)
            except Exception:
                score = 0.0
            text_value = "\n".join(content_parts)
            if file_id or text_value:
                rows.append({
                    "file_id": file_id,
                    "filename": filename,
                    "score": score,
                    "text": text_value,
                })
    rows.sort(key=lambda row: float(row.get("score") or 0.0), reverse=True)
    output = []
    seen = set()
    for row in rows:
        key = (str(row.get("file_id") or ""), str(row.get("text") or ""))
        if key in seen:
            continue
        seen.add(key)
        output.append(row)
        if len(output) >= max(1, int(max_results or 12)):
            break
    diagnostic_log(
        "website_vector_search_fallback_complete_v69047",
        result_count=len(output),
        store_count=len(vector_store_ids),
    )
    return output


def _capture_file_search_rows_v69047(rows):
    """Capture direct-search rows using the same bounded per-session evidence state."""
    if is_graphic_workspace(assistant):
        return
    existing = list(st.session_state.get("_workspace_file_search_results_v69040") or [])
    seen = {
        (str(row.get("file_id") or ""), str(row.get("text") or ""))
        for row in existing if isinstance(row, dict)
    }
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        key = (str(row.get("file_id") or ""), str(row.get("text") or ""))
        if key in seen:
            continue
        seen.add(key)
        existing.append(dict(row))
    existing.sort(key=lambda row: float((row or {}).get("score") or 0.0), reverse=True)
    existing = existing[:24]
    st.session_state["_workspace_file_search_results_v69040"] = existing
    if str(assistant or "") == "🔧 Technical Support":
        st.session_state["_technical_file_search_results_v69012"] = existing


def _website_image_response_rows_with_retry_v69047(request, event_name):
    """Return image-search rows, falling back to direct vector search on include rejection."""
    try:
        response = client.responses.create(**dict(request or {}))
    except Exception as error:
        if (
            _is_openai_bad_request(error)
            and "file_search_call.results" in (dict(request or {}).get("include") or [])
        ):
            rows = _website_request_vector_search_rows_v69047(request)
            diagnostic_log(
                str(event_name or "website_image_search") + "_direct_retry_v69047",
                result_count=len(rows),
                error_type=type(error).__name__,
            )
            return rows
        raise
    return _response_file_search_results_v69012(response)


def _stream_one_ai_response(request):
    """
    Yield text for one Responses API call and return its final response object.

    The generator return value is captured with ``yield from`` by ask_ai_stream.
    A single safe retry is allowed when the API rejects a request containing
    file_search. This keeps normal Graphic Chat available even when a configured
    vector store or multi-tool combination is temporarily invalid.
    """
    active_request = dict(request or {})
    retried_without_file_search = False
    retried_without_file_search_results_include_v69012 = False

    while True:
        try:
            stream = client.responses.create(
                **active_request,
                stream=True,
            )
            break
        except TypeError as error:
            error_text = str(error or "").lower()
            if "stream" in error_text and (
                "unexpected keyword" in error_text
                or "unexpected argument" in error_text
                or "not supported" in error_text
            ):
                raise _StreamingNotSupportedError(str(error)) from error
            raise
        except Exception as error:
            has_file_search = any(
                isinstance(tool, dict) and tool.get("type") == "file_search"
                for tool in (active_request.get("tools") or [])
            )
            if _is_openai_bad_request(error) and has_file_search:
                if (
                    "file_search_call.results" in (active_request.get("include") or [])
                    and not retried_without_file_search_results_include_v69012
                ):
                    fallback_rows_v69047 = _website_request_vector_search_rows_v69047(
                        active_request
                    )
                    if fallback_rows_v69047:
                        _capture_file_search_rows_v69047(fallback_rows_v69047)
                    diagnostic_log(
                        "responses_bad_request_file_search_results_include_retry_v69012",
                        workspace=str(assistant),
                        error_type=type(error).__name__,
                        recovered_rows=len(fallback_rows_v69047),
                    )
                    active_request = _request_without_file_search_results_include_v69012(
                        active_request
                    )
                    retried_without_file_search_results_include_v69012 = True
                    continue
                if not retried_without_file_search:
                    diagnostic_log(
                        "responses_bad_request_file_search_retry",
                        workspace=str(assistant),
                        error_type=type(error).__name__,
                    )
                    active_request = _request_without_file_search(active_request)
                    retried_without_file_search = True
                    continue
            raise

    received_text = False
    final_response = None

    for event in stream:
        event_type = str(getattr(event, "type", "") or "")

        if event_type == "response.output_text.delta":
            delta = str(getattr(event, "delta", "") or "")
            if delta:
                received_text = True
                yield delta

        elif event_type == "response.refusal.delta":
            delta = str(getattr(event, "delta", "") or "")
            if delta:
                received_text = True
                yield delta

        elif event_type in {
            "response.completed",
            "response.incomplete",
            "response.failed",
        }:
            final_response = getattr(event, "response", None)

        elif event_type == "error":
            message = str(
                getattr(event, "message", "")
                or getattr(event, "error", "")
                or "OpenAI streaming request failed."
            )
            raise RuntimeError(message)

    if final_response is not None:
        _capture_response_file_search_results_v69012(final_response)
        final_text = str(
            getattr(final_response, "output_text", "") or ""
        )
        if not received_text and final_text:
            yield final_text
        return final_response

    # A streaming connection that ends without a completed/incomplete/failed
    # event is not a successful response. Raise so the caller preserves the
    # partial answer instead of silently treating the truncated stream as done.
    raise RuntimeError(
        "The OpenAI response stream ended before a final response event."
    )


def ask_ai_stream(
    prompt_text,
    uploaded_files,
    detected_live_request=None,
    detected_technical_tool=None,
    detected_workspace_tool=None,
    response_mode=None,
    use_file_search=True,
    live_data_override=_LIVE_DATA_UNSET,
    order_displayed_by_app=False,
):
    """
    Yield the complete Responses API answer.

    When OpenAI explicitly reports that a response is incomplete because it hit
    the output-token limit, continue from the prior response up to a bounded
    number of times. This preserves long Excel/catalogue extractions in the same
    visible chat message without creating an unlimited loop.
    """
    original_request = _build_ai_request(
        prompt_text,
        uploaded_files,
        detected_live_request=detected_live_request,
        detected_technical_tool=detected_technical_tool,
        detected_workspace_tool=detected_workspace_tool,
        response_mode=response_mode,
        use_file_search=use_file_search,
        live_data_override=live_data_override,
        order_displayed_by_app=order_displayed_by_app,
    )

    request = original_request

    try:
        for continuation_index in range(MAX_AI_AUTO_CONTINUATIONS + 1):
            final_response = yield from _stream_one_ai_response(request)

            if final_response is None:
                return

            status = str(
                getattr(final_response, "status", "") or ""
            ).strip().lower()

            if status == "failed":
                raise RuntimeError(
                    _response_error_message(
                        final_response,
                        "OpenAI response generation failed.",
                    )
                )

            if status != "incomplete":
                return

            incomplete_reason = _response_incomplete_reason(final_response)
            if incomplete_reason not in {
                "max_tokens",
                "max_output_tokens",
            }:
                raise RuntimeError(
                    "OpenAI returned an incomplete response"
                    + (
                        f" ({incomplete_reason})."
                        if incomplete_reason
                        else "."
                    )
                )

            if continuation_index >= MAX_AI_AUTO_CONTINUATIONS:
                yield (
                    "\n\n[The response reached the configured long-output "
                    "continuation limit. Ask “continue” to generate any "
                    "remaining material.]"
                )
                return

            request = _continuation_request(
                final_response,
                original_request,
            )
            if request is None:
                yield (
                    "\n\n[The response stopped at the output limit and could "
                    "not be continued automatically. Ask “continue” to resume.]"
                )
                return

        return

    except _StreamingNotSupportedError:
        # Compatibility with an older OpenAI SDK that does not support stream.
        pass

    # Non-streaming compatibility fallback with the same bounded continuation.
    request = original_request
    for continuation_index in range(MAX_AI_AUTO_CONTINUATIONS + 1):
        response = client.responses.create(**request)
        _capture_response_file_search_results_v69012(response)
        fallback_text = str(getattr(response, "output_text", "") or "")
        if fallback_text:
            yield fallback_text

        status = str(getattr(response, "status", "") or "").strip().lower()
        if status == "failed":
            raise RuntimeError(
                _response_error_message(
                    response,
                    "OpenAI response generation failed.",
                )
            )

        if status != "incomplete":
            return

        incomplete_reason = _response_incomplete_reason(response)
        if incomplete_reason not in {"max_tokens", "max_output_tokens"}:
            raise RuntimeError(
                "OpenAI returned an incomplete response"
                + (
                    f" ({incomplete_reason})."
                    if incomplete_reason
                    else "."
                )
            )

        if continuation_index >= MAX_AI_AUTO_CONTINUATIONS:
            yield (
                "\n\n[The response reached the configured long-output "
                "continuation limit. Ask “continue” to generate any "
                "remaining material.]"
            )
            return

        request = _continuation_request(response, original_request)
        if request is None:
            yield (
                "\n\n[The response stopped at the output limit and could not "
                "be continued automatically. Ask “continue” to resume.]"
            )
            return





def is_admin_image_file(uploaded_file):
    mime_type = str(getattr(uploaded_file, "type", "") or "").lower()
    suffix = Path(str(getattr(uploaded_file, "name", "") or "")).suffix.lower()
    return mime_type.startswith("image/") or suffix in {".jpg", ".jpeg", ".png"}


@st.cache_data(ttl=86400, max_entries=128, show_spinner=False)
def _extract_admin_image_knowledge_cached(
    image_url,
    original_name,
    database_label,
    extra_context,
):
    instructions = (
        "Extract accurate reusable AutoTecPro knowledge from the image. "
        "Return clean plain text only. Never invent compatibility, product, "
        "vehicle, pricing, or technical details."
    )
    prompt_text = (
        f"Original filename: {original_name}\n"
        f"Selected database: {database_label}\n"
    )
    if extra_context:
        prompt_text += f"Admin context: {extra_context}\n"
    prompt_text += "\nExtract this image into reusable AutoTecPro knowledge."

    response = client.responses.create(
        model="gpt-5.5",
        instructions=instructions,
        input=[{
            "role": "user",
            "content": [
                {"type": "input_text", "text": prompt_text},
                {"type": "input_image", "image_url": image_url},
            ],
        }],
    )
    return clean_visible_chat_text(response.output_text)


def convert_admin_image_to_knowledge_file(uploaded_file, database_choice, admin_context=""):
    """
    Convert an uploaded JPG/PNG reference image into a searchable TXT document.

    OpenAI vector stores are optimized for text-based retrieval. This function
    uses vision once during admin upload to extract visible text, model numbers,
    vehicle/product relationships, and reusable rules. The generated TXT file is
    then uploaded to the selected vector store.

    Returns:
        (file_like_object, extracted_text)
    """
    image_url = normalized_image_data_url(uploaded_file)
    original_name = str(getattr(uploaded_file, "name", "reference_image"))
    database_label = str(database_choice or "Knowledge Base")
    extra_context = str(admin_context or "").strip()

    extraction_instructions = """
You are AutoTecPro's internal knowledge extraction specialist.

Analyze the uploaded reference image carefully and convert it into accurate,
searchable internal knowledge.

Extract only information that is actually visible or strongly supported by the
image. Do not invent missing vehicle years, part numbers, prices, compatibility,
or technical specifications.

Prioritize:
- Document/reference title
- Vehicle make, model, generation, and year range
- Factory radio/SYNC/Uconnect/RPO system
- Screen size and climate-control type
- KVN/factory code/model number
- AutoTecPro part number, SKU, product name, and screen size
- Compatibility rules and visual identification rules
- Troubleshooting steps, labels, warnings, and notes
- Any visible table, comparison, legend, or mapping

Write clean plain text with clear headings and bullet points.
Include the original filename and selected database.
If text is unclear, mark it as uncertain instead of guessing.
Do not output HTML, markdown code fences, or JSON.
"""

    prompt_text = (
        f"Original filename: {original_name}\n"
        f"Selected database: {database_label}\n"
    )
    if extra_context:
        prompt_text += f"Admin context: {extra_context}\n"
    prompt_text += "\nExtract this image into reusable AutoTecPro knowledge."

    extracted_text = _extract_admin_image_knowledge_cached(
        image_url,
        original_name,
        database_label,
        extra_context,
    )
    if not extracted_text:
        raise ValueError("The image could not be converted into searchable knowledge.")

    final_text = (
        f"AutoTecPro Image Knowledge Record\n"
        f"Original file: {original_name}\n"
        f"Database: {database_label}\n"
        f"Created at: {datetime.now(timezone.utc).isoformat()}\n\n"
        f"{extracted_text}\n"
    )

    output = io.BytesIO(final_text.encode("utf-8"))
    safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(original_name).stem).strip("_")
    output.name = f"{safe_stem or 'image'}_knowledge.txt"
    output.seek(0)

    return output, final_text




# ============================================================
# Intelligent Excel / CSV Knowledge Extraction
# ============================================================

TABULAR_KNOWLEDGE_EXTENSIONS = {".xlsx", ".xlsm", ".csv"}


def is_tabular_knowledge_file(uploaded_file):
    """Return True for spreadsheet formats supported by the structured importer."""
    extension = Path(str(getattr(uploaded_file, "name", ""))).suffix.lower()
    return extension in TABULAR_KNOWLEDGE_EXTENSIONS


def _clean_tabular_cell(value):
    """Convert one spreadsheet value to stable searchable text."""
    if value is None:
        return ""
    if isinstance(value, bool):
        return "Yes" if value else "No"
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    cleaned = html.unescape(str(value))
    cleaned = cleaned.replace("\u00a0", " ")
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return cleaned


def _canonical_tabular_header(header, column_index):
    """Map common workbook headings to stable field names without losing labels."""
    original = _clean_tabular_cell(header)
    normalized = re.sub(r"[^a-z0-9]+", " ", original.casefold()).strip()

    if normalized == "vehicle brand":
        return "Vehicle Brand"
    if normalized == "original system climate configuration":
        return "Original System / Climate Configuration"

    rules = [
        (("kvn part", "part number", "part no", "model number", "model no"), "Model / Part Number"),
        (("autotec part", "item number", "item no", "item #", "sku"), "AutoTec Item Number"),
        (("retain original system", "original system retained", "retain factory system", "compatibility original system"), "Original System Retained"),
        (("original system", "factory system", "oem system", "sync version"), "Original System Type / Retention"),
        (("original amplifier", "factory amplifier", "oem amplifier"), "Original Amplifier Retained"),
        (("original camera", "factory camera", "oem camera"), "Original Camera Retained"),
        (("rear ent", "rear entertainment"), "Original Rear Entertainment Retained"),
        (("rca output",), "RCA Output"),
        (("xm", "satellite radio"), "XM Retained"),
        (("screen", "display size"), "Screen Size"),
        (("model", "vehicle model", "vehicle"), "Vehicle / Model"),
        (("year", "years"), "Vehicle Year / Range"),
        (("brand", "make", "manufacturer"), "Vehicle Brand"),
        (("description", "product description"), "Description"),
        (("factory code",), "Factory Code"),
        (("price cad", "cad price"), "Price CAD"),
        (("price usd", "usd price"), "Price USD"),
        (("installation video",), "Installation Video Link"),
        (("youtube", "demo link"), "Demo Link"),
        (("website", "product page"), "Website Link"),
        (("camera type",), "Camera Type"),
        (("camera",), "Camera"),
        (("note", "notes"), "Notes"),
    ]

    for aliases, canonical in rules:
        if any(alias in normalized for alias in aliases):
            return canonical

    return original or f"Column {column_index}"


def _tabular_header_score(values):
    """Score a possible header row using density and AutoTecPro table vocabulary."""
    cleaned = [_clean_tabular_cell(value) for value in values]
    nonempty = [value for value in cleaned if value]
    if len(nonempty) < 2:
        return -1

    vocabulary = (
        "model", "screen", "part", "item", "description", "compatibility",
        "original", "camera", "amplifier", "xm", "rca", "price", "factory",
        "year", "vehicle", "brand", "note", "link", "system", "retain",
    )
    hits = sum(
        1 for value in nonempty
        if any(word in value.casefold() for word in vocabulary)
    )
    text_ratio = sum(not re.fullmatch(r"[-+]?\d+(?:\.\d+)?", value) for value in nonempty)
    return (hits * 5) + (len(nonempty) * 2) + text_ratio


def _detect_tabular_header_row(rows, max_scan=30):
    """Locate the most likely header row near the top of a worksheet."""
    candidates = []
    for index, row in enumerate(rows[:max_scan], start=1):
        candidates.append((_tabular_header_score(row), index))
    candidates.sort(reverse=True)
    return candidates[0][1] if candidates and candidates[0][0] >= 6 else 1


def _normalize_compatibility_value(header, value):
    """Translate compatibility symbols only inside feature/retention columns."""
    raw = _clean_tabular_cell(value)
    lowered_header = str(header or "").casefold()
    is_feature = any(
        token in lowered_header
        for token in (
            "retain", "compatibility", "original system", "amplifier",
            "camera", "rear entertainment", "xm", "rca output", "supported",
        )
    )
    if not is_feature or not raw:
        return raw

    compact = raw.casefold().strip()
    if compact in {"•", "●", "✓", "✔", "yes", "y", "true", "supported", "retain", "retained"}:
        return "Yes / Supported / Retained"
    if compact in {"x", "✕", "✖", "no", "n", "false", "not supported", "not retained"}:
        return "No / Not Supported / Not Retained"
    if compact in {"-", "—", "n/a", "na"}:
        return "Not Applicable / Not Specified"
    return raw


def _is_financial_tabular_header(header):
    normalized = str(header or "").casefold()
    return any(
        term in normalized
        for term in (
            "price", "cost", "subtotal", "total", "tax", "fee", "discount",
            "coupon", "payment", "currency", "profit", "margin", "wholesale",
        )
    )


def _is_inherited_context_header(header):
    """Identify identity columns where blank cells conventionally mean same as above."""
    normalized = str(header or "").casefold()
    return any(
        term in normalized
        for term in (
            "brand", "vehicle", "model", "year", "category", "make",
            "manufacturer", "product family",
        )
    ) and not any(
        term in normalized
        for term in ("part number", "item number", "price", "retained", "compatibility")
    )


def _combine_multilevel_headers(rows, header_row_number):
    """Combine a sparse parent heading row with the detected detailed header row."""
    header_values = list(rows[header_row_number - 1])
    parent_values = list(rows[header_row_number - 2]) if header_row_number > 1 else []
    combined = []
    parent_context = ""

    for index, value in enumerate(header_values, start=1):
        parent = _clean_tabular_cell(parent_values[index - 1]) if index <= len(parent_values) else ""
        if parent:
            parent_context = parent
        child = _clean_tabular_cell(value)

        # Human-formatted compatibility sheets often leave the Brand and
        # Configuration header cells blank. Infer only these high-confidence
        # positions so the row relationship remains explicit.
        if not child and index == 1 and len(header_values) >= 2:
            second_header = _clean_tabular_cell(header_values[1]).casefold()
            if "model" in second_header or "vehicle" in second_header:
                child = "Vehicle Brand"
        if not child and index == 4 and len(header_values) >= 5:
            left_header = _clean_tabular_cell(header_values[2]).casefold()
            right_header = _clean_tabular_cell(header_values[4]).casefold()
            if "screen" in left_header and ("part" in right_header or "model" in right_header):
                child = "Original System / Climate Configuration"

        # Titles such as "KVN Android 13 Part Number" should not prefix the first
        # identity column, while section labels such as Compatibility add useful context.
        useful_parent = parent_context if parent_context.casefold() in {"compatibility", "specification", "specifications", "features"} else ""
        display = " | ".join(part for part in (useful_parent, child) if part)
        combined.append(_canonical_tabular_header(display, index))
    return combined


def _make_unique_headers(headers):
    seen = {}
    unique = []
    for header in headers:
        base = str(header or "Column").strip() or "Column"
        seen[base] = seen.get(base, 0) + 1
        unique.append(base if seen[base] == 1 else f"{base} ({seen[base]})")
    return unique


def _structured_row_sentence(record):
    """Create one natural-language sentence that keeps every row relationship intact."""
    model = next((v for k, v in record.items() if "part number" in k.casefold()), "")
    vehicle = next((v for k, v in record.items() if "vehicle / model" in k.casefold()), "")
    brand = next((v for k, v in record.items() if "brand" in k.casefold()), "")
    retention = next((v for k, v in record.items() if k == "Original System Retained"), "")
    identity = " ".join(value for value in (brand, vehicle) if value).strip()
    parts = []
    if model:
        parts.append(f"Model or part number {model}")
    if identity:
        parts.append(f"applies to {identity}")
    if retention:
        parts.append(f"original system retained: {retention}")
    if parts:
        return "; ".join(parts) + "."
    return "This row is one complete product or compatibility configuration."


def _rows_to_structured_knowledge(rows, sheet_name, source_name, database_choice):
    """Convert worksheet rows into row-bound knowledge records."""
    if not rows:
        return [], {"header_row": 0, "records": 0}

    header_row_number = _detect_tabular_header_row(rows)
    headers = _make_unique_headers(_combine_multilevel_headers(rows, header_row_number))
    financial_allowed = database_choice != "Technical Support Database"
    inherited = {}
    records = []

    for source_row_number, row in enumerate(rows[header_row_number:], start=header_row_number + 1):
        values = list(row) + [None] * max(0, len(headers) - len(row))
        raw_nonempty = sum(bool(_clean_tabular_cell(value)) for value in values[:len(headers)])
        if raw_nonempty == 0:
            # Do not clear inherited identity context across visual separator rows.
            continue

        record = {}
        for column_index, header in enumerate(headers):
            value = _clean_tabular_cell(values[column_index] if column_index < len(values) else "")
            if _is_inherited_context_header(header):
                if value:
                    inherited[header] = value
                elif inherited.get(header):
                    value = inherited[header]

            value = _normalize_compatibility_value(header, value)
            if not value:
                continue
            if not financial_allowed and _is_financial_tabular_header(header):
                continue
            record[header] = value

        # Skip decorative or title-only rows that do not contain enough relational data.
        if len(record) < 2:
            continue

        records.append({
            "source_row": source_row_number,
            "fields": record,
        })

    return records, {"header_row": header_row_number, "records": len(records)}


def _read_excel_rows(file_bytes, extension):
    if load_workbook is None:
        raise RuntimeError(
            "Excel structured learning requires openpyxl. Add openpyxl to requirements.txt."
        )
    workbook = load_workbook(
        io.BytesIO(file_bytes),
        data_only=True,
        read_only=True,
        keep_links=False,
        keep_vba=(extension == ".xlsm"),
    )
    result = []
    try:
        for worksheet in workbook.worksheets:
            # Hidden helper/status sheets are usually validation sources, not knowledge tables.
            if str(getattr(worksheet, "sheet_state", "visible")) != "visible":
                continue
            rows = [tuple(row) for row in worksheet.iter_rows(values_only=True)]
            result.append((worksheet.title, rows))
    finally:
        workbook.close()
    return result


def _read_csv_rows(file_bytes):
    decoded = bytes(file_bytes or b"").decode("utf-8-sig", errors="replace")
    sample = decoded[:8192]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
    except Exception:
        dialect = csv.excel
    return [("CSV", [tuple(row) for row in csv.reader(io.StringIO(decoded), dialect)])]


def convert_tabular_file_to_knowledge_file(uploaded_file, database_choice):
    """Create a searchable text companion with exact row-to-column relationships."""
    original_name = Path(str(getattr(uploaded_file, "name", "spreadsheet.xlsx"))).name
    extension = Path(original_name).suffix.lower()
    file_bytes = uploaded_file.getvalue()
    if not file_bytes:
        raise ValueError("The spreadsheet is empty.")

    if extension in {".xlsx", ".xlsm"}:
        sheets = _read_excel_rows(file_bytes, extension)
    elif extension == ".csv":
        sheets = _read_csv_rows(file_bytes)
    else:
        raise ValueError(f"Structured learning does not support {extension or 'this file type'}.")

    output_lines = [
        "AUTOTECPRO INTELLIGENT STRUCTURED SPREADSHEET KNOWLEDGE",
        f"Original file: {original_name}",
        f"Destination: {database_choice}",
        f"Created at (UTC): {datetime.now(timezone.utc).isoformat()}",
        "Learning rule: Every RECORD below represents one complete source row. Do not mix a field from one record with another record.",
        "Blank identity cells were filled from the nearest preceding row only for brand, vehicle, year, category, or product-family context.",
        "Compatibility symbols were normalized only in feature/retention columns. Blank feature cells remain unspecified and must not be assumed Yes or No.",
        "Technical Support exports exclude financial and commercial fields.",
        "",
    ]

    total_records = 0
    sheet_summaries = []
    for sheet_name, rows in sheets:
        records, summary = _rows_to_structured_knowledge(
            rows,
            sheet_name,
            original_name,
            database_choice,
        )
        total_records += len(records)
        sheet_summaries.append((sheet_name, summary))
        if not records:
            continue
        output_lines.extend([
            f"===== SHEET: {sheet_name} =====",
            f"Detected header row: {summary['header_row']}",
            f"Structured records: {len(records)}",
            "",
        ])
        for record_index, item in enumerate(records, start=1):
            fields = item["fields"]
            output_lines.append(
                f"RECORD {record_index} | Source: {original_name} | Sheet: {sheet_name} | Excel row: {item['source_row']}"
            )
            output_lines.append(_structured_row_sentence(fields))
            for header, value in fields.items():
                output_lines.append(f"- {header}: {value}")
            output_lines.append("END RECORD")
            output_lines.append("")

    if total_records == 0:
        raise ValueError("No structured spreadsheet records could be detected.")

    output_lines.insert(4, f"Total structured records: {total_records}")
    final_text = "\n".join(output_lines).strip() + "\n"
    safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(original_name).stem).strip("._-")
    digest = hashlib.sha256(file_bytes).hexdigest()[:12]
    searchable_file = ManagedUploadedFile(
        final_text.encode("utf-8"),
        f"{safe_stem or 'spreadsheet'}__structured_rows_{digest}.txt",
        "text/plain",
    )
    return searchable_file, final_text, {
        "records": total_records,
        "sheets": sheet_summaries,
    }


def upload_to_vector_store(uploaded_file, vector_store_id):
    vector_store_id = str(vector_store_id or "").strip()
    if not vector_store_id.startswith("vs_"):
        raise RuntimeError(
            "The selected vector store is not configured. Add its vs_ ID to "
            "Streamlit Secrets and restart the app."
        )
    openai_file = client.files.create(file=uploaded_file, purpose="assistants")
    client.vector_stores.files.create(vector_store_id=vector_store_id, file_id=openai_file.id)
    try:
        vector_store_has_filename.clear()
    except Exception:
        pass
    try:
        _vector_store_file_catalog_v69040.clear()
    except Exception:
        pass
    return openai_file.id


