# AutoTecPro AI v69000 — Final Website Precision + Main-Content Hygiene
# Built directly on v68999. Graphic v68835 Reference / v68829 After Install authorities,
# the v68995 Graphic runtime layer, and Technical Support text→related-image rendering
# remain unchanged. This release is website-learning-only: it hardens AutoTec/site-brand
# rejection even when nearby article text is technical, removes header/sidebar/site chrome
# from learned text, preserves broad WordPress technical-image recall, and keeps every
# validated technical image visible before approval.
WEBSITE_FETCH_TIMEOUT_SECONDS = 25
WEBSITE_MAX_RESPONSE_BYTES = 5 * 1024 * 1024
WEBSITE_MAX_EXTRACTED_CHARS = 120000
WEBSITE_MAX_DISCOVERED_IMAGES = 200
WEBSITE_MAX_ANALYZED_IMAGES = 200
WEBSITE_MAX_IMAGE_BYTES = 8 * 1024 * 1024
WEBSITE_IMAGE_FETCH_TIMEOUT_SECONDS = 18
WEBSITE_AUTO_DISPLAY_MAX_IMAGES = 4
WEBSITE_LEARNING_RELEASE_V69000 = "v69000-final-website-precision"

# v69024: website-learning provenance authority. This deliberately invalidates
# older image-QA reuse when page-zone/product provenance was not part of approval.
WEBSITE_INGESTION_AUTHORITY_VERSION_V69024 = "v69025-source-zone-provenance-2"


class KnowledgePageHTMLParser(HTMLParser):
    """Extract readable page text plus high-recall website image candidates.

    v68996 keeps the existing readable-text behavior while expanding image discovery
    for WordPress/WPBakery/lazy-load pages. It records normal ``img`` sources,
    ``picture/source`` srcsets, full-size lightbox links, common WordPress data
    attributes, and inline/CSS background-image URLs. Candidate filtering remains a
    later step so discovery itself does not silently discard technical images.
    """

    SKIP_TAGS = {
        "script", "style", "noscript", "svg", "canvas", "iframe",
        "nav", "header", "footer", "aside", "button",
    }
    BLOCK_TAGS = {
        "article", "section", "main", "header", "div", "p", "br",
        "li", "ul", "ol", "table", "tr", "td", "th",
        "h1", "h2", "h3", "h4", "h5", "h6",
        "blockquote", "pre", "title",
    }
    IMAGE_DATA_ATTRIBUTES = (
        "data-src", "data-lazy-src", "data-original", "data-lazy",
        "data-large-file", "data-orig-file", "data-full", "data-full-src",
        "data-image", "data-image-url", "data-url", "data-bg",
        "data-background", "data-background-image", "data-thumb", "data-thumbnail",
    )
    SRCSET_ATTRIBUTES = ("data-srcset", "srcset")

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._skip_depth = 0
        self._parts = []
        self.title = ""
        self._inside_title = False
        self.images = []

        self._current_heading_level = ""
        self._current_heading_parts = []
        self._last_heading = ""
        self._recent_text_chunks = []
        # v69017 ingestion accuracy: retain ordered text blocks so every image can
        # be associated with both the instructions before it and the instructions
        # immediately after it. This is ingestion-only metadata and does not change
        # the Technical answer/output pipeline.
        self._text_sequence_v69017 = []
        self._anchor_stack = []
        self._picture_depth = 0
        self._picture_sources = []
        self._picture_had_img = False
        self._image_group_counter = 0

    @staticmethod
    def _srcset_urls(value):
        rows = []
        for order, part in enumerate(str(value or "").split(",")):
            item = part.strip()
            if not item:
                continue
            pieces = item.split()
            url = pieces[0].strip(" \t\r\n\"'") if pieces else ""
            descriptor = pieces[1] if len(pieces) > 1 else ""
            rank = 0.0
            match = re.fullmatch(r"([0-9.]+)(w|x)", descriptor, flags=re.I)
            if match:
                try:
                    rank = float(match.group(1)) * (100000.0 if match.group(2).lower() == "x" else 1.0)
                except Exception:
                    rank = 0.0
            if url:
                rows.append((rank, -order, url))
        rows.sort(reverse=True)
        return [row[2] for row in rows]

    @staticmethod
    def _style_urls(value):
        return [
            html.unescape(str(match[1] or "").strip(" \t\r\n\"'"))
            for match in re.findall(
                r"url\(\s*(['\"]?)(.*?)\1\s*\)",
                str(value or ""),
                flags=re.I | re.S,
            )
            if str(match[1] or "").strip()
        ]

    @staticmethod
    def _looks_image_like(value):
        text = html.unescape(str(value or "").strip())
        if not text or text.startswith(("data:", "blob:", "javascript:")):
            return False
        return bool(
            re.search(r"\.(?:jpe?g|png|webp|avif)(?:$|[?#])", text, flags=re.I)
            or re.search(r"/(?:uploads|images?|media|gallery|photos?)/", text, flags=re.I)
        )

    def _context(self):
        nearby_text = " ".join(
            chunk for chunk in self._recent_text_chunks[-8:] if chunk
        )
        nearby_text = re.sub(r"\s+", " ", nearby_text).strip()
        return {
            "nearest_heading": self._last_heading,
            "heading_level": self._current_heading_level,
            "nearby_text": nearby_text[-1800:],
        }

    def _append_image(self, src, *, alt="", title="", source_kind="html", full_size=False, origin_group=""):
        src = html.unescape(str(src or "").strip())
        if not src:
            return
        record = {
            "src": src,
            "alt": re.sub(r"\s+", " ", str(alt or "")).strip(),
            "title": re.sub(r"\s+", " ", str(title or "")).strip(),
            "source_kind": str(source_kind or "html"),
            "full_size_candidate": bool(full_size),
            "origin_group": str(origin_group or ""),
            "text_sequence_index_v69017": len(self._text_sequence_v69017),
            **self._context(),
        }
        self.images.append(record)

    def handle_starttag(self, tag, attrs):
        tag = str(tag or "").lower()
        attributes = dict(attrs or [])

        # Collect image-bearing attributes before skipping textual content. This lets
        # technical background/lazy assets survive even on wrapper elements.
        style_value = str(attributes.get("style") or "")
        for bg_url in self._style_urls(style_value):
            self._append_image(bg_url, source_kind="inline-background")

        if tag not in {"img", "source"}:
            for name in self.IMAGE_DATA_ATTRIBUTES:
                value = str(attributes.get(name) or "").strip()
                if value and self._looks_image_like(value):
                    self._append_image(value, source_kind=name)

        if tag == "picture":
            self._picture_depth += 1
            if self._picture_depth == 1:
                self._picture_sources = []
                self._picture_had_img = False

        if tag == "a":
            href = str(attributes.get("href") or "").strip()
            self._anchor_stack.append(href)

        if tag == "source" and self._picture_depth:
            for attr_name in self.SRCSET_ATTRIBUTES:
                for src in self._srcset_urls(attributes.get(attr_name)):
                    self._picture_sources.append(src)

        if tag in self.SKIP_TAGS:
            self._skip_depth += 1
            return

        if self._skip_depth:
            return

        if tag == "title":
            self._inside_title = True

        if tag in {"h1", "h2", "h3", "h4", "h5", "h6"}:
            self._current_heading_level = tag
            self._current_heading_parts = []

        if tag in self.BLOCK_TAGS:
            self._parts.append("\n")

        if tag == "img":
            self._image_group_counter += 1
            origin_group = f"img-{self._image_group_counter}"
            if self._picture_depth:
                self._picture_had_img = True
            alt_text = str(attributes.get("alt") or "").strip()
            title_text = str(attributes.get("title") or "").strip()

            urls = []
            # Prefer full-resolution WordPress attributes and largest srcsets, but
            # retain all distinct forms so later URL/SHA dedupe can choose safely.
            for name in (
                "data-orig-file", "data-large-file", "data-full", "data-full-src",
                "data-src", "data-lazy-src", "data-original", "data-lazy", "src",
            ):
                value = str(attributes.get(name) or "").strip()
                if value:
                    urls.append((value, name, name in {"data-orig-file", "data-large-file", "data-full", "data-full-src"}))
            for attr_name in self.SRCSET_ATTRIBUTES:
                srcset_urls = self._srcset_urls(attributes.get(attr_name))
                for src in srcset_urls:
                    urls.append((src, f"img-{attr_name}", True))
            for src in self._picture_sources:
                urls.append((src, "picture-source", True))

            anchor_href = self._anchor_stack[-1] if self._anchor_stack else ""
            if anchor_href and self._looks_image_like(anchor_href):
                urls.insert(0, (anchor_href, "linked-full-image", True))

            seen_local = set()
            for candidate_src, source_kind, full_size in urls:
                candidate_src = html.unescape(str(candidate_src or "").strip())
                if not candidate_src or candidate_src in seen_local:
                    continue
                seen_local.add(candidate_src)
                self._append_image(
                    candidate_src,
                    alt=alt_text,
                    title=title_text,
                    source_kind=source_kind,
                    full_size=full_size,
                    origin_group=origin_group,
                )

            if alt_text:
                self._parts.append(f"\nImage description: {alt_text}\n")

    def handle_endtag(self, tag):
        tag = str(tag or "").lower()

        if tag == "a" and self._anchor_stack:
            self._anchor_stack.pop()
        if tag == "picture":
            self._picture_depth = max(0, self._picture_depth - 1)
            if self._picture_depth == 0:
                if self._picture_sources and not self._picture_had_img:
                    self._append_image(
                        self._picture_sources[0],
                        source_kind="picture-source-only",
                        full_size=True,
                    )
                self._picture_sources = []
                self._picture_had_img = False

        if tag in self.SKIP_TAGS:
            if self._skip_depth:
                self._skip_depth -= 1
            return

        if self._skip_depth:
            return

        if tag == "title":
            self._inside_title = False

        if tag in {"h1", "h2", "h3", "h4", "h5", "h6"}:
            heading = re.sub(r"\s+", " ", " ".join(self._current_heading_parts)).strip()
            if heading:
                self._last_heading = heading
                self._recent_text_chunks.append(heading)
                self._recent_text_chunks = self._recent_text_chunks[-12:]
            self._current_heading_parts = []
            self._current_heading_level = ""

        if tag in self.BLOCK_TAGS:
            self._parts.append("\n")

    def handle_data(self, data):
        # Style/script text is excluded by SKIP_TAGS. CSS image URLs are recovered
        # separately from the raw HTML candidate scan, so stylesheet text never
        # contaminates searchable website knowledge.
        if self._skip_depth:
            return

        value = str(data or "").strip()
        if not value:
            return

        if self._inside_title and not self.title:
            self.title = value

        if self._current_heading_level:
            self._current_heading_parts.append(value)

        if not self._inside_title:
            self._recent_text_chunks.append(value)
            self._recent_text_chunks = self._recent_text_chunks[-12:]
            self._text_sequence_v69017.append(value)

        self._parts.append(value + " ")

    def finalize_image_contexts_v69017(self):
        """Attach section-local text before and after each discovered image.

        Installation pages frequently place the explanation after the photo. Older
        ingestion only retained preceding text, which could make a correct image look
        unrelated. Keep a bounded bidirectional context window instead.
        """
        sequence = [re.sub(r"\s+", " ", str(x or "")).strip() for x in self._text_sequence_v69017]
        for record in self.images:
            try:
                idx = max(0, min(len(sequence), int(record.get("text_sequence_index_v69017") or 0)))
            except Exception:
                idx = 0
            before = " ".join(x for x in sequence[max(0, idx - 8):idx] if x)
            after = " ".join(x for x in sequence[idx:min(len(sequence), idx + 8)] if x)
            before = re.sub(r"\s+", " ", before).strip()[-1800:]
            after = re.sub(r"\s+", " ", after).strip()[:1800]
            record["context_before_text_v69017"] = before
            record["context_after_text_v69017"] = after
            heading = re.sub(r"\s+", " ", str(record.get("nearest_heading") or "")).strip()
            combined = " ".join(x for x in (heading, before, after) if x)
            record["nearby_text"] = re.sub(r"\s+", " ", combined).strip()[:3600]
        return self.images

    def text(self):
        return "".join(self._parts)


# ============================================================
# v69024 — Source-Zone Website Knowledge Provenance Engine
# ============================================================

def _website_page_type_v69024(page_url, page_html=""):
    """Classify a learned webpage before image/text extraction."""
    parsed = urlparse(str(page_url or ""))
    path = str(parsed.path or "").casefold()
    if "/product/" in path:
        return "woocommerce_product"
    technical_tokens = (
        "installation-instruction", "installation_instruction", "technical-information",
        "technical-inforamtion", "technical_information", "installation", "instruction",
    )
    if any(token in path for token in technical_tokens):
        return "technical_article"
    html_value = str(page_html or "").casefold()
    if "woocommerce-product-gallery" in html_value and "product_title" in html_value:
        return "woocommerce_product"
    return "generic_article"


def _website_dom_attr_text_v69024(attrs):
    values = []
    for key, value in (attrs or []):
        key = str(key or "").casefold()
        if key in {"class", "id", "role", "itemprop", "data-block-name", "aria-label"} or key.startswith("data-"):
            values.append(str(value or ""))
    value = " ".join(values).casefold().replace("_", " ").replace("-", " ")
    return re.sub(r"\s+", " ", value).strip()


def _website_source_zone_is_excluded_v69024(zone):
    return str(zone or "").strip().casefold() in {
        "related_products", "upsells", "cross_sells", "recommendations",
        "review_media", "previous_next_product", "site_chrome",
    }


def _website_dom_zone_v69024(tag, attrs, page_type, parent_zone=""):
    """Return deterministic source-zone provenance for one DOM node."""
    tag = str(tag or "").casefold()
    page_type = str(page_type or "generic_article").strip().casefold()
    parent_zone = str(parent_zone or "").strip() or (
        "product_content" if page_type == "woocommerce_product" else "article_body"
    )
    attr_text = _website_dom_attr_text_v69024(attrs)
    haystack = f" {attr_text} "

    # v69048: WooCommerce stores authoritative product choices and explanatory
    # labels inside ``form.cart`` / ``variations_form``.  Treat only those forms as
    # product content; search, login, review, currency and checkout forms remain
    # site chrome.  ``form`` is intentionally no longer a base SKIP_TAG because the
    # zone authority below already quarantines every non-product form before text is
    # passed to the readable-content parser.
    if page_type == "woocommerce_product" and tag == "form":
        if re.search(r"\bvariations?\s+form\b|\bcart\b", haystack):
            return "product_summary"
        return "site_chrome"

    # v69025: classify site-chrome by tag before the legacy base parser can
    # inspect wrapper style/data attributes.  This closes header/footer/nav/aside
    # background-image leakage while preserving ordinary article/product content.
    if tag in {"header", "footer", "nav", "aside", "form", "button"}:
        return "site_chrome"

    # Non-authoritative WooCommerce/WordPress zones are excluded before text/image QA.
    if re.search(r"\brelated\s+(?:products?|posts?|articles?)\b|\b(?:products?|posts?|articles?)\s+related\b", haystack):
        return "related_products"
    if re.search(r"\bupsells?\b|\bup\s+sells?\b", haystack):
        return "upsells"
    if re.search(r"\bcross\s+sells?\b|\bcrosssells?\b", haystack):
        return "cross_sells"
    if re.search(r"\brecommend(?:ed|ations?)\b|\brecently\s+viewed\b|\byou\s+may\s+also\s+like\b", haystack):
        return "recommendations"
    if re.search(r"\bwoocommerce\s+reviews\b|\bcustomer\s+reviews\b|\breview\s+media\b", haystack):
        return "review_media"
    if re.search(r"\bpost\s+navigation\b|\bprevious\s+product\b|\bnext\s+product\b", haystack):
        return "previous_next_product"
    # ``layout-sidebar-none`` is the current-product root in the AutoTecPro theme,
    # not a sidebar.  The old broad ``\bsidebar\b`` match classified that entire
    # wrapper as site chrome, producing the observed 77-word title/breadcrumb-only
    # extraction while image discovery continued independently.
    if re.search(
        r"\bsite\s+(?:header|footer|branding|navigation)\b|"
        r"\bsidebar\b(?!\s+(?:none|false|disabled|off)\b)|"
        r"\bmega\s+menu\b",
        haystack,
    ):
        return "site_chrome"

    if page_type == "woocommerce_product":
        if re.search(r"\bwoocommerce\s+product\s+gallery\b|\bproduct\s+gallery\b|\bproduct\s+images?\b", haystack):
            return "product_gallery"
        if re.search(r"\bentry\s+summary\b|\bproduct\s+summary\b|\bproduct\s+meta\b|\bshort\s+description\b", haystack):
            return "product_summary"
        if re.search(r"\bwoocommerce\s+tabs\b|\bproduct\s+description\b|\btabs?\s+panel\b|\bdescription\s+tab\b", haystack):
            return "product_description"
        if re.search(r"\btechnical\b|\binstallation\b|\binstruction\b|\bspecification\b|\bfeatures?\b", haystack):
            return "product_technical_content"
        return parent_zone if parent_zone not in {"root", "article_body"} else "product_content"

    if page_type == "technical_article":
        if re.search(r"\bentry\s+content\b|\bpost\s+content\b|\barticle\s+content\b|\bmain\s+content\b|\bwpb\s+content\s+wrapper\b", haystack):
            return "technical_section"
        return parent_zone if parent_zone != "root" else "article_body"

    return parent_zone if parent_zone != "root" else "article_body"


class KnowledgePageHTMLParserV69024(KnowledgePageHTMLParser):
    """Zone-aware parser: excluded page areas never enter learned text or image candidates."""

    _VOID_TAGS_V69024 = {
        "area", "base", "br", "col", "embed", "hr", "img", "input", "link",
        "meta", "param", "source", "track", "wbr",
    }

    def __init__(self, page_url="", page_type=""):
        super().__init__()
        self.page_url_v69024 = str(page_url or "")
        self.page_type_v69024 = str(page_type or "").strip() or _website_page_type_v69024(page_url)
        base_zone = "product_content" if self.page_type_v69024 == "woocommerce_product" else "article_body"
        self._zone_stack_v69024 = [{"tag": "__root__", "zone": base_zone, "excluded": False}]
        self._void_zone_v69024 = ""
        self.excluded_zone_nodes_v69024 = 0
        self.excluded_image_nodes_v69024 = 0

    def _zone_state_v69024(self):
        return self._zone_stack_v69024[-1] if self._zone_stack_v69024 else {"zone": "article_body", "excluded": False}

    def _context(self):
        value = super()._context()
        state = self._zone_state_v69024()
        value["source_zone_v69024"] = self._void_zone_v69024 or str(state.get("zone") or "")
        value["page_type_v69024"] = self.page_type_v69024
        value["ingestion_authority_version_v69024"] = WEBSITE_INGESTION_AUTHORITY_VERSION_V69024
        return value

    def handle_starttag(self, tag, attrs):
        tag = str(tag or "").casefold()
        parent = self._zone_state_v69024()
        zone = _website_dom_zone_v69024(tag, attrs, self.page_type_v69024, parent.get("zone"))
        excluded = bool(parent.get("excluded")) or _website_source_zone_is_excluded_v69024(zone)
        is_void = tag in self._VOID_TAGS_V69024
        if not is_void:
            self._zone_stack_v69024.append({"tag": tag, "zone": zone, "excluded": excluded})
        if excluded:
            if not bool(parent.get("excluded")):
                self.excluded_zone_nodes_v69024 += 1
            if tag in {"img", "source"}:
                self.excluded_image_nodes_v69024 += 1
            return
        previous_void = self._void_zone_v69024
        if is_void:
            self._void_zone_v69024 = zone
        try:
            super().handle_starttag(tag, attrs)
        finally:
            self._void_zone_v69024 = previous_void

    def handle_endtag(self, tag):
        tag = str(tag or "").casefold()
        state = self._zone_state_v69024()
        # Theme-independent fallback: some WooCommerce themes omit useful class/id
        # tokens but still use a standard section heading. Once such a heading closes,
        # quarantine its parent container before any product-card images are parsed.
        if tag in {"h1", "h2", "h3", "h4", "h5", "h6"} and not bool(state.get("excluded")):
            heading_v69024 = re.sub(r"\s+", " ", " ".join(getattr(self, "_current_heading_parts", []) or [])).strip().casefold()
            heading_zone_v69024 = ""
            if re.fullmatch(r"related\s+(?:products?|posts?|articles?)", heading_v69024):
                heading_zone_v69024 = "related_products"
            elif re.fullmatch(r"(?:you may also like|recommended products?|recommendations?)", heading_v69024):
                heading_zone_v69024 = "recommendations"
            elif re.fullmatch(r"(?:upsells?|cross[- ]?sells?)", heading_v69024):
                heading_zone_v69024 = "upsells" if "up" in heading_v69024 else "cross_sells"
            if heading_zone_v69024 and len(self._zone_stack_v69024) >= 2:
                parent_v69024 = self._zone_stack_v69024[-2]
                if not bool(parent_v69024.get("excluded")):
                    parent_v69024["zone"] = heading_zone_v69024
                    parent_v69024["excluded"] = True
                    self.excluded_zone_nodes_v69024 += 1
        if not bool(state.get("excluded")):
            super().handle_endtag(tag)
        # HTMLParser may emit an end callback for self-closing/void tags. Only pop
        # the semantic container when the closing tag matches the stack top.
        if len(self._zone_stack_v69024) > 1 and str(state.get("tag") or "") == tag:
            self._zone_stack_v69024.pop()

    def handle_data(self, data):
        if bool(self._zone_state_v69024().get("excluded")):
            return
        super().handle_data(data)


# All later learning and legacy-parser call sites bind to the provenance-aware parser.
KnowledgePageHTMLParser = KnowledgePageHTMLParserV69024

def normalize_website_url(raw_url):
    """Validate and normalize one public HTTP(S) webpage URL."""
    value = str(raw_url or "").strip()
    if not value:
        raise ValueError("Please enter a website URL.")

    if "://" not in value:
        value = "https://" + value

    parsed = urlparse(value)
    if parsed.scheme.lower() not in {"http", "https"}:
        raise ValueError("Only HTTP and HTTPS website links are supported.")

    if not parsed.hostname:
        raise ValueError("The website URL is invalid.")

    if parsed.username or parsed.password:
        raise ValueError("Website URLs containing credentials are not allowed.")

    return parsed.geturl()



def canonical_website_url_identity(raw_url):
    """
    Return a stable identity used only to compare website URLs.

    Harmless presentation and redirect differences are ignored:
    - http versus https
    - optional www prefix
    - hostname capitalization
    - default ports 80 and 443
    - URL fragments
    - duplicate slashes and a trailing slash

    The actual hostname, non-default port, path, and query remain significant,
    so changing to a genuinely different page still requires extraction again.
    """
    normalized = normalize_website_url(raw_url)
    parsed = urlparse(normalized)

    hostname = str(parsed.hostname or "").strip().lower().rstrip(".")
    if hostname.startswith("www."):
        hostname = hostname[4:]

    try:
        hostname = hostname.encode("idna").decode("ascii")
    except Exception:
        pass

    port = parsed.port
    if port in {80, 443}:
        port = None

    host_identity = hostname
    if port is not None:
        host_identity = f"{hostname}:{port}"

    path = re.sub(r"/{2,}", "/", str(parsed.path or "/"))
    if path != "/":
        path = path.rstrip("/")
    if not path:
        path = "/"

    query = str(parsed.query or "").strip()

    identity = host_identity + path
    if query:
        identity += "?" + query

    return identity


def validate_public_website_host(url):
    """
    Block localhost, private networks, link-local ranges, and metadata services.

    This prevents the Admin URL field from being used to access internal
    services from the Streamlit server.
    """
    parsed = urlparse(url)
    hostname = str(parsed.hostname or "").strip().lower()

    if hostname in {"localhost", "localhost.localdomain"}:
        raise ValueError("Local or private website addresses are not allowed.")

    try:
        address_info = socket.getaddrinfo(
            hostname,
            parsed.port or (443 if parsed.scheme == "https" else 80),
            type=socket.SOCK_STREAM,
        )
    except socket.gaierror as error:
        raise ValueError(f"The website hostname could not be resolved: {error}")

    resolved_addresses = {
        item[4][0].split("%", 1)[0]
        for item in address_info
        if item and item[4]
    }

    if not resolved_addresses:
        raise ValueError("The website hostname did not resolve to an address.")

    for address in resolved_addresses:
        ip_value = ipaddress.ip_address(address)
        if (
            ip_value.is_private
            or ip_value.is_loopback
            or ip_value.is_link_local
            or ip_value.is_multicast
            or ip_value.is_reserved
            or ip_value.is_unspecified
        ):
            raise ValueError(
                "Local, private, reserved, or internal website addresses "
                "are not allowed."
            )


def clean_extracted_website_text(raw_text):
    """Normalize spacing and remove common repeated webpage noise."""
    text_value = str(raw_text or "").replace("\x00", " ")
    lines = []

    noise_exact = {
        "accept cookies", "reject cookies", "manage cookies",
        "cookie settings", "privacy choices", "skip to content",
        "back to top", "sign in", "log in", "subscribe",
        # v69000: recurring WordPress/site-chrome labels must never become
        # vehicle-specific Technical Support knowledge.
        "shop departments", "about us", "my account", "view cart",
        "shopping cart", "checkout", "customer service", "contact us",
        "privacy policy", "terms and conditions",
        "related products", "related product", "related posts", "related articles",
        "you may also like", "recommended products", "recommendations",
    }

    previous = None
    for raw_line in text_value.splitlines():
        line = re.sub(r"\s+", " ", raw_line).strip()
        if not line:
            if lines and lines[-1] != "":
                lines.append("")
            continue

        lower_line = line.casefold()
        if lower_line in noise_exact:
            continue

        # v69000: logo/banner alt text can otherwise leak into the reviewed
        # technical article as "Image description: AutoTecPro Navigation Systems".
        if lower_line.startswith("image description:"):
            image_desc = lower_line.split(":", 1)[1].strip()
            if (
                image_desc in {
                    "autotecpro navigation systems", "autotec navigation systems",
                    "autotecpro", "autotec", "www.autotecpro.com",
                }
                or ("autotecpro" in image_desc and any(
                    token in image_desc for token in ("logo", "navigation systems", "website", "brand")
                ))
            ):
                continue

        # Remove immediate repeated navigation/header lines.
        if line == previous:
            continue

        lines.append(line)
        previous = line

    cleaned = "\n".join(lines)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()

    if len(cleaned) > WEBSITE_MAX_EXTRACTED_CHARS:
        cleaned = cleaned[:WEBSITE_MAX_EXTRACTED_CHARS].rstrip()
        cleaned += "\n\n[Content truncated at the extraction safety limit.]"

    return cleaned



def _website_raw_html_image_candidates_v68996(page_html):
    """Recover image URLs that may not be attached to a normal ``img`` tag.

    This is intentionally bounded to recognizable image-bearing attributes, CSS
    ``url(...)`` values, and direct image links. It does not scrape arbitrary quoted
    strings from JavaScript, which would create excessive false positives.
    """
    value = str(page_html or "")
    records = []
    attr_names = (
        "data-src", "data-lazy-src", "data-original", "data-lazy",
        "data-large-file", "data-orig-file", "data-full", "data-full-src",
        "data-image", "data-image-url", "data-url", "data-bg",
        "data-background", "data-background-image", "href", "src", "poster", "content",
    )
    attr_pattern = "|".join(re.escape(x) for x in attr_names)
    for match in re.finditer(
        rf"\b({attr_pattern})\s*=\s*([\"'])(.*?)\2",
        value,
        flags=re.I | re.S,
    ):
        name = str(match.group(1) or "").lower()
        candidate = html.unescape(str(match.group(3) or "").strip())
        if not candidate or candidate.startswith(("data:", "blob:", "javascript:")):
            continue
        if not (
            re.search(r"\.(?:jpe?g|png|webp|avif)(?:$|[?#])", candidate, flags=re.I)
            or re.search(r"/(?:uploads|images?|media|gallery|photos?)/", candidate, flags=re.I)
        ):
            continue
        records.append({
            "src": candidate,
            "alt": "",
            "title": "",
            "nearest_heading": "",
            "heading_level": "",
            "nearby_text": "",
            "source_kind": f"raw-{name}",
            "full_size_candidate": name in {"data-large-file", "data-orig-file", "data-full", "data-full-src", "href"},
        })

    # JSON/JavaScript gallery payloads commonly embed direct raster URLs rather than
    # attaching them to an HTML image attribute. Recover only URL-shaped values with
    # a recognized raster extension to keep the candidate pool bounded.
    js_scan_value = value.replace("\\/", "/")
    for match in re.finditer(
        r"(?:(?:https?:)?//|/)[^\s\"'<>]+?\.(?:jpe?g|png|webp|avif)(?:\?[^\s\"'<>]*)?",
        js_scan_value,
        flags=re.I,
    ):
        candidate = html.unescape(str(match.group(0) or "").strip())
        records.append({
            "src": candidate,
            "alt": "",
            "title": "",
            "nearest_heading": "",
            "heading_level": "",
            "nearby_text": "",
            "source_kind": "raw-script-or-markup-image-url",
            "full_size_candidate": False,
        })

    # CSS background-image / url(...) support, including URLs inside <style> blocks.
    for match in re.finditer(r"url\(\s*(['\"]?)(.*?)\1\s*\)", value, flags=re.I | re.S):
        candidate = html.unescape(str(match.group(2) or "").strip())
        if not candidate or candidate.startswith(("data:", "blob:", "javascript:")):
            continue
        if re.search(r"\.(?:jpe?g|png|webp|avif)(?:$|[?#])", candidate, flags=re.I):
            records.append({
                "src": candidate,
                "alt": "",
                "title": "",
                "nearest_heading": "",
                "heading_level": "",
                "nearby_text": "",
                "source_kind": "css-background",
                "full_size_candidate": False,
            })
    return records



def _website_scoped_raw_html_image_candidates_v69024(page_html, page_url, page_type, parser_images):
    """Recover alternate raw URLs without introducing new assets from excluded zones.

    v69025 applies the same provenance rule to *all* parsed webpage types, including
    generic articles.  A raw/script/CSS URL may enrich an already-authoritative DOM
    asset, but it may not create a brand-new learned asset with no approved zone.
    """
    raw_records = _website_raw_html_image_candidates_v68996(page_html)

    authoritative = {}
    for item in parser_images or []:
        if not isinstance(item, dict):
            continue
        zone = str(item.get("source_zone_v69024") or "").strip()
        if _website_source_zone_is_excluded_v69024(zone):
            continue
        src = str(item.get("src") or "").strip()
        if not src:
            continue
        try:
            key = _website_asset_identity_v68999(urljoin(page_url, src))
        except Exception:
            continue
        if key and any(key):
            authoritative[key] = dict(item)

    output = []
    for item in raw_records:
        if not isinstance(item, dict):
            continue
        src = str(item.get("src") or "").strip()
        if not src:
            continue
        try:
            key = _website_asset_identity_v68999(urljoin(page_url, src))
        except Exception:
            continue
        context = authoritative.get(key)
        if not context:
            continue
        merged = dict(item)
        for field in (
            "alt", "title", "nearest_heading", "heading_level", "nearby_text",
            "context_before_text_v69017", "context_after_text_v69017", "origin_group",
            "source_zone_v69024", "page_type_v69024", "ingestion_authority_version_v69024",
        ):
            if not merged.get(field) and context.get(field):
                merged[field] = context.get(field)
        output.append(merged)
    return output




def _website_woocommerce_authoritative_raw_recovery_v69029(page_html, page_url, page_type):
    """Recover current-product raster assets when the normal DOM parser found none.

    This is a fail-closed WooCommerce-only safety net. It starts at the current
    product/gallery root and stops before Related Products / upsells / cross-sells /
    recommendations. It is used only when the normal provenance-aware path produced
    zero candidates, so it cannot broaden pages that already parse correctly.
    """
    if str(page_type or "").strip().casefold() != "woocommerce_product":
        return []
    value = str(page_html or "")
    if not value:
        return []
    lower = value.casefold()

    start_patterns = (
        r'<[^>]+\bid\s*=\s*["\']product-\d+',
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\bwoocommerce-product-gallery\b',
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\bproduct-gallery\b',
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\bsingle-product\b',
    )
    start = None
    # Prefer the actual product node/gallery over a body-level single-product class.
    for pattern in start_patterns:
        match = re.search(pattern, value, flags=re.I | re.S)
        if match:
            start = int(match.start())
            break
    if start is None:
        return []

    tail = value[start:]
    end_patterns = (
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\brelated(?:\s+products?)?\b',
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\bupsells?\b',
        r'<[^>]+\bclass\s*=\s*["\'][^"\']*\bcross[-_ ]?sells?\b',
        r'>\s*related\s+products?\s*<',
        r'>\s*you\s+may\s+also\s+like\s*<',
    )
    ends = []
    for pattern in end_patterns:
        match = re.search(pattern, tail, flags=re.I | re.S)
        if match and int(match.start()) > 0:
            ends.append(int(match.start()))
    end = min(ends) if ends else len(tail)
    # Keep the bounded current-product region only. Do not scan the page header or
    # anything after Related Products / recommendation sections.
    region = tail[:end]
    raw_records = _website_raw_html_image_candidates_v68996(region)
    output = []
    seen = set()
    for item in raw_records:
        if not isinstance(item, dict):
            continue
        src = str(item.get("src") or "").strip()
        if not src:
            continue
        try:
            absolute = normalize_website_url(urljoin(page_url, src))
            key = _website_asset_identity_v68999(absolute)
        except Exception:
            continue
        if key in seen:
            continue
        seen.add(key)
        record = dict(item)
        record["src"] = absolute
        record["source_kind"] = "authoritative-product-raw-v69029:" + str(record.get("source_kind") or "raw")
        record["source_zone_v69024"] = "product_content"
        record["page_type_v69024"] = "woocommerce_product"
        record["ingestion_authority_version_v69024"] = WEBSITE_INGESTION_AUTHORITY_VERSION_V69024
        output.append(record)
        if len(output) >= WEBSITE_MAX_DISCOVERED_IMAGES:
            break
    return output


def _website_asset_identity_v68999(raw_url):
    """Return a stable logical identity for one WordPress/CDN raster asset.

    Presentation variants are collapsed without changing the URL actually downloaded:
    WordPress ``-300x200``/``-scaled`` filenames, cache-busting query parameters, and
    common CDN resize parameters all map to one logical asset. Distinct source files keep
    distinct identities, so two genuinely different technical images are never merged.
    """
    try:
        normalized = normalize_website_url(raw_url)
    except Exception:
        return ("", "", "")
    parsed = urlparse(normalized)
    host = str(parsed.hostname or "").casefold().rstrip(".")
    path = re.sub(r"/{2,}", "/", str(parsed.path or ""))
    # WordPress responsive variants and generated derivatives.
    path = re.sub(
        r"-(?:\d{2,5}x\d{2,5}|scaled|rotated)(?=\.(?:jpe?g|png|webp|avif)$)",
        "",
        path,
        flags=re.I,
    )
    # Some optimizers chain a size and scaled marker.
    path = re.sub(
        r"-(?:\d{2,5}x\d{2,5})-(?:scaled|rotated)(?=\.(?:jpe?g|png|webp|avif)$)",
        "",
        path,
        flags=re.I,
    )
    query_pairs = []
    for pair in str(parsed.query or "").split("&"):
        if not pair:
            continue
        key = pair.split("=", 1)[0].strip().casefold()
        if key in {
            "w", "h", "width", "height", "resize", "fit", "crop", "quality", "q",
            "auto", "format", "fm", "dpr", "ssl", "ver", "v", "cache", "cb",
        }:
            continue
        query_pairs.append(pair)
    stable_query = "&".join(sorted(query_pairs))
    return host, path.casefold(), stable_query.casefold()


def _website_asset_basename_v68999(raw_url):
    try:
        parsed = urlparse(str(raw_url or ""))
        return html.unescape(Path(str(parsed.path or "")).name).casefold()
    except Exception:
        return ""


def _website_variant_resolution_rank_v68999(raw_url):
    """Prefer full/original WordPress variants, otherwise the largest srcset derivative."""
    name = _website_asset_basename_v68999(raw_url)
    match = re.search(r"-(\d{2,5})x(\d{2,5})(?=\.(?:jpe?g|png|webp|avif)$)", name, flags=re.I)
    if match:
        return int(match.group(1)) * int(match.group(2))
    # No explicit responsive suffix normally means original/full-size.
    return 10**12


def _website_image_candidate_urls(parser_images, page_url):
    """Resolve, score, filter, and de-duplicate useful webpage image candidates.

    v68996 favors recall for technical/installation pages while still suppressing
    obvious site chrome. Full-size/lightbox and WordPress original-file URLs win over
    thumbnails when multiple markup forms point to the same logical asset.
    """
    results = []
    seen = set()

    absolute_skip_tokens = (
        "favicon", "sprite", "avatar", "emoji", "payment", "paypal", "visa",
        "mastercard", "amex", "social", "facebook", "instagram", "twitter",
        "youtube", "tiktok", "tracker", "analytics", "gravatar", "woocommerce",
        "trustpilot", "klarna", "afterpay", "shop-pay", "apple-pay",
        "logo", "header-logo", "footer-logo", "site-logo",
    )
    explicit_brand_tokens = (
        "autotec-logo", "autotecpro-logo", "autotec_brand", "autotecpro_brand",
        "autotecpro.com", "www.autotecpro.com", "autotec-navigation-logo",
    )
    soft_skip_tokens = (
        "icon", "badge", "pixel", "placeholder", "loading", "spinner",
    )
    positive_tokens = (
        "install", "installation", "instruction", "camera", "reverse", "harness",
        "wiring", "connector", "cable", "protocol", "setting", "settings",
        "dip", "switch", "aux", "lvds", "usb", "factory", "radio",
        "screen", "module", "adapter", "canbus", "can bus", "diagram",
        "connection", "plug", "socket", "port", "rear entertainment", "amplifier",
        "amp wire", "microphone", "audio", "car model", "climate", "ac settings",
        "power supply", "pin", "pinout", "steering", "backup camera",
    )

    for order_index, raw in enumerate(parser_images or []):
        if not isinstance(raw, dict):
            continue

        src = str(raw.get("src") or "").strip()
        if not src or src.startswith(("data:", "blob:", "javascript:")):
            continue

        resolved = urljoin(page_url, html.unescape(src))
        try:
            normalized = normalize_website_url(resolved)
        except Exception:
            continue

        parsed = urlparse(normalized)
        # Initial de-duplication is exact-URL only. Responsive/full-size variants must
        # survive until the later logical-asset resolver can choose the best-quality one.
        identity = (
            str(parsed.scheme or "").lower(),
            str(parsed.netloc or "").lower(),
            re.sub(r"/{2,}", "/", str(parsed.path or "")),
            str(parsed.query or ""),
        )
        if identity in seen:
            continue
        seen.add(identity)

        alt = re.sub(r"\s+", " ", str(raw.get("alt") or "")).strip()
        title = re.sub(r"\s+", " ", str(raw.get("title") or "")).strip()
        nearest_heading = re.sub(r"\s+", " ", str(raw.get("nearest_heading") or "")).strip()
        nearby_text = re.sub(r"\s+", " ", str(raw.get("nearby_text") or "")).strip()
        context_before_v69017 = re.sub(r"\s+", " ", str(raw.get("context_before_text_v69017") or "")).strip()
        context_after_v69017 = re.sub(r"\s+", " ", str(raw.get("context_after_text_v69017") or "")).strip()
        source_kind = str(raw.get("source_kind") or "img").strip()
        full_size_candidate = bool(raw.get("full_size_candidate"))
        origin_group = str(raw.get("origin_group") or "").strip()
        source_zone_v69024 = str(raw.get("source_zone_v69024") or "").strip()
        page_type_v69024 = str(raw.get("page_type_v69024") or "").strip()
        if _website_source_zone_is_excluded_v69024(source_zone_v69024):
            continue

        asset_identity = " ".join(
            part for part in (str(parsed.path or ""), alt, title, source_kind) if part
        ).casefold()
        asset_basename = _website_asset_basename_v68999(normalized)
        contextual_haystack = " ".join(
            part for part in (asset_identity, nearest_heading, nearby_text) if part
        ).casefold()
        technical_context = any(token in contextual_haystack for token in positive_tokens)

        if any(token in asset_identity for token in absolute_skip_tokens):
            continue
        # Site-brand tokens are evaluated against the asset filename/alt/title only,
        # never against the autotecpro.com hostname. This removes logo/banner assets
        # without suppressing legitimate technical images hosted on the same site.
        brand_identity = " ".join((asset_basename, alt.casefold(), title.casefold()))
        if any(token in brand_identity for token in explicit_brand_tokens):
            continue
        # Soft terms such as "icon" can legitimately describe a technical settings
        # screenshot. Skip them only when there is no positive technical evidence.
        if any(token in asset_identity for token in soft_skip_tokens) and not technical_context:
            continue

        score = 0
        if technical_context:
            score += 6
        if nearest_heading:
            score += 2
        if nearby_text:
            score += 1
        if alt:
            score += 1
        if title:
            score += 1
        if full_size_candidate:
            score += 2
        if source_kind.startswith(("picture-", "img-srcset", "data-orig-file", "data-large-file", "data-full", "linked-full-image")):
            score += 2
        if re.search(r"\.(?:jpg|jpeg|png|webp|avif)(?:$|[?#])", normalized, flags=re.I):
            score += 1
        score += int({
            "product_gallery": 7, "product_technical_content": 7,
            "product_description": 5, "technical_section": 7,
            "product_summary": 3, "product_content": 2, "article_body": 2,
        }.get(source_zone_v69024, 0))

        # High-recall fallback: a normal raster image URL is allowed into the candidate
        # pool even without nearby text. Vision analysis later decides whether to keep it.
        if score <= 0 and not re.search(r"\.(?:jpg|jpeg|png|webp|avif)(?:$|[?#])", normalized, flags=re.I):
            continue
        score = max(score, 1)

        results.append({
            "url": normalized,
            "alt": alt,
            "title": title,
            "nearest_heading": nearest_heading,
            "nearby_text": nearby_text[:3600],
            "context_before_text_v69017": context_before_v69017[-1800:],
            "context_after_text_v69017": context_after_v69017[:1800],
            "context_score": score,
            "technical_context": bool(technical_context),
            "source_kind": source_kind,
            "full_size_candidate": full_size_candidate,
            "origin_group": origin_group,
            "source_zone_v69024": source_zone_v69024,
            "page_type_v69024": page_type_v69024,
            "ingestion_authority_version_v69024": str(raw.get("ingestion_authority_version_v69024") or WEBSITE_INGESTION_AUTHORITY_VERSION_V69024),
            "discovery_order": int(order_index),
        })

    # First collapse all alternate URLs emitted by one <img>/<picture> element.
    # A WordPress image can expose src, srcset, data-large-file, and a lightbox href;
    # those are representations of one page image, not four separate instructions.
    grouped = {}
    ungrouped = []
    for item in results:
        group = str(item.get("origin_group") or "")
        if not group:
            ungrouped.append(item)
            continue
        rank = (
            int(bool(item.get("full_size_candidate"))),
            _website_variant_resolution_rank_v68999(str(item.get("url") or "")),
            int(item.get("context_score") or 0),
            -int(item.get("discovery_order") or 0),
        )
        previous = grouped.get(group)
        if previous is None:
            grouped[group] = item
        else:
            previous_rank = (
                int(bool(previous.get("full_size_candidate"))),
                _website_variant_resolution_rank_v68999(str(previous.get("url") or "")),
                int(previous.get("context_score") or 0),
                -int(previous.get("discovery_order") or 0),
            )
            if rank > previous_rank:
                grouped[group] = item
    results = list(grouped.values()) + ungrouped

    # Collapse WordPress thumbnail/srcset variants to one logical asset, preferring
    # original/full-size URLs and the candidate with the strongest context. Exact
    # byte-level SHA dedupe still runs after download because different URLs can also
    # serve the same image bytes.
    logical = {}
    for item in results:
        logical_key = _website_asset_identity_v68999(str(item.get("url") or ""))
        previous = logical.get(logical_key)
        current_rank = (
            int(bool(item.get("full_size_candidate"))),
            _website_variant_resolution_rank_v68999(str(item.get("url") or "")),
            int(item.get("context_score") or 0),
            -int(item.get("discovery_order") or 0),
        )
        if previous is None:
            logical[logical_key] = item
            continue
        previous_rank = (
            int(bool(previous.get("full_size_candidate"))),
            _website_variant_resolution_rank_v68999(str(previous.get("url") or "")),
            int(previous.get("context_score") or 0),
            -int(previous.get("discovery_order") or 0),
        )
        if current_rank > previous_rank:
            # Preserve richer nearby context from the earlier record when the chosen
            # full-size URL itself came from a sparse lightbox/data attribute.
            if not item.get("nearest_heading") and previous.get("nearest_heading"):
                item["nearest_heading"] = previous.get("nearest_heading")
            if not item.get("nearby_text") and previous.get("nearby_text"):
                item["nearby_text"] = previous.get("nearby_text")
            if not item.get("context_before_text_v69017") and previous.get("context_before_text_v69017"):
                item["context_before_text_v69017"] = previous.get("context_before_text_v69017")
            if not item.get("context_after_text_v69017") and previous.get("context_after_text_v69017"):
                item["context_after_text_v69017"] = previous.get("context_after_text_v69017")
            if not item.get("alt") and previous.get("alt"):
                item["alt"] = previous.get("alt")
            logical[logical_key] = item

    results = list(logical.values())
    results.sort(
        key=lambda item: (
            -int(bool(item.get("technical_context"))),
            int(item.get("discovery_order") or 0),
            -int(bool(item.get("full_size_candidate"))),
            -int(item.get("context_score") or 0),
        )
    )
    return results[:WEBSITE_MAX_DISCOVERED_IMAGES]


WEBSITE_MAX_REDIRECT_HOPS = 5


def _public_request_with_validated_redirects(
    session, method, url, *, headers=None, timeout=None, stream=False, data=None,
    max_redirects=WEBSITE_MAX_REDIRECT_HOPS,
):
    """Issue an HTTP request while validating every redirect target before use."""
    current_url = normalize_website_url(url)
    current_method = str(method or "GET").upper()
    current_data = data
    for hop in range(int(max_redirects) + 1):
        validate_public_website_host(current_url)
        response = session.request(
            current_method, current_url, headers=headers, timeout=timeout,
            allow_redirects=False, stream=stream, data=current_data,
        )
        if response.status_code not in {301, 302, 303, 307, 308}:
            return response
        if hop >= int(max_redirects):
            response.close()
            raise ValueError("Website redirected too many times.")
        location = str(response.headers.get("Location") or "").strip()
        if not location:
            return response
        next_url = normalize_website_url(urljoin(current_url, location))
        validate_public_website_host(next_url)
        response.close()
        if response.status_code in {301, 302, 303} and current_method != "HEAD":
            current_method = "GET"
            current_data = None
        current_url = next_url
    raise ValueError("Website redirect validation failed.")


def _website_image_size_policy_v68996(width, height, context_score=0, technical_context=False):
    """Return whether dimensions are useful enough for website technical analysis."""
    width = max(0, int(width or 0))
    height = max(0, int(height or 0))
    strong_context = bool(technical_context) or int(context_score or 0) >= 6
    min_w = 90 if strong_context else 180
    min_h = 70 if strong_context else 120
    min_pixels = 12000 if strong_context else 30000
    max_ratio = 12 if strong_context else 8
    passed = bool(
        width >= min_w
        and height >= min_h
        and (width * height) >= min_pixels
        and width / max(1, height) <= max_ratio
        and height / max(1, width) <= max_ratio
    )
    return {
        "passed": passed,
        "strong_context": strong_context,
        "min_width": min_w,
        "min_height": min_h,
        "min_pixels": min_pixels,
        "max_aspect_ratio": max_ratio,
    }


@st.cache_data(ttl=1800, max_entries=128, show_spinner=False)
def _download_public_website_image(image_url, context_score=0, technical_context=False):
    """Fetch and validate one public website image for vision analysis.

    v68996 retains strict decorative filtering but allows smaller connector/settings
    crops when the webpage context is strongly technical.
    """
    normalized_url = normalize_website_url(image_url)
    validate_public_website_host(normalized_url)

    response = _public_request_with_validated_redirects(
        http_session, "GET", normalized_url,
        headers={
            "User-Agent": (
                "Mozilla/5.0 (compatible; AutoTecProKnowledgeBot/1.0; "
                "+https://autotecpro.com)"
            ),
            "Accept": "image/avif,image/webp,image/png,image/jpeg,image/*;q=0.8,*/*;q=0.1",
        },
        timeout=WEBSITE_IMAGE_FETCH_TIMEOUT_SECONDS,
        stream=True,
    )
    response.raise_for_status()
    final_url = normalize_website_url(response.url)
    validate_public_website_host(final_url)

    content_type = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
    if not content_type.startswith("image/"):
        raise ValueError(f"URL did not return an image ({content_type or 'unknown'}).")
    if content_type in {"image/svg+xml", "image/gif"}:
        raise ValueError("Decorative/vector/animated image skipped.")

    declared_length = response.headers.get("Content-Length")
    if declared_length:
        try:
            if int(declared_length) > WEBSITE_MAX_IMAGE_BYTES:
                raise ValueError("Website image exceeds the 8 MB safety limit.")
        except ValueError as error:
            if "8 MB" in str(error):
                raise

    chunks = []
    total = 0
    for chunk in response.iter_content(chunk_size=65536):
        if not chunk:
            continue
        total += len(chunk)
        if total > WEBSITE_MAX_IMAGE_BYTES:
            raise ValueError("Website image exceeds the 8 MB safety limit.")
        chunks.append(chunk)
    raw = b"".join(chunks)
    if not raw:
        raise ValueError("Website image was empty.")

    width = height = 0
    normalized_bytes = raw
    normalized_mime = content_type if content_type.startswith("image/") else "image/jpeg"

    if Image is not None:
        try:
            source = ImageOps.exif_transpose(Image.open(io.BytesIO(raw)))
            width, height = source.size
            size_policy = _website_image_size_policy_v68996(
                width, height, context_score=context_score, technical_context=technical_context
            )
            if not size_policy.get("passed"):
                raise ValueError(
                    "Image dimensions are too small or too narrow for useful technical knowledge."
                )

            work = source.convert("RGB")
            work.thumbnail((1800, 1800), Image.Resampling.LANCZOS)
            buf = io.BytesIO()
            work.save(buf, format="JPEG", quality=90, optimize=True)
            normalized_bytes = buf.getvalue()
            normalized_mime = "image/jpeg"
        except ValueError:
            raise
        except Exception:
            pass

    return {
        "source_url": final_url,
        "bytes": normalized_bytes,
        "mime_type": normalized_mime,
        "original_content_type": content_type,
        "width": width,
        "height": height,
        "sha256": hashlib.sha256(raw).hexdigest(),
    }


WEBSITE_PREVIEW_HARD_DECORATIVE_TOKENS_V68998 = (
    "favicon", "sprite", "avatar", "emoji", "payment", "paypal", "visa",
    "mastercard", "amex", "social", "facebook", "instagram", "twitter",
    "youtube", "tiktok", "tracker", "analytics", "gravatar", "trustpilot",
    "klarna", "afterpay", "shop-pay", "apple-pay", "header-logo",
    "footer-logo", "site-logo", "brand-logo", "autotecpro_brand_logo",
    "/logo.", "/logo-", "/logo_", "/logos/",
)


def _website_preview_visual_metrics_v68998(image_bytes):
    """Return deterministic metrics used only to suppress blank/decorative previews."""
    metrics = {
        "valid": False, "entropy": 0.0, "gray_stddev": 0.0,
        "edge_ratio": 0.0, "visible_alpha_ratio": 1.0,
        "near_white_ratio": 0.0, "foreground_ratio": 1.0,
        "foreground_bbox_ratio": 1.0, "border_background_difference_ratio": 1.0,
    }
    if Image is None or not image_bytes:
        return metrics
    try:
        from PIL import ImageStat, ImageFilter
        source = Image.open(io.BytesIO(bytes(image_bytes)))
        rgba = ImageOps.exif_transpose(source).convert("RGBA")
        alpha = rgba.getchannel("A")
        alpha_hist = alpha.histogram()
        visible = sum(alpha_hist[8:])
        total = max(1, sum(alpha_hist))
        visible_alpha_ratio = visible / total
        rgb = rgba.convert("RGB")
        gray = rgb.convert("L")
        stat = ImageStat.Stat(gray)
        gray_stddev = float(stat.stddev[0] if stat.stddev else 0.0)
        try:
            entropy = float(gray.entropy())
        except Exception:
            entropy = 0.0
        edge = gray.filter(ImageFilter.FIND_EDGES)
        edge_hist = edge.histogram()
        edge_pixels = sum(edge_hist[24:])
        edge_ratio = edge_pixels / max(1, sum(edge_hist))

        # Logo-card detection metrics. Use a small thumbnail so validation stays cheap.
        probe = rgb.copy()
        probe.thumbnail((360, 360), Image.Resampling.BILINEAR)
        pw, ph = probe.size
        pixels = list(probe.getdata())
        ptotal = max(1, len(pixels))
        near_white = sum(1 for r, g, b in pixels if r >= 242 and g >= 242 and b >= 242) / ptotal
        border = []
        if pw and ph:
            border.extend(probe.crop((0, 0, pw, 1)).getdata())
            border.extend(probe.crop((0, max(0, ph-1), pw, ph)).getdata())
            border.extend(probe.crop((0, 0, 1, ph)).getdata())
            border.extend(probe.crop((max(0, pw-1), 0, pw, ph)).getdata())
        if border:
            br = sorted(x[0] for x in border)[len(border)//2]
            bg = sorted(x[1] for x in border)[len(border)//2]
            bb = sorted(x[2] for x in border)[len(border)//2]
        else:
            br = bg = bb = 255
        fg_coords = []
        bg_diff = 0
        for idx, (r, g, b) in enumerate(pixels):
            diff = abs(r-br) + abs(g-bg) + abs(b-bb)
            if diff >= 54:
                bg_diff += 1
                fg_coords.append((idx % max(1, pw), idx // max(1, pw)))
        foreground_ratio = bg_diff / ptotal
        bbox_ratio = 0.0
        if fg_coords:
            xs = [x for x, _ in fg_coords]; ys = [y for _, y in fg_coords]
            bbox_ratio = ((max(xs)-min(xs)+1) * (max(ys)-min(ys)+1)) / max(1, pw*ph)
        metrics.update({
            "valid": True,
            "entropy": round(entropy, 4),
            "gray_stddev": round(gray_stddev, 4),
            "edge_ratio": round(edge_ratio, 6),
            "visible_alpha_ratio": round(visible_alpha_ratio, 6),
            "near_white_ratio": round(near_white, 6),
            "foreground_ratio": round(foreground_ratio, 6),
            "foreground_bbox_ratio": round(bbox_ratio, 6),
            "border_background_difference_ratio": round(foreground_ratio, 6),
        })
    except Exception:
        pass
    return metrics


def _website_known_brand_asset_v69000(candidate, downloaded=None):
    """Return a deterministic reason for known AutoTec/site-brand assets.

    This gate is intentionally independent of nearby technical text. A logo placed
    inside a wiring section must remain a logo; contextual section text cannot promote
    it into Technical Support knowledge. Genuine technical images are protected when
    their own filename/alt/title carries installation/settings/wiring semantics.
    """
    candidate = dict(candidate or {})
    downloaded = dict(downloaded or {})
    url = str(candidate.get("url") or downloaded.get("source_url") or "")
    basename = _website_asset_basename_v68999(url)
    alt = re.sub(r"\s+", " ", str(candidate.get("alt") or "")).strip().casefold()
    title = re.sub(r"\s+", " ", str(candidate.get("title") or "")).strip().casefold()
    own_text = " ".join((basename, alt, title)).casefold()
    brand_tokens = (
        "autotecpro-logo", "autotec-logo", "autotecpro_logo", "autotec_logo",
        "autotecpro-brand", "autotec-brand", "autotecpro_brand", "autotec_brand",
        "www.autotecpro.com", "autotecpro.com-logo", "autotecpro navigation systems",
        "autotec navigation systems", "site-logo", "header-logo", "footer-logo",
    )
    # Strong, explicit brand identities win before generic technical words such as
    # "navigation" are considered; "AutoTecPro Navigation Systems" is the site logo,
    # not a navigation-setting screenshot.
    if any(token in own_text for token in brand_tokens):
        return "known-autotec-site-branding"
    technical_own_tokens = (
        "wiring", "diagram", "harness", "connector", "camera", "setting",
        "settings", "car model", "climate", "protocol", "canbus", "can bus",
        "amplifier", "audio", "bluetooth", "navigation", "google", "factory",
        "power", "aux", "lvds", "microphone", "temperature", "screen",
    )
    if any(token in own_text for token in technical_own_tokens):
        return ""
    # A bare AutoTec/AutoTecPro alt/title is branding unless the asset itself carries
    # a technical semantic token above. This does not inspect the autotecpro.com host.
    if alt in {"autotec", "autotecpro", "autotecpro navigation systems"} or title in {
        "autotec", "autotecpro", "autotecpro navigation systems"
    }:
        return "known-autotec-site-branding"
    return ""


def _website_preview_decorative_reason_v68998(candidate, downloaded, metrics):
    """Reject only deterministic broken/blank/obvious site-chrome candidates.

    This is intentionally conservative. Ambiguous photographs/screenshots remain visible
    and the existing AI SKIP_IMAGE gate decides usefulness only after staff approval.
    """
    candidate = dict(candidate or {})
    downloaded = dict(downloaded or {})
    identity = " ".join([
        str(candidate.get("url") or ""),
        str(downloaded.get("source_url") or ""),
        str(candidate.get("alt") or ""),
        str(candidate.get("title") or ""),
        str(candidate.get("source_kind") or ""),
    ]).casefold()
    technical = bool(candidate.get("technical_context"))
    basename = _website_asset_basename_v68999(str(candidate.get("url") or downloaded.get("source_url") or ""))
    explicit_brand_identity = " ".join((
        basename, str(candidate.get("alt") or "").casefold(),
        str(candidate.get("title") or "").casefold(),
    ))
    brand_reason_v69000 = _website_known_brand_asset_v69000(candidate, downloaded)
    if brand_reason_v69000:
        return brand_reason_v69000
    if any(token in identity for token in WEBSITE_PREVIEW_HARD_DECORATIVE_TOKENS_V68998):
        return "obvious-site-chrome"
    if any(token in explicit_brand_identity for token in (
        "autotec-logo", "autotecpro-logo", "autotec_brand", "autotecpro_brand",
        "autotecpro.com", "www.autotecpro.com",
    )):
        return "autotec-site-branding"
    if not bool(metrics.get("valid")):
        return "invalid-image-bytes"
    if float(metrics.get("visible_alpha_ratio") or 0.0) < 0.015:
        return "effectively-transparent"
    entropy = float(metrics.get("entropy") or 0.0)
    stddev = float(metrics.get("gray_stddev") or 0.0)
    edge_ratio = float(metrics.get("edge_ratio") or 0.0)
    if entropy < 0.55 and stddev < 2.25:
        return "blank-or-near-uniform"
    near_white = float(metrics.get("near_white_ratio") or 0.0)
    foreground_ratio = float(metrics.get("foreground_ratio") or 0.0)
    foreground_bbox_ratio = float(metrics.get("foreground_bbox_ratio") or 0.0)
    # A logo card is typically a mostly-uniform/white field with a small isolated
    # foreground mark. This catches branding files whose filename gives no clue.
    # Strong technical context gets a much tighter threshold so small connector crops
    # and settings screenshots are not accidentally removed.
    # v69000 hard boundary: a highly uniform white card with one isolated low-edge
    # mark remains decorative even when the surrounding article section is technical.
    # Genuine settings screenshots normally occupy a broad bounding box and have much
    # higher edge density, so they remain eligible.
    if (
        near_white >= 0.72
        and foreground_bbox_ratio <= 0.50
        and foreground_ratio <= 0.20
        and edge_ratio < 0.16
    ):
        return "probable-logo-or-brand-card"
    # Same principle for non-white logo cards: most pixels match the border/background
    # and a compact mark carries the only content.
    if (
        foreground_ratio <= 0.115
        and foreground_bbox_ratio <= 0.42
        and entropy < 4.8
        and edge_ratio < 0.14
    ):
        return "probable-isolated-brand-mark"
    width = int(downloaded.get("width") or 0)
    height = int(downloaded.get("height") or 0)
    ratio = max(width, height) / max(1, min(width, height))
    # Common logos/badges are shallow, low-information and detached from technical text.
    # Never apply this heuristic to candidates carrying real technical context.
    if (
        width and height
        and min(width, height) <= 320
        and ratio >= 2.5
        and foreground_ratio <= 0.45
        and entropy < 5.3
        and edge_ratio < 0.20
    ):
        return "probable-decorative-branding"
    return ""


def _website_preview_data_url_v68999(image_bytes, mime_type="image/jpeg"):
    """Create a lightweight Admin preview without changing the cached analysis bytes."""
    raw = bytes(image_bytes or b"")
    if not raw:
        return ""
    if Image is None:
        return f"data:{mime_type or 'image/jpeg'};base64," + base64.b64encode(raw).decode("ascii")
    try:
        source = ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert("RGB")
        source.thumbnail((900, 900), Image.Resampling.LANCZOS)
        buf = io.BytesIO()
        source.save(buf, format="JPEG", quality=82, optimize=True)
        preview = buf.getvalue()
        return "data:image/jpeg;base64," + base64.b64encode(preview).decode("ascii")
    except Exception:
        return f"data:{mime_type or 'image/jpeg'};base64," + base64.b64encode(raw).decode("ascii")


@st.cache_data(ttl=1800, max_entries=256, show_spinner=False)
def _website_preview_candidate_v68998(candidate_json):
    """Server-validate one candidate and return a self-contained preview data URL."""
    try:
        candidate = json.loads(candidate_json) if isinstance(candidate_json, str) else dict(candidate_json or {})
    except Exception:
        candidate = {}
    url = str(candidate.get("url") or "").strip()
    result = {
        "url": url, "status": "unavailable", "reason": "",
        "preview_data_url": "", "sha256": "", "width": 0, "height": 0,
        "source_url": "", "metrics": {},
    }
    if not url.startswith(("https://", "http://")):
        result["reason"] = "unsupported-url"
        return result
    try:
        downloaded = _download_public_website_image(
            url,
            context_score=int(candidate.get("context_score") or 0),
            technical_context=bool(candidate.get("technical_context")),
        )
        raw = bytes(downloaded.get("bytes") or b"")
        metrics = _website_preview_visual_metrics_v68998(raw)
        reason = _website_preview_decorative_reason_v68998(candidate, downloaded, metrics)
        result.update({
            "sha256": str(downloaded.get("sha256") or ""),
            "width": int(downloaded.get("width") or 0),
            "height": int(downloaded.get("height") or 0),
            "source_url": str(downloaded.get("source_url") or url),
            "metrics": metrics,
        })
        if reason:
            result["status"] = "filtered"
            result["reason"] = reason
            return result
        mime = str(downloaded.get("mime_type") or "image/jpeg")
        result["preview_data_url"] = _website_preview_data_url_v68999(raw, mime)
        result["status"] = "display"
        return result
    except Exception as error:
        result["status"] = "unavailable"
        result["reason"] = f"{type(error).__name__}: {str(error)[:240]}"
        return result


def _website_validated_preview_records_v68999(candidates):
    """Validate all discovered candidates, SHA-dedupe them, and build visible cards."""
    records = []
    valid_urls = []
    seen_sha = set()
    stats = {
        "discovered": len(list(candidates or [])),
        "displayed": 0, "decorative_filtered": 0, "unavailable": 0,
        "sha_duplicates": 0,
    }
    for item in candidates or []:
        if not isinstance(item, dict):
            continue
        payload = json.dumps(item, ensure_ascii=False, sort_keys=True, default=str)
        check = _website_preview_candidate_v68998(payload)
        status = str(check.get("status") or "")
        if status == "filtered":
            stats["decorative_filtered"] += 1
            continue
        if status != "display":
            stats["unavailable"] += 1
            continue
        digest = str(check.get("sha256") or "")
        if digest and digest in seen_sha:
            stats["sha_duplicates"] += 1
            continue
        if digest:
            seen_sha.add(digest)
        section = str(item.get("nearest_heading") or "").strip()
        alt = str(item.get("alt") or item.get("title") or "").strip()
        records.append({
            "name": section or alt or "Website instruction image",
            "data_url": str(check.get("preview_data_url") or ""),
            "source": "website_knowledge",
        })
        valid_urls.append(str(item.get("url") or ""))
    stats["displayed"] = len(records)
    return records, valid_urls, stats


def _ingestion_json_object_v69017(value):
    """Parse one fail-closed JSON object from a model response."""
    text = str(value or "").strip()
    if not text:
        return None
    text = re.sub(r"^```(?:json)?\s*|\s*```$", "", text, flags=re.I | re.S).strip()
    candidates = [text]
    start, end = text.find("{"), text.rfind("}")
    if start >= 0 and end > start:
        candidates.append(text[start:end + 1])
    for candidate in candidates:
        try:
            parsed = json.loads(candidate)
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            continue
    return None


def _ingestion_image_structured_extract_v69017(
    image_data_url,
    *,
    source_label,
    page_title,
    section_heading,
    context_before,
    context_after,
    alt_text,
    database_choice,
):
    """Extract image knowledge as structured evidence instead of free prose."""
    instructions = (
        "You are AutoTecPro's ingestion evidence extractor. Analyze only what is visible "
        "in the image and what is explicitly supported by the supplied source context. "
        "Never invent compatibility, vehicle years, settings, part numbers, or hidden wiring. "
        "Return ONLY one JSON object and no markdown."
    )
    prompt = f"""Destination: {database_choice}
Source: {source_label}
Page/document title: {page_title}
Section heading: {section_heading or '(none)'}
Text immediately BEFORE image: {context_before or '(none)'}
Text immediately AFTER image: {context_after or '(none)'}
Alt/caption text: {alt_text or '(none)'}

Return exactly these JSON keys:
keep_image: boolean
visual_summary: concise searchable description
visible_text: array of important labels/text actually visible
vehicle_make: string or empty
vehicle_model: string or empty
year_range: string or empty
system_or_variant: string or empty
topic: concise technical/sales/marketing topic
relationship: one of direct, contextual, unrelated
context_conflict: boolean
confidence: number from 0 to 1
reason: concise evidence-based reason

Use keep_image=false for decorative, branding, generic vehicle photography, blank, duplicate-looking,
or otherwise non-reusable images. relationship=direct only when the image directly illustrates the
same instruction/setting/component described by the local context."""
    response = client.responses.create(
        model="gpt-5.5",
        instructions=instructions,
        input=[{
            "role": "user",
            "content": [
                {"type": "input_text", "text": prompt},
                {"type": "input_image", "image_url": image_data_url, "detail": "high"},
            ],
        }],
    )
    return _ingestion_json_object_v69017(getattr(response, "output_text", ""))


def _ingestion_image_relation_verify_v69017(
    image_data_url,
    *,
    source_label,
    page_title,
    section_heading,
    context_before,
    context_after,
    alt_text,
    extracted,
):
    """Independent second-pass verifier for image ↔ section relationships."""
    extracted = dict(extracted or {})
    instructions = (
        "You are AutoTecPro's independent ingestion QA verifier. Do not trust the first-pass "
        "conclusion. Re-evaluate the image and local source context yourself. Approve automatic "
        "knowledge linkage only when the image is genuinely useful and the relationship to the "
        "section/instruction is supported. Return ONLY JSON."
    )
    prompt = f"""Source: {source_label}
Title: {page_title}
Section: {section_heading or '(none)'}
Text BEFORE: {context_before or '(none)'}
Text AFTER: {context_after or '(none)'}
Alt/caption: {alt_text or '(none)'}
First-pass extraction (evidence only, not authority): {json.dumps(extracted, ensure_ascii=False)}

Return exactly:
approved: boolean
relationship: one of direct, contextual, unrelated
confidence: number 0 to 1
vehicle_or_year_conflict: boolean
section_conflict: boolean
reason: concise explanation

Fail closed if the image cannot be confidently tied to useful source knowledge."""
    response = client.responses.create(
        model="gpt-5.5",
        instructions=instructions,
        input=[{
            "role": "user",
            "content": [
                {"type": "input_text", "text": prompt},
                {"type": "input_image", "image_url": image_data_url, "detail": "high"},
            ],
        }],
    )
    return _ingestion_json_object_v69017(getattr(response, "output_text", ""))


def _analyze_ingestion_image_with_qa_v69017(
    image_data_url,
    *,
    source_label,
    page_title,
    section_heading,
    context_before,
    context_after,
    alt_text,
    database_choice,
):
    """Two-pass ingestion authority used by website and embedded-document images."""
    extracted = _ingestion_image_structured_extract_v69017(
        image_data_url,
        source_label=source_label,
        page_title=page_title,
        section_heading=section_heading,
        context_before=context_before,
        context_after=context_after,
        alt_text=alt_text,
        database_choice=database_choice,
    )
    if not extracted or not bool(extracted.get("keep_image")):
        return {"approved": False, "reason": "extractor_rejected_or_invalid", "extracted": extracted or {}}
    try:
        extract_conf = float(extracted.get("confidence") or 0.0)
    except Exception:
        extract_conf = 0.0
    if bool(extracted.get("context_conflict")) or str(extracted.get("relationship") or "").lower() == "unrelated" or extract_conf < 0.72:
        return {"approved": False, "reason": "extractor_low_confidence_or_conflict", "extracted": extracted}

    verified = _ingestion_image_relation_verify_v69017(
        image_data_url,
        source_label=source_label,
        page_title=page_title,
        section_heading=section_heading,
        context_before=context_before,
        context_after=context_after,
        alt_text=alt_text,
        extracted=extracted,
    )
    try:
        verify_conf = float((verified or {}).get("confidence") or 0.0)
    except Exception:
        verify_conf = 0.0
    approved = bool(verified and verified.get("approved"))
    approved = approved and verify_conf >= 0.80
    approved = approved and not bool(verified.get("vehicle_or_year_conflict"))
    approved = approved and not bool(verified.get("section_conflict"))
    approved = approved and str(verified.get("relationship") or "").lower() in {"direct", "contextual"}

    visible_text = extracted.get("visible_text") or []
    if not isinstance(visible_text, list):
        visible_text = [str(visible_text)]
    search_parts = [
        str(extracted.get("visual_summary") or ""),
        "Visible labels: " + "; ".join(str(x) for x in visible_text if str(x).strip()),
        "Vehicle: " + " ".join(x for x in (str(extracted.get("vehicle_make") or ""), str(extracted.get("vehicle_model") or ""), str(extracted.get("year_range") or "")) if x),
        "System/variant: " + str(extracted.get("system_or_variant") or ""),
        "Topic: " + str(extracted.get("topic") or ""),
        "Relationship: " + str((verified or {}).get("relationship") or extracted.get("relationship") or ""),
    ]
    search_text = re.sub(r"\s+", " ", " ".join(x for x in search_parts if x and not x.endswith(": "))).strip()
    return {
        "approved": bool(approved),
        "analysis": search_text,
        "extracted": extracted,
        "verified": verified or {},
        "relationship_confidence": round(min(extract_conf, verify_conf), 4),
        "relationship": str((verified or {}).get("relationship") or extracted.get("relationship") or "").lower(),
        "qa_version": "v69017-two-pass",
        "reason": str((verified or {}).get("reason") or extracted.get("reason") or "").strip(),
    }

def analyze_website_images(extraction, database_choice, selected_urls=None):
    """Download, filter, analyze, and de-duplicate useful images from one page.

    v69005 distinguishes "no selection supplied" from an explicitly empty
    selection. An explicit empty list means the reviewer removed every image and
    must never fall back to analyzing all discovered candidates.
    """
    selection_provided_v69005 = selected_urls is not None
    selected_set = {
        str(item or "").strip()
        for item in (selected_urls or [])
        if str(item or "").strip()
    }
    candidates = list(extraction.get("image_candidates") or [])
    if selection_provided_v69005:
        candidates = [
            item for item in candidates
            if str((item or {}).get("url") or "") in selected_set
        ]

    # Reuse durable visual analysis for byte-identical images already approved
    # on this same canonical page/database. This makes same-URL updates truly
    # incremental and avoids provider drift deleting an unchanged image.
    existing_by_digest_v69005 = {}
    try:
        existing_rows_v69005, existing_loaded_v69005 = (
            _website_image_index_rows_for_page_v69003(extraction, database_choice)
        )
        if existing_loaded_v69005:
            for existing_entry_v69005 in existing_rows_v69005:
                existing_payload_v69005 = dict(existing_entry_v69005.get("payload") or {})
                existing_digest_v69005 = str(existing_payload_v69005.get("image_sha256") or "").strip().lower()
                if (
                    existing_digest_v69005
                    and str(existing_payload_v69005.get("visual_analysis") or "").strip()
                    and str(existing_payload_v69005.get("ingestion_qa_version_v69017") or "").strip()
                    and str(existing_payload_v69005.get("ingestion_authority_version_v69024") or "").strip() == WEBSITE_INGESTION_AUTHORITY_VERSION_V69024
                    and str(existing_payload_v69005.get("page_identity_sha256_v69024") or "").strip()
                    == str((extraction.get("page_identity_v69024") or {}).get("identity_sha256") or "").strip()
                ):
                    existing_by_digest_v69005[existing_digest_v69005] = existing_payload_v69005
    except Exception:
        existing_by_digest_v69005 = {}

    learned = []
    seen_hashes = set()
    attempted = 0
    skipped = 0
    failures = 0
    reused = 0
    provider_calls = 0

    for candidate in candidates:
        if len(learned) >= WEBSITE_MAX_ANALYZED_IMAGES:
            break
        if not isinstance(candidate, dict):
            continue
        attempted += 1
        try:
            downloaded = _download_public_website_image(
                candidate.get("url"),
                context_score=int(candidate.get("context_score") or 0),
                technical_context=bool(candidate.get("technical_context")),
            )
            digest = str(downloaded.get("sha256") or "")
            if digest and digest in seen_hashes:
                skipped += 1
                continue
            if digest:
                seen_hashes.add(digest)

            existing_payload_v69005 = existing_by_digest_v69005.get(digest.lower()) if digest else None
            if existing_payload_v69005:
                if str(candidate.get("source_zone_v69024") or "").strip() != str(existing_payload_v69005.get("source_zone_v69024") or "").strip():
                    existing_payload_v69005 = None
            if existing_payload_v69005:
                analysis = str(existing_payload_v69005.get("visual_analysis") or "").strip()
                reused += 1
            else:
                data_url = (
                    f"data:{downloaded.get('mime_type') or 'image/jpeg'};base64,"
                    + base64.b64encode(downloaded.get("bytes") or b"").decode("ascii")
                )
                provider_calls += 2
                qa_v69017 = _analyze_ingestion_image_with_qa_v69017(
                    data_url,
                    source_label=str(extraction.get("source_url") or ""),
                    page_title=str(extraction.get("title") or ""),
                    section_heading=str(candidate.get("nearest_heading") or ""),
                    context_before=str(candidate.get("context_before_text_v69017") or candidate.get("nearby_text") or ""),
                    context_after=str(candidate.get("context_after_text_v69017") or ""),
                    alt_text=str(candidate.get("alt") or candidate.get("title") or ""),
                    database_choice=str(database_choice or ""),
                )
                if not qa_v69017.get("approved"):
                    skipped += 1
                    continue
                analysis = str(qa_v69017.get("analysis") or "").strip()
            if not analysis or analysis.strip().upper() == "SKIP_IMAGE":
                skipped += 1
                continue

            if existing_payload_v69005:
                qa_v69017 = {
                    "approved": True,
                    "relationship": str(existing_payload_v69005.get("image_relationship_v69017") or "direct"),
                    "relationship_confidence": float(existing_payload_v69005.get("image_relationship_confidence_v69017") or 1.0),
                    "qa_version": str(existing_payload_v69005.get("ingestion_qa_version_v69017") or "v69017-two-pass"),
                    "extracted": existing_payload_v69005.get("image_structured_metadata_v69017") or {},
                    "verified": {},
                    "reason": "durable_v69017_reuse",
                }

            learned.append({
                "url": str(downloaded.get("source_url") or candidate.get("url") or ""),
                "alt": str(candidate.get("alt") or "").strip(),
                "title": str(candidate.get("title") or "").strip(),
                "nearest_heading": str(candidate.get("nearest_heading") or "").strip(),
                "nearby_text": str(candidate.get("nearby_text") or "").strip(),
                "context_before_text_v69017": str(candidate.get("context_before_text_v69017") or "").strip(),
                "context_after_text_v69017": str(candidate.get("context_after_text_v69017") or "").strip(),
                "image_relationship_v69017": str(qa_v69017.get("relationship") or "").strip(),
                "image_relationship_confidence_v69017": float(qa_v69017.get("relationship_confidence") or 0.0),
                "ingestion_qa_version_v69017": str(qa_v69017.get("qa_version") or "").strip(),
                "image_structured_metadata_v69017": dict(qa_v69017.get("extracted") or {}),
                "image_qa_reason_v69017": str(qa_v69017.get("reason") or "").strip(),
                "source_kind": str(candidate.get("source_kind") or "").strip(),
                "source_zone_v69024": str(candidate.get("source_zone_v69024") or "").strip(),
                "page_type_v69024": str(extraction.get("page_type_v69024") or candidate.get("page_type_v69024") or "").strip(),
                "page_identity_v69024": dict(extraction.get("page_identity_v69024") or {}),
                "ingestion_authority_version_v69024": WEBSITE_INGESTION_AUTHORITY_VERSION_V69024,
                "context_score": int(candidate.get("context_score") or 0),
                "technical_context": bool(candidate.get("technical_context")),
                "analysis": analysis,
                "sha256": digest,
                "width": int(downloaded.get("width") or 0),
                "height": int(downloaded.get("height") or 0),
            })
        except Exception as error:
            skipped += 1
            failures += 1
            diagnostic_log(
                "website_image_ingestion_skipped_v68870",
                image_url=str((candidate or {}).get("url") or "")[:500],
                error_type=type(error).__name__,
                error=str(error)[:500],
            )

    return {
        "images": learned,
        "attempted": attempted,
        "skipped": skipped,
        "failures": failures,
        "reused": reused,
        "provider_calls": provider_calls,
        "selection_provided_v69005": bool(selection_provided_v69005),
        "discovered": len(candidates),
        "limited": len(candidates) > WEBSITE_MAX_ANALYZED_IMAGES,
    }


def build_website_knowledge_package_document(
    extraction,
    database_choice,
    reviewed_content=None,
    image_analysis=None,
):
    """Build one searchable package containing webpage text plus image knowledge."""
    content = clean_extracted_website_text(
        reviewed_content if reviewed_content is not None else extraction.get("content")
    )
    image_analysis = image_analysis or {}
    images = list(image_analysis.get("images") or [])
    approved_image_origins_v69040 = sorted({
        str(urlparse(str(item.get("url") or "")).hostname or "").strip().casefold()
        for item in images if isinstance(item, dict)
        and str(item.get("url") or "").startswith("https://")
        and str(urlparse(str(item.get("url") or "")).hostname or "").strip()
    })

    lines = [
        "AUTOTECPRO WEBSITE KNOWLEDGE PACKAGE",
        f"Destination: {database_choice}",
        f"Page title: {extraction.get('title')}",
        f"Requested URL: {extraction.get('requested_url') or extraction.get('source_url')}",
        f"Final source URL: {extraction.get('source_url')}",
        f"Extracted at (UTC): {extraction.get('extracted_at')}",
        f"Page content SHA-256: {extraction.get('content_hash')}",
        f"Page type v69024: {extraction.get('page_type_v69024')}",
        f"Ingestion authority: {extraction.get('ingestion_authority_version_v69024') or WEBSITE_INGESTION_AUTHORITY_VERSION_V69024}",
        f"PAGE_IDENTITY_JSON_V69024: {json.dumps(extraction.get('page_identity_v69024') or {}, ensure_ascii=False, separators=(',', ':'))}",
        f"Useful website images analyzed: {len(images)}",
        "APPROVED_IMAGE_ORIGINS_V69040: " + ",".join(approved_image_origins_v69040),
        "",
        "WEBPAGE TEXT",
        "============",
        content,
        "",
    ]

    if images:
        lines.extend([
            "WEBSITE IMAGE KNOWLEDGE",
            "=======================",
            (
                "IMPORTANT FOR TECHNICAL SUPPORT RETRIEVAL: When an image below directly "
                "supports a future answer, use its exact AUTO_DISPLAY_IMAGE URL. Never "
                "invent, modify, or substitute an image URL."
            ),
            "",
        ])
        for index, item in enumerate(images, start=1):
            caption = (
                str(item.get("alt") or item.get("title") or "").strip()
                or f"Source image {index}"
            )
            lines.extend([
                f"IMAGE {index}",
                f"SECTION_HEADING: {str(item.get('nearest_heading') or '').strip()}",
                f"NEARBY_INSTRUCTION_TEXT: {str(item.get('nearby_text') or '').strip()}",
                f"CONTEXT_BEFORE_IMAGE: {str(item.get('context_before_text_v69017') or '').strip()}",
                f"CONTEXT_AFTER_IMAGE: {str(item.get('context_after_text_v69017') or '').strip()}",
                f"IMAGE_RELATIONSHIP: {str(item.get('image_relationship_v69017') or '').strip()}",
                f"IMAGE_RELATIONSHIP_CONFIDENCE: {item.get('image_relationship_confidence_v69017')}",
                f"SOURCE_ZONE_V69024: {str(item.get('source_zone_v69024') or '').strip()}",
                f"PAGE_TYPE_V69024: {str(item.get('page_type_v69024') or extraction.get('page_type_v69024') or '').strip()}",
                f"INGESTION_AUTHORITY_VERSION_V69024: {str(item.get('ingestion_authority_version_v69024') or WEBSITE_INGESTION_AUTHORITY_VERSION_V69024).strip()}",
                f"PAGE_IDENTITY_JSON_V69024: {json.dumps(item.get('page_identity_v69024') or extraction.get('page_identity_v69024') or {}, ensure_ascii=False, separators=(',', ':'))}",
                f"INGESTION_QA_VERSION: {str(item.get('ingestion_qa_version_v69017') or '').strip()}",
                f"IMAGE_STRUCTURED_METADATA_JSON: {json.dumps(item.get('image_structured_metadata_v69017') or {}, ensure_ascii=False, separators=(',', ':'))}",
                f"AUTO_DISPLAY_IMAGE: {item.get('url')}",
                f"IMAGE_CAPTION: {caption}",
                f"IMAGE_SHA256: {item.get('sha256')}",
                f"IMAGE_SIZE: {item.get('width')}x{item.get('height')}",
                "IMAGE_ANALYSIS:",
                str(item.get("analysis") or "").strip(),
                "",
            ])

    return "\n".join(lines).strip() + "\n"


WEBSITE_IMAGE_INDEX_SOURCE_V68883 = "website_image_index_v68883"
WEBSITE_IMAGE_INDEX_PREFIX_V68883 = "WEBSITE_IMAGE_INDEX_JSON_V68883:"
WEBSITE_IMAGE_INDEX_MAX_ROWS_V68883 = 1500
WEBSITE_IMAGE_INDEX_QUERY_MAX_IMAGES_V68883 = 3


def _website_image_index_keywords_v68883(extraction, image_item):
    parts = [
        str(extraction.get("title") or ""),
        str(extraction.get("source_url") or ""),
        str(image_item.get("nearest_heading") or ""),
        str(image_item.get("nearby_text") or ""),
        str(image_item.get("alt") or ""),
        str(image_item.get("title") or ""),
        str(image_item.get("analysis") or ""),
    ]
    value = re.sub(r"\s+", " ", " ".join(parts)).strip().casefold()
    tokens = re.findall(r"[a-z0-9][a-z0-9._/-]{1,}", value)
    seen = set()
    ordered = []
    for token in tokens:
        clean = token.strip("._/-")
        if len(clean) < 2 or clean in seen:
            continue
        seen.add(clean)
        ordered.append(clean)
        if len(ordered) >= 120:
            break
    return ", ".join(ordered)


def _website_image_archive_path_v68883(extraction, image_item, mime_type="image/jpeg"):
    digest = str(image_item.get("sha256") or "").strip().lower()
    if not digest:
        digest = hashlib.sha256(
            str(image_item.get("url") or "").encode("utf-8")
        ).hexdigest()
    parsed = urlparse(str(extraction.get("source_url") or ""))
    host = re.sub(r"[^A-Za-z0-9._-]+", "-", parsed.hostname or "website").strip("-") or "website"
    extension = ".png" if "png" in str(mime_type or "").casefold() else ".jpg"
    return f"website_knowledge/{host}/{digest[:2]}/{digest}{extension}"


