def _website_image_index_issue_v68883(image_item):
    digest = str(image_item.get("sha256") or "").strip().lower()
    if not digest:
        digest = hashlib.sha256(
            str(image_item.get("url") or "").encode("utf-8")
        ).hexdigest()
    return f"website-image:{digest[:40]}"


def _website_image_page_identity_v69003(payload_or_extraction):
    """Return the canonical page identity used for page-scoped website image records."""
    source = dict(payload_or_extraction or {})
    raw_url = (
        str(source.get("requested_page") or "").strip()
        or str(source.get("source_page") or "").strip()
        or str(source.get("requested_url") or "").strip()
        or str(source.get("source_url") or "").strip()
    )
    if not raw_url:
        return ""
    try:
        return canonical_website_url_identity(raw_url)
    except Exception:
        return raw_url.rstrip("/").casefold()


def _website_image_scoped_issue_v69003(payload):
    """Use page + database + image identity so the same image can safely exist on multiple pages."""
    payload = dict(payload or {})
    page_identity = _website_image_page_identity_v69003(payload)
    database_choice = str(payload.get("database_choice") or "").strip().casefold()
    image_identity = str(payload.get("image_sha256") or "").strip().lower()
    if not image_identity:
        image_identity = hashlib.sha256(
            str(payload.get("image_url") or "").encode("utf-8")
        ).hexdigest()
    page_hash = hashlib.sha256(
        f"{database_choice}|{page_identity}".encode("utf-8")
    ).hexdigest()[:16]
    return f"website-image:{page_hash}:{image_identity[:40]}"


def _website_image_index_upsert_v68883(payload):
    """Persist one page-scoped compact image-index row using learned_knowledge."""
    if not isinstance(payload, dict):
        return False
    issue = _website_image_scoped_issue_v69003(payload)

    try:
        existing = (
            supabase.table("learned_knowledge")
            .select("id")
            .eq("source_type", WEBSITE_IMAGE_INDEX_SOURCE_V68883)
            .eq("issue", issue)
            .limit(1)
            .execute()
            .data
            or []
        )
    except Exception:
        existing = []

    solution = WEBSITE_IMAGE_INDEX_PREFIX_V68883 + json.dumps(
        payload,
        ensure_ascii=False,
        separators=(",", ":"),
    )
    database_choice_v69040 = str(payload.get("database_choice") or "")
    assistant_label_v69040 = {
        "Technical Support Database": "Technical Support",
        "Sales Database": "Sales",
        "Marketing Database": "Marketing",
    }.get(database_choice_v69040, "Technical Support")
    row = {
        "assistant": assistant_label_v69040,
        "record_type": "website_image",
        "vehicle": str(payload.get("page_title") or "")[:240],
        "issue": issue,
        "question": str(payload.get("section_heading") or "Website image")[:500],
        "source_question": str(payload.get("source_page") or "")[:1200],
        "solution": solution,
        "approved_answer": solution,
        "keywords": str(payload.get("keywords") or "")[:5000],
        "source_type": WEBSITE_IMAGE_INDEX_SOURCE_V68883,
        "staff_confirmed": True,
        "confidence_score": 100,
        "updated_at": now_iso(),
    }

    clean_row = filter_payload_for_table("learned_knowledge", row)
    if existing:
        (
            supabase.table("learned_knowledge")
            .update(clean_row)
            .eq("id", existing[0]["id"])
            .execute()
        )
    else:
        safe_insert_row("learned_knowledge", clean_row)
    try:
        _workspace_durable_image_payloads_v69041.clear()
    except Exception:
        pass
    return True


def _website_image_index_db_rows_v69005(columns, *, order_recent=False, max_rows=20000):
    """Load website-image index rows in bounded pages and report completeness.

    v69004 used a single 1,500-row window. Once the global website-image index
    exceeded that size, old page rows could become invisible to retrieval/sync,
    and shared-archive reference checks could become unsafe. v69005 paginates and
    fails closed when the safety ceiling is reached.
    """
    rows = []
    batch_size = 1000
    complete = True
    for start in range(0, int(max_rows), batch_size):
        try:
            query = (
                supabase.table("learned_knowledge")
                .select(columns)
                .eq("source_type", WEBSITE_IMAGE_INDEX_SOURCE_V68883)
            )
            if order_recent:
                query = query.order("updated_at", desc=True)
            else:
                # Stable ordering is required for offset/range pagination.
                query = query.order("id", desc=False)
            range_method = getattr(query, "range", None)
            if callable(range_method):
                query = range_method(start, start + batch_size - 1)
            else:
                if start:
                    complete = False
                    break
                query = query.limit(batch_size)
            page = list(query.execute().data or [])
        except Exception:
            return rows, False
        rows.extend(page)
        if len(page) < batch_size:
            return rows, True
    if len(rows) >= int(max_rows):
        complete = False
    return rows, complete


def _website_image_index_rows_for_page_v69003(extraction, database_choice):
    """Load durable website-image rows for one canonical page and one destination database."""
    target_page = _website_image_page_identity_v69003(extraction)
    target_database = str(database_choice or "").strip().casefold()
    matches = []
    rows, rows_complete_v69005 = _website_image_index_db_rows_v69005(
        "id,issue,solution,approved_answer,source_type",
        max_rows=20000,
    )
    if not rows_complete_v69005:
        diagnostic_log(
            "website_image_page_sync_load_incomplete_v69005",
            loaded=len(rows),
        )
        return [], False

    for row in rows:
        raw = str(row.get("solution") or row.get("approved_answer") or "")
        if not raw.startswith(WEBSITE_IMAGE_INDEX_PREFIX_V68883):
            continue
        try:
            payload = json.loads(raw[len(WEBSITE_IMAGE_INDEX_PREFIX_V68883):])
        except Exception:
            continue
        if not isinstance(payload, dict):
            continue
        if str(payload.get("database_choice") or "").strip().casefold() != target_database:
            continue
        if _website_image_page_identity_v69003(payload) != target_page:
            continue
        matches.append({"row": row, "payload": payload})
    return matches, True


def _website_archive_path_is_referenced_v69003(archive_path):
    """Fail closed: remove a stored image only when no other website-image row references it."""
    target = str(archive_path or "").strip()
    if not target:
        return False, True
    rows, rows_complete_v69005 = _website_image_index_db_rows_v69005(
        "id,solution,approved_answer,source_type",
        max_rows=20000,
    )
    if not rows_complete_v69005:
        return True, False
    for row in rows:
        raw = str(row.get("solution") or row.get("approved_answer") or "")
        if not raw.startswith(WEBSITE_IMAGE_INDEX_PREFIX_V68883):
            continue
        try:
            payload = json.loads(raw[len(WEBSITE_IMAGE_INDEX_PREFIX_V68883):])
        except Exception:
            continue
        if str((payload or {}).get("archive_storage_path") or "").strip() == target:
            return True, True
    return False, True


def _website_sync_page_image_index_v69003(extraction, database_choice, image_items):
    """Delete stale/legacy image-index rows for this page after replacement is safely indexed."""
    existing, loaded_ok = _website_image_index_rows_for_page_v69003(
        extraction,
        database_choice,
    )
    stats = {
        "loaded": len(existing),
        "stale_deleted": 0,
        "legacy_migrated": 0,
        "archive_deleted": 0,
        "failures": 0,
        "completed": bool(loaded_ok),
    }
    if not loaded_ok:
        stats["failures"] += 1
        stats["completed"] = False
        return stats

    current_payloads = []
    current_issues = set()
    for item in image_items or []:
        if not isinstance(item, dict):
            continue
        payload = _website_image_index_record_v68883(
            extraction,
            database_choice,
            item,
        )
        current_payloads.append(payload)
        current_issues.add(_website_image_scoped_issue_v69003(payload))

    candidate_archive_paths = set()
    for entry in existing:
        row = dict(entry.get("row") or {})
        payload = dict(entry.get("payload") or {})
        row_id = str(row.get("id") or "").strip()
        issue = str(row.get("issue") or "").strip()
        expected_issue = _website_image_scoped_issue_v69003(payload)
        image_digest = str(payload.get("image_sha256") or "").strip().lower()
        if not image_digest:
            image_digest = hashlib.sha256(
                str(payload.get("image_url") or "").encode("utf-8")
            ).hexdigest()
        page_payload = dict(payload)
        page_payload["image_sha256"] = image_digest
        current_issue_for_payload = _website_image_scoped_issue_v69003(page_payload)
        should_keep = current_issue_for_payload in current_issues and issue == expected_issue
        if should_keep:
            continue
        if not row_id:
            stats["failures"] += 1
            stats["completed"] = False
            continue
        try:
            supabase.table("learned_knowledge").delete().eq("id", row_id).execute()
            archive_path = str(payload.get("archive_storage_path") or "").strip()
            if archive_path:
                candidate_archive_paths.add(archive_path)
            if current_issue_for_payload in current_issues:
                stats["legacy_migrated"] += 1
            else:
                stats["stale_deleted"] += 1
        except Exception as error:
            stats["failures"] += 1
            stats["completed"] = False
            diagnostic_log(
                "website_image_page_sync_delete_failed_v69003",
                row_id=row_id,
                error_type=type(error).__name__,
                error=str(error)[:500],
            )

    for archive_path in sorted(candidate_archive_paths):
        referenced, checked = _website_archive_path_is_referenced_v69003(archive_path)
        if not checked:
            stats["failures"] += 1
            stats["completed"] = False
            continue
        if referenced:
            continue
        try:
            _product_library_storage_remove([archive_path])
            stats["archive_deleted"] += 1
        except Exception as error:
            stats["failures"] += 1
            stats["completed"] = False
            diagnostic_log(
                "website_image_page_sync_archive_delete_failed_v69003",
                archive_path=archive_path,
                error_type=type(error).__name__,
                error=str(error)[:500],
            )

    try:
        _website_image_index_rows_v68883.clear()
    except Exception:
        pass
    try:
        _workspace_durable_image_payloads_v69041.clear()
    except Exception:
        pass
    return stats


def _website_archive_and_index_images_v68883(
    extraction,
    database_choice,
    image_items,
):
    """Best-effort archive + durable metadata index for approved website images.

    Text/vector-store saving remains authoritative and must not fail merely because
    private image archival/index persistence is temporarily unavailable.
    """
    indexed = 0
    archived = 0
    failures = 0

    for image_item in image_items or []:
        if not isinstance(image_item, dict):
            continue
        archive_path = ""
        archive_mime = ""
        try:
            downloaded = _download_public_website_image(
                image_item.get("url"),
                context_score=int(image_item.get("context_score") or 0),
                technical_context=bool(image_item.get("technical_context")),
            )
            raw = bytes(downloaded.get("bytes") or b"")
            archive_mime = str(downloaded.get("mime_type") or "image/jpeg")
            if raw:
                archive_path = _website_image_archive_path_v68883(
                    extraction,
                    image_item,
                    archive_mime,
                )
                _product_library_storage_upload(
                    archive_path,
                    raw,
                    archive_mime,
                )
                archived += 1
        except Exception as error:
            diagnostic_log(
                "website_image_archive_failed_v68883",
                image_url=str(image_item.get("url") or "")[:500],
                error_type=type(error).__name__,
                error=str(error)[:500],
            )

        try:
            payload = _website_image_index_record_v68883(
                extraction,
                database_choice,
                image_item,
                archive_path=archive_path,
                archive_mime_type=archive_mime,
            )
            if _website_image_index_upsert_v68883(payload):
                indexed += 1
        except Exception as error:
            failures += 1
            diagnostic_log(
                "website_image_index_save_failed_v68883",
                image_url=str(image_item.get("url") or "")[:500],
                error_type=type(error).__name__,
                error=str(error)[:500],
            )

    try:
        _website_image_index_rows_v68883.clear()
    except Exception:
        pass

    return {
        "indexed": indexed,
        "archived": archived,
        "failures": failures,
    }


@st.cache_data(ttl=300, max_entries=4, show_spinner=False)
def _website_image_index_rows_v68883():
    """Load durable approved website-image metadata without touching file_search."""
    rows, rows_complete_v69005 = _website_image_index_db_rows_v69005(
        "id,issue,vehicle,solution,approved_answer,keywords,source_type,updated_at",
        order_recent=True,
        max_rows=20000,
    )
    if not rows_complete_v69005:
        diagnostic_log(
            "website_image_index_load_incomplete_v69005",
            loaded=len(rows),
        )

    parsed = []
    for row in rows:
        raw = str(row.get("solution") or row.get("approved_answer") or "")
        if not raw.startswith(WEBSITE_IMAGE_INDEX_PREFIX_V68883):
            continue
        try:
            payload = json.loads(raw[len(WEBSITE_IMAGE_INDEX_PREFIX_V68883):])
        except Exception:
            continue
        if isinstance(payload, dict) and (
            str(payload.get("image_url") or "").startswith("https://")
            or str(payload.get("archive_storage_path") or "").strip()
        ):
            parsed.append(payload)
    return parsed


def _website_image_query_context_v68883(prompt_text):
    """Use current Technical request plus a small recent conversation window."""
    parts = [str(prompt_text or "").strip()]
    for message in list(st.session_state.get("messages") or [])[-6:]:
        if not isinstance(message, dict):
            continue
        visible, _ = extract_images_from_message_content(
            str(message.get("content") or "")
        )
        visible = clean_visible_chat_text(visible)
        visible = re.sub(r"\s+", " ", str(visible or "")).strip()
        if visible:
            parts.append(visible[:900])
    return "\n".join(parts)


