KNOWLEDGE_SUBMISSION_TYPES = [
    ("technical_solution", "🔧", "Technical Solution"),
    ("product_knowledge", "📦", "Product Knowledge"),
    ("sales_knowledge", "📈", "Sales Knowledge"),
    ("installation_guide", "📘", "Installation Guide"),
    ("faq", "❓", "FAQ"),
    ("other", "📝", "Other"),
]


def knowledge_submission_destination(knowledge_type):
    """Map a simple staff choice to the correct live knowledge database."""
    if str(knowledge_type or "") == "sales_knowledge":
        return "📈 Sales", SALES_VECTOR_STORE_ID
    return "🔧 Technical Support", TECHNICAL_VECTOR_STORE_ID




PENDING_ATTACHMENT_PREFIX = "pending_attachments:"


def _create_pending_openai_file(uploaded_file):
    """Store a supporting file in OpenAI without adding it to a vector store."""
    try:
        uploaded_file.seek(0)
    except Exception:
        pass
    created = client.files.create(file=uploaded_file, purpose="assistants")
    return {
        "file_id": created.id,
        "name": str(getattr(uploaded_file, "name", "supporting file")),
    }


def _pending_submission_metadata(row):
    """Read pending type and attachment references from a queue row."""
    keywords = str(row.get("keywords") or "")
    type_match = re.search(
        r"\[PENDING_KNOWLEDGE:([a-z_]+)\]",
        keywords,
        flags=re.IGNORECASE,
    )
    knowledge_type = (
        type_match.group(1).lower()
        if type_match
        else "technical_solution"
    )

    raw_file_data = str(row.get("openai_file_id") or "")
    attachments = []
    if raw_file_data.startswith(PENDING_ATTACHMENT_PREFIX):
        try:
            parsed = json.loads(
                raw_file_data[len(PENDING_ATTACHMENT_PREFIX):]
            )
            if isinstance(parsed, list):
                attachments = [
                    item for item in parsed
                    if isinstance(item, dict) and item.get("file_id")
                ]
        except Exception:
            attachments = []

    return knowledge_type, attachments


def is_pending_knowledge_row(row):
    """Return True only for staff submissions awaiting admin review."""
    if not isinstance(row, dict):
        return False

    keywords = str(row.get("keywords") or "")
    source_type = str(row.get("source_type") or "").strip().lower()
    embedding_status = str(
        row.get("embedding_status") or ""
    ).strip().lower()

    # Staff submissions are stored with typed markers such as:
    # [PENDING_KNOWLEDGE:technical_solution]
    # [PENDING_KNOWLEDGE:sales_knowledge]
    # Also accept the older untyped marker for backward compatibility.
    pending_keyword_marker = bool(
        re.search(
            r"\[PENDING_KNOWLEDGE(?::[a-z0-9_\-]+)?\]",
            keywords,
            flags=re.IGNORECASE,
        )
    )

    pending_source_type = source_type.startswith(
        "pending_knowledge_submission:"
    )

    pending_status = (
        embedding_status == "pending_review"
        and not bool(row.get("synced"))
    )

    return (
        pending_keyword_marker
        or pending_source_type
        or pending_status
    )


