def _product_library_normalize_followup_phrase(prompt):
    """Normalize natural Product Library follow-ups that refer to the current model."""
    value = re.sub(r"\s+", " ", str(prompt or "")).strip().lower()
    if not value:
        return ""

    # Staff often refer to the remembered Product Library record indirectly.
    # Remove those references so commands such as
    # "show me all photo of this model" normalize to "show me all photo".
    value = re.sub(
        r"\b(?:of|for)\s+(?:this|the|same)\s+"
        r"(?:model|unit|screen|radio|product|one)\b",
        "",
        value,
    )
    value = re.sub(
        r"\b(?:this|the|same)\s+"
        r"(?:model|unit|screen|radio|product|one)\b",
        "",
        value,
    )
    value = re.sub(r"\s+", " ", value).strip(" .,:;!?-")
    return value


def _product_library_is_asset_refinement_followup(prompt):
    """Detect natural short commands that refine the previous product gallery."""
    value = _product_library_normalize_followup_phrase(prompt)
    if not value:
        return False

    # These commands intentionally work without repeating the model number after
    # a verified Product Library product has already been selected.
    exact_commands = {
        "photo", "photos", "image", "images", "all", "all photo", "all photos",
        "all image", "all images", "show all", "show all photo",
        "show all photos", "show all image", "show all images",
        "show photo", "show photos", "show image", "show images",
        "show me all", "show me all photo", "show me all photos",
        "show me all image", "show me all images", "show them all",
        "show every photo", "show every image",
        "front", "rear", "back", "left", "right", "installed",
        "screen on", "screen off", "packaging", "package",
        "part", "parts", "accessory", "accessories", "kit",
        "mainboard", "motherboard", "pcb", "canbus", "can bus",
        "harness", "wiring", "usb", "gps", "wifi", "wi-fi",
        "sim", "microphone", "mic", "camera", "lvds", "power cable",
        "pinout", "ports", "connector", "connectors",
    }
    if value in exact_commands:
        return True

    refinement_phrases = (
        "only parts", "parts only", "part only", "only accessories",
        "accessories only", "only front", "front only", "only rear",
        "rear only", "back only", "only left", "left only",
        "only right", "right only", "only installed", "installed only",
        "only harness", "harness only", "only canbus", "canbus only",
        "only wiring", "wiring only", "only camera", "camera only",
        "only microphone", "microphone only", "only gps", "gps only",
        "only usb", "usb only", "only mainboard", "mainboard only",
        "front photo", "front photos", "rear photo", "rear photos",
        "left photo", "left photos", "right photo", "right photos",
        "show front", "show rear", "show left", "show right",
        "show parts", "show accessories", "show harness", "show canbus",
    )
    return any(phrase in value for phrase in refinement_phrases)


def _product_library_requests_all_photos(prompt):
    """Return True when a follow-up asks to restore every photo for the product."""
    value = _product_library_normalize_followup_phrase(prompt)
    return value in {
        "photo", "photos", "image", "images", "all", "all photo", "all photos",
        "all image", "all images", "show all", "show all photo",
        "show all photos", "show all image", "show all images",
        "show photo", "show photos", "show image", "show images",
        "show me all", "show me all photo", "show me all photos",
        "show me all image", "show me all images", "show them all",
        "show every photo", "show every image",
    }


def _product_library_parts_only_requested(prompt):
    """Return True when the user wants only included-parts/accessory images."""
    value = _product_library_normalize_followup_phrase(prompt)
    return any(phrase in value for phrase in (
        "only parts", "parts only", "part only", "only accessories",
        "accessories only", "parts photo", "parts photos", "part photo",
        "part photos", "included parts", "included accessories",
    ))


def _product_library_requested_subtypes(prompt):
    """Return ordered subtype intents inferred from the user's wording."""
    value = _product_library_normalize_followup_phrase(prompt)
    if not value:
        return []

    matches = []
    for subtype, phrases in PRODUCT_LIBRARY_ASSET_INTENTS.items():
        best_position = None
        for phrase in phrases:
            position = value.find(phrase)
            if position >= 0 and (best_position is None or position < best_position):
                best_position = position
        if best_position is not None:
            matches.append((best_position, subtype))

    matches.sort(key=lambda item: item[0])
    return [subtype for _, subtype in matches]


def _product_library_asset_relevance(asset, requested_subtypes):
    """Score one image asset against requested subtype intent and legacy metadata."""
    asset = asset or {}
    subtype = str(asset.get("asset_subtype") or "").strip().lower()
    asset_type = str(asset.get("asset_type") or "").strip().lower()
    filename = str(
        asset.get("original_filename")
        or asset.get("optimized_filename")
        or ""
    ).strip().lower().replace("_", " ").replace("-", " ")

    score = 0
    if requested_subtypes:
        for index, requested in enumerate(requested_subtypes):
            if subtype == requested:
                score = max(score, 300 - index)
            elif requested == "accessories" and asset_type == "parts_photo":
                # A generic "only parts" follow-up means every Parts Photo,
                # even when individual files are classified as harness/CANBUS/etc.
                score = max(score, 260 - index)
            elif requested.replace("_", " ") in filename:
                score = max(score, 220 - index)

        # Legacy files may not yet have subtype metadata. Apply conservative
        # filename synonyms only within the already-matched product.
        for requested in requested_subtypes:
            for phrase in PRODUCT_LIBRARY_ASSET_INTENTS.get(requested, ()):
                if phrase in filename:
                    score = max(score, 180)

    if asset_type in {"product_photo", "parts_photo"}:
        score += 20
    if subtype and subtype != "other":
        score += 5
    return score


def _product_library_product_score(product, prompt):
    """Score product-code, vehicle, year, system, size, and alias matches."""
    value = re.sub(r"\s+", " ", str(prompt or "")).strip().casefold()
    if not value:
        return 0

    code = str(product.get("product_code") or "").strip().casefold()
    name = str(product.get("product_name") or "").strip().casefold()
    compatibility = str(
        product.get("vehicle_compatibility") or ""
    ).strip().casefold()
    description = str(product.get("description") or "").strip().casefold()
    aliases = [
        str(item).strip().casefold()
        for item in (product.get("aliases") or [])
        if str(item).strip()
    ]

    score = 0

    # A product-code request is considered decisive.
    if code and re.search(
        rf"(?<![a-z0-9]){re.escape(code)}(?![a-z0-9])",
        value,
    ):
        score += 200

    if name and name in value:
        score += 80

    for alias in aliases:
        if alias and alias in value:
            score += 70

    searchable = " ".join(
        [code, name, compatibility, description, *aliases]
    )
    prompt_tokens = {
        token
        for token in re.findall(r"[a-z0-9][a-z0-9._/-]*", value)
        if len(token) >= 2
    }

    important_terms = {
        "sync", "f150", "f250", "f350", "f450", "f550",
        "silverado", "sierra", "ram", "qhd", "manual", "auto",
        "android", "tesla", "inch",
    }

    for token in prompt_tokens:
        if token in searchable:
            score += 8 if token in important_terms else 4

    # Match a requested vehicle year against compatibility ranges such as
    # 2015-2021, including common Unicode dash variants.
    requested_years = {
        int(year)
        for year in re.findall(r"\b(19\d{2}|20\d{2})\b", value)
    }
    normalized_searchable = (
        searchable.replace("–", "-").replace("—", "-").replace("−", "-")
    )
    product_years = {
        int(year)
        for year in re.findall(r"\b(19\d{2}|20\d{2})\b", normalized_searchable)
    }
    year_ranges = [
        (int(start), int(end))
        for start, end in re.findall(
            r"\b(19\d{2}|20\d{2})\s*-\s*(19\d{2}|20\d{2})\b",
            normalized_searchable,
        )
    ]

    for requested_year in requested_years:
        if requested_year in product_years:
            score += 20
        elif any(
            min(start, end) <= requested_year <= max(start, end)
            for start, end in year_ranges
        ):
            score += 20

    # Screen-size phrases are strong disambiguators.
    requested_sizes = re.findall(
        r"\b(\d{2}(?:\.\d)?)\s*(?:inch|inches|in|\\?[\"])\b",
        value,
    )
    for size in requested_sizes:
        if size in searchable:
            score += 25

    return score


def _product_library_candidate_label(product):
    """Build a concise human-readable candidate label."""
    code = str(product.get("product_code") or "Unknown code").strip()
    name = str(product.get("product_name") or "Unnamed product").strip()
    compatibility = str(
        product.get("vehicle_compatibility") or ""
    ).strip()
    description = str(product.get("description") or "").strip()

    details = compatibility or description
    details = re.sub(r"\s+", " ", details)
    if len(details) > 120:
        details = details[:117].rstrip() + "..."

    return f"{code} — {name}" + (f" — {details}" if details else "")


TECHNICAL_PHOTO_CONTEXT_KEY_V68879 = "_technical_photo_context_v68879"


def _technical_photo_context_v68879():
    value = st.session_state.get(TECHNICAL_PHOTO_CONTEXT_KEY_V68879)
    if not isinstance(value, dict):
        return {}

    # v68880: pending Technical-photo state belongs to one conversation only.
    # A short reply in another case must never inherit the previous case's
    # request or uploaded image.
    stored_conversation_id = str(value.get("conversation_id") or "").strip()
    current_conversation_id = str(
        st.session_state.get("conversation_id") or ""
    ).strip()
    if (
        stored_conversation_id
        and current_conversation_id
        and stored_conversation_id != current_conversation_id
    ):
        st.session_state.pop(TECHNICAL_PHOTO_CONTEXT_KEY_V68879, None)
        diagnostic_log(
            "technical_photo_stale_conversation_context_rejected_v68880",
            stored_conversation_id=stored_conversation_id,
            current_conversation_id=current_conversation_id,
        )
        return {}

    return value


def _technical_photo_request_v68879(prompt_text):
    if str(assistant or "") != "🔧 Technical Support":
        return False
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not value:
        return False
    visual_terms = (
        "photo", "photos", "picture", "pictures", "image", "images",
        "show me", "display", "diagram", "screenshot",
    )
    technical_terms = (
        "car model", "a/c", "ac model", "protocol", "setting", "settings",
        "wiring", "harness", "camera", "connector", "installation", "screen",
    )
    return any(term in value for term in visual_terms) and any(
        term in value for term in technical_terms
    )


def _technical_short_clarification_v68879(prompt_text):
    value = re.sub(r"\s+", " ", str(prompt_text or "")).strip().casefold()
    if not value or len(value) > 48:
        return False
    facets = _product_library_reply_facets(value)
    return bool(
        facets.get("screen_sizes")
        or facets.get("sync_versions")
        or facets.get("climate_terms")
        or re.fullmatch(r"(?:manual|automatic|auto|sync\s*[123])", value)
    )


def _technical_recent_user_context_v68879(max_messages=3):
    """Return only recent user wording so short photo follow-ups retain model context.

    Assistant replies are intentionally excluded because they can contain several
    alternative product codes/options and would make Product Library matching
    ambiguous again.
    """
    rows = []
    for message in reversed(list(st.session_state.get("messages") or [])):
        if str(message.get("role") or "").strip().casefold() != "user":
            continue
        visible, _ = extract_images_from_message_content(
            str(message.get("content") or "")
        )
        visible = re.sub(
            r"\s+",
            " ",
            clean_visible_chat_text(visible),
        ).strip()
        if not visible:
            continue
        rows.append(visible[:500])
        if len(rows) >= max(1, int(max_messages or 1)):
            break
    rows.reverse()
    return "\n".join(rows)


def _technical_store_photo_context_v68879(prompt_text, uploaded_files):
    records = []
    for item in uploaded_files or []:
        mime = str(getattr(item, "type", "") or "").casefold()
        if not mime.startswith("image/"):
            continue
        try:
            records.append(_managed_upload_record(item))
        except Exception:
            continue

    prior = _technical_photo_context_v68879()
    context = {
        "request_text": str(prompt_text or prior.get("request_text") or "").strip(),
        "prior_user_context": (
            _technical_recent_user_context_v68879(max_messages=3)
            or str(prior.get("prior_user_context") or "")
        ),
        "image_records": records or list(prior.get("image_records") or []),
        "conversation_id": str(st.session_state.get("conversation_id") or ""),
        "updated_at": time.time(),
    }
    st.session_state[TECHNICAL_PHOTO_CONTEXT_KEY_V68879] = context
    return context


def _technical_restore_photo_files_v68879():
    context = _technical_photo_context_v68879()
    records = context.get("image_records") or []
    return _managed_upload_objects(records) if records else []


def _technical_effective_followup_prompt_v68879(prompt_text):
    current = re.sub(r"\s+", " ", str(prompt_text or "")).strip()
    context = _technical_photo_context_v68879()
    original = re.sub(
        r"\s+",
        " ",
        str(context.get("request_text") or ""),
    ).strip()
    prior_user_context = str(context.get("prior_user_context") or "").strip()
    if not original or not _technical_short_clarification_v68879(current):
        return current

    context_prefix = (
        "RECENT USER TECHNICAL CONTEXT:\n"
        + prior_user_context
        + "\n\n"
        if prior_user_context
        else ""
    )
    return (
        context_prefix
        + original
        + "\n\nTECHNICAL PHOTO CLARIFICATION ANSWER: "
        + current
        + "\nUse this clarification to complete the original photo request now. "
          "Do not ask again for a detail already supplied."
    )


def _technical_clear_photo_context_v68879():
    st.session_state.pop(TECHNICAL_PHOTO_CONTEXT_KEY_V68879, None)


def _product_library_pending_candidates():
    value = st.session_state.get("product_library_pending_candidates")
    return value if isinstance(value, list) else []


def _product_library_candidate_facets(candidate):
    """Return normalized selection facets for one Product Library candidate.

    Older Product Library rows do not always store screen size and factory system in
    dedicated columns. Infer the well-established AutoTecPro code conventions as a
    fallback so clarification replies such as ``SYNC 1`` followed by ``14.4`` can
    resolve deterministically without asking for a final option number.
    """
    aliases = candidate.get("aliases") or []
    if not isinstance(aliases, list):
        aliases = [aliases]

    code = str(candidate.get("product_code") or "").strip()
    values = [
        code,
        candidate.get("product_name"),
        candidate.get("vehicle_compatibility"),
        candidate.get("description"),
        *aliases,
    ]
    joined = " ".join(str(item or "") for item in values).casefold()
    normalized = re.sub(r"[^a-z0-9.]+", " ", joined).strip()
    compact = _product_library_normalize_code(joined)
    code_compact = _product_library_normalize_code(code)

    sync_versions = set()
    for match in re.findall(r"\bsync\s*([123])\b", normalized):
        sync_versions.add(match)
    # AutoTecPro Ford 732 family conventions: QS1/S2/S3 map to SYNC 1/2/3.
    if re.search(r"(?:^|pro)qs1$", code_compact) or code_compact.endswith("qs1"):
        sync_versions.add("1")
    if code_compact.endswith("s2"):
        sync_versions.add("2")
    if code_compact.endswith("s3"):
        sync_versions.add("3")

    screen_sizes = set(re.findall(r"\b(\d{2}(?:\.\d)?)\s*(?:inch|inches|in|\")?\b", normalized))
    # Product-code fallback for the Ford 732 family.
    if code_compact.startswith("732pro"):
        screen_sizes.add("17")
    elif code_compact.startswith("732"):
        screen_sizes.add("14.4")

    climate_terms = set()
    if re.search(r"\bmanual\s*(?:a/?c|ac|climate)\b", normalized):
        climate_terms.add("manual")
    if re.search(r"\bauto(?:matic)?\s*(?:a/?c|ac|climate)\b", normalized):
        climate_terms.add("automatic")

    return {
        "normalized": normalized,
        "compact": compact,
        "sync_versions": sync_versions,
        "screen_sizes": screen_sizes,
        "climate_terms": climate_terms,
    }


def _product_library_reply_facets(prompt):
    """Extract only explicit clarification facets from a short user reply."""
    value = re.sub(r"\s+", " ", str(prompt or "")).strip().casefold()
    normalized = re.sub(r"[^a-z0-9.]+", " ", value).strip()

    sync_versions = set(re.findall(r"\bsync\s*([123])\b", normalized))
    if not sync_versions:
        compact = re.sub(r"[^a-z0-9]+", "", value)
        compact_match = re.search(r"sync([123])", compact)
        if compact_match:
            sync_versions.add(compact_match.group(1))

    screen_sizes = set()
    for match in re.findall(r"(?<!\d)(\d{2}(?:\.\d)?)(?!\d)", value):
        if match in {"14.4", "17", "12.1", "13.8", "15.6", "17.2"}:
            screen_sizes.add(match)

    climate_terms = set()
    if re.search(r"\bmanual\s*(?:a/?c|ac|climate)?\b", normalized):
        climate_terms.add("manual")
    if re.search(r"\bauto(?:matic)?\s*(?:a/?c|ac|climate)?\b", normalized):
        climate_terms.add("automatic")

    return {
        "sync_versions": sync_versions,
        "screen_sizes": screen_sizes,
        "climate_terms": climate_terms,
    }


def _product_library_resolve_pending_selection(prompt):
    """Resolve a clarification reply and auto-open once one product remains.

    The narrowed candidate list is preserved between turns. Factory-system and
    screen-size replies are applied as structured facets, including Product Library
    rows that rely on AutoTecPro product-code conventions instead of dedicated
    metadata fields. As soon as one verified candidate remains, it is returned to
    the normal image lookup in the same turn—no final option-number confirmation.
    """
    candidates = _product_library_pending_candidates()
    if not candidates:
        return None

    value = re.sub(r"\s+", " ", str(prompt or "")).strip()
    lowered = value.casefold()

    if lowered in {"cancel", "none", "neither", "start over"}:
        st.session_state.pop("product_library_pending_candidates", None)
        st.session_state.pop("product_library_pending_filters", None)
        return {"cancelled": True}

    number_match = re.fullmatch(r"(?:option\s*)?(\d{1,2})", lowered)
    if number_match:
        selected_index = int(number_match.group(1)) - 1
        if 0 <= selected_index < len(candidates):
            selected = candidates[selected_index]
            st.session_state.pop("product_library_pending_candidates", None)
            st.session_state.pop("product_library_pending_filters", None)
            return {"product": selected}

    normalized_reply = _product_library_normalize_code(value)
    for candidate in candidates:
        if normalized_reply == _product_library_normalize_code(candidate.get("product_code")):
            st.session_state.pop("product_library_pending_candidates", None)
            st.session_state.pop("product_library_pending_filters", None)
            return {"product": candidate}

    reply_facets = _product_library_reply_facets(value)
    previous_filters = st.session_state.get("product_library_pending_filters")
    if not isinstance(previous_filters, dict):
        previous_filters = {}
    cumulative = {
        "sync_versions": set(previous_filters.get("sync_versions") or []),
        "screen_sizes": set(previous_filters.get("screen_sizes") or []),
        "climate_terms": set(previous_filters.get("climate_terms") or []),
    }
    for key in cumulative:
        cumulative[key].update(reply_facets.get(key) or set())

    has_structured_facets = any(cumulative.values())
    filtered = []
    if has_structured_facets:
        for candidate in candidates:
            facets = _product_library_candidate_facets(candidate)
            if cumulative["sync_versions"] and not (
                cumulative["sync_versions"] & facets["sync_versions"]
            ):
                continue
            if cumulative["screen_sizes"] and not (
                cumulative["screen_sizes"] & facets["screen_sizes"]
            ):
                continue
            if cumulative["climate_terms"] and not (
                cumulative["climate_terms"] & facets["climate_terms"]
            ):
                continue
            filtered.append(candidate)

    # Preserve legacy natural text matching for aliases or model wording that is not
    # represented by the structured facets above.
    if not has_structured_facets:
        normalized_text = re.sub(r"[^a-z0-9.]+", " ", lowered).strip()
        compact_text = _product_library_normalize_code(value)
        reply_tokens = [token for token in normalized_text.split() if token]
        for candidate in candidates:
            facets = _product_library_candidate_facets(candidate)
            token_match = bool(reply_tokens) and all(
                token in facets["normalized"] or token in facets["compact"]
                for token in reply_tokens
            )
            compact_match = bool(compact_text) and compact_text in facets["compact"]
            if token_match or compact_match:
                filtered.append(candidate)

    if len(filtered) == 1:
        selected = filtered[0]
        st.session_state.pop("product_library_pending_candidates", None)
        st.session_state.pop("product_library_pending_filters", None)
        return {"product": selected, "auto_resolved": True}

    if len(filtered) > 1:
        st.session_state["product_library_pending_candidates"] = filtered
        st.session_state["product_library_pending_filters"] = {
            key: sorted(values) for key, values in cumulative.items()
        }
        return {
            "clarification": True,
            "candidates": filtered,
            "narrowed": True,
        }

    if len(value) <= 40:
        return {
            "clarification": True,
            "candidates": candidates,
            "invalid_selection": True,
        }

    st.session_state.pop("product_library_pending_candidates", None)
    st.session_state.pop("product_library_pending_filters", None)
    return None



def _product_library_normalize_code(value):
    """Normalize human-entered/stored product codes for reliable matching."""
    clean = str(value or "").strip().casefold()
    clean = clean.replace("–", "-").replace("—", "-").replace("−", "-")
    return re.sub(r"[^a-z0-9]+", "", clean)


def _product_library_normalize_rows(payload):
    """Return a flat list of dictionary rows from Supabase/cache payloads.

    Depending on the Supabase client version, cache serialization, or a legacy
    helper, a read result may be returned as a normal row list, a response-like
    mapping containing ``data``, or a one-level nested list. Product Library UI
    code expects each row to be a mapping and calls ``row.get(...)``. Normalizing
    at the read boundary prevents a malformed/nested payload from crashing the
    entire Browse Products view while leaving valid rows unchanged.
    """
    if payload is None:
        return []

    if isinstance(payload, dict):
        if "data" in payload:
            payload = payload.get("data")
        else:
            return [payload]

    rows = []
    pending = list(payload) if isinstance(payload, (list, tuple)) else [payload]
    while pending:
        item = pending.pop(0)
        if isinstance(item, dict):
            # A response-shaped mapping can occasionally be nested in a list.
            if set(item.keys()) == {"data"} and isinstance(
                item.get("data"), (list, tuple)
            ):
                pending[0:0] = list(item.get("data") or [])
            else:
                rows.append(item)
        elif isinstance(item, (list, tuple)):
            pending[0:0] = list(item)

    return rows


@st.cache_data(ttl=60, max_entries=4, show_spinner=False)
def _product_library_cached_products():
    """Cache the bounded Product Library catalogue used by chat lookup."""
    database = get_supabase_admin_client()
    response = (
        database.table("product_library")
        .select(
            "id,product_code,product_name,vehicle_compatibility,"
            "description,aliases,active,updated_at"
        )
        .limit(1000)
        .execute()
    )
    return _product_library_normalize_rows(getattr(response, "data", response))


@st.cache_data(ttl=60, max_entries=2, show_spinner=False)
def _product_library_cached_asset_catalog():
    """Cache the bounded legacy asset catalogue once per minute.

    Older Product Library rows sometimes require normalized matching. Previously
    every expanded product repeated the same 5,000-row Supabase scan. Sharing one
    cached catalogue makes Manage Products substantially smoother without changing
    legacy matching behavior.
    """
    asset_columns = (
        "id,product_id,product_code,asset_type,asset_subtype,original_filename,"
        "optimized_filename,content_type,storage_bucket,storage_path,"
        "storage_status,archive_provider,archive_status,archive_file_id,archive_web_url,created_at"
    )
    response = (
        get_supabase_admin_client()
        .table("product_assets")
        .select(asset_columns)
        .order("created_at", desc=False)
        .limit(5000)
        .execute()
    )
    return _product_library_normalize_rows(getattr(response, "data", response))


@st.cache_data(ttl=60, max_entries=2, show_spinner=False)
def _product_library_cached_asset_index():
    """Index the legacy asset catalogue once instead of rescanning 5,000 rows per product."""
    catalogue = _product_library_cached_asset_catalog()
    by_code = {}
    by_product_id = {}
    by_path_root = {}

    for index, asset in enumerate(catalogue):
        if not isinstance(asset, dict):
            continue
        asset_code = _product_library_normalize_code(asset.get("product_code"))
        product_id = str(asset.get("product_id") or "").strip()
        storage_path = str(asset.get("storage_path") or "").strip().lstrip("/")
        path_root = _product_library_normalize_code(
            storage_path.split("/", 1)[0] if storage_path else ""
        )
        if asset_code:
            by_code.setdefault(asset_code, []).append(index)
        if product_id:
            by_product_id.setdefault(product_id, []).append(index)
        if path_root:
            by_path_root.setdefault(path_root, []).append(index)

    return {
        "by_code": by_code,
        "by_product_id": by_product_id,
        "by_path_root": by_path_root,
    }


@st.cache_data(ttl=60, max_entries=256, show_spinner=False)
def _product_library_cached_assets(product_code, product_id):
    """Return every asset belonging to one product, including legacy rows.

    Product Library records created at different times may differ in product-code
    capitalization/punctuation or may contain only product_id. Therefore, exact
    product_code and product_id query results are always merged. A bounded legacy
    scan is then used to recover rows whose normalized code or storage-path root
    matches the selected product. Results are deduplicated and sorted once.
    """
    database = get_supabase_admin_client()
    asset_columns = (
        "id,product_id,product_code,asset_type,asset_subtype,original_filename,"
        "optimized_filename,content_type,storage_bucket,storage_path,"
        "storage_status,archive_provider,archive_status,archive_file_id,archive_web_url,created_at"
    )

    clean_code = str(product_code or "").strip()
    clean_id = str(product_id or "").strip()
    normalized_code = _product_library_normalize_code(clean_code)
    collected = []
    used_legacy_scan = False

    def add_rows(rows):
        for row in rows or []:
            if isinstance(row, dict):
                collected.append(row)

    # Always run and merge both indexed lookups. Previously the product_id query
    # was skipped as soon as any exact-code rows existed, which hid newer assets
    # saved under a differently cased/legacy product_code.
    if clean_code:
        add_rows(
            database.table("product_assets")
            .select(asset_columns)
            .eq("product_code", clean_code)
            .order("created_at", desc=False)
            .limit(500)
            .execute().data
            or []
        )

    if clean_id:
        add_rows(
            database.table("product_assets")
            .select(asset_columns)
            .eq("product_id", clean_id)
            .order("created_at", desc=False)
            .limit(500)
            .execute().data
            or []
        )

    # A normalized scan is still required because Supabase equality matching is
    # case-sensitive and older rows may have missing/incorrect product_id values.
    # Keep it bounded to protect performance.
    if normalized_code:
        all_assets = _product_library_cached_asset_catalog()
        asset_index = _product_library_cached_asset_index()
        used_legacy_scan = True
        candidate_indexes = set(
            asset_index.get("by_code", {}).get(normalized_code, [])
        )
        candidate_indexes.update(
            asset_index.get("by_path_root", {}).get(normalized_code, [])
        )
        if clean_id:
            candidate_indexes.update(
                asset_index.get("by_product_id", {}).get(clean_id, [])
            )

        for index in sorted(candidate_indexes):
            if 0 <= index < len(all_assets):
                collected.append(all_assets[index])

    # Prefer the database id. For malformed legacy rows without id, use a stable
    # composite key so the same image is never rendered twice.
    deduplicated = {}
    for asset in collected:
        asset_id = str(asset.get("id") or "").strip()
        fallback_key = "|".join([
            str(asset.get("product_id") or "").strip(),
            _product_library_normalize_code(asset.get("product_code")),
            str(asset.get("storage_path") or "").strip(),
            str(asset.get("original_filename") or "").strip(),
        ])
        key = f"id:{asset_id}" if asset_id else f"legacy:{fallback_key}"
        deduplicated[key] = asset

    assets = list(deduplicated.values())
    assets.sort(key=lambda row: str(row.get("created_at") or ""))
    return assets, used_legacy_scan


def _product_library_clear_read_caches():
    """Clear Product Library read caches after any mutation."""
    _product_library_cached_products.clear()
    _product_library_cached_asset_catalog.clear()
    _product_library_cached_asset_index.clear()
    _product_library_cached_assets.clear()
    _product_library_dashboard_data.clear()
    try:
        _product_library_asset_data_url.clear()
    except Exception:
        pass


def _product_library_fact_lookup(prompt):
    """
    Resolve one authoritative Product Library record for normal product-fact queries.

    This lookup never loads images and never interrupts the existing vector-store
    flow. Ambiguous broad matches return no Product Library result so the normal
    workspace vector stores remain the fallback source.
    """
    if not _product_library_prompt_requests_facts(prompt):
        return None

    products = [
        product for product in (_product_library_cached_products() or [])
        if product.get("active") is not False
    ]
    ranked = sorted(
        (
            (_product_library_product_score(product, prompt), product)
            for product in products
        ),
        key=lambda item: (
            item[0],
            str(item[1].get("updated_at") or ""),
        ),
        reverse=True,
    )
    ranked = [item for item in ranked if item[0] > 0]
    if not ranked:
        return None

    top_score, top_product = ranked[0]
    exact_code_match = top_score >= 200

    # Require a meaningful match. Exact codes are decisive. Natural-language
    # compatibility queries need a stronger score than incidental token overlap.
    minimum_score = 12 if exact_code_match else 24
    if top_score < minimum_score:
        return None

    # Do not inject a possibly wrong structured record when two products are nearly
    # tied. In that case, preserve the existing vector-store answer flow.
    if not exact_code_match and len(ranked) > 1:
        second_score = ranked[1][0]
        if second_score >= max(minimum_score, top_score - 8):
            return None

    return {
        "product": top_product,
        "score": top_score,
        "source": "product_library_fact_lookup",
        "images": [],
        "assets": [],
        "requested_subtypes": [],
        "fact_only": True,
    }



def _product_library_explicit_product_matches(prompt, products):
    """Return products explicitly named in the current message.

    This check runs before remembered-product follow-up handling, so a command such
    as "front photo of 861-Pro" switches the active product instead of incorrectly
    applying the filter to the previous model.
    """
    raw_value = re.sub(r"\s+", " ", str(prompt or "")).strip().casefold()
    compact_value = _product_library_normalize_code(raw_value)
    if not raw_value or not compact_value:
        return []

    matches = []
    for product in products or []:
        code = str(product.get("product_code") or "").strip()
        aliases = product.get("aliases") or []
        if not isinstance(aliases, list):
            aliases = [aliases]

        identifiers = [code, *[str(alias or "").strip() for alias in aliases]]
        identifier_matches = []
        for identifier in identifiers:
            normalized = _product_library_normalize_code(identifier)
            if len(normalized) < 3:
                continue
            if normalized in compact_value:
                identifier_matches.append(len(normalized))

        if identifier_matches:
            matches.append((max(identifier_matches), product))

    if not matches:
        return []

    # Prefer the most specific code/alias. This prevents a base code such as 732
    # from competing with a longer explicit code such as 732Pro-S3.
    longest = max(length for length, _ in matches)
    deduplicated = {}
    for length, product in matches:
        if length != longest:
            continue
        key = str(product.get("id") or product.get("product_code") or "").strip()
        if key:
            deduplicated[key] = product
    return list(deduplicated.values())

def _product_library_chat_lookup(prompt, max_images=None):
    """
    Resolve Product Library photo requests.

    Exact product codes open immediately. Broad vehicle requests with multiple
    credible matches return a clarification list and remember those candidates,
    allowing the user to reply with a number or product code.
    """
    pending_result = _product_library_resolve_pending_selection(prompt)
    last_product = st.session_state.get("product_library_last_product")
    active_products = [
        product for product in (_product_library_cached_products() or [])
        if product.get("active") is not False
    ]
    explicit_products = _product_library_explicit_product_matches(
        prompt,
        active_products,
    )

    # IMPORTANT: a pending clarification reply must be resolved before broad
    # explicit-product matching. Replies such as ``14.4`` can match every 14.4-inch
    # product in the catalogue; if explicit matching runs first, it discards the
    # previously confirmed SYNC filter and reopens an unnecessary confirmation
    # table. Preserve the cumulative clarification state and immediately continue
    # to the verified image lookup once one candidate remains.
    if pending_result:
        if pending_result.get("cancelled"):
            return {
                "cancelled": True,
                "images": [],
            }
        if pending_result.get("clarification"):
            return pending_result
        product = pending_result.get("product")
    # An explicitly named model replaces the remembered model when there is no
    # active clarification result, including combined requests such as
    # "front photo of 861-Pro".
    elif len(explicit_products) == 1:
        st.session_state.pop("product_library_pending_candidates", None)
        st.session_state.pop("product_library_pending_filters", None)
        product = explicit_products[0]
    elif len(explicit_products) > 1:
        st.session_state["product_library_pending_candidates"] = explicit_products[:8]
        st.session_state.pop("product_library_pending_filters", None)
        return {
            "clarification": True,
            "candidates": explicit_products[:8],
            "images": [],
        }
    # Support natural follow-ups such as "only parts" after a product gallery.
    # Reuse only the last verified Product Library product when the current
    # message does not explicitly name a different product.
    elif (
        _product_library_is_asset_refinement_followup(prompt)
        and isinstance(last_product, dict)
        and last_product.get("product_code")
    ):
        product = last_product
    else:
        if not _product_library_prompt_requests_images(prompt):
            return None

        ranked = sorted(
            (
                (_product_library_product_score(product, prompt), product)
                for product in active_products
            ),
            key=lambda item: (
                item[0],
                str(item[1].get("updated_at") or ""),
            ),
            reverse=True,
        )
        ranked = [item for item in ranked if item[0] > 0]
        if not ranked or ranked[0][0] < 12:
            return None

        top_score = ranked[0][0]
        exact_code_match = top_score >= 200

        # Keep candidates close to the best score. A broad vehicle/year query
        # can legitimately match multiple systems or screen sizes.
        candidate_floor = max(12, top_score - 12)
        candidates = [
            product
            for score, product in ranked
            if score >= candidate_floor
        ][:8]

        if not exact_code_match and len(candidates) > 1:
            st.session_state["product_library_pending_candidates"] = candidates
            st.session_state.pop("product_library_pending_filters", None)
            return {
                "clarification": True,
                "candidates": candidates,
                "images": [],
            }

        product = ranked[0][1]

    if isinstance(product, dict) and product.get("product_code"):
        st.session_state["product_library_last_product"] = dict(product)

    product_code = str(product.get("product_code") or "").strip()
    normalized_code = _product_library_normalize_code(product_code)
    product_id = str(product.get("id") or "").strip()

    assets, used_legacy_scan = _product_library_cached_assets(
        product_code,
        product_id,
    )

    def _is_display_image_asset(asset):
        storage_path = str(asset.get("storage_path") or "").strip()
        if not storage_path:
            return False

        content_type = str(asset.get("content_type") or "").strip().lower()
        optimized_name = str(
            asset.get("optimized_filename")
            or Path(storage_path).name
            or ""
        ).strip().lower()
        storage_status = str(
            asset.get("storage_status") or ""
        ).strip().lower()

        failed_statuses = {
            "failed", "error", "missing", "deleted", "unavailable", "removed"
        }
        return (
            content_type.startswith("image/")
            or optimized_name.endswith((".jpg", ".jpeg", ".png", ".webp"))
        ) and storage_status not in failed_statuses

    image_assets = [
        asset for asset in assets
        if _is_display_image_asset(asset)
    ]

    # A generic follow-up such as "photo" or "all" means restore every
    # available display image for the currently selected product. It must not be
    # narrowed by accidental words from the earlier request.
    all_photos_requested = _product_library_requests_all_photos(prompt)
    requested_subtypes = (
        [] if all_photos_requested
        else _product_library_requested_subtypes(prompt)
    )

    preferred_types = {
        "parts_photo",
        "product_photo",
        "parts",
        "photo",
        "product_photos",
    }
    preferred = [
        asset for asset in image_assets
        if str(asset.get("asset_type") or "").strip().lower()
        in preferred_types
    ]

    parts_only_requested = _product_library_parts_only_requested(prompt)
    if parts_only_requested:
        parts_assets = [
            asset for asset in image_assets
            if str(asset.get("asset_type") or "").strip().lower() == "parts_photo"
            or str(asset.get("asset_subtype") or "").strip().lower() == "accessories"
        ]
        candidate_assets = parts_assets
    else:
        candidate_assets = preferred or image_assets

    # By default, return every verified matching image. A caller may still pass an
    # explicit positive max_images value for a future constrained view, but the chat
    # gallery itself must not silently stop at six images.
    try:
        image_limit = int(max_images) if max_images is not None else None
    except (TypeError, ValueError):
        image_limit = None
    if image_limit is not None and image_limit <= 0:
        image_limit = None

    if requested_subtypes:
        ranked_assets = sorted(
            (
                (_product_library_asset_relevance(asset, requested_subtypes), asset)
                for asset in candidate_assets
            ),
            key=lambda item: (
                item[0],
                str(item[1].get("created_at") or ""),
            ),
            reverse=True,
        )
        relevant_assets = [asset for score, asset in ranked_assets if score >= 180]
        selected = (
            relevant_assets[:image_limit]
            if image_limit is not None
            else relevant_assets
        )
    elif all_photos_requested:
        # The user explicitly asked for all photos for the remembered model.
        selected = list(candidate_assets)
    else:
        selected = (
            candidate_assets[:image_limit]
            if image_limit is not None
            else list(candidate_assets)
        )

    images = []
    for asset in selected:
        image_source = _product_library_asset_data_url(asset)

        # The Manage Products page already uses this signed URL successfully,
        # so use it as a direct browser-display fallback.
        if not image_source:
            image_source = _product_library_signed_url(
                asset.get("storage_path"),
                expires=86400,
            )

        if image_source:
            images.append({
                "name": str(
                    asset.get("original_filename")
                    or asset.get("optimized_filename")
                    or "Product Library image"
                ),
                "data_url": image_source,
                "generated": False,
                "source": "product_library",
                "asset_type": str(asset.get("asset_type") or "other"),
                "asset_subtype": str(asset.get("asset_subtype") or ""),
                "storage_path": str(asset.get("storage_path") or ""),
                "content_type": str(asset.get("content_type") or "image/jpeg"),
                "archive_web_url": str(asset.get("archive_web_url") or ""),
            })

    diagnostic_log(
        "product_library_chat_lookup_result",
        product_code=product_code,
        normalized_code=normalized_code,
        matched_assets_found=len(assets),
        used_legacy_scan=used_legacy_scan,
        image_assets_found=len(image_assets),
        requested_subtypes=",".join(requested_subtypes),
        selected_assets=len(selected),
        images_loaded=len(images),
    )

    return {
        "product": product,
        "assets": selected,
        "images": images,
        "requested_subtypes": requested_subtypes,
    }

def _product_library_chat_context(lookup):
    if not isinstance(lookup, dict):
        return ""

    if lookup.get("cancelled"):
        return (
            "\n\nPRODUCT LIBRARY CLARIFICATION CANCELLED:\n"
            "Confirm briefly that the product-photo selection was cancelled."
        )

    if lookup.get("clarification"):
        candidates = lookup.get("candidates") or []
        candidate_lines = [
            f"{index}. {_product_library_candidate_label(product)}"
            for index, product in enumerate(candidates, start=1)
        ]
        invalid_note = (
            "The user's last selection was not valid. "
            if lookup.get("invalid_selection")
            else ""
        )
        candidate_facets = [
            _product_library_candidate_facets(product)
            for product in candidates
        ]
        sync_options = sorted({
            value
            for facets in candidate_facets
            for value in facets.get("sync_versions", set())
        })
        screen_options = sorted({
            value
            for facets in candidate_facets
            for value in facets.get("screen_sizes", set())
        })
        missing_detail = "the remaining distinguishing detail"
        if len(sync_options) > 1:
            missing_detail = "the factory SYNC version"
        elif len(screen_options) > 1:
            missing_detail = "the desired screen size"

        return (
            "\n\nPRODUCT LIBRARY CLARIFICATION REQUIRED:\n"
            f"{invalid_note}"
            f"I found {len(candidates)} possible matching products.\n"
            + "\n".join(candidate_lines)
            + f"\nAsk only for {missing_detail}. Accept a natural reply such as "
              "SYNC 1, 14.4, or 17. Do not ask for an option number or product "
              "code when the supplied detail leaves exactly one candidate. Once "
              "one candidate remains, the app will automatically load and display "
              "its verified Product Library photos in the same turn. Do not add "
              "unrelated technical details while clarification is still required."
        )

    if not lookup.get("product"):
        return ""

    product = lookup["product"]
    asset_names = [
        _product_library_asset_heading(asset)
        for asset in lookup.get("assets") or []
    ]
    requested_subtypes = [
        PRODUCT_ASSET_SUBTYPE_LABELS.get(value, value.replace("_", " ").title())
        for value in (lookup.get("requested_subtypes") or [])
    ]
    fact_only = bool(lookup.get("fact_only"))
    compatibility = str(product.get("vehicle_compatibility") or "").strip()
    description = str(product.get("description") or "").strip()

    if fact_only:
        return (
            "\n\nVERIFIED PRODUCT LIBRARY FACT RESULT (server-side Supabase lookup):\n"
            f"Product code: {product.get('product_code')}\n"
            f"Product name: {product.get('product_name')}\n"
            f"Compatibility: {compatibility or 'Not specified'}\n"
            f"Description: {description or 'Not specified'}\n"
            "SOURCE PRIORITY RULES:\n"
            "- Treat Product Library product code, product name, aliases, and any "
            "explicitly populated compatibility or description facts as the current "
            "structured source of truth.\n"
            "- Continue using the workspace vector store search for missing details, "
            "procedures, troubleshooting, installation guidance, limitations, and "
            "other supporting knowledge.\n"
            "- If Compatibility is 'Not specified', do not interpret that as "
            "incompatible; use verified vector-store knowledge and clearly identify "
            "the supporting source.\n"
            "- If a vector-store result conflicts with an explicitly populated "
            "Product Library field, follow Product Library for that structured field "
            "and mention the conflict instead of guessing."
        )

    return (
        "\n\nVERIFIED PRODUCT LIBRARY RESULT (server-side Supabase lookup):\n"
        f"Product code: {product.get('product_code')}\n"
        f"Product name: {product.get('product_name')}\n"
        f"Compatibility: {compatibility or 'Not specified'}\n"
        f"Description: {description or 'Not specified'}\n"
        f"Requested asset detail: "
        f"{', '.join(requested_subtypes) if requested_subtypes else 'General product photos'}\n"
        f"Matching image files found: "
        f"{', '.join(asset_names) if asset_names else 'None'}\n"
        f"Images successfully loaded for chat display: "
        f"{len(lookup.get('images') or [])}\n"
        "Tell the user only what this verified record supports. If the "
        "loaded-image count is greater than zero, state that the matching "
        "photos are displayed below the answer. Do not say the app cannot "
        "display them. Continue using vector-store knowledge for missing "
        "non-image details."
    )



def _product_library_upsert_product(product_code, product_name, compatibility, description, aliases, active=True):
    payload = {
        "product_code": product_code,
        "product_name": product_name,
        "vehicle_compatibility": compatibility,
        "description": description,
        "aliases": aliases,
        "active": bool(active),
        "updated_by": str(st.session_state.get("username") or ""),
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    existing = (
        supabase.table("product_library")
        .select("id")
        .eq("product_code", product_code)
        .limit(1)
        .execute()
        .data
        or []
    )
    if existing:
        result = (
            supabase.table("product_library")
            .update(payload)
            .eq("id", existing[0]["id"])
            .execute()
        )
        return (result.data or [existing[0]])[0]
    result = supabase.table("product_library").insert(payload).execute()
    return (result.data or [None])[0]


def _product_library_upload_asset(product, asset_type, uploaded_file, asset_subtype="other"):
    """Upload one Product Library asset and prevent exact duplicate records."""
    product_code = str(product.get("product_code") or "")
    product_id = product.get("id")
    clean_subtype = str(asset_subtype or "other").strip().lower()
    if clean_subtype not in _product_library_subtype_options(asset_type):
        clean_subtype = "other"
    filename = _product_library_safe_filename(uploaded_file.name)
    original = uploaded_file.getvalue()
    content_type = str(uploaded_file.type or "application/octet-stream")
    if len(original) > PRODUCT_LIBRARY_MAX_ORIGINAL_BYTES:
        raise RuntimeError(f"{filename} exceeds the 20 MB Product Library limit.")

    # Build a deterministic fingerprint before any external upload. Images use a
    # deterministic Supabase path; non-images use filename + byte size because the
    # current product_assets schema does not contain a checksum column.
    digest = hashlib.sha256(original).hexdigest()[:16]
    optimized = b""
    optimized_filename = ""
    optimized_type = ""
    optimized_bytes = 0
    storage_path = ""
    storage_status = "not_applicable"

    if content_type.startswith("image/"):
        optimized, optimized_filename, optimized_type = _product_library_optimize_image(
            original, filename, PRODUCT_LIBRARY_DISPLAY_MAX_PX
        )
        storage_path = (
            f"{product_code}/{asset_type}/{clean_subtype}/"
            f"{digest}-{optimized_filename}"
        )
        duplicate_query = (
            supabase.table("product_assets")
            .select("id,original_filename,storage_path")
            .eq("product_id", product_id)
            .eq("storage_path", storage_path)
            .limit(1)
            .execute().data
            or []
        )
    else:
        duplicate_query = (
            supabase.table("product_assets")
            .select("id,original_filename,original_bytes")
            .eq("product_id", product_id)
            .eq("asset_type", asset_type)
            .eq("asset_subtype", clean_subtype)
            .eq("original_filename", filename)
            .eq("original_bytes", len(original))
            .limit(1)
            .execute().data
            or []
        )

    if duplicate_query:
        raise RuntimeError(
            f"{filename} is already saved for this product and asset category."
        )

    # Save the optimized display image first so an external archive-provider
    # outage cannot abort the Product Library upload.
    if storage_path:
        _product_library_storage_upload(storage_path, optimized, optimized_type)
        optimized_bytes = len(optimized)
        storage_status = "available"

    archive_provider = "none"
    archive_status = "not_configured"
    archive_file_id = ""
    archive_web_url = ""
    drive_error = None

    if _product_library_google_configured():
        try:
            product_folder = _product_library_drive_create_folder(
                product_code, GOOGLE_DRIVE_ROOT_FOLDER_ID
            )
            category_folder = _product_library_drive_create_folder(
                PRODUCT_ASSET_LABELS.get(asset_type, "Other"), product_folder["id"]
            )
            subtype_folder = _product_library_drive_create_folder(
                PRODUCT_ASSET_SUBTYPE_LABELS.get(clean_subtype, "Other"),
                category_folder["id"],
            )
            drive_file = _product_library_drive_upload_bytes(
                filename, content_type, original, subtype_folder["id"]
            )
            archive_provider = "google_drive"
            archive_status = "available"
            archive_file_id = str(drive_file.get("id") or "")
            archive_web_url = str(drive_file.get("webViewLink") or "")
        except Exception as error:
            drive_error = error
            diagnostic_log(
                "product_library_google_archive_unavailable",
                filename=filename,
                auth_failure=_product_library_google_auth_failure(error),
                error_type=type(error).__name__,
                error=error,
            )

    # Google Drive is the preferred archive, but it must never make a valid
    # Product Library upload fail. Preserve the original privately in Supabase
    # Storage whenever Drive is unavailable, misconfigured, expired, or revoked.
    if archive_status != "available":
        fallback_path = _product_library_original_fallback_path(
            product_code, asset_type, clean_subtype, digest, filename
        )
        try:
            _product_library_storage_upload(fallback_path, original, content_type)
            archive_provider = "supabase_storage_fallback"
            archive_status = (
                "available_google_auth_fallback"
                if drive_error and _product_library_google_auth_failure(drive_error)
                else "available_fallback"
            )
            archive_file_id = fallback_path
            archive_web_url = ""
        except Exception as fallback_error:
            # Image assets still have their optimized private copy. Non-image
            # assets have no usable file without an archive, so fail truthfully.
            if not storage_path:
                raise RuntimeError(
                    f"{filename} could not be archived in Google Drive or Supabase Storage: "
                    f"{fallback_error}"
                ) from fallback_error
            archive_provider = "none"
            archive_status = "unavailable"
            diagnostic_log(
                "product_library_original_fallback_failed",
                filename=filename,
                error_type=type(fallback_error).__name__,
                error=fallback_error,
            )

    record = {
        "product_id": product_id,
        "product_code": product_code,
        "asset_type": asset_type,
        "asset_subtype": clean_subtype,
        "original_filename": filename,
        "original_bytes": len(original),
        "optimized_filename": optimized_filename,
        "optimized_bytes": optimized_bytes,
        "content_type": content_type,
        "storage_bucket": PRODUCT_LIBRARY_BUCKET if storage_path else "",
        "storage_path": storage_path,
        "storage_status": storage_status,
        "archive_provider": archive_provider,
        "archive_status": archive_status,
        "archive_file_id": archive_file_id,
        "archive_web_url": archive_web_url,
        "uploaded_by": str(st.session_state.get("username") or ""),
    }
    result = supabase.table("product_assets").insert(record).execute()
    saved = (result.data or [record])[0]
    _product_library_clear_read_caches()
    return saved


@st.cache_data(ttl=30, show_spinner=False)
def _product_library_dashboard_data():
    products = supabase.table("product_library").select("id,active").execute().data or []
    assets = (
        supabase.table("product_assets")
        .select("id,optimized_bytes,storage_status,archive_status")
        .execute().data
        or []
    )
    return {
        "products": len(products),
        "active": sum(1 for row in products if row.get("active")),
        "assets": len(assets),
        "optimized_bytes": sum(int(row.get("optimized_bytes") or 0) for row in assets),
        "storage_missing": sum(1 for row in assets if row.get("storage_status") not in {"available", "not_applicable"}),
        "archive_missing": sum(
            1 for row in assets
            if not str(row.get("archive_status") or "").startswith("available")
        ),
    }


def _product_library_format_bytes(value):
    size = float(value or 0)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024


@_optional_ui_fragment
def render_product_library_dashboard_fragment():
    """Render dashboard metrics without rerunning unrelated app sections."""
    refresh_col, _ = st.columns([0.22, 0.78])
    with refresh_col:
        if st.button(
            "Refresh dashboard",
            key="product_library_dashboard_fragment_refresh",
            use_container_width=True,
        ):
            _product_library_dashboard_data.clear()
            _product_library_clear_read_caches()
            _rerun_fragment_or_app()
    try:
        data = _product_library_dashboard_data()
        cols = st.columns(4)
        metrics = [
            ("Total Products", data["products"]),
            ("Active Products", data["active"]),
            ("Total Assets", data["assets"]),
            ("Optimized Storage", _product_library_format_bytes(data["optimized_bytes"])),
        ]
        for column, (label, value) in zip(cols, metrics):
            with column:
                st.metric(label, value)
        status_cols = st.columns(2)
        with status_cols[0]:
            st.metric("Assets Missing Display Copy", data["storage_missing"])
        with status_cols[1]:
            st.metric("Assets Missing Drive Archive", data["archive_missing"])
    except Exception as error:
        st.error(f"Product Library dashboard could not load: {error}")




@_optional_ui_fragment
def render_product_library_manage_fragment():
    """Isolate high-frequency Product Library management interactions.

    Search, product expansion, section switching, and Replace/Delete panel toggles
    stay local. Existing successful mutation paths still perform full reruns.
    """
    product_library_notice = (
        st.session_state.pop("product_library_notice", "")
        or st.session_state.pop("product_library_delete_notice", "")
    )
    if product_library_notice:
        st.success(product_library_notice)

    search_value = st.text_input("Search products", placeholder="Product code, name, compatibility, or alias")
    try:
        # Reuse the bounded Product Library cache so search, expansion, and
        # section switching never repeat the same Supabase catalogue query.
        products = [dict(row) for row in (_product_library_cached_products() or [])]
        products.sort(
            key=lambda row: str(row.get("updated_at") or ""),
            reverse=True,
        )
        needle = str(search_value or "").strip().casefold()
        if needle:
            products = [
                row for row in products
                if needle in " ".join([
                    str(row.get("product_code") or ""),
                    str(row.get("product_name") or ""),
                    str(row.get("vehicle_compatibility") or ""),
                    json.dumps(row.get("aliases") or [], ensure_ascii=False),
                ]).casefold()
            ]
        st.caption(f"Showing {len(products)} product(s)")
        for product in products:
            product_id = str(product.get("id") or "")
            title = f"{product.get('product_code')} — {product.get('product_name')}"
            product_is_open = (
                str(st.session_state.get("product_library_open_product_id") or "")
                == product_id
            )
            with st.expander(title, expanded=product_is_open):
                section_key = f"product_library_section_{product_id}"
                if section_key not in st.session_state:
                    st.session_state[section_key] = "Edit Product"
                selected_product_section = st.radio(
                    "Product section",
                    ["Edit Product", "Files", "Delete Product"],
                    horizontal=True,
                    key=section_key,
                    label_visibility="collapsed",
                    on_change=_product_library_select_section,
                    args=(product_id, section_key),
                )

                if selected_product_section == "Edit Product":
                    with st.form(f"product_edit_{product_id}"):
                        st.text_input("Product / Model Code", value=str(product.get("product_code") or ""), disabled=True)
                        edit_name = st.text_input("Product Name", value=str(product.get("product_name") or ""))
                        edit_compatibility = st.text_area("Vehicle Compatibility", value=str(product.get("vehicle_compatibility") or ""), height=90)
                        edit_description = st.text_area("Description", value=str(product.get("description") or ""), height=120)
                        edit_aliases = st.text_input("Aliases", value=", ".join(str(item) for item in (product.get("aliases") or [])))
                        edit_active = st.checkbox("Active Product", value=bool(product.get("active")), key=f"active_{product_id}")
                        save_edit_submit_cols = st.columns([1, 2, 1])
                        with save_edit_submit_cols[1]:
                            save_edit = st.form_submit_button(
                                "Save Product Changes",
                                use_container_width=True,
                            )
                    if save_edit:
                        try:
                            aliases = [item.strip() for item in edit_aliases.split(",") if item.strip()]
                            _product_library_update_product(
                                product_id, edit_name, edit_compatibility,
                                edit_description, aliases, edit_active,
                            )
                            st.success("Product information updated.")
                            st.rerun()
                        except Exception as error:
                            st.error(f"Product update failed: {error}")

                if selected_product_section == "Files":
                    with st.form(f"product_add_files_{product_id}"):
                        add_asset_type = st.selectbox(
                            "Asset Type", PRODUCT_ASSET_TYPES,
                            format_func=lambda value: PRODUCT_ASSET_LABELS.get(value, value.title()),
                            key=f"asset_type_{product_id}",
                        )
                        add_asset_subtype = st.selectbox(
                            "Asset Subtype",
                            _product_library_subtype_options(add_asset_type),
                            format_func=lambda value: PRODUCT_ASSET_SUBTYPE_LABELS.get(value, value.replace("_", " ").title()),
                            key=f"asset_subtype_{product_id}_{add_asset_type}",
                            help="Choose the specific view, component, or document purpose.",
                        )
                        add_uploads = st.file_uploader(
                            "Upload more files",
                            accept_multiple_files=True,
                            type=["jpg", "jpeg", "png", "webp", "pdf", "docx", "txt", "csv", "zip"],
                            key=f"add_files_{product_id}",
                        )
                        add_files_submit_cols = st.columns([1, 2, 1])
                        with add_files_submit_cols[1]:
                            add_files_submitted = st.form_submit_button(
                                "Upload More Files",
                                use_container_width=True,
                            )
                    if add_files_submitted:
                        if not add_uploads:
                            st.warning("Please select at least one file.")
                        else:
                            failures = []
                            for uploaded_file in add_uploads:
                                try:
                                    _product_library_upload_asset(product, add_asset_type, uploaded_file, add_asset_subtype)
                                except Exception as error:
                                    failures.append(f"{uploaded_file.name}: {error}")
                            if failures:
                                for failure in failures:
                                    st.error(failure)
                            else:
                                st.session_state["product_library_notice"] = (
                                    f"Uploaded {len(add_uploads)} additional file(s)."
                                )
                                st.session_state["product_library_open_product_id"] = product_id
                                st.session_state[f"product_library_section_{product_id}"] = "Files"
                                _rerun_fragment_or_app()

                    cached_assets, _ = _product_library_cached_assets(
                        str(product.get("product_code") or ""),
                        product_id,
                    )
                    assets = list(reversed([dict(row) for row in (cached_assets or [])]))

                    # Hide duplicate legacy rows in the manager while keeping the newest
                    # record. Future exact duplicates are blocked during upload.
                    unique_assets = []
                    seen_asset_keys = set()
                    st.markdown(
                        """
                        <style>
                        div[class*="st-key-replace_asset_panel_"],
                        div[class*="st-key-delete_asset_panel_"] {
                            position: relative;
                        }

                        div[class*="st-key-replace_panel_minimize_"] button,
                        div[class*="st-key-delete_panel_minimize_"] button {
                            width: 26px !important;
                            min-width: 26px !important;
                            max-width: 26px !important;
                            height: 26px !important;
                            min-height: 26px !important;
                            padding: 0 !important;
                            border-radius: 7px !important;
                            font-size: 17px !important;
                            line-height: 1 !important;
                        }

                        .atp-replacement-help-row {
                            display: flex;
                            align-items: center;
                            justify-content: space-between;
                            gap: 10px;
                            margin: 0 0 6px;
                        }

                        .atp-replacement-help-label {
                            font-weight: 600;
                        }

                        .atp-replacement-help-icon {
                            width: 18px;
                            height: 18px;
                            border: 1px solid rgba(148, 163, 184, 0.9);
                            border-radius: 50%;
                            display: inline-flex;
                            align-items: center;
                            justify-content: center;
                            font-size: 11px;
                            font-weight: 700;
                            line-height: 1;
                            cursor: help;
                            opacity: 0.9;
                            flex: 0 0 auto;
                        }

                        div[class*="st-key-replacement_upload_shell_"]
                        div[data-testid="stFileUploader"] small,
                        div[class*="st-key-replacement_upload_shell_"]
                        div[data-testid="stFileUploaderDropzoneInstructions"] {
                            display: none !important;
                        }

                        div[class*="st-key-replacement_upload_shell_"]
                        div[data-testid="stFileUploader"] section::after,
                        div[class*="st-key-replacement_upload_shell_"]
                        div[data-testid="stFileUploaderDropzone"]::after {
                            content: "20MB per file • JPG, PNG, WEBP, PDF, DOCX, XLS, XLSX, XLSM, XLSB, CSV, PPT, PPTX, ZIP";
                            display: block;
                            width: 100%;
                            margin-top: 6px;
                            color: #94a3b8;
                            font-size: 11.5px;
                            line-height: 1.3;
                            text-align: center;
                            pointer-events: none;
                        }
                        </style>
                        """,
                        unsafe_allow_html=True,
                    )

                    for asset in assets:
                        stable_key = (
                            str(asset.get("storage_path") or "").strip()
                            or str(asset.get("archive_file_id") or "").strip()
                            or "|".join([
                                str(asset.get("asset_type") or ""),
                                str(asset.get("asset_subtype") or ""),
                                str(asset.get("original_filename") or ""),
                            ])
                        )
                        if stable_key in seen_asset_keys:
                            continue
                        seen_asset_keys.add(stable_key)
                        unique_assets.append(asset)
                    assets = unique_assets

                    if not assets:
                        st.info("No files have been uploaded for this product.")

                    st.markdown(
                        """
                        <style>
                        div[class*="st-key-product_asset_meta_"] {
                            width: min(100%, 920px) !important;
                            margin: 0.45rem auto 0.7rem auto !important;
                        }
                        div[class*="st-key-product_asset_meta_"] p {
                            margin: 0.08rem 0 !important;
                            line-height: 1.35 !important;
                            color: var(--text-color) !important;
                        }
                        div[class*="st-key-product_asset_toolbar_"] {
                            width: min(100%, 1040px) !important;
                            margin: 0 auto 0.15rem auto !important;
                        }
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stHorizontalBlock"] {
                            display: grid !important;
                            grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
                            gap: 0.65rem !important;
                        }
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stColumn"] {
                            width: auto !important;
                            min-width: 0 !important;
                            flex: none !important;
                        }
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stLinkButton"],
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stButton"] {
                            width: 100% !important;
                        }
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stLinkButton"] > a,
                        div[class*="st-key-product_asset_toolbar_"]
                        div[data-testid="stButton"] > button {
                            width: 100% !important;
                            min-height: 2.5rem !important;
                            height: 2.5rem !important;
                            padding-top: 0 !important;
                            padding-bottom: 0 !important;
                            display: inline-flex !important;
                            align-items: center !important;
                            justify-content: center !important;
                            box-sizing: border-box !important;
                        }
                        @media (max-width: 768px) {
                            div[class*="st-key-product_asset_meta_"],
                            div[class*="st-key-product_asset_toolbar_"] {
                                width: 100% !important;
                            }
                            div[class*="st-key-product_asset_toolbar_"]
                            div[data-testid="stHorizontalBlock"] {
                                grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
                            }
                        }
                        </style>
                        """,
                        unsafe_allow_html=True,
                    )

                    for asset in assets:
                        asset_id = str(asset.get("id") or "")
                        asset_placeholder = st.empty()
                        with asset_placeholder.container():
                            signed_url = _product_library_signed_url(asset.get("storage_path"))
                            if signed_url and str(asset.get("content_type") or "").startswith("image/"):
                                st.image(signed_url, use_container_width=True)

                            filename = str(
                                asset.get("original_filename") or "Unnamed file"
                            )
                            asset_type = str(asset.get("asset_type") or "other")
                            subtype = str(asset.get("asset_subtype") or "").strip()
                            type_label = PRODUCT_ASSET_LABELS.get(
                                asset_type,
                                asset_type.replace("_", " ").title(),
                            )
                            subtype_label = PRODUCT_ASSET_SUBTYPE_LABELS.get(
                                subtype,
                                subtype.replace("_", " ").title(),
                            )
                            location_label = (
                                f"{type_label} / {subtype_label}"
                                if subtype_label
                                else type_label
                            )

                            with st.container(
                                key=f"product_asset_meta_{asset_id}"
                            ):
                                st.markdown(f"**{html.escape(filename)}**")
                                st.caption(location_label)
                                st.caption(
                                    f"Display: {asset.get('storage_status') or 'unknown'}  ·  "
                                    f"Archive: {asset.get('archive_status') or 'unknown'}"
                                )

                            replace_panel_key = f"replace_panel_{asset_id}"
                            delete_panel_key = f"delete_panel_{asset_id}"

                            archive_url = _product_library_original_url(asset)
                            with st.container(
                                key=f"product_asset_toolbar_{asset_id}"
                            ):
                                action_cols = st.columns(4, gap="small")

                                with action_cols[0]:
                                    if signed_url:
                                        st.link_button(
                                            "View",
                                            str(signed_url),
                                            use_container_width=True,
                                            help="Open the optimized display copy",
                                        )
                                    else:
                                        st.button(
                                            "View",
                                            key=f"view_asset_disabled_{asset_id}",
                                            disabled=True,
                                            use_container_width=True,
                                        )

                                with action_cols[1]:
                                    if archive_url:
                                        st.link_button(
                                            "Original",
                                            archive_url,
                                            use_container_width=True,
                                            help="Open the original private archive",
                                        )
                                    else:
                                        st.button(
                                            "Original",
                                            key=f"original_asset_disabled_{asset_id}",
                                            disabled=True,
                                            use_container_width=True,
                                        )

                                with action_cols[2]:
                                    st.button(
                                        "Replace",
                                        key=f"replace_asset_toggle_{asset_id}",
                                        use_container_width=True,
                                        help="Replace this Product Library file",
                                        on_click=_product_library_toggle_asset_panel,
                                        args=(product_id, asset_id, "replace"),
                                    )

                                with action_cols[3]:
                                    st.button(
                                        "Delete",
                                        key=f"delete_asset_toggle_{asset_id}",
                                        use_container_width=True,
                                        help="Delete this Product Library file",
                                        on_click=_product_library_toggle_asset_panel,
                                        args=(product_id, asset_id, "delete"),
                                    )

                            if st.session_state.get(replace_panel_key, False):
                                with st.container(
                                    border=True,
                                    key=f"replace_asset_panel_{asset_id}",
                                ):
                                    panel_header_cols = st.columns(
                                        [1, 0.05],
                                        gap="small",
                                        vertical_alignment="center",
                                    )
                                    with panel_header_cols[0]:
                                        st.markdown("**Replace File**")
                                    with panel_header_cols[1]:
                                        with st.container(
                                            key=f"replace_panel_minimize_{asset_id}"
                                        ):
                                            st.button(
                                                "−",
                                                key=f"minimize_replace_{asset_id}",
                                                help="Minimize Replace File",
                                                on_click=_product_library_close_asset_panel,
                                                args=(product_id, asset_id, "replace"),
                                            )

                                    with st.form(f"replace_asset_form_{asset_id}"):
                                        st.markdown(
                                            """
                                            <div class="atp-replacement-help-row">
                                                <span class="atp-replacement-help-label">Choose one replacement file</span>
                                                <span class="atp-replacement-help-icon" title="The replacement keeps the same asset type. The old file is removed only after the new file uploads successfully.">?</span>
                                            </div>
                                            """,
                                            unsafe_allow_html=True,
                                        )
                                        with st.container(
                                            key=f"replacement_upload_shell_{asset_id}"
                                        ):
                                            replacement_file = st.file_uploader(
                                                "Choose one replacement file",
                                                accept_multiple_files=False,
                                                type=[
                                                    "jpg", "jpeg", "png", "webp",
                                                    "pdf", "docx", "txt", "csv", "zip",
                                                ],
                                                key=f"replacement_upload_{asset_id}",
                                                label_visibility="collapsed",
                                            )
                                        replacement_submitted = st.form_submit_button(
                                            "Save Replacement",
                                            use_container_width=True,
                                        )
                                    if replacement_submitted:
                                        if replacement_file is None:
                                            st.warning("Please select a replacement file.")
                                        else:
                                            try:
                                                _product_library_replace_asset(
                                                    product,
                                                    asset,
                                                    replacement_file,
                                                )
                                                st.session_state[replace_panel_key] = False
                                                st.session_state["product_library_open_product_id"] = product_id
                                                st.session_state[f"product_library_section_{product_id}"] = "Files"
                                                st.session_state["product_library_notice"] = "File replaced successfully."
                                                st.rerun()
                                            except Exception as error:
                                                st.error(
                                                    "File replacement failed: "
                                                    f"{error}"
                                                )

                            if st.session_state.get(delete_panel_key, False):
                                with st.container(
                                    border=True,
                                    key=f"delete_asset_panel_{asset_id}",
                                ):
                                    delete_header_cols = st.columns(
                                        [1, 0.05],
                                        gap="small",
                                        vertical_alignment="center",
                                    )
                                    with delete_header_cols[0]:
                                        st.markdown("**Delete this file?**")
                                    with delete_header_cols[1]:
                                        with st.container(
                                            key=f"delete_panel_minimize_{asset_id}"
                                        ):
                                            st.button(
                                                "−",
                                                key=f"minimize_delete_{asset_id}",
                                                help="Minimize Delete File",
                                                on_click=_product_library_close_asset_panel,
                                                args=(product_id, asset_id, "delete"),
                                            )
                                    st.caption(
                                        "This removes the display copy, Product Library "
                                        "record, and Google Drive archive."
                                    )
                                    with st.form(f"delete_asset_form_{asset_id}"):
                                        confirm_asset = st.checkbox(
                                            "Confirm delete this file",
                                            key=f"confirm_asset_{asset_id}",
                                        )
                                        delete_asset_clicked = st.form_submit_button(
                                            "Delete File",
                                            type="primary",
                                            use_container_width=True,
                                        )

                                    if delete_asset_clicked:
                                        if not confirm_asset:
                                            st.warning(
                                                "Please check ‘Confirm delete this file’ first."
                                            )
                                        else:
                                            try:
                                                with st.spinner("Deleting file..."):
                                                    _product_library_delete_asset(asset)
                                                st.session_state.pop(delete_panel_key, None)
                                                st.session_state.pop(replace_panel_key, None)
                                                st.session_state["product_library_open_product_id"] = product_id
                                                st.session_state[f"product_library_section_{product_id}"] = "Files"
                                                st.session_state["product_library_notice"] = (
                                                    "File deleted from Product Library, Supabase Storage, "
                                                    "and Google Drive archive."
                                                )
                                                st.rerun()
                                            except Exception as error:
                                                st.error(
                                                    "File deletion failed: "
                                                    f"{error}"
                                                )

                            st.divider()

                if selected_product_section == "Delete Product":
                    st.warning(
                        "This permanently removes the product metadata and all linked Product Library files. "
                        "Google Drive originals are moved to Trash."
                    )
                    delete_submit_cols = st.columns([1, 2, 1])
                    with delete_submit_cols[1]:
                        delete_product_clicked = st.button(
                            "Delete Product Permanently",
                            key=f"delete_product_{product_id}",
                            type="primary",
                            use_container_width=True,
                        )

                    if delete_product_clicked:
                        try:
                            with st.spinner("Deleting product and linked files..."):
                                delete_result = _product_library_delete_product(product)

                            cleanup_warnings = delete_result.get("cleanup_warnings") or []
                            if cleanup_warnings:
                                diagnostic_log(
                                    "product_library_delete_completed_with_warnings",
                                    product_id=product_id,
                                    warning_count=len(cleanup_warnings),
                                )

                            st.session_state["product_library_delete_notice"] = (
                                "Product and linked records deleted successfully."
                            )
                            st.rerun()
                        except Exception as error:
                            diagnostic_log(
                                "product_library_delete_failed",
                                product_id=product_id,
                                error=error,
                            )
                            st.error(f"Product deletion failed: {error}")
    except Exception as error:
        st.error(f"Product records could not load: {error}")





