# v68880: refresh the signed workspace cookie only after the destination UI has
# been emitted. This preserves reconnect recovery while removing the cookie
# component write from the workspace-navigation callback/critical paint path.
_pending_workspace_auth_refresh_v68880 = str(
    st.session_state.pop("_workspace_auth_refresh_pending_v68880", "") or ""
).strip()
if _pending_workspace_auth_refresh_v68880:
    _workspace_cookie_started_v68880 = time.perf_counter()
    username_v68880 = str(st.session_state.get("username") or "").strip()
    if username_v68880:
        try:
            save_authenticated_session(
                username_v68880,
                remember=bool(
                    st.session_state.get("_atp_session_remembered")
                ),
                workspace=_pending_workspace_auth_refresh_v68880,
            )
            diagnostic_log(
                "workspace_auth_refresh_deferred_v68880",
                workspace=_pending_workspace_auth_refresh_v68880,
                elapsed_seconds=round(
                    time.perf_counter() - _workspace_cookie_started_v68880,
                    4,
                ),
            )
        except Exception as error:
            diagnostic_log(
                "workspace_auth_refresh_failed",
                error=str(error),
            )

# v69023: only after the destination UI and deferred workspace-cookie refresh
# have been emitted do we release the global first-render quarantine. This makes
# every manual workspace switch use the same stable lifecycle.
_workspace_complete_first_render_v69023(
    st.session_state.get("current_assistant")
)

# v69006: render one print-only transcript after all chat processing for this
# Streamlit run. This includes restored History messages and any answer appended
# during the current run, while remaining completely hidden on screen.
try:
    _print_messages_v69006 = list(st.session_state.get("messages") or [])
    _print_assistant_v69006 = str(locals().get("assistant") or "Technical Support")
    if (
        st.session_state.get("logged_in", False)
        and _print_messages_v69006
        and _print_assistant_v69006 not in {
            "⚙️ Admin Panel",
            "📦 Product Library",
            "🧠 Knowledge Submission",
        }
    ):
        _existing_print_placeholder_v69018 = locals().get(
            "_print_transcript_placeholder_v69018"
        )
        if _existing_print_placeholder_v69018 is not None:
            render_print_transcript_v69007(
                _print_messages_v69006,
                assistant_label=_print_assistant_v69006,
                target=_existing_print_placeholder_v69018,
            )
        else:
            render_print_transcript_v69007(
                _print_messages_v69006,
                assistant_label=_print_assistant_v69006,
            )
except Exception as _print_transcript_error_v69006:
    diagnostic_log(
        "print_transcript_render_failed_v69006",
        error_type=type(_print_transcript_error_v69006).__name__,
        error=str(_print_transcript_error_v69006)[:500],
    )

